export const FLASH = [{"id":"t:4c","kind":"term","course":"m02","lesson":"marketing-mix","front":"4Cs","back":"Robert Lauterborn’s (1990) buyer’s-side alternative to the 4Ps: consumer wants and needs, cost to satisfy, convenience to buy, and communication.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:4p","kind":"term","course":"m02","lesson":"marketing-mix","front":"4Ps","back":"Product, price, place and promotion: the four headings E. Jerome McCarthy (1960) used to organise the marketing mix.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:7p","kind":"term","course":"m02","lesson":"marketing-mix","front":"7Ps","back":"The 4Ps plus people, process and physical evidence, proposed by Booms and Bitner (1981) for marketing services.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:95% confidence interval","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"95% confidence interval","back":"A range calculated from sample data by a method that captures the true value in 95% of samples; in Excel’s regression output, the Lower 95% and Upper 95% of each coefficient.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:a/b test","kind":"term","course":"b01","lesson":"data-collection","front":"A/B test","back":"An experiment in which units such as website visitors are randomly assigned to two versions, A and B, so that a difference in outcomes can be attributed to the version rather than to who saw it.","href":"learn/analytics/b01/data-collection/"},{"id":"t:absolute reference","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Absolute reference","back":"A cell reference with a dollar sign before both its column and its row, such as $A$1, which stays the same when the formula is filled or copied.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:acceleration effect","kind":"term","course":"m01","lesson":"business-buying","front":"Acceleration effect","back":"The tendency for orders of equipment and other durable inputs to swing by a much larger percentage than the end demand they serve, because orders depend on the change in demand as well as its level.","href":"learn/marketing/m01/business-buying/"},{"id":"t:account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Account","back":"A record of all the increases and decreases in one item, such as cash or accounts payable, together with its balance.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:account balance","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Account balance","back":"The difference between an account’s total debits and total credits, including any balance brought forward, stated on the side of the larger total.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:account form","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Account form","back":"A balance sheet layout with assets on the left and liabilities and equity on the right, like the two sides of an account.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Accounting","back":"An information system that identifies the economic events of an organisation, records them in money and communicates the results to the people who make decisions about it.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:accounting cycle","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Accounting cycle","back":"The sequence of steps a business repeats every accounting period, from analysing transactions to preparing a post-closing trial balance.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:accounting equation","kind":"term","course":"f01","lesson":"accounting-equation","front":"Accounting equation","back":"Assets = liabilities + equity: the business’s resources equal the claims of creditors and owners on them.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:accounting profit","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Accounting profit","back":"Revenue minus expenses as measured under the accounting rules; also called net income.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:accounts payable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Accounts payable","back":"Amounts a business owes suppliers for goods and services bought on credit. Called trade payables under IFRS.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:accounts receivable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Accounts receivable","back":"Amounts customers owe a business for goods or services delivered on credit, usually due within 30 to 60 days and without interest. Called trade receivables under IFRS.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:accrual","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Accrual","back":"A timing difference in which revenue or an expense is recognised before the cash is received or paid. Meanwhile the amount is a receivable or a payable.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:accrual basi","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Accrual basis","back":"A way of keeping accounts that records revenue when it is earned and expenses when they are incurred, whenever the cash is received or paid. Financial statements under US GAAP and IFRS use it.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:accrued expense","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accrued expense","back":"An expense incurred in the period but not yet paid or recorded, such as wages or interest owed. It is recorded with a payable.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accrued interest","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Accrued interest","back":"Interest that has built up since the last payment or crediting date but has not yet been paid or added to the balance.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:accrued liability","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Accrued liability","back":"A liability for an expense incurred but not yet paid, such as wages, interest or utilities: the balance sheet side of an accrued expense.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:accrued revenue","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accrued revenue","back":"Revenue earned in the period but not yet received or recorded, for example work done but not yet invoiced. It is recorded with a receivable.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accumulated depreciation","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accumulated depreciation","back":"All the depreciation recorded on an asset since it was acquired, held in a contra-asset account with a credit balance.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accuracy","kind":"term","course":"b01","lesson":"data-quality","front":"Accuracy","back":"Whether values correctly describe the real-world thing or event they represent.","href":"learn/analytics/b01/data-quality/"},{"id":"t:actual product","kind":"term","course":"m02","lesson":"product-decisions","front":"Actual product","back":"The features, quality level, design, brand name and packaging that deliver the core benefit.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:add-back","kind":"term","course":"f02","lesson":"indirect-method","front":"Add-back","back":"An amount added to net income in the indirect method because it reduced net income without reducing cash in the period, such as depreciation or a loss on the sale of equipment.","href":"learn/finance/f02/indirect-method/"},{"id":"t:additional paid-in capital","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Additional paid-in capital","back":"The amount shareholders paid for shares above their par or stated value. Called share premium under IFRS and in the UK.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:adjustable-rate mortgage","kind":"term","course":"f04","lesson":"mortgages","front":"Adjustable-rate mortgage","back":"A mortgage whose interest rate is fixed for an initial period and then resets at intervals to an index plus a margin, within rate caps. Often shortened to ARM.","href":"learn/finance/f04/mortgages/"},{"id":"t:adjusted ebitda","kind":"term","course":"f02","lesson":"income-statement","front":"Adjusted EBITDA","back":"A label for an EBITDA-like measure with further adjustments beyond net income plus interest, taxes, depreciation and amortisation. Its definition is the company’s own, so it must be read with its reconciliation.","href":"learn/finance/f02/income-statement/"},{"id":"t:adjusted trial balance","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Adjusted trial balance","back":"A list of every account and its balance after the adjusting entries have been posted, used to prepare the financial statements.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:adjusting entry","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Adjusting entry","back":"A journal entry made at the end of a period to bring an account up to date, so that revenue and expenses are recognised in the right period. It involves at least one income statement account and one balance sheet account, and never Cash.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:advertising","kind":"term","course":"m02","lesson":"promotion-mix","front":"Advertising","back":"Paid, non-personal communication from an identified sponsor through mass or digital media.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:affordable method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Affordable method","back":"Setting the promotion budget at whatever the business has left after its other costs and profit target.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:agency cost","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agency costs","back":"The total cost of an agency relationship: monitoring costs paid by principals, bonding costs paid by agents, and the residual loss that remains.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agency problem","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agency problem","back":"The conflict that arises when an agent’s interests differ from the principal’s and the principal cannot fully observe or control the agent’s actions.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agent","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agent","back":"In an agency relationship, the person who acts and makes decisions on behalf of a principal.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agent (in a sale)","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Agent (in a sale)","back":"In revenue recognition, a business that arranges for another party to provide a good or service. It recognises revenue at the amount of its fee or commission.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:agent or broker","kind":"term","course":"m02","lesson":"distribution-channels","front":"Agent or broker","back":"An intermediary that arranges sales for a producer in return for a commission or fee without taking ownership of the goods.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:aggregation","kind":"term","course":"b02","lesson":"transforming-data","front":"Aggregation","back":"Collapsing groups of rows into one summary row per group by applying a function such as sum, mean or count. It moves a table to a coarser granularity.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:aging of receivable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Aging of receivables","back":"A schedule that groups receivables by how long they have been outstanding and applies a higher expected loss rate to older groups, used to estimate the allowance.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:aida","kind":"term","course":"m02","lesson":"promotion-mix","front":"AIDA","back":"A response-hierarchy model in which a buyer moves through attention, interest, desire and action. Usually credited to E. St. Elmo Lewis around 1898, though the attribution is disputed.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:allowance for doubtful account","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Allowance for doubtful accounts","back":"A contra-asset account holding the estimated amount of accounts receivable that will not be collected, deducted from Accounts Receivable on the balance sheet. Also called the allowance for credit losses.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:allowance method","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Allowance method","back":"Accounting for bad debts by estimating, at each period end, the receivables not expected to be collected, recording that estimate as an expense and an allowance, and later writing off specific accounts against the allowance.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:ambiguous date","kind":"term","course":"b02","lesson":"types-and-formats","front":"Ambiguous date","back":"A date written so that its day and month could be swapped to give a different valid date, such as 04/03/2026 (4 March or 3 April).","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:amortisation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Amortisation","back":"The spreading of the cost of an intangible asset, such as purchased software or a customer contract, over the years it is used. The word is also used for the gradual repayment of a loan’s principal.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:amortisation schedule","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Amortisation schedule","back":"A table showing, for each payment on a loan, the interest, the principal repaid and the balance still owed.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:amortising loan","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Amortising loan","back":"A loan repaid by regular payments that each cover the interest due and repay part of the principal, so the balance falls to zero by the last payment.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:analysis toolpak","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Analysis ToolPak","back":"An Excel add-in, loaded from File &gt; Options &gt; Add-ins, that adds statistical tools (Descriptive Statistics, Histogram, Correlation, Regression and others) under Data &gt; Data Analysis. Most tools, including Descriptive Statistics and Regression, write values rather than formulas, so their reports don’t update when the data change.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Analytics","back":"The scientific process of transforming data into insight for making better decisions (the definition INFORMS published in 2012).","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:analytics process","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Analytics process","back":"The five steps of an analysis used in this course: question, data, analysis, decision and measure, repeated as each measured result raises the next question.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:anchoring","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Anchoring","back":"The tendency for an estimate of an uncertain value, such as what a price should be, to be pulled towards a number seen first, even an irrelevant one (Tversky and Kahneman, 1974).","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:annual percentage yield","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Annual percentage yield","back":"The rate US banks disclose on deposit accounts under the Truth in Savings rules, reflecting the total interest paid on the account including compounding. An effective annual rate. Often shortened to APY.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:annual report","kind":"term","course":"f02","lesson":"linking-the-statements","front":"Annual report","back":"The document a business issues after its financial year: the financial statements and their notes, and, for larger companies, management’s commentary and the auditor’s report.","href":"learn/finance/f02/linking-the-statements/"},{"id":"t:annuity","kind":"term","course":"f04","lesson":"annuities","front":"Annuity","back":"A series of equal payments made at equal intervals for a fixed number of periods, such as loan instalments, rent or a regular savings deposit. Also the name of an insurance product that pays an income.","href":"learn/finance/f04/annuities/"},{"id":"t:annuity due","kind":"term","course":"f04","lesson":"annuities","front":"Annuity due","back":"An annuity whose payments are made at the start of each period, so the first payment is made now. Worth an ordinary annuity × (1 + r).","href":"learn/finance/f04/annuities/"},{"id":"t:annuity factor","kind":"term","course":"f04","lesson":"annuities","front":"Annuity factor","back":"The present value of $1 a period for n periods at rate r: [1 − (1 + r)^−n] ÷ r. Multiplied by the payment, it gives the present value of an ordinary annuity.","href":"learn/finance/f04/annuities/"},{"id":"t:approval limit","kind":"term","course":"m01","lesson":"business-buying","front":"Approval limit","back":"The largest amount a person may commit their organisation to on their own authority; larger purchases need approval from someone more senior or a committee.","href":"learn/marketing/m01/business-buying/"},{"id":"t:approved supplier list","kind":"term","course":"m01","lesson":"business-buying","front":"Approved supplier list","back":"The suppliers an organisation has vetted and allows its staff to buy from; a new supplier must usually be approved before it can be used.","href":"learn/marketing/m01/business-buying/"},{"id":"t:approximate match","kind":"term","course":"b03","lesson":"lookups","front":"Approximate match","back":"A lookup that, when no key equals the lookup value, returns the row of the largest key below it (or, in some modes, the smallest key above it); used with band tables sorted by their lower bounds.","href":"learn/analytics/b03/lookups/"},{"id":"t:apr","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"APR","back":"Annual percentage rate. In its simple sense, a periodic rate multiplied by the number of periods in a year, ignoring compounding; a US credit card’s APR is calculated this way. For closed-end US consumer loans, such as mortgages and car loans, the disclosed APR is broader and also reflects certain fees.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:arbitrage","kind":"term","course":"f00","lesson":"decision-principles","front":"Arbitrage","back":"Buying and selling the same, or equivalent, cash flows at the same time for different prices, making a profit with no risk and none of one’s own money.","href":"learn/finance/f00/decision-principles/"},{"id":"t:argument","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Argument","back":"A value, reference, range or expression given to a function inside its parentheses, such as the range in SUM(J2:J232).","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:articulation","kind":"term","course":"f01","lesson":"financial-statements","front":"Articulation","back":"The links between the financial statements: net income flows into equity, ending equity into the balance sheet, and ending cash from the statement of cash flows into the balance sheet.","href":"learn/finance/f01/financial-statements/"},{"id":"t:ask","kind":"term","course":"f00","lesson":"market-participants","front":"Ask","back":"The price at which a dealer will sell a security; also called the offer.","href":"learn/finance/f00/market-participants/"},{"id":"t:asset","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Asset","back":"A resource the business controls as a result of past events and that is expected to bring it economic benefits. The FASB defines it as a present right of an entity to an economic benefit.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:attitude","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Attitude","back":"A person’s lasting evaluation of an object or idea, such as a brand, with the feelings and tendency to act that go with it.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:attribution","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Attribution","back":"Rules for dividing credit for a conversion among the marketing touchpoints that preceded it, such as last click, first click, linear or data-driven.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:audit","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Audit","back":"An independent examination of financial statements, after which the auditor gives an opinion on whether they are presented fairly, in all material respects, in accordance with the applicable financial reporting framework.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:augmented product","kind":"term","course":"m02","lesson":"product-decisions","front":"Augmented product","back":"The additional services and benefits offered with the actual product, such as guarantees, installation, support and loyalty schemes.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:authorised share","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Authorised shares","back":"The maximum number of shares of a class that a corporation’s charter allows it to issue.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:average annual inflation rate","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Average annual inflation rate","back":"The constant yearly inflation rate that would produce the same cumulative inflation over n years: (end index ÷ start index)^(1/n) − 1.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:average order value","kind":"term","course":"b01","lesson":"kpis","front":"Average order value","back":"Revenue divided by the number of orders in a period: the mean value of an order. Abbreviated AOV.","href":"learn/analytics/b01/kpis/"},{"id":"t:bad debt expense","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Bad debt expense","back":"The expense for credit sales a business does not expect to collect. Also called credit loss expense or uncollectible accounts expense.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:balance sheet","kind":"term","course":"f01","lesson":"financial-statements","front":"Balance sheet","back":"The statement of assets, liabilities and equity at a point in time. Called the statement of financial position under IFRS.","href":"learn/finance/f01/financial-statements/"},{"id":"t:balance-column account","kind":"term","course":"f01","lesson":"general-ledger","front":"Balance-column account","back":"A ledger account laid out with date, explanation, reference, debit, credit and balance columns, showing the balance after every posting. Also called a running-balance or three-column account.","href":"learn/finance/f01/general-ledger/"},{"id":"t:balanced scorecard","kind":"term","course":"b01","lesson":"kpis","front":"Balanced scorecard","back":"A set of measures proposed by Kaplan and Norton (1992) that adds customer, internal-process and innovation-and-learning perspectives to financial measures.","href":"learn/analytics/b01/kpis/"},{"id":"t:balloon payment","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Balloon payment","back":"A large final payment that repays all or most of a loan’s principal at maturity, as on an interest-only loan.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:bank run","kind":"term","course":"f00","lesson":"market-participants","front":"Bank run","back":"A rush by many depositors to withdraw their money at once, which can bring down even a sound bank because its loans cannot be turned into cash quickly.","href":"learn/finance/f00/market-participants/"},{"id":"t:base effect","kind":"term","course":"b01","lesson":"summarising-data","front":"Base effect","back":"A large percentage change produced mainly by a small or unusual starting value rather than by a large change in the quantity itself.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:base period","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Base period","back":"The date or period whose prices serve as the yardstick for real amounts; a price index is often set to 100 in it.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:baseline","kind":"term","course":"b01","lesson":"business-questions","front":"Baseline","back":"The value a result is compared with to judge whether anything changed, such as the previous period, the same period last year, a target, a comparison group or a forecast.","href":"learn/analytics/b01/business-questions/"},{"id":"t:basic earnings per share","kind":"term","course":"f02","lesson":"income-statement","front":"Basic earnings per share","back":"Net income less preferred dividends, divided by the weighted average number of common shares outstanding in the period.","href":"learn/finance/f02/income-statement/"},{"id":"t:bid","kind":"term","course":"f00","lesson":"market-participants","front":"Bid","back":"The price at which a dealer will buy a security.","href":"learn/finance/f00/market-participants/"},{"id":"t:bid-ask spread","kind":"term","course":"f00","lesson":"market-participants","front":"Bid-ask spread","back":"The ask minus the bid: the cost of buying and immediately selling, and the dealer’s gross reward for providing liquidity.","href":"learn/finance/f00/market-participants/"},{"id":"t:bin","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Bin","back":"One of the intervals a numeric range is divided into for counting. Excel counts a value in a bin when it is above the bin’s lower edge and no more than its upper edge.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:binding constraint","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Binding constraint","back":"A constraint that holds exactly at the optimum, so that the resource it describes is used up; relaxing it could improve the objective.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:binning","kind":"term","course":"b02","lesson":"transforming-data","front":"Binning","back":"Replacing a numeric value with the interval (bin) it falls in. Bin edges can be equal-width, equal-frequency (quantiles) or set by a business rule.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:board of director","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Board of directors","back":"The group elected by a corporation’s shareholders to oversee management: hiring and paying the chief executive, approving strategy and dividends, and overseeing financial reporting.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:bond","kind":"term","course":"f00","lesson":"financial-markets","front":"Bond","back":"A debt security that promises interest and repayment of the amount borrowed on stated dates; its holder is a lender to the issuer.","href":"learn/finance/f00/financial-markets/"},{"id":"t:bond market","kind":"term","course":"f00","lesson":"financial-markets","front":"Bond market","back":"The market for debt securities issued by governments, companies and other bodies.","href":"learn/finance/f00/financial-markets/"},{"id":"t:book value","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Book value","back":"An asset’s cost minus its accumulated depreciation; called the carrying amount under IFRS.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:book value of equity","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Book value of equity","back":"Shareholders’ equity as recorded in the balance sheet: total assets minus total liabilities, measured by the accounting rules.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:box and whisker chart","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Box and whisker chart","back":"A chart of a distribution that draws the first and third quartiles as a box with the median inside it, whiskers for the spread beyond the box, a marker for the mean, and separate points for outliers. Also called a box plot.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:box–cox transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Box–Cox transformation","back":"The power transformation (x^λ − 1) ÷ λ, or ln x when λ = 0, with λ estimated from strictly positive data to make them as close to normal as possible.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:brand","kind":"term","course":"m02","lesson":"product-decisions","front":"Brand","back":"A name, term, sign, symbol or design, or a combination of them, that identifies a seller’s product and distinguishes it from competitors’.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:break-even inflation rate","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Break-even inflation rate","back":"The inflation rate at which an inflation-protected bond and an ordinary bond of the same term give the same return: (1 + nominal yield) ÷ (1 + real yield) − 1.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:break-even point","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Break-even point","back":"The volume (or revenue) at which total contribution equals fixed costs, so profit is zero: fixed costs ÷ contribution margin per unit.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:break-even roa","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Break-even ROAS","back":"The ROAS at which a campaign’s contribution just covers its cost: 1 ÷ the contribution margin ratio.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:broker","kind":"term","course":"f00","lesson":"market-participants","front":"Broker","back":"A firm that arranges trades for clients as their agent, without owning the securities, and is paid a commission or fee.","href":"learn/finance/f00/market-participants/"},{"id":"t:bundling","kind":"term","course":"m02","lesson":"price-response","front":"Bundling","back":"Selling two or more products together for one price, usually less than the sum of their separate prices. Pure bundling sells only the bundle; mixed bundling also sells the items separately.","href":"learn/marketing/m02/price-response/"},{"id":"t:business analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Business analytics","back":"Analytics applied to the decisions of a business, such as what to sell, at what price, to whom, through which channel and with how much stock.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:business buying process","kind":"term","course":"m01","lesson":"business-buying","front":"Business buying process","back":"The stages of an organisational purchase: problem recognition, general need description, product specification, supplier search, proposal solicitation, supplier selection, order-routine specification and performance review.","href":"learn/marketing/m01/business-buying/"},{"id":"t:business goal","kind":"term","course":"m01","lesson":"marketing-objectives","front":"Business goal","back":"What a business as a whole aims to achieve, usually in money or size, such as more revenue, more profit or a larger market share.","href":"learn/marketing/m01/marketing-objectives/"},{"id":"t:business key","kind":"term","course":"b02","lesson":"duplicates","front":"Business key","back":"The column or columns that identify one real-world thing in the business’s own terms, such as an order number or booking reference.","href":"learn/analytics/b02/duplicates/"},{"id":"t:business market","kind":"term","course":"m01","lesson":"business-buying","front":"Business market","back":"The organisations that buy goods and services to produce other products, to run their operations or to resell: businesses, resellers, governments and institutions.","href":"learn/marketing/m01/business-buying/"},{"id":"t:business-to-business","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Business-to-business","back":"Marketing to organisations that buy for their own operations or to resell. Abbreviated B2B.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:business-to-consumer","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Business-to-consumer","back":"Marketing to individuals and households who buy for their own use. Abbreviated B2C.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:buyer (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"Buyer (buying centre)","back":"In a buying centre, the person with formal responsibility for dealing with suppliers and arranging the terms of the purchase.","href":"learn/marketing/m01/business-buying/"},{"id":"t:buying centre","kind":"term","course":"m01","lesson":"business-buying","front":"Buying centre","back":"All the people in an organisation who take part in a purchase decision, each in one or more roles; also called the decision-making unit.","href":"learn/marketing/m01/business-buying/"},{"id":"t:buying decision process","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Buying decision process","back":"The five stages a consumer goes through in a considered purchase: need recognition, information search, evaluation of alternatives, purchase decision and post-purchase behaviour. Routine purchases skip stages.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:calculated column","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Calculated column","back":"A column of an Excel table filled by one formula, which Excel copies to every row, including rows added later.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Capital","back":"In finance, the money supplied to a business by investors, as debt or equity, to buy the assets it needs. The assets themselves (machines, buildings) are sometimes called physical capital.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:capital budgeting","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Capital budgeting","back":"The process a firm uses to decide which long-term investments are worth making, by comparing what they cost with the value of what they are expected to return.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:capital market","kind":"term","course":"f00","lesson":"financial-markets","front":"Capital market","back":"The market for long-term finance: debt maturing in more than a year, and shares.","href":"learn/finance/f00/financial-markets/"},{"id":"t:capital structure","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Capital structure","back":"The mix of debt and equity a business uses to finance its assets.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:capitalise","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Capitalise","back":"To record a cost as an asset, because it will bring benefits beyond the current period, rather than as an expense of the period.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:case normalisation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Case normalisation","back":"Converting text to a single case, usually lower case, so that values differing only in capitals compare as equal.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:cash basi","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Cash basis","back":"A way of keeping accounts that records revenue when cash is received and expenses when cash is paid.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:cash equivalent","kind":"term","course":"f02","lesson":"cash-flow-statement","front":"Cash equivalents","back":"Short-term, highly liquid investments that are readily convertible to known amounts of cash and so near maturity that changes in interest rates barely affect their value: generally those with a maturity of three months or less when acquired, such as Treasury bills and money market funds.","href":"learn/finance/f02/cash-flow-statement/"},{"id":"t:cash flow","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Cash flow","back":"Cash received or paid out by a person or business over a period, or expected to be received or paid as a result of a decision.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:cash-flow stream","kind":"term","course":"f04","lesson":"discounting-cash-flows","front":"Cash-flow stream","back":"A series of cash flows due at different dates. An even stream (equal amounts at equal intervals for a fixed number of periods) is an annuity; an uneven one is valued by discounting each cash flow separately.","href":"learn/finance/f04/discounting-cash-flows/"},{"id":"t:cash-flow timeline","kind":"term","course":"f04","lesson":"present-and-future-value","front":"Cash-flow timeline","back":"A line marked off in equal periods, with time 0 at the valuation date and each cash flow written at the date it occurs, used to set up time-value problems.","href":"learn/finance/f04/present-and-future-value/"},{"id":"t:categorical encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Categorical encoding","back":"Converting the labels of a categorical variable into numbers that a model can use.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:categorical variable","kind":"term","course":"b01","lesson":"data-types","front":"Categorical variable","back":"A variable whose values place each observation in a group, such as channel, product or a survey answer. It is nominal or ordinal.","href":"learn/analytics/b01/data-types/"},{"id":"t:category axi","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Category axis","back":"The axis of a column, bar or line chart that places text labels at equal spacing whatever they say, or dates in time order (a date axis); numbers placed on it are treated as labels.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:category consolidation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Category consolidation","back":"Merging the variants of a categorical value into the values of a controlled vocabulary, which changes the counts and statistics of each category.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:causation","kind":"term","course":"b01","lesson":"interpreting-results","front":"Causation","back":"A relationship in which changing one quantity would change another.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:cell range","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Cell range","back":"A rectangle of cells written as its top-left and bottom-right cells joined by a colon, such as B2:D9; a whole column is written F:F.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:cell reference","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Cell reference","back":"The address of a cell, its column letter followed by its row number (such as F2), used in a formula to read that cell’s value.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:censu","kind":"term","course":"b01","lesson":"data-collection","front":"Census","back":"A study that observes every member of the population, rather than a sample.","href":"learn/analytics/b01/data-collection/"},{"id":"t:certified public accountant","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Certified public accountant","back":"In the United States, an accountant licensed by a state board of accountancy after passing a national exam and meeting the state’s requirements. Often shortened to CPA.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:cfo","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"CFO","back":"Chief financial officer: the senior executive responsible for a company’s financial decisions, including investment, financing and working capital, and for its financial reporting.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:change in accounting estimate","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Change in accounting estimate","back":"A revision of an estimate, such as an asset’s useful life or residual value, because of new information. It is applied from the period of the change onward, without restating earlier periods.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:channel conflict","kind":"term","course":"m02","lesson":"distribution-channels","front":"Channel conflict","back":"Disagreement between members of a marketing channel that gets in the way of the channel working. Vertical conflict is between levels; horizontal conflict is between members at the same level.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:channel level","kind":"term","course":"m02","lesson":"distribution-channels","front":"Channel level","back":"One layer of intermediaries between the producer and the final customer. A direct channel has zero levels.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:chart of account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Chart of accounts","back":"The list of all the accounts a business uses, each with a name and usually a number, arranged by type.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:churn rate","kind":"term","course":"m01","lesson":"customer-value","front":"Churn rate","back":"The share of customers at the start of a period who have stopped buying by its end: 1 minus the retention rate.","href":"learn/marketing/m01/customer-value/"},{"id":"t:circular reference","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Circular reference","back":"A formula that refers to its own cell, directly or through other formulas.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:classified balance sheet","kind":"term","course":"f01","lesson":"financial-statements","front":"Classified balance sheet","back":"A balance sheet that groups assets and liabilities into current and noncurrent categories.","href":"learn/finance/f01/financial-statements/"},{"id":"t:cleaning log","kind":"term","course":"b02","lesson":"data-quality-report","front":"Cleaning log","back":"The ordered record of every cleaning step: what was done, to which rows and columns, by what rule, and the row count afterwards.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:client concentration","kind":"term","course":"b03","lesson":"dashboards","front":"Client concentration","back":"The share of revenue that comes from a business’s largest few clients; a high share means the loss of one client would hurt badly.","href":"learn/analytics/b03/dashboards/"},{"id":"t:closing entry","kind":"term","course":"f01","lesson":"closing-entries","front":"Closing entries","back":"Journal entries made at the end of an accounting period that transfer the balances of the revenue, expense and dividend accounts to Retained Earnings, leaving those accounts at zero.","href":"learn/finance/f01/closing-entries/"},{"id":"t:code point","kind":"term","course":"b02","lesson":"text-and-categories","front":"Code point","back":"The number the Unicode standard assigns to a character, written in the form U+00E9.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:colour scale","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Colour scale","back":"A conditional format that shades cells along a gradient of two or three colours between the lowest and highest values.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:combo chart","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Combo chart","back":"A chart that combines two or more chart types, such as columns and a line, often with a secondary axis.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:commercial bank","kind":"term","course":"f00","lesson":"market-participants","front":"Commercial bank","back":"A bank that takes deposits, makes loans and provides payment services to households and firms.","href":"learn/finance/f00/market-participants/"},{"id":"t:commodity market","kind":"term","course":"f00","lesson":"financial-markets","front":"Commodity market","back":"The market for raw materials such as oil, metals and crops, traded for immediate delivery (spot) or through futures contracts.","href":"learn/finance/f00/financial-markets/"},{"id":"t:common stock","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Common stock","back":"The equity account that records what shareholders have paid the corporation in exchange for its common shares (share capital under IFRS). Some companies split this amount between the shares’ par value and additional paid-in capital, a detail later courses cover.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:comparison date","kind":"term","course":"f04","lesson":"present-and-future-value","front":"Comparison date","back":"The single date to which amounts due at different dates are moved, by compounding or discounting, before they are compared or added. Also called the focal date.","href":"learn/finance/f04/present-and-future-value/"},{"id":"t:comparison group","kind":"term","course":"b01","lesson":"interpreting-results","front":"Comparison group","back":"A group that did not get a change, used to estimate what would probably have happened to the affected group without it.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:compensating error","kind":"term","course":"f01","lesson":"trial-balance","front":"Compensating error","back":"Two or more errors whose effects on the debit and credit totals cancel out, so the trial balance still balances.","href":"learn/finance/f01/trial-balance/"},{"id":"t:competition-based pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Competition-based pricing","back":"Setting a price mainly from competitors’ prices: charging the going rate in markets for similar products, or bidding against expected rival bids in sealed-bid contracts.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:competitive advantage","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Competitive advantage","back":"Whatever lets a business attract customers or earn profits better than its rivals; in value terms, creating a wider gap than rivals between customers’ willingness to pay and the cost of serving them. It may be temporary or sustained.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:competitive-parity method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Competitive-parity method","back":"Setting the promotion budget to match competitors’ spending, in dollars or relative to sales.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:competitor analysi","kind":"term","course":"m01","lesson":"situation-analysis","front":"Competitor analysis","back":"Identifying the firms and other options customers could choose instead, and studying their offers, prices, strengths, weaknesses and likely responses.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:competitor orientation","kind":"term","course":"m01","lesson":"market-orientation","front":"Competitor orientation","back":"Understanding what current and potential competitors can and are likely to do; one of Narver and Slater’s three components of market orientation.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:completeness","kind":"term","course":"b01","lesson":"data-quality","front":"Completeness","back":"The proportion of values present out of those that should be present.","href":"learn/analytics/b01/data-quality/"},{"id":"t:complex buying behaviour","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Complex buying behaviour","back":"Buying with high involvement among brands that differ significantly: extensive search and careful evaluation.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:component depreciation","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Component depreciation","back":"Depreciating separately each significant part of an asset that has a different useful life, such as a building’s structure, roof and lifts. Required by IAS 16; acceptable but not required under US GAAP.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:composite key","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Composite key","back":"A primary key made of two or more columns, such as order_id and line together in a line-item report.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:compound annual growth rate","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Compound annual growth rate","back":"The constant yearly rate that takes a starting value to an ending value over a number of years: (end ÷ start)^(1/years) − 1. Often shortened to CAGR.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:compound entry","kind":"term","course":"f01","lesson":"journal-entries","front":"Compound entry","back":"A journal entry with more than one debit, more than one credit, or both. Its debit total still equals its credit total.","href":"learn/finance/f01/journal-entries/"},{"id":"t:compound growth rate","kind":"term","course":"b01","lesson":"summarising-data","front":"Compound growth rate","back":"The constant rate per period that takes a starting value to an ending value over n periods: (end ÷ start)^(1/n) − 1. Over years it is the compound annual growth rate.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:compound interest","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Compound interest","back":"Interest calculated on the principal and on interest already added to the balance, so the balance grows by the same percentage each period.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:compounding","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Compounding","back":"Earning interest on interest already earned, because each period’s interest is added to the balance and earns interest in later periods.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:compounding frequency","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Compounding frequency","back":"How many times a year interest is calculated and added to the balance: annually, semi-annually, quarterly, monthly or daily.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:concatenation","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Concatenation","back":"Joining pieces of text into one, with the & operator or a function such as CONCAT or TEXTJOIN.","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:conceptual framework","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Conceptual framework","back":"A coherent set of concepts underlying accounting standards: the objective of financial reporting, the qualities that make information useful, and the definition, recognition and measurement of the elements of financial statements.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:conditional aggregate","kind":"term","course":"b03","lesson":"conditional-sums-and-counts","front":"Conditional aggregate","back":"A sum, count, average, maximum or minimum taken over only the rows of a table that meet one or more conditions.","href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"t:conditional formatting","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Conditional formatting","back":"Formatting that a spreadsheet applies to a cell only while a rule about its value, or a formula, is true, and that updates when the values change.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:confounding variable","kind":"term","course":"b01","lesson":"interpreting-results","front":"Confounding variable","back":"A third variable that affects both of two quantities being compared, making them move together, or apart, without either causing the other. Also called a confounder.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:consent","kind":"term","course":"b01","lesson":"data-collection","front":"Consent","back":"Under the UK GDPR, a freely given, specific, informed and unambiguous indication of a person’s wishes, by a statement or a clear affirmative action, agreeing to the use of their personal data. It can be withdrawn at any time.","href":"learn/analytics/b01/data-collection/"},{"id":"t:consideration set","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Consideration set","back":"The options a buyer seriously considers when choosing, a subset of the options they know about; also called the evoked set.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:consistency","kind":"term","course":"b01","lesson":"data-quality","front":"Consistency","back":"Whether the same thing is represented the same way wherever it appears, within a dataset and across datasets.","href":"learn/analytics/b01/data-quality/"},{"id":"t:constraint","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Constraint","back":"A limit that every solution of an optimisation model must respect, written as a formula compared with a bound by ≤, = or ≥, such as hours used ≤ hours available.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:consumer","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Consumer","back":"The person who uses an offering, who may or may not be the customer who chose and paid for it.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:consumer price index","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Consumer Price Index","back":"The best-known US price index, published by the Bureau of Labor Statistics: a measure of the average change over time in the prices urban consumers pay for a basket of goods and services. Often shortened to CPI.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:continuous compounding","kind":"term","course":"f04","lesson":"effective-annual-rates","front":"Continuous compounding","back":"The limit of compounding ever more often. A nominal rate compounded continuously grows an amount by the factor e^(rate × years), an effective annual rate of e^rate − 1.","href":"learn/finance/f04/effective-annual-rates/"},{"id":"t:continuous variable","kind":"term","course":"b01","lesson":"data-types","front":"Continuous variable","back":"A numerical variable that can take any value within a range, at least in principle, usually a measurement such as weight or time.","href":"learn/analytics/b01/data-types/"},{"id":"t:contra account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Contra account","back":"An account paired with another account whose balance it reduces, such as Accumulated Depreciation—Equipment, which reduces Equipment. The two are reported together.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:contra-revenue account","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Contra-revenue account","back":"An account with a normal debit balance that reduces revenue on the income statement, such as Sales Returns and Allowances or Sales Discounts.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:contract asset","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Contract asset","back":"A business’s right to payment for goods or services it has already transferred, when that right depends on something other than the passage of time, such as its own further performance. When only time stands in the way, the right is a receivable instead.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:contract liability","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Contract liability","back":"A business’s obligation to transfer goods or services to a customer from whom it has received payment, or from whom payment is due. In the ledger it is usually called unearned or deferred revenue.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:contrast ratio","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Contrast ratio","back":"A measure of the difference in brightness between two colours, (L₁ + 0.05) ÷ (L₂ + 0.05), where L₁ and L₂ are the relative luminances of the lighter and darker colour; it runs from 1:1 to 21:1.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:contributed capital","kind":"term","course":"f01","lesson":"accounting-equation","front":"Contributed capital","back":"Equity supplied by owners in exchange for shares, recorded in Common Stock (share capital under IFRS).","href":"learn/finance/f01/accounting-equation/"},{"id":"t:contribution margin","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Contribution margin","back":"Price received minus variable cost per unit: what each unit contributes towards fixed costs and then profit. As a share of price it is the contribution margin ratio.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:control","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Control","back":"In revenue recognition, the customer’s ability to direct the use of a good or service and obtain substantially all of its remaining benefits. Revenue is recognised when control transfers.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:control account","kind":"term","course":"f01","lesson":"general-ledger","front":"Control account","back":"A general-ledger account whose balance must equal the total of a subsidiary ledger, such as Accounts Receivable for the customer accounts.","href":"learn/finance/f01/general-ledger/"},{"id":"t:control group","kind":"term","course":"b01","lesson":"data-collection","front":"Control group","back":"In an experiment, the group that receives the existing version or no change, against which the changed group is compared.","href":"learn/analytics/b01/data-collection/"},{"id":"t:controlled vocabulary","kind":"term","course":"b02","lesson":"text-and-categories","front":"Controlled vocabulary","back":"The agreed list of allowed values for a column, usually set in the data dictionary or by an outside standard.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:controller","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Controller","back":"The manager responsible for a company’s accounting, financial reporting and internal controls.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:convenience product","kind":"term","course":"m02","lesson":"product-decisions","front":"Convenience product","back":"A consumer product bought often and quickly, with little comparison, usually at a low price and from many outlets.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:convenience sample","kind":"term","course":"b01","lesson":"data-collection","front":"Convenience sample","back":"A sample made up of whoever is easiest to reach, such as the first replies to a link. It is not random and is often biased.","href":"learn/analytics/b01/data-collection/"},{"id":"t:convergence","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Convergence","back":"The effort by the FASB and the IASB, formalised in the 2002 Norwalk Agreement, to remove differences between US GAAP and IFRS and to coordinate their future standards.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:conversion rate","kind":"term","course":"b01","lesson":"kpis","front":"Conversion rate","back":"The percentage of visits, or of ad clicks, that end in a chosen action such as an order or a sign-up. Which denominator is used varies between tools and reports, so always state it.","href":"learn/analytics/b01/kpis/"},{"id":"t:core benefit","kind":"term","course":"m02","lesson":"product-decisions","front":"Core benefit","back":"The underlying need a customer satisfies by buying a product; what the customer is really buying.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:corporate finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Corporate finance","back":"The branch of finance concerned with the decisions of businesses: which investments to make, how to pay for them and how to manage day-to-day cash. Also called business finance.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:correcting entry","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Correcting entry","back":"A journal entry that fixes an error in an entry already posted, by recording the difference between what was recorded and what should have been.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:correlated","kind":"term","course":"b01","lesson":"interpreting-results","front":"Correlated","back":"Describes two quantities that tend to move together, so that high values of one tend to go with high (or low) values of the other. Correlation alone does not show that one causes the other.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:correlation coefficient","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Correlation coefficient","back":"Pearson’s r: a number from −1 to +1 that measures how closely two numeric variables follow a straight line, positive when they rise together. Excel’s CORREL.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:cost leadership","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Cost leadership","back":"A generic strategy of achieving the lowest cost of serving customers in an industry, so that the business can charge lower prices or earn higher margins than its rivals.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:cost of capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Cost of capital","back":"The return that the suppliers of a business’s capital expect, and so the return the business must be expected to earn to keep their money. For debt it is close to the interest rate; for equity it is the return shareholders could expect elsewhere for a similar risk.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:cost of goods sold","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Cost of goods sold","back":"The cost of the inventory sold in a period, recognised as an expense in the period the related revenue is recognised. Often shortened to COGS.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:cost of sale","kind":"term","course":"f02","lesson":"income-statement","front":"Cost of sales","back":"The direct cost of the goods and services sold in a period: cost of goods sold, plus cost of services for a business that sells services.","href":"learn/finance/f02/income-statement/"},{"id":"t:cost of service","kind":"term","course":"f02","lesson":"income-statement","front":"Cost of services","back":"The direct costs of providing services sold, such as the wages of staff who deliver them and the materials they use.","href":"learn/finance/f02/income-statement/"},{"id":"t:cost-plus pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Cost-plus pricing","back":"Setting a price by adding a markup, a fixed percentage of the unit cost, to that cost.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:covenant","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Covenants","back":"Promises written into a loan or bond agreement that restrict what the borrower may do or require it to meet conditions, such as a minimum current ratio or limits on dividends and further borrowing.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:cpa","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CPA","back":"Cost per acquisition (or per action): spend ÷ conversions.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:cpc","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CPC","back":"Cost per click: spend ÷ clicks.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:cpm","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CPM","back":"Cost per thousand impressions: spend ÷ impressions × 1,000.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:credit","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Credit","back":"The right side of an account, or an amount entered there (abbreviated Cr). A credit increases liabilities, equity and revenue and decreases assets, expenses and dividends.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:credit term","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Credit terms","back":"The conditions of a sale on credit: when payment is due and any discount for paying early. “n/30” means the full amount is due within 30 days; “2/10, n/30” offers 2% off for payment within 10 days.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:crisp-dm","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"CRISP-DM","back":"The Cross-Industry Standard Process for Data Mining: a six-phase method for analytics projects (business understanding, data understanding, data preparation, modelling, evaluation and deployment), published as version 1.0 in 2000.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:criteria range","kind":"term","course":"b03","lesson":"conditional-sums-and-counts","front":"Criteria range","back":"The range of cells that a criterion is tested against, row by row, in functions such as SUMIFS and COUNTIFS.","href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"t:criterion","kind":"term","course":"b03","lesson":"conditional-sums-and-counts","front":"Criterion","back":"A condition used by a function such as SUMIFS or COUNTIFS to decide which rows to include, such as \"web\", \"›=50\" or \"›=\"&K1; plural criteria.","href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"t:cross-field check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Cross-field check","back":"A validation rule that tests a relationship between values in the same row, such as check-out falling after check-in.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:cross-sectional data","kind":"term","course":"b01","lesson":"data-types","front":"Cross-sectional data","back":"Data on many units at one point or in one period of time, such as every respondent’s answers to one survey.","href":"learn/analytics/b01/data-types/"},{"id":"t:ctr","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CTR","back":"Click-through rate: clicks ÷ impressions.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:culture","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Culture","back":"The values, ideas and attitudes that members of a group learn and share, which shape what they need, want and regard as normal.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:cumulative inflation","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Cumulative inflation","back":"The total percentage rise in prices over an interval of several periods: the end index level divided by the start level, minus 1.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:current asset","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current asset","back":"Cash, or an asset expected to be turned into cash, sold or used up within one year or the operating cycle, whichever is longer, such as receivables, inventory and prepayments.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:current liability","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current liability","back":"An obligation expected to be settled within one year or the operating cycle, whichever is longer, usually out of current assets, such as amounts owed to suppliers, wages, taxes and loan repayments due within the year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:current portion of long-term debt","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Current portion of long-term debt","back":"The part of a long-term loan’s principal that is due within one year (or the operating cycle) after the balance sheet date, shown as a current liability; the rest remains noncurrent.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:current ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current ratio","back":"Current assets divided by current liabilities: how many dollars of current assets a firm holds for each dollar it must pay within the year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:customer","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Customer","back":"The person or organisation that chooses and pays for an offering. The customer is not always the consumer who uses it.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:customer acquisition cost","kind":"term","course":"m01","lesson":"customer-value","front":"Customer acquisition cost","back":"Marketing and sales spending on winning new customers in a period, divided by the number of new customers won. Abbreviated CAC.","href":"learn/marketing/m01/customer-value/"},{"id":"t:customer equity","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Customer equity","back":"The potential profit a business can earn from its current and potential customers.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:customer journey","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Customer journey","back":"The whole sequence of touchpoints and decisions a customer goes through, from first noticing a need to the experience after the purchase.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:customer lifetime value","kind":"term","course":"m01","lesson":"customer-value","front":"Customer lifetime value","back":"The present value of the margins a customer is expected to bring in over the whole relationship. Abbreviated CLV.","href":"learn/marketing/m01/customer-value/"},{"id":"t:customer loyalty","kind":"term","course":"m01","lesson":"customer-value","front":"Customer loyalty","back":"A customer’s tendency to keep buying from a business (behavioural loyalty) and to prefer and recommend it (attitudinal loyalty).","href":"learn/marketing/m01/customer-value/"},{"id":"t:customer orientation","kind":"term","course":"m01","lesson":"market-orientation","front":"Customer orientation","back":"Understanding target customers well enough to keep creating value for them; one of Narver and Slater’s three components of market orientation.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:customer satisfaction","kind":"term","course":"m01","lesson":"customer-value","front":"Customer satisfaction","back":"The customer’s judgement, after buying, of how well an offer performed compared with what they expected.","href":"learn/marketing/m01/customer-value/"},{"id":"t:customer value","kind":"term","course":"m01","lesson":"customer-value","front":"Customer value","back":"The customer’s judgement of the benefits of an offer relative to its total cost in money, time, effort and risk, compared with the alternatives.","href":"learn/marketing/m01/customer-value/"},{"id":"t:customer-centric","kind":"term","course":"m01","lesson":"market-orientation","front":"Customer-centric","back":"Describes an organisation built and measured around customers and their needs (for example by retention and lifetime value) rather than around its products.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:d&a","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"D&A","back":"Depreciation and amortisation: the part of the cost of long-lived physical and intangible assets charged as an expense in the period.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:dark pattern","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Dark pattern","back":"A design that steers people into choices they would not make if they understood them, such as a pre-ticked add-on or a cancellation made deliberately hard.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:dashboard","kind":"term","course":"b01","lesson":"kpis","front":"Dashboard","back":"A single screen or page showing a small set of KPIs, each with its current value, target, comparison and trend, for the people who act on them.","href":"learn/analytics/b01/kpis/"},{"id":"t:data bar","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Data bar","back":"A conditional format that draws a bar inside each cell whose length, by default, is proportional to the cell’s value.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:data dictionary","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Data dictionary","back":"A document recording, for each column of a dataset, its meaning, level of measurement, type, unit, allowed values, rule for blanks and business rules.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:data leakage","kind":"term","course":"b02","lesson":"scaling","front":"Data leakage","back":"Using information when building a model that would not be available when the model makes real predictions, such as test-set values used to fit a preparation step. It makes performance estimates too optimistic.","href":"learn/analytics/b02/scaling/"},{"id":"t:data lifecycle","kind":"term","course":"b01","lesson":"data-quality","front":"Data lifecycle","back":"The stages data passes through, from planning and collection through preparation, storage and use to sharing and finally archiving or deletion.","href":"learn/analytics/b01/data-quality/"},{"id":"t:data lineage","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data lineage","back":"The traceable path from a figure or cleaned table back through every step to the raw data and the version of the steps that produced it.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data minimisation","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data minimisation","back":"The data-protection principle that personal data should be adequate, relevant and limited to what is necessary for the purpose.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data owner","kind":"term","course":"b01","lesson":"data-quality","front":"Data owner","back":"The person accountable for a dataset: for deciding what it should contain and how it is defined, who may use it, and how its quality problems are resolved.","href":"learn/analytics/b01/data-quality/"},{"id":"t:data profiling","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Data profiling","back":"Systematically describing what a dataset contains (types, blanks, distinct values, ranges, distributions and relationships between columns) before using or changing it.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:data quality dimension","kind":"term","course":"b01","lesson":"data-quality","front":"Data quality dimension","back":"One aspect of data quality that can be assessed and measured on its own, such as completeness or validity.","href":"learn/analytics/b01/data-quality/"},{"id":"t:data quality report","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data quality report","back":"A document that travels with a cleaned dataset and records its source, its problems, the decisions taken and why, their effect on the results, the remaining limitations and how to reproduce the cleaning.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data sery","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Data series","back":"A set of related values plotted together in a chart, such as order value for each month. Each series has its own colour or marker and its own entry in the legend.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:data table","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Data table","back":"An Excel what-if tool that recalculates a formula for a list of values of one input cell, or for every combination of values of two input cells, and shows the results as a grid.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:data type","kind":"term","course":"b02","lesson":"types-and-formats","front":"Data type","back":"The kind of value a column holds (such as number, text, date and time, or boolean), which determines the operations that make sense on it.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:data validation","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Data validation","back":"An Excel feature that restricts what can be typed into cells (a list, a range of numbers or dates, a text length or a formula) and shows an input message or an error alert.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:dataset","kind":"term","course":"b01","lesson":"data-types","front":"Dataset","back":"A collection of values organised so that each value describes one characteristic of one thing; usually a table of rows and columns.","href":"learn/analytics/b01/data-types/"},{"id":"t:date of record","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Date of record","back":"The date that decides which shareholders will receive a declared dividend: those on the register that day. No journal entry is made.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:day-count convention","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Day-count convention","back":"The rule a contract or market uses to turn days into a fraction of a year for interest, such as actual/365, actual/360 or 30/360. Conventions vary between countries, markets and products.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:dealer","kind":"term","course":"f00","lesson":"market-participants","front":"Dealer","back":"A firm that trades securities with clients from its own inventory, as a principal, and earns the difference between its buying and selling prices.","href":"learn/finance/f00/market-participants/"},{"id":"t:debit","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Debit","back":"The left side of an account, or an amount entered there (abbreviated Dr). A debit increases assets, expenses and dividends and decreases liabilities, equity and revenue.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:debt","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Debt","back":"Money borrowed under a contract that promises the lender interest and repayment of the principal on stated dates. Lenders do not own the business and are paid before shareholders.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:debt-to-equity ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Debt-to-equity ratio","back":"Debt divided by shareholders’ equity, a measure of leverage. Some analysts use interest-bearing debt in the numerator, others total liabilities.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:decider (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"Decider (buying centre)","back":"In a buying centre, the person or group with the power to choose the supplier or approve the purchase.","href":"learn/marketing/m01/business-buying/"},{"id":"t:decision variable","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Decision variable","back":"A quantity the decision maker controls and an optimisation model chooses, such as the number of events to accept; in Solver, a variable cell.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:decision-focused question","kind":"term","course":"b01","lesson":"business-questions","front":"Decision-focused question","back":"A business question tied to a choice someone must make, stated so that different possible answers would lead to different actions.","href":"learn/analytics/b01/business-questions/"},{"id":"t:declaration date","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Declaration date","back":"The date a corporation’s board declares a dividend, when it becomes a liability and retained earnings are reduced.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:decline stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Decline stage","back":"The stage in which sales and profits fall, and the firm decides whether to keep, harvest or drop the product.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:deduplication","kind":"term","course":"b02","lesson":"duplicates","front":"Deduplication","back":"Finding records that describe the same thing and reducing each group to a single record, or merging them, according to stated rules.","href":"learn/analytics/b02/duplicates/"},{"id":"t:default","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Default","back":"Failure to make a promised interest or principal payment on time, which gives the lender the right to take legal action to recover what it is owed.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:default effect","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Default effect","back":"The tendency for people to stay with whichever option is pre-selected for them, so that the choice of default changes what most people end up with.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:deferral","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Deferral","back":"A timing difference in which cash is received or paid before the revenue or expense is recognised. Meanwhile the amount is a liability (unearned revenue) or an asset (prepaid expense).","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:deferred annuity","kind":"term","course":"f04","lesson":"annuities","front":"Deferred annuity","back":"An annuity whose first payment comes later than one period from now. Valued with the annuity formula one period before the first payment, then discounted to today.","href":"learn/finance/f04/annuities/"},{"id":"t:defined name","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Defined name","back":"A name given to a cell, range or value, such as Rise for the cell holding a price rise, that formulas can use instead of the reference.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:deflation","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Deflation","back":"A sustained fall in the general level of prices: negative inflation.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:demand","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Demand","back":"A want backed by the ability and the willingness to pay for it. Demand is always demand at a particular price.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:demand curve","kind":"term","course":"m02","lesson":"price-response","front":"Demand curve","back":"The quantity of a product customers would buy at each price over a period, with everything else held constant. A price change moves along it; other changes shift it.","href":"learn/marketing/m02/price-response/"},{"id":"t:depreciable amount","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Depreciable amount","back":"Cost minus residual value: the total depreciation to be recognised over an asset’s useful life.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:depreciation","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Depreciation","back":"The systematic allocation of the cost of a long-lived asset, less its residual value, over its useful life. It is an expense in the accounts but uses no cash in the period it is recorded, and it is not a measure of market value.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:derivatives market","kind":"term","course":"f00","lesson":"financial-markets","front":"Derivatives market","back":"The market for contracts (forwards, futures, options, swaps) whose value depends on the price of something else, such as a share, a rate, a currency or a commodity.","href":"learn/finance/f00/financial-markets/"},{"id":"t:derived demand","kind":"term","course":"m01","lesson":"business-buying","front":"Derived demand","back":"Demand for a product that arises from the demand for what it helps to produce, and ultimately from the demand of consumers.","href":"learn/marketing/m01/business-buying/"},{"id":"t:derived variable","kind":"term","course":"b02","lesson":"transforming-data","front":"Derived variable","back":"A new variable calculated from other variables of the same row, such as expected total = quantity × unit price − discount, or nights = check-out date − check-in date.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:descriptive analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Descriptive analytics","back":"Analytics that answers “what happened?” by summarising past data into counts, totals, averages, rates, comparisons and charts.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:diagnostic analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Diagnostic analytics","back":"Analytics that answers “why did it happen?” by breaking results into parts, comparing groups and periods, and testing possible explanations.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:difference-in-difference","kind":"term","course":"b01","lesson":"interpreting-results","front":"Difference-in-differences","back":"An estimate of an effect: the change in the affected group minus the change in a comparison group over the same period, assuming the two would otherwise have moved in parallel.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:differentiation","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Differentiation","back":"A generic strategy of being unique in ways customers value, so that they will pay a premium price.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:diluted earnings per share","kind":"term","course":"f02","lesson":"income-statement","front":"Diluted earnings per share","back":"Earnings per share recalculated as if options, convertible securities and similar instruments had been turned into common shares, when that would reduce it.","href":"learn/finance/f02/income-statement/"},{"id":"t:direct and digital marketing","kind":"term","course":"m02","lesson":"promotion-mix","front":"Direct and digital marketing","back":"Communication with targeted individuals that invites a direct response, through email, direct mail, websites, apps and targeted online ads.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:direct channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Direct channel","back":"A channel with no intermediaries: the producer sells to the final customer itself, for example through its own shops or website.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:direct finance","kind":"term","course":"f00","lesson":"financial-markets","front":"Direct finance","back":"Finance in which borrowers sell their own securities to savers, who then hold a claim on the borrower.","href":"learn/finance/f00/financial-markets/"},{"id":"t:direct method","kind":"term","course":"f02","lesson":"cash-flow-statement","front":"Direct method","back":"A way of presenting cash flows from operating activities that lists the major classes of operating receipts and payments, such as cash collected from customers and cash paid to suppliers and employees.","href":"learn/finance/f02/cash-flow-statement/"},{"id":"t:direct write-off method","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Direct write-off method","back":"Recording bad debt expense only when a specific customer’s account is found to be uncollectible. Not acceptable under US GAAP or IFRS unless the amounts are immaterial.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:discount factor","kind":"term","course":"f04","lesson":"present-and-future-value","front":"Discount factor","back":"The present value of $1 received after n periods at a rate r per period: 1 ÷ (1 + r)ⁿ. Multiplying an amount by it gives the amount’s present value.","href":"learn/finance/f04/present-and-future-value/"},{"id":"t:discount point","kind":"term","course":"f04","lesson":"mortgages","front":"Discount points","back":"Fees paid to a lender at closing in exchange for a lower interest rate; one point costs 1% of the loan amount. Often called points.","href":"learn/finance/f04/mortgages/"},{"id":"t:discount rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Discount rate","back":"The rate used to discount future amounts: the return available elsewhere on an investment of similar risk. Riskier amounts are discounted at higher rates.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:discounting","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Discounting","back":"Converting an amount to be received in the future into its value today by dividing by (1 + r) for each period of waiting.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:discrete variable","kind":"term","course":"b01","lesson":"data-types","front":"Discrete variable","back":"A numerical variable that takes separate values with gaps between them, usually a count, such as packs ordered.","href":"learn/analytics/b01/data-types/"},{"id":"t:dissonance-reducing buying behaviour","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Dissonance-reducing buying behaviour","back":"Buying with high involvement among brands that seem alike: a fairly quick choice, often followed by doubts the buyer then tries to reduce.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:distinct count","kind":"term","course":"b03","lesson":"pivot-tables","front":"Distinct count","back":"The number of different values in a field, counting each value once however many records share it, such as the number of customers rather than orders.","href":"learn/analytics/b03/pivot-tables/"},{"id":"t:distributor","kind":"term","course":"m02","lesson":"distribution-channels","front":"Distributor","back":"A wholesaler that works closely with the producers it represents, usually holding their stock and selling and delivering it to stores. The terms are often used interchangeably.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:diversification","kind":"term","course":"f00","lesson":"decision-principles","front":"Diversification","back":"Spreading money across investments whose results do not move in lockstep, so that losses on some are partly offset by gains on others.","href":"learn/finance/f00/decision-principles/"},{"id":"t:dividend","kind":"term","course":"f01","lesson":"accounting-equation","front":"Dividends","back":"Distributions of profit to a corporation’s shareholders. They reduce equity but are not an expense.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:dividends payable","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Dividends payable","back":"A current liability for dividends declared but not yet paid.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:double-declining-balance method","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Double-declining-balance method","back":"An accelerated depreciation method that charges twice the straight-line rate on the asset’s book value at the start of each year, never taking book value below the residual value.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:double-entry bookkeeping","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Double-entry bookkeeping","back":"The system of recording every transaction in at least two accounts with equal debits and credits, so that the accounting equation stays in balance.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:doubling time","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Doubling time","back":"The time an amount takes to double at a constant compound rate r per period: ln 2 ÷ ln(1 + r) periods.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:down payment","kind":"term","course":"f04","lesson":"mortgages","front":"Down payment","back":"The part of a property’s price that the buyer pays from their own funds; the mortgage finances the rest.","href":"learn/finance/f04/mortgages/"},{"id":"t:driver tree","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Driver tree","back":"An issue tree whose branches are linked by arithmetic, such as revenue = visits × conversion rate × average order value, so that a change at the top can be traced to the drivers below it.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:drop-down list","kind":"term","course":"b03","lesson":"dashboards","front":"Drop-down list","back":"A cell limited by data validation to the values in a list, which the user picks from an arrow beside the cell; in a dashboard it lets the reader choose what the formulas show.","href":"learn/analytics/b03/dashboards/"},{"id":"t:dual aspect","kind":"term","course":"f01","lesson":"accounting-equation","front":"Dual aspect","back":"The principle that every transaction affects at least two items in the accounting equation, so it stays in balance.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:dummy variable","kind":"term","course":"b02","lesson":"encoding-categories","front":"Dummy variable","back":"A 0/1 column that marks whether a row belongs to one category. With dummy coding, a variable with k categories is represented by k − 1 dummy variables plus a reference category.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:dummy-variable trap","kind":"term","course":"b02","lesson":"encoding-categories","front":"Dummy-variable trap","back":"The perfect multicollinearity that arises when all k one-hot columns of a variable are used together with an intercept, so the coefficients can’t be uniquely estimated.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:duplicate record","kind":"term","course":"b01","lesson":"data-quality","front":"Duplicate record","back":"A row that describes the same real-world entity or event as another row in the same dataset.","href":"learn/analytics/b01/data-quality/"},{"id":"t:dynamic array function","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Dynamic array function","back":"A function, such as FILTER, SORT, SORTBY or UNIQUE, that returns several values which spill into the neighbouring cells; available in Excel for Microsoft 365, Excel 2021 and Excel 2024.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:early-payment discount","kind":"term","course":"f04","lesson":"effective-annual-rates","front":"Early-payment discount","back":"A reduction in an invoice for paying before a stated date, written for example 2/10, net 30: 2% off if paid within 10 days, otherwise the full amount within 30. Also called a cash discount.","href":"learn/finance/f04/effective-annual-rates/"},{"id":"t:earnings per share","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Earnings per share","back":"Net income divided by the number of shares outstanding. Often shortened to EPS.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:ebit","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EBIT","back":"Earnings before interest and taxes: profit before paying lenders and tax. For a company with no income or costs outside its operations, EBIT equals operating profit; otherwise the two differ.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:ebitda","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EBITDA","back":"Earnings before interest, taxes, depreciation and amortisation: EBIT plus D&amp;A. A widely used but non-GAAP measure of operating earnings.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:economic entity assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Economic entity assumption","back":"The assumption that a business is separate from its owners and from other businesses, so its records contain only its own transactions and events.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:economic profit","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Economic profit","back":"Accounting profit minus the opportunity costs that accounting does not record, such as the owner’s forgone salary and the return her money could have earned elsewhere.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:economic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Economics","back":"The study of how people, firms and societies make decisions in the face of scarcity.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:edit distance","kind":"term","course":"b02","lesson":"duplicates","front":"Edit distance","back":"The smallest number of single-character insertions, deletions and substitutions needed to turn one string into another; also called Levenshtein distance.","href":"learn/analytics/b02/duplicates/"},{"id":"t:effective annual rate","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Effective annual rate","back":"The interest rate that, compounded once a year, gives the same result as a quoted rate with more frequent compounding: (1 + r/m)^m − 1. Often shortened to EAR.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:effective tax rate","kind":"term","course":"f02","lesson":"income-statement","front":"Effective tax rate","back":"Income tax expense divided by income before income tax.","href":"learn/finance/f02/income-statement/"},{"id":"t:elastic demand","kind":"term","course":"m02","lesson":"price-response","front":"Elastic demand","back":"Demand whose elasticity has a magnitude above 1: quantity changes by a larger percentage than price, so revenue moves in the opposite direction to price.","href":"learn/marketing/m02/price-response/"},{"id":"t:emergency fund","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Emergency fund","back":"Money a person keeps in liquid form to cover unexpected costs or a loss of income, usually measured in months of essential spending.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:endowment","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Endowment","back":"A fund whose capital is invested so that its income pays for a purpose, such as a scholarship or a professorship, indefinitely.","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:enterprise value","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Enterprise value","back":"Market capitalisation plus debt minus cash: the value of a company’s operating business, claimed jointly by its lenders and shareholders. Often shortened to EV.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:equation of value","kind":"term","course":"f04","lesson":"present-and-future-value","front":"Equation of value","back":"An equation stating that two sets of payments are worth the same at a given rate, written by moving every payment to one comparison date. Used to reschedule debts and to solve for an unknown payment or date.","href":"learn/finance/f04/present-and-future-value/"},{"id":"t:equity","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Equity","back":"The owners’ residual claim on a business. In the accounts it is assets minus liabilities (book value); in finance it is money invested in exchange for ownership, paid after lenders and other creditors, with no promised payments and no limit on the upside.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:equity market","kind":"term","course":"f00","lesson":"financial-markets","front":"Equity market","back":"The market for shares (stock), which are ownership claims on companies. Also called the stock market.","href":"learn/finance/f00/financial-markets/"},{"id":"t:equivalent rate","kind":"term","course":"f04","lesson":"effective-annual-rates","front":"Equivalent rates","back":"Rates quoted with different compounding frequencies that produce the same growth over a year, and so have the same effective annual rate.","href":"learn/finance/f04/effective-annual-rates/"},{"id":"t:error of commission","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of commission","back":"An amount recorded on the correct side but in the wrong account of the same type, such as rent posted to utilities expense or an invoice posted to the wrong customer.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of omission","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of omission","back":"A transaction left out of the records entirely. Both sides are missing, so the trial balance still balances.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of original entry","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of original entry","back":"A wrong amount recorded in the journal and posted to both accounts, so debits still equal credits.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of principle","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of principle","back":"An amount recorded on the correct side but in the wrong type of account, such as a repair (an expense) debited to equipment (an asset).","href":"learn/finance/f01/trial-balance/"},{"id":"t:error value","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Error value","back":"A result such as #DIV/0!, #VALUE!, #NAME?, #REF!, #N/A or #NUM! that Excel shows when a formula can’t calculate, naming the kind of problem.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:escalation clause","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Escalation clause","back":"A contract term that changes a payment in line with a named price index, such as the CPI, so that the payment keeps its purchasing power.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:escrow account","kind":"term","course":"f04","lesson":"mortgages","front":"Escrow account","back":"An account set up by a mortgage lender and funded from part of each monthly payment, from which property taxes and homeowners insurance are paid. Also called an impound account.","href":"learn/finance/f04/mortgages/"},{"id":"t:ev/ebitda","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EV/EBITDA","back":"Enterprise value divided by EBITDA: a multiple that compares differently financed companies on the same footing.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:exact duplicate","kind":"term","course":"b02","lesson":"duplicates","front":"Exact duplicate","back":"A row whose values are identical to another row’s in every column.","href":"learn/analytics/b02/duplicates/"},{"id":"t:exact match","kind":"term","course":"b03","lesson":"lookups","front":"Exact match","back":"A lookup that returns a result only when it finds a key equal to the lookup value, and #N/A when it doesn’t.","href":"learn/analytics/b03/lookups/"},{"id":"t:excel table","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Excel table","back":"A range that Excel manages as one named object, with a header row, filter buttons and columns that formulas can refer to by name; it grows when rows or columns are added next to it.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:exchange","kind":"term","course":"f00","lesson":"financial-markets","front":"Exchange","back":"An organised marketplace with published rules and standardised products, where buyers’ and sellers’ orders meet and prices are visible to all.","href":"learn/finance/f00/financial-markets/"},{"id":"t:exchange (marketing)","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Exchange (marketing)","back":"Obtaining something of value from someone by offering something in return. It needs at least two parties, each with something the other values, each able to communicate and deliver, and each free to accept or reject the offer.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:exchange-traded fund","kind":"term","course":"f00","lesson":"market-participants","front":"Exchange-traded fund","back":"A fund whose shares trade on a stock exchange throughout the day at market prices, which may differ slightly from its NAV (ETF).","href":"learn/finance/f00/market-participants/"},{"id":"t:exclusive distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Exclusive distribution","back":"Allowing only one or a very few outlets in each area to sell a product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:executory contract","kind":"term","course":"f01","lesson":"accounting-equation","front":"Executory contract","back":"A contract in which neither party has yet performed. It is not recorded in the accounts until one side acts, for example by paying or delivering.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:expanded accounting equation","kind":"term","course":"f01","lesson":"accounting-equation","front":"Expanded accounting equation","back":"Assets = liabilities + common stock + beginning retained earnings + revenue − expenses − dividends.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:expectation disconfirmation","kind":"term","course":"m01","lesson":"customer-value","front":"Expectation disconfirmation","back":"The gap between an offer’s perceived performance and the customer’s expectations. Performance above expectations is positive disconfirmation, below them negative disconfirmation, and equal to them confirmation.","href":"learn/marketing/m01/customer-value/"},{"id":"t:expected credit losse","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Expected credit losses","back":"An estimate of the amounts a business does not expect to collect on its receivables or loans, based on past experience, current conditions and reasonable and supportable forecasts. US GAAP’s CECL model (ASC 326) and IFRS 9 both measure allowances this way.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:expected value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Expected value","back":"The probability-weighted average of the possible outcomes of an uncertain event: each outcome multiplied by its probability, then added.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:expense","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Expense","back":"Decreases in assets, or increases in liabilities, from using up resources in delivering goods or services. Expenses decrease equity; distributions to owners, such as dividends, are not expenses.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:expense recognition principle","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Expense recognition principle","back":"Expenses are recognised in the period in which they are incurred, usually the period whose revenue they helped to earn. Often called the matching principle.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:exploratory data analysi","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Exploratory data analysis","back":"Analysis that examines data with summaries and charts to see what patterns they contain before committing to a model or hypothesis.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:extrapolation","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Extrapolation","back":"Using a fitted relationship to predict outside the range of the data it was fitted to, where there is no evidence that the relationship still holds.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:face value","kind":"term","course":"f04","lesson":"discounting-cash-flows","front":"Face value","back":"The amount a note or bond promises to repay at maturity, on which its interest is calculated; also called par value or principal.","href":"learn/finance/f04/discounting-cash-flows/"},{"id":"t:fad","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Fad","back":"A burst of intense enthusiasm for a product that rises quickly and collapses quickly.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:faithful representation","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Faithful representation","back":"The quality of information that depicts what it claims to depict: complete, neutral and free from error. One of the two fundamental qualitative characteristics.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:fasb","kind":"term","course":"f01","lesson":"what-is-accounting","front":"FASB","back":"The Financial Accounting Standards Board: the independent, private-sector, not-for-profit body, established in 1973, that sets US GAAP and is recognised by the SEC as the accounting standard setter for public companies.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:fashion","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Fashion","back":"A style that is currently accepted or popular in a field; fashions typically rise slowly, stay popular for a while and decline slowly.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:fdic","kind":"term","course":"f00","lesson":"market-participants","front":"FDIC","back":"The Federal Deposit Insurance Corporation: the independent US agency, established in 1933, that insures bank deposits and deals with failed banks.","href":"learn/finance/f00/market-participants/"},{"id":"t:feasible region","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Feasible region","back":"The set of all values of the decision variables that satisfy every constraint of an optimisation model.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:feature scaling","kind":"term","course":"b02","lesson":"scaling","front":"Feature scaling","back":"Converting numeric variables to comparable, unitless scales before they are used together in an analysis or model.","href":"learn/analytics/b02/scaling/"},{"id":"t:federal reserve","kind":"term","course":"f00","lesson":"market-participants","front":"Federal Reserve","back":"The central bank of the United States, created in 1913, which conducts monetary policy, supervises banks and supports financial stability and the payments system.","href":"learn/finance/f00/market-participants/"},{"id":"t:fifo","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"FIFO","back":"First in, first out: a cost formula that assigns the oldest costs to the units sold, leaving the most recent costs in ending inventory.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Finance","back":"The study of how people, businesses and governments raise, allocate and manage money over time, under uncertainty.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:finance charge","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Finance charge","back":"Under the US Truth in Lending rules (Regulation Z), the cost of consumer credit as a dollar amount, including interest and charges such as points and loan fees.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:financial accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Financial accounting","back":"The branch of accounting that prepares general-purpose financial statements for outside users, such as investors and lenders, following accounting standards (US GAAP or IFRS).","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:financial asset","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial assets","back":"Claims whose value comes from the payments they promise or make possible, such as shares, bonds, deposits and loans, rather than from any physical use.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial intermediary","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial intermediary","back":"An institution, such as a bank, insurance company, pension fund or investment fund, that gathers money from savers and provides it to borrowers or invests it, changing the kind of claim along the way.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial market","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial market","back":"Any arrangement through which people with money to spare provide it to people who need it, in exchange for claims on future payments; also the place or system in which those claims are traded.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial statement","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Financial statements","back":"Structured reports of a business’s performance and cash flows for a period and its financial position at a date, prepared under accounting rules: the income statement, statement of changes in equity, balance sheet and statement of cash flows, together with their notes.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:financial system","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Financial system","back":"The banks, markets and other institutions that move money from savers to borrowers and businesses, price time and risk, and help people share risk.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:financing activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Financing activities","back":"Cash flows with owners and lenders: issuing stock, borrowing, repaying loan principal and paying dividends.","href":"learn/finance/f01/financial-statements/"},{"id":"t:financing decision","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Financing decision","back":"A firm’s choice of how to pay for its investments: with owners’ money (equity), borrowed money (debt) or a mix, called its capital structure.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:fisher relation","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Fisher relation","back":"The exact link between a nominal rate, a real rate and inflation over the same period: (1 + nominal) = (1 + real) × (1 + inflation).","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:fitness for purpose","kind":"term","course":"b01","lesson":"data-quality","front":"Fitness for purpose","back":"Whether data is good enough for the use intended. The UK Government Data Quality Framework treats it as the definition of data quality: the same data can be fit for one purpose and unfit for another.","href":"learn/analytics/b01/data-quality/"},{"id":"t:five why","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Five whys","back":"A root-cause technique that asks “why?” of a problem and then of each answer in turn, usually about five times, until it reaches a cause that can be acted on.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:fixed cost","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Fixed cost","back":"A cost whose total stays the same over a period whatever the volume, within the range of activity planned: rent, salaries, listing fees, a committed promotion budget.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:fixed-rate mortgage","kind":"term","course":"f04","lesson":"mortgages","front":"Fixed-rate mortgage","back":"A mortgage whose interest rate stays the same for the whole term, so the monthly payment of principal and interest never changes.","href":"learn/finance/f04/mortgages/"},{"id":"t:focu","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Focus","back":"A generic strategy of serving one narrow segment better than broad competitors, through lower cost (cost focus) or differentiation (differentiation focus).","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:forecast","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Forecast","back":"An estimate, made in advance, of a future value such as next month’s orders. Because it is uncertain, it is best given with a range or as scenarios.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:forecast error","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Forecast error","back":"The actual value minus the forecast, once the actual is known. A positive error means the forecast was too low.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:foreign private issuer","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Foreign private issuer","back":"A company incorporated outside the United States that meets the SEC’s tests for foreign status (broadly, no more than half its voting shares held by US residents or, if more, management, assets and administration not mainly in the United States). Since 2007 the SEC has accepted its IFRS statements without reconciliation to US GAAP.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:foreign-exchange market","kind":"term","course":"f00","lesson":"financial-markets","front":"Foreign-exchange market","back":"The market in which currencies are exchanged for one another. It is almost entirely over the counter.","href":"learn/finance/f00/financial-markets/"},{"id":"t:format check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Format check","back":"A validation rule that a text value follows a pattern, such as an email address containing exactly one @.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:formula","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Formula","back":"An entry in a spreadsheet cell that begins with an equals sign and calculates a result from values, references, operators and functions.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:freight-in","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Freight-in","back":"The cost of transporting purchased goods to the buyer. It is part of the cost of inventory; freight-out, to customers, is a selling expense.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:frequency","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Frequency","back":"The average number of times each person reached was exposed to the campaign: impressions ÷ reach.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:frequency encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Frequency encoding","back":"Replacing each category with its share of the training rows.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:full disclosure principle","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Full disclosure principle","back":"The principle that the financial statements and their notes should include all the information a reader needs to understand them.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:full outer join","kind":"term","course":"b02","lesson":"transforming-data","front":"Full outer join","back":"A join that keeps every row of both tables, matched where possible.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:fully indexed rate","kind":"term","course":"f04","lesson":"mortgages","front":"Fully indexed rate","back":"For an adjustable-rate mortgage, the index plus the margin: the rate the loan would reset to before any caps apply.","href":"learn/finance/f04/mortgages/"},{"id":"t:function","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Function","back":"A named calculation built into a spreadsheet, such as SUM or IF, called in a formula with its arguments in parentheses.","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:function of expense method","kind":"term","course":"f02","lesson":"income-statement","front":"Function of expense method","back":"Presenting expenses grouped by the activity they serve, such as cost of sales, selling, and general and administrative.","href":"learn/finance/f02/income-statement/"},{"id":"t:future value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Future value","back":"What an amount invested today will be worth at a later date, at a given rate of return: FV = PV(1 + r)ⁿ.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:fuzzy matching","kind":"term","course":"b02","lesson":"duplicates","front":"Fuzzy matching","back":"Comparing values by how similar they are rather than whether they are exactly equal, to find records that probably refer to the same thing.","href":"learn/analytics/b02/duplicates/"},{"id":"t:gaap","kind":"term","course":"f01","lesson":"what-is-accounting","front":"GAAP","back":"Generally accepted accounting principles: the body of standards and conventions that businesses in a jurisdiction follow in financial reporting. US GAAP is set by the FASB.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:gain on disposal","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Gain on disposal","back":"The amount by which the proceeds from selling a long-lived asset exceed its book value at the date of sale; a shortfall is a loss on disposal. Neither is revenue.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:gatekeeper (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"Gatekeeper (buying centre)","back":"In a buying centre, a person who controls what information and which salespeople reach the others.","href":"learn/marketing/m01/business-buying/"},{"id":"t:general journal","kind":"term","course":"f01","lesson":"journal-entries","front":"General journal","back":"The all-purpose journal, in which any kind of transaction can be recorded. Businesses that also keep special journals use it for entries that fit none of them, such as adjusting and closing entries.","href":"learn/finance/f01/journal-entries/"},{"id":"t:general ledger","kind":"term","course":"f01","lesson":"general-ledger","front":"General ledger","back":"The collection of all a business’s accounts, one for each account in the chart of accounts, showing every amount posted to each account and its balance.","href":"learn/finance/f01/general-ledger/"},{"id":"t:generic strategy","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Generic strategies","back":"Michael Porter’s broad ways of outperforming rivals: cost leadership, differentiation and focus, with focus pursued through either cost or differentiation.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:geometric mean","kind":"term","course":"b02","lesson":"skewed-data","front":"Geometric mean","back":"The nth root of the product of n positive values, equal to the back-transformed mean of their logs; never larger than the arithmetic mean.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:goal seek","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Goal Seek","back":"An Excel what-if tool that finds the value of one input cell that makes a formula cell equal a target value, by trying values in turn.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:going concern assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Going concern assumption","back":"The assumption that, unless there is evidence to the contrary, a business will continue operating for the foreseeable future.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:goodharts law","kind":"term","course":"b01","lesson":"kpis","front":"Goodhart’s law","back":"The observation that a measure tends to stop tracking what it was meant to track once people are rewarded for moving it; often put as “when a measure becomes a target, it ceases to be a good measure”.","href":"learn/analytics/b01/kpis/"},{"id":"t:goods available for sale","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Goods available for sale","back":"Beginning inventory plus purchases for the period: everything the business could have sold. It ends either in cost of goods sold or in ending inventory.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:goodwill","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Goodwill","back":"The amount by which the price paid for a business exceeds the fair value of its identifiable assets less its liabilities. It is recognised only when a business is acquired.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:gordon growth model","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Gordon growth model","back":"The constant-growth dividend discount model: a share is worth next year’s dividend divided by (required return − growth rate), P₀ = D₁ ÷ (r − g).","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:granularity","kind":"term","course":"b02","lesson":"transforming-data","front":"Granularity","back":"The level of detail that one row of a table represents, such as one order, one customer or one region in one month.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:greenwashing","kind":"term","course":"m01","lesson":"market-orientation","front":"Greenwashing","back":"Making environmental claims about a product or business that are vague, exaggerated or unsupported by evidence.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:gross margin","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Gross margin","back":"Gross profit as a percentage of net sales or net revenue; also called the gross profit margin.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:gross profit","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Gross profit","back":"Net sales (or net revenue) minus cost of goods sold (or cost of sales). Called gross margin in some textbooks.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:gross rating point","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Gross rating points","back":"A measure of the weight of a campaign: reach (as a percentage of the target audience) × average frequency, or impressions as a percentage of the audience. Abbreviated GRPs.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:growing annuity","kind":"term","course":"f04","lesson":"annuities","front":"Growing annuity","back":"A stream of payments for a fixed number of periods in which each payment is a constant percentage larger than the one before.","href":"learn/finance/f04/annuities/"},{"id":"t:growing perpetuity","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Growing perpetuity","back":"A stream of payments that continues for ever and grows at a constant rate g each period. Its present value is the next payment divided by (r − g), and it exists only when r > g.","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:growth factor","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Growth factor","back":"The number (1 + r)ⁿ by which compound growth at a rate r per period multiplies an amount over n periods.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:growth stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Growth stage","back":"The stage in which sales rise quickly, competitors enter and profits rise.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:guardrail metric","kind":"term","course":"b01","lesson":"kpis","front":"Guardrail metric","back":"A measure that must not get worse while a KPI is being improved, used to catch gains that come at a hidden cost.","href":"learn/analytics/b01/kpis/"},{"id":"t:habitual buying behaviour","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Habitual buying behaviour","back":"Buying with low involvement among brands that seem alike: routine repurchase with little search or evaluation.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:hedge fund","kind":"term","course":"f00","lesson":"market-participants","front":"Hedge fund","back":"A private, unregistered investment fund, generally open only to wealthy or sophisticated investors, free to use leverage, short selling and derivatives.","href":"learn/finance/f00/market-participants/"},{"id":"t:hedging","kind":"term","course":"f00","lesson":"financial-markets","front":"Hedging","back":"Using a financial contract, often a derivative, to reduce a risk one already faces.","href":"learn/finance/f00/financial-markets/"},{"id":"t:hierarchy-of-effects model","kind":"term","course":"m02","lesson":"promotion-mix","front":"Hierarchy-of-effects model","back":"Any model that describes buying as a sequence of mental stages, such as awareness, knowledge, liking, preference, conviction and purchase.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:high cardinality","kind":"term","course":"b02","lesson":"encoding-categories","front":"High cardinality","back":"A categorical variable with a very large number of distinct values, such as postcodes or product codes.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:historical cost principle","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Historical cost principle","back":"The principle that assets are recorded at what they cost to acquire and get ready for use, and generally kept at that amount rather than updated to current value.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:holdout group","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Holdout group","back":"A randomly chosen group deliberately not exposed to a campaign, used as the comparison for measuring its incremental effect.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:hypothesi","kind":"term","course":"b01","lesson":"business-questions","front":"Hypothesis","back":"A proposed explanation or prediction, stated precisely enough that data could show it to be wrong.","href":"learn/analytics/b01/business-questions/"},{"id":"t:hypothesis-driven analysi","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Hypothesis-driven analysis","back":"Analysis that starts from stated hypotheses and gathers the evidence that would confirm or contradict each, usually the most promising and cheapest first.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:iasb","kind":"term","course":"f01","lesson":"what-is-accounting","front":"IASB","back":"The International Accounting Standards Board: the independent standard-setting body within the IFRS Foundation that develops IFRS Accounting Standards. It was set up in 2001.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:icon set","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Icon set","back":"A conditional format that puts one of three to five icons in each cell according to the band of values, set by thresholds, that the cell falls in.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:identifier","kind":"term","course":"b01","lesson":"data-types","front":"Identifier","back":"A value whose job is to say which thing a row describes, such as an order number, customer number or postcode. It may be written with digits but is never an amount.","href":"learn/analytics/b01/data-types/"},{"id":"t:ifr","kind":"term","course":"f01","lesson":"what-is-accounting","front":"IFRS","back":"International Financial Reporting Standards (formally IFRS Accounting Standards), written by the IASB. Each jurisdiction decides whether and for which companies to require them.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:impairment","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Impairment","back":"A loss recognised when an asset’s carrying amount can no longer be recovered from its use or sale, measured under US GAAP against fair value and under IFRS against recoverable amount.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:implied interest rate","kind":"term","course":"f04","lesson":"annuities","front":"Implied interest rate","back":"The interest rate at which the present value of a stream of payments equals the amount borrowed or the cash price: the rate a credit or instalment arrangement really charges.","href":"learn/finance/f04/annuities/"},{"id":"t:impression","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Impressions","back":"The number of times an ad is displayed. Repeat views by the same person count separately; a served impression is counted on delivery, a viewable one only if it could actually be seen.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Imputation","back":"Replacing a missing value with a substitute value, such as a mean, a group median, a category such as “Unknown” or a model’s prediction.","href":"learn/analytics/b02/missing-values/"},{"id":"t:incentive pay","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Incentive pay","back":"Pay that depends on results, such as bonuses tied to targets, shares that vest over time and stock options, intended to align managers’ interests with owners’.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:income statement","kind":"term","course":"f01","lesson":"financial-statements","front":"Income statement","back":"The statement of revenue, expenses and net income for a period. It measures performance on the accrual basis.","href":"learn/finance/f01/financial-statements/"},{"id":"t:income summary","kind":"term","course":"f01","lesson":"closing-entries","front":"Income Summary","back":"A temporary account used only during closing. Revenue and expenses are closed into it, so its balance equals net income or net loss; it is then closed to Retained Earnings. It never appears on a financial statement.","href":"learn/finance/f01/closing-entries/"},{"id":"t:income tax expense","kind":"term","course":"f02","lesson":"income-statement","front":"Income tax expense","back":"The income tax charged on a period’s income, whether or not it has been paid. Deducted from income before income tax to give net income.","href":"learn/finance/f02/income-statement/"},{"id":"t:income taxes payable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Income taxes payable","back":"Income tax owed for a period but not yet paid at the balance sheet date: the tax for the period less estimated payments already made.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:incremental cash flow","kind":"term","course":"f00","lesson":"decision-principles","front":"Incremental cash flow","back":"The difference between the cash flows with a decision and without it; the only cash flows that should influence the decision.","href":"learn/finance/f00/decision-principles/"},{"id":"t:incrementality","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Incrementality","back":"The part of an outcome, such as sales, that was caused by the marketing and would not have happened without it.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:indirect channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Indirect channel","back":"A channel that uses one or more intermediaries between the producer and the final customer.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:indirect finance","kind":"term","course":"f00","lesson":"financial-markets","front":"Indirect finance","back":"Finance in which a financial intermediary takes savers’ money and provides it to borrowers; savers hold a claim on the intermediary, not on the borrower.","href":"learn/finance/f00/financial-markets/"},{"id":"t:indirect method","kind":"term","course":"f02","lesson":"cash-flow-statement","front":"Indirect method","back":"A way of presenting cash flows from operating activities that starts from net income (under IFRS from 2027, operating profit) and adjusts it for noncash items, gains and losses, and changes in operating current assets and liabilities.","href":"learn/finance/f02/cash-flow-statement/"},{"id":"t:inelastic demand","kind":"term","course":"m02","lesson":"price-response","front":"Inelastic demand","back":"Demand whose elasticity has a magnitude below 1: quantity changes by a smaller percentage than price, so revenue moves in the same direction as price.","href":"learn/marketing/m02/price-response/"},{"id":"t:inflation","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Inflation","back":"A sustained rise in the general level of prices, measured as the percentage change in a price index.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:influencer (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"Influencer (buying centre)","back":"In a buying centre, a person whose views or expertise shape the specification or the choice without making the final decision, such as an engineer or a specialist. Not to be confused with a social-media influencer.","href":"learn/marketing/m01/business-buying/"},{"id":"t:information search","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Information search","back":"The stage in which a buyer looks for information about ways to meet a need, from memory (internal search) or from personal, commercial, public and experiential sources (external search).","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:initial public offering","kind":"term","course":"f00","lesson":"financial-markets","front":"Initial public offering","back":"A company’s first sale of shares to the general public (IPO).","href":"learn/finance/f00/financial-markets/"},{"id":"t:initiator (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"Initiator (buying centre)","back":"In a buying centre, the person who first suggests the purchase.","href":"learn/marketing/m01/business-buying/"},{"id":"t:inner join","kind":"term","course":"b02","lesson":"transforming-data","front":"Inner join","back":"A join that keeps only the rows whose key appears in both tables.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:institutional investor","kind":"term","course":"f00","lesson":"market-participants","front":"Institutional investors","back":"Organisations that invest large pools of other people’s money, such as pension funds, insurance companies, mutual funds and hedge funds.","href":"learn/finance/f00/market-participants/"},{"id":"t:intangible asset","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Intangible asset","back":"An identifiable asset without physical substance, such as a patent, copyright, trademark, licence or software.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:integer constraint","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Integer constraint","back":"A constraint that a decision variable must take a whole-number value; int in Excel’s Solver.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:integrated marketing communication","kind":"term","course":"m02","lesson":"promotion-mix","front":"Integrated marketing communications","back":"Planning and coordinating all promotion tools so that they deliver one clear, consistent message about the brand. Abbreviated IMC.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:intensive distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Intensive distribution","back":"Placing a product in as many outlets as possible.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:inter-functional coordination","kind":"term","course":"m01","lesson":"market-orientation","front":"Inter-functional coordination","back":"Using the whole business, not just a marketing department, to create value for customers; one of Narver and Slater’s three components of market orientation.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:interest","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Interest","back":"The price of using someone else’s money: what a borrower pays a lender, usually stated as a percentage of the amount borrowed per year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:interest rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Interest rate","back":"The price of using money for a period, stated as a percentage of the amount per year: received by savers and lenders, paid by borrowers.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:interest-only loan","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Interest-only loan","back":"A loan whose regular payments cover only the interest, so the principal is repaid in full at the end in one balloon payment.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:interest-rate spread","kind":"term","course":"f00","lesson":"financial-markets","front":"Interest-rate spread","back":"The difference between the rate an intermediary charges borrowers and the rate it pays savers, in percentage points.","href":"learn/finance/f00/financial-markets/"},{"id":"t:intermediary","kind":"term","course":"m02","lesson":"distribution-channels","front":"Intermediary","back":"A business between the producer and the final customer that buys, sells, stores, moves or promotes the product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:internal control","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Internal control","back":"The processes, carried out by an organisation’s board, managers and staff, that give reasonable assurance that its operations run well, its reporting is reliable and it complies with laws and regulations.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:internal rate of return","kind":"term","course":"f04","lesson":"discounting-cash-flows","front":"Internal rate of return","back":"The discount rate at which the net present value of a set of cash flows is zero: the rate of return, per period, that an investment earns on its own cash flows (for a borrower, what the borrowing costs). For a loan or bond bought at a given price and held to maturity, it is the yield to maturity. Cash flows that change sign more than once can have several IRRs, or none. Often shortened to IRR.","href":"learn/finance/f04/discounting-cash-flows/"},{"id":"t:interquartile range","kind":"term","course":"b01","lesson":"summarising-data","front":"Interquartile range","back":"The third quartile minus the first quartile: the width of the middle half of the data (IQR).","href":"learn/analytics/b01/summarising-data/"},{"id":"t:interval variable","kind":"term","course":"b01","lesson":"data-types","front":"Interval variable","back":"A numerical variable on which differences are meaningful but zero is an arbitrary point, so ratios are not, such as a calendar date or a temperature in °C.","href":"learn/analytics/b01/data-types/"},{"id":"t:introduction stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Introduction stage","back":"The first stage of the life cycle after launch: low awareness, slow sales growth, high costs and usually losses.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:inventory","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Inventory","back":"Goods held for sale in the ordinary course of business (and, for a manufacturer, materials and goods in production). An asset, measured at cost or, if lower, net realisable value.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:inventory write-down","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Inventory write-down","back":"A reduction of inventory’s carrying amount to net realisable value, recognised as an expense. IFRS requires it to be reversed if value recovers, up to the original amount; US GAAP doesn’t allow a reversal.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:investing activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Investing activities","back":"Cash flows from buying and selling long-term assets, such as equipment, and investments.","href":"learn/finance/f01/financial-statements/"},{"id":"t:investment bank","kind":"term","course":"f00","lesson":"market-participants","front":"Investment bank","back":"A firm that helps companies and governments raise money by underwriting new securities, advises on mergers and acquisitions, and often trades securities.","href":"learn/finance/f00/market-participants/"},{"id":"t:investment decision","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Investment decision","back":"A firm’s choice of which long-term assets and projects to put money into. The analysis behind it is capital budgeting.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:investment finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Investment finance","back":"The branch of finance concerned with the decisions of investors: which securities to buy, how to combine them and what they are worth. Also called investments.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:involvement","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Involvement","back":"How much a purchase matters to the buyer: its personal relevance, what is at stake and the buyer’s interest in the category. It depends on the buyer and the situation as well as the product.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:iso 8601","kind":"term","course":"b02","lesson":"types-and-formats","front":"ISO 8601","back":"The international standard for representing dates and times, with units from largest to smallest; dates are usually written YYYY-MM-DD (its extended format) or YYYYMMDD (its basic format).","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:issue tree","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Issue tree","back":"A diagram that breaks a problem or question into smaller questions, level by level, until each can be answered with specific evidence.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:issuer","kind":"term","course":"f00","lesson":"financial-markets","front":"Issuer","back":"The company, government or other body that creates a security and receives the money when it is first sold.","href":"learn/finance/f00/financial-markets/"},{"id":"t:join","kind":"term","course":"b02","lesson":"transforming-data","front":"Join","back":"Combining two tables by matching the values of a key column, so that each row gains the matching columns of the other table.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:journal","kind":"term","course":"f01","lesson":"journal-entries","front":"Journal","back":"A record of transactions in date order, each written as a complete entry with its debits, credits and explanation. Also called the book of original entry.","href":"learn/finance/f01/journal-entries/"},{"id":"t:journal entry","kind":"term","course":"f01","lesson":"journal-entries","front":"Journal entry","back":"The record of one transaction in a journal: the date, the accounts and amounts debited and credited, and a short explanation.","href":"learn/finance/f01/journal-entries/"},{"id":"t:journalising","kind":"term","course":"f01","lesson":"journal-entries","front":"Journalising","back":"Recording transactions in a journal.","href":"learn/finance/f01/journal-entries/"},{"id":"t:key performance indicator","kind":"term","course":"b01","lesson":"kpis","front":"Key performance indicator","back":"A metric chosen to track progress towards a business objective, with an exact formula, a target, a direction (higher or lower is better) and an owner. Abbreviated KPI.","href":"learn/analytics/b01/kpis/"},{"id":"t:kurtosi","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Kurtosis","back":"A measure of how heavy a distribution’s tails are. Excel’s KURT reports excess kurtosis, which is about 0 for normally distributed data and positive for heavier tails.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:label encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Label encoding","back":"Giving each category an arbitrary integer code, often in alphabetical order. Misleading for nominal input variables in linear and distance-based models.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:lagging indicator","kind":"term","course":"b01","lesson":"kpis","front":"Lagging indicator","back":"A measure of an outcome after it has happened, such as revenue for a month or profit for a year.","href":"learn/analytics/b01/kpis/"},{"id":"t:law of one price","kind":"term","course":"f00","lesson":"decision-principles","front":"Law of one price","back":"The principle that identical goods or assets, producing identical cash flows, should sell for the same price, because otherwise traders could profit by buying the cheaper and selling the dearer.","href":"learn/finance/f00/decision-principles/"},{"id":"t:leading indicator","kind":"term","course":"b01","lesson":"kpis","front":"Leading indicator","back":"A measure that moves before an outcome and, if the link holds, signals where that outcome is heading, such as visits or checkouts started before orders and revenue.","href":"learn/analytics/b01/kpis/"},{"id":"t:leading zero","kind":"term","course":"b02","lesson":"types-and-formats","front":"Leading zero","back":"A zero at the start of a code, such as the first two digits of 004517. It carries no numerical value but is part of the identifier, and is lost if the code is stored as a number.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:least-squares line","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Least-squares line","back":"The regression line that makes the sum of the squared residuals as small as possible; it passes through the point of means.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:left join","kind":"term","course":"b02","lesson":"transforming-data","front":"Left join","back":"A join that keeps every row of the left table, leaving the right table’s columns missing where there is no match.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:left-skewed","kind":"term","course":"b02","lesson":"skewed-data","front":"Left-skewed","back":"Having a long tail of small values; the mean is usually below the median. Also called negatively skewed.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:lender credit","kind":"term","course":"f04","lesson":"mortgages","front":"Lender credit","back":"Money a lender contributes to a borrower’s closing costs in exchange for a higher interest rate: the opposite of discount points.","href":"learn/finance/f04/mortgages/"},{"id":"t:level of measurement","kind":"term","course":"b01","lesson":"data-types","front":"Level of measurement","back":"The classification of a variable as nominal, ordinal, interval or ratio (Stevens, 1946), according to which comparisons between its values are meaningful.","href":"learn/analytics/b01/data-types/"},{"id":"t:leverage","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Leverage","back":"The use of debt to finance part of a business. Because interest is set by the loan contract and does not rise when the business does well, leverage magnifies shareholders’ gains and losses. Also called gearing.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:liability","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Liability","back":"A present obligation of the business to transfer an economic resource to others, arising from past events.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:lifestyle","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Lifestyle","back":"A person’s pattern of living, expressed in their activities, interests and opinions.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:lifo","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"LIFO","back":"Last in, first out: a cost formula that assigns the newest costs to the units sold, leaving the oldest costs in ending inventory. Allowed under US GAAP, prohibited by IAS 2.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:lifo conformity rule","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"LIFO conformity rule","back":"The US tax rule (26 U.S.C. §472) that a taxpayer using LIFO for tax must not use another method to measure income in its reports to owners or for credit purposes.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:line extension","kind":"term","course":"m02","lesson":"product-decisions","front":"Line extension","back":"A new variant (flavour, size, format) added under an existing brand in a category where the brand already sells. Taking a brand into a new category is a brand extension.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:linear programme","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Linear programme","back":"An optimisation model whose objective and constraints are all sums of decision variables multiplied by constants, so that it can be solved exactly by the simplex method.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:liquidity","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Liquidity","back":"For an asset, how quickly it can be turned into cash with little loss of value. For a firm or person, the ability to meet obligations as they fall due.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:listwise deletion","kind":"term","course":"b02","lesson":"missing-values","front":"Listwise deletion","back":"Dropping every row that has a missing value in any variable an analysis uses; also called complete-case analysis.","href":"learn/analytics/b02/missing-values/"},{"id":"t:locale","kind":"term","course":"b02","lesson":"types-and-formats","front":"Locale","back":"The conventions of a language and region for writing numbers, dates, times and currency, such as the decimal mark, the thousands separator and the order of day and month.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:lock-up","kind":"term","course":"f00","lesson":"market-participants","front":"Lock-up","back":"An agreement by a company’s existing shareholders not to sell their shares for a period after an IPO, typically 180 days.","href":"learn/finance/f00/market-participants/"},{"id":"t:log transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Log transformation","back":"Replacing each value x with ln x (or a log to another base); it needs positive values and turns equal ratios into equal differences.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:log1p transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Log1p transformation","back":"Replacing each value x with ln(1 + x), so that zeros become 0; its effect depends on the units of x.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:logarithm","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Logarithm","back":"The power to which a base must be raised to give a number: the base-10 logarithm of 1,000 is 3 because 10³ = 1,000. The natural logarithm, ln, uses the base e ≈ 2.71828.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:logical value","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Logical value","back":"TRUE or FALSE: the result of a comparison such as J2>=50, and what IF, AND, OR and NOT work with.","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:logistic","kind":"term","course":"m02","lesson":"distribution-channels","front":"Logistics","back":"Planning and controlling the physical flow of goods, including inventory, storage and transport, from the producer to the customer.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:long format","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Long format","back":"A layout in which that variable has a column of its own and each combination of values has its own row.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:lookup table","kind":"term","course":"b03","lesson":"lookups","front":"Lookup table","back":"A range holding the keys a lookup searches and the values it can return, such as a price list or a table of bands.","href":"learn/analytics/b03/lookups/"},{"id":"t:lookup value","kind":"term","course":"b03","lesson":"lookups","front":"Lookup value","back":"The value a lookup formula searches for, such as the product named in an order row.","href":"learn/analytics/b03/lookups/"},{"id":"t:loss aversion","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Loss aversion","back":"The tendency for a loss to weigh more than a gain of the same size, both measured from a reference point (Kahneman and Tversky, 1979). It is different from risk aversion.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:lower of cost and net realisable value","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Lower of cost and net realisable value","back":"The rule that inventory is carried at the lower of its cost and its net realisable value; the reduction is an expense of the period.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:machine learning","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Machine learning","back":"Methods in which a computer fits a model to data, learning a relationship between inputs and an outcome from examples rather than from rules written by a person. Supervised learning learns from examples with known outcomes; unsupervised learning looks for structure, such as groups, without them.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:macroeconomic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Macroeconomics","back":"The part of economics that studies the economy as a whole: total output and growth, unemployment, inflation, interest rates and government and central bank policy.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:macroenvironment","kind":"term","course":"m01","lesson":"situation-analysis","front":"Macroenvironment","back":"The wider political, economic, social, technological, environmental and legal forces that shape a whole market and that no single business controls.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:management-defined performance measure","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Management-defined performance measure","back":"Under IFRS 18, a subtotal of income and expenses that a company uses in public communications outside its financial statements to convey management’s view of its performance, and that IFRS does not itself specify. It must be explained and reconciled in a note.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:managerial accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Managerial accounting","back":"The branch of accounting that prepares internal reports, such as budgets, cost reports and forecasts, to help managers plan, control and decide. It follows no externally imposed rules and often uses nonfinancial measures. Also called management accounting.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:mapping table","kind":"term","course":"b02","lesson":"text-and-categories","front":"Mapping table","back":"A table that lists each variant of a value and the value it should become, kept as reviewed and versioned data rather than as one-off edits.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:mar","kind":"term","course":"b02","lesson":"missing-values","front":"MAR","back":"Missing at random: whether a value is missing depends only on recorded variables; within groups defined by them it is unrelated to the missing value itself.","href":"learn/analytics/b02/missing-values/"},{"id":"t:margin","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Margin","back":"Profit per unit as a percentage of price: (price − cost) ÷ price. Also called margin on price or, in some texts, markup on selling price.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:market","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Market","back":"The set of actual and potential buyers of an offering.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:market capitalisation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market capitalisation","back":"Share price multiplied by the number of shares outstanding: the market value of a company’s equity. Often shortened to market cap.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:market intelligence","kind":"term","course":"m01","lesson":"market-orientation","front":"Market intelligence","back":"Information about customers’ current and future needs and the forces that shape them, including competitors, technology and regulation, gathered for decisions.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:market maker","kind":"term","course":"f00","lesson":"market-participants","front":"Market maker","back":"A dealer that stands ready at all times to buy a security at its bid and sell it at its ask, providing liquidity.","href":"learn/finance/f00/market-participants/"},{"id":"t:market offering","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Market offering","back":"The combination of goods, services, information and experiences a business offers to satisfy a need or want.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:market orientation","kind":"term","course":"m01","lesson":"market-orientation","front":"Market orientation","back":"The marketing concept put into practice: organisation-wide generation of intelligence about customers’ current and future needs, its dissemination across departments and responsiveness to it (Kohli and Jaworski, 1990); described by Narver and Slater (1990) as customer orientation, competitor orientation and inter-functional coordination.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:market share","kind":"term","course":"m01","lesson":"situation-analysis","front":"Market share","back":"A business’s sales as a percentage of total sales in a defined market over the same period, measured in money or in units.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:market value","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market value","back":"What buyers and sellers are paying for something now. For a listed company’s equity it is the market capitalisation.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:market-to-book ratio","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market-to-book ratio","back":"Market capitalisation divided by the book value of equity (or price per share divided by book value per share). Also called price-to-book.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:marketing","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Marketing","back":"The activity of creating, communicating, delivering and exchanging offerings that have value for customers, clients, partners and society (a paraphrase of the American Marketing Association’s definition).","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:marketing channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Marketing channel","back":"The set of organisations that work together to make a product available to the people who use it; also called a distribution channel.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:marketing concept","kind":"term","course":"m01","lesson":"market-orientation","front":"Marketing concept","back":"The belief that a business reaches its goals by finding out what target customers need and want and satisfying them better than competitors do.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:marketing environment","kind":"term","course":"m01","lesson":"situation-analysis","front":"Marketing environment","back":"The actors and forces outside the marketing function that affect its ability to build and keep relationships with customers; divided into the microenvironment and the macroenvironment.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:marketing funnel","kind":"term","course":"m01","lesson":"marketing-objectives","front":"Marketing funnel","back":"A model of the stages customers pass through, from awareness through consideration and conversion to retention and advocacy, with fewer people at each stage.","href":"learn/marketing/m01/marketing-objectives/"},{"id":"t:marketing mix","kind":"term","course":"m02","lesson":"marketing-mix","front":"Marketing mix","back":"The set of controllable decisions a business combines to create, communicate, deliver and capture value for its target market.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:marketing myopia","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Marketing myopia","back":"Defining a business by the product it makes rather than the customer need it serves, which hides substitutes and changes in what customers want (Theodore Levitt, 1960).","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:marketing objective","kind":"term","course":"m01","lesson":"marketing-objectives","front":"Marketing objective","back":"A statement of what customers must do, how much and by when, for a business goal to be met, such as the number of customers to win or keep, with a measure, a level and a date.","href":"learn/marketing/m01/marketing-objectives/"},{"id":"t:marketing process","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Marketing process","back":"The five steps of marketing work used in this course: understand customers and the market, design a customer-driven strategy, build the offer, build profitable relationships, and capture value in return.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:marketing roi","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Marketing ROI","back":"Return on marketing investment: (incremental contribution − marketing cost) ÷ marketing cost. Variants use gross profit or lifetime value.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:marketing strategy","kind":"term","course":"m01","lesson":"marketing-objectives","front":"Marketing strategy","back":"How a business intends to reach its marketing objectives: which customers it will serve and how it will compete for them.","href":"learn/marketing/m01/marketing-objectives/"},{"id":"t:markup","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Markup","back":"Profit per unit as a percentage of cost: (price − cost) ÷ cost.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:masking","kind":"term","course":"b02","lesson":"outliers","front":"Masking","back":"The effect in which outliers inflate the mean and standard deviation used to detect them, so that they, or other outliers, no longer look extreme.","href":"learn/analytics/b02/outliers/"},{"id":"t:maslows hierarchy of need","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Maslow’s hierarchy of needs","back":"Abraham Maslow’s (1943) theory that people have five sets of basic needs (physiological, safety, belonging, esteem and self-actualisation) and that higher needs come to dominate as lower ones are largely satisfied. Research gives little support to a strict order.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:materiality","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Materiality","back":"Information is material if omitting or misstating it could influence the decisions of the people relying on the report. It depends on the size and nature of the item in a particular business; there is no universal threshold.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:maturity stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Maturity stage","back":"The stage in which sales growth slows and flattens, competition is intense and one brand’s gains come mainly from others. Usually the longest stage.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:mcar","kind":"term","course":"b02","lesson":"missing-values","front":"MCAR","back":"Missing completely at random: whether a value is missing is unrelated to any data, recorded or not.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mean","kind":"term","course":"b01","lesson":"summarising-data","front":"Mean","back":"The sum of the values divided by how many there are; the arithmetic average. Multiplied by the count it gives the total.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:mean imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Mean imputation","back":"Filling every missing value in a column with the mean of the observed values; it keeps the mean, shrinks the spread and weakens relationships.","href":"learn/analytics/b02/missing-values/"},{"id":"t:measurement bia","kind":"term","course":"b01","lesson":"data-collection","front":"Measurement bias","back":"Systematic error from the way a value is measured or a question is asked, which pushes results in one direction.","href":"learn/analytics/b01/data-collection/"},{"id":"t:mece","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"MECE","back":"Mutually exclusive, collectively exhaustive: a test for the branches of a split or a set of categories, which should not overlap and should together cover every possibility.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:median","kind":"term","course":"b01","lesson":"summarising-data","front":"Median","back":"The middle value of a set of values sorted in order, with half at or below it and half at or above; with an even number of values, the average of the two middle ones.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:median absolute deviation","kind":"term","course":"b02","lesson":"outliers","front":"Median absolute deviation","back":"The median of the absolute distances of the values from their median (MAD); a robust measure of spread.","href":"learn/analytics/b02/outliers/"},{"id":"t:melt","kind":"term","course":"b02","lesson":"transforming-data","front":"Melt","back":"Reshaping from wide to long format, also called unpivoting: several columns become one column of former headers and one column of values.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:merchandising business","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Merchandising business","back":"A business that buys finished goods and resells them without changing them, such as a retailer or wholesaler.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:metric","kind":"term","course":"b01","lesson":"kpis","front":"Metric","back":"A quantity calculated from data by an exact rule, such as the number of orders in a month or the average rating.","href":"learn/analytics/b01/kpis/"},{"id":"t:microeconomic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Microeconomics","back":"The part of economics that studies the decisions of individual households and firms and how they interact in particular markets.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:microenvironment","kind":"term","course":"m01","lesson":"situation-analysis","front":"Microenvironment","back":"The actors close to a business that it deals with directly: customers, competitors, suppliers, intermediaries, publics and the rest of the business itself.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:midpoint formula","kind":"term","course":"m02","lesson":"price-response","front":"Midpoint formula","back":"A way of calculating elasticity between two observed points that divides each change by the average of the two values, so the answer is the same in either direction. Also called arc elasticity.","href":"learn/marketing/m02/price-response/"},{"id":"t:min–max normalisation","kind":"term","course":"b02","lesson":"scaling","front":"Min–max normalisation","back":"Rescaling a variable as (x − minimum) ÷ (maximum − minimum), so the training data run from 0 to 1.","href":"learn/analytics/b02/scaling/"},{"id":"t:missing value","kind":"term","course":"b01","lesson":"data-quality","front":"Missing value","back":"A cell where a value should exist but was not recorded, whether it appears as a blank, a code such as NA or −999, a text stand-in such as “unknown”, or an impossible value.","href":"learn/analytics/b01/data-quality/"},{"id":"t:missing-value indicator","kind":"term","course":"b02","lesson":"missing-values","front":"Missing-value indicator","back":"A 0/1 column that records which values were missing before imputation, kept for auditing and as a possible model input.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mixed reference","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Mixed reference","back":"A cell reference that fixes either its column ($A1) or its row (A$1), so that only the other part moves when the formula is filled or copied.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:mnar","kind":"term","course":"b02","lesson":"missing-values","front":"MNAR","back":"Missing not at random: whether a value is missing depends on the missing value itself, even after allowing for the recorded variables.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mode","kind":"term","course":"b01","lesson":"summarising-data","front":"Mode","back":"The value that occurs most often in a set of values; the only average available for nominal data.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:modified rebuy","kind":"term","course":"m01","lesson":"business-buying","front":"Modified rebuy","back":"A buying situation in which an organisation wants to change the specification, price, terms or supplier of something it has bought before.","href":"learn/marketing/m01/business-buying/"},{"id":"t:modified z-score","kind":"term","course":"b02","lesson":"outliers","front":"Modified z-score","back":"A robust z-score, 0.6745 × (x − median) ÷ MAD; absolute values above 3.5 are flagged as potential outliers.","href":"learn/analytics/b02/outliers/"},{"id":"t:monetary unit assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Monetary unit assumption","back":"The assumption that only events measurable in money are recorded, in a currency treated as a stable unit, so changes in its purchasing power are ignored.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:money market","kind":"term","course":"f00","lesson":"financial-markets","front":"Money market","back":"The market for short-term debt maturing in less than a year, such as Treasury bills and commercial paper.","href":"learn/finance/f00/financial-markets/"},{"id":"t:mortgage","kind":"term","course":"f04","lesson":"mortgages","front":"Mortgage","back":"A loan to buy a property that is secured on that property, so the lender can take the property if the borrower does not repay as agreed.","href":"learn/finance/f04/mortgages/"},{"id":"t:motive","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Motive","back":"A need that has become pressing enough to make a person act to satisfy it.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:multi-step income statement","kind":"term","course":"f02","lesson":"income-statement","front":"Multi-step income statement","back":"An income statement that deducts costs in stages and shows subtotals such as gross profit, operating income and income before income tax before net income.","href":"learn/finance/f02/income-statement/"},{"id":"t:multichannel distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Multichannel distribution","back":"Selling the same product through more than one channel at the same time.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:multiple imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Multiple imputation","back":"Creating several completed copies of a dataset with different plausible fills, analysing each, and pooling the results so that the uncertainty about the missing values is reflected in the answer.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mutual fund","kind":"term","course":"f00","lesson":"market-participants","front":"Mutual fund","back":"An SEC-registered investment company that pools money from many investors; investors buy shares from and sell them back to the fund at the NAV calculated once each business day.","href":"learn/finance/f00/market-participants/"},{"id":"t:nature of expense method","kind":"term","course":"f02","lesson":"income-statement","front":"Nature of expense method","back":"Presenting expenses grouped by their nature, such as goods purchased, employee wages, depreciation and rent, without allocating them to activities.","href":"learn/finance/f02/income-statement/"},{"id":"t:near duplicate","kind":"term","course":"b02","lesson":"duplicates","front":"Near duplicate","back":"A record that describes the same entity as another but whose values differ slightly, for example in case, spacing, spelling or a second email address.","href":"learn/analytics/b02/duplicates/"},{"id":"t:need","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Need","back":"A state of felt lack that a person or organisation is motivated to fix, such as staying alert or feeling valued at work.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:need recognition","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Need recognition","back":"The first stage of the buying decision process: the buyer notices a gap between their actual state and a desired state, prompted by an internal or external trigger.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:nested function","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Nested function","back":"A function used as an argument of another function, as in ROUND(AVERAGE(M2:M232),2); the inner one is calculated first.","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:net asset value","kind":"term","course":"f00","lesson":"market-participants","front":"Net asset value","back":"A fund’s assets minus its liabilities; per share, divided by the number of fund shares outstanding (NAV).","href":"learn/finance/f00/market-participants/"},{"id":"t:net asset","kind":"term","course":"f01","lesson":"accounting-equation","front":"Net assets","back":"Assets minus liabilities; another name for equity.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:net debt","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Net debt","back":"Debt minus cash. Enterprise value equals market capitalisation plus net debt.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:net income","kind":"term","course":"f01","lesson":"accounting-equation","front":"Net income","back":"Revenue minus expenses for a period. A negative result is a net loss.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:net present value","kind":"term","course":"f04","lesson":"discounting-cash-flows","front":"Net present value","back":"The sum of the present values of all the cash flows a decision causes, including any paid or received today, with money received positive and money paid negative, each discounted at the return available elsewhere at similar risk. A positive NPV is the value the decision adds, in today’s money. Often shortened to NPV.","href":"learn/finance/f04/discounting-cash-flows/"},{"id":"t:net proceed","kind":"term","course":"f00","lesson":"market-participants","front":"Net proceeds","back":"What the issuer receives from an offering after the underwriting spread: shares sold × offer price × (1 − spread).","href":"learn/finance/f00/market-participants/"},{"id":"t:net realisable value","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Net realisable value","back":"For inventory, the estimated selling price in the ordinary course of business less the estimated costs of completion and of making the sale.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:net receivable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Net receivables","back":"Accounts receivable minus the allowance for doubtful accounts: the amount a business expects to collect. Also called the net realisable value of receivables.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:net revenue","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Net revenue","back":"Gross revenue less sales returns and allowances and sales discounts; also called net sales. The first total on a multi-step income statement.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:new task","kind":"term","course":"m01","lesson":"business-buying","front":"New task","back":"A buying situation in which an organisation buys something for the first time, with the most uncertainty, information search and people involved.","href":"learn/marketing/m01/business-buying/"},{"id":"t:no-par stock","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"No-par stock","back":"Shares issued without a par value. Unless the board assigns a stated value, the whole amount received is credited to Common Stock.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:nominal amount","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Nominal amount","back":"An amount of money in the dollars of the date it is paid or received, with no adjustment for inflation. Also called current dollars.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:nominal annual rate","kind":"term","course":"f04","lesson":"effective-annual-rates","front":"Nominal annual rate","back":"A yearly interest rate quoted without compounding: the periodic rate multiplied by the number of periods in a year. An APR in its simple sense is a nominal annual rate.","href":"learn/finance/f04/effective-annual-rates/"},{"id":"t:nominal return","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Nominal return","back":"The percentage change in the number of dollars an investment is worth, before allowing for inflation.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:nominal variable","kind":"term","course":"b01","lesson":"data-types","front":"Nominal variable","back":"A categorical variable whose categories have no natural order, such as region or product. Supports equality, counts and the mode.","href":"learn/analytics/b01/data-types/"},{"id":"t:non-breaking space","kind":"term","course":"b02","lesson":"text-and-categories","front":"Non-breaking space","back":"A space character (Unicode U+00A0) that looks like an ordinary space but is a different character, often left behind by web pages and documents, and not removed by some trim functions.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:non-compensatory rule","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Non-compensatory rule","back":"A choice rule under which a weakness on one attribute can’t be made up by strength on another, such as a cut-off every option must pass (conjunctive) or choosing the best option on the most important attribute (lexicographic).","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:non-gaap financial measure","kind":"term","course":"f02","lesson":"income-statement","front":"Non-GAAP financial measure","back":"A measure of financial performance or position, such as EBITDA, that is not defined by the accounting framework used in the financial statements.","href":"learn/finance/f02/income-statement/"},{"id":"t:non-response bia","kind":"term","course":"b01","lesson":"data-collection","front":"Non-response bias","back":"Systematic error that arises when the people who answer a survey differ, in what is being measured, from those who don’t.","href":"learn/analytics/b01/data-collection/"},{"id":"t:noncash expense","kind":"term","course":"f02","lesson":"indirect-method","front":"Noncash expense","back":"An expense that reduces net income without any cash payment in the period, such as depreciation, amortisation or an impairment loss. The indirect method adds it back.","href":"learn/finance/f02/indirect-method/"},{"id":"t:noncash investing and financing activity","kind":"term","course":"f02","lesson":"cash-flow-statement","front":"Noncash investing and financing activities","back":"Investing and financing transactions that change assets or liabilities without any cash moving, such as buying equipment by signing a note or converting debt into stock. They are left out of the statement of cash flows and disclosed separately.","href":"learn/finance/f02/cash-flow-statement/"},{"id":"t:noncurrent asset","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Noncurrent asset","back":"Any asset that is not current, typically one the business expects to use for more than a year, such as equipment, vehicles, buildings and land.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:noncurrent liability","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Noncurrent liability","back":"An obligation not due for settlement within one year or the operating cycle, such as the later instalments of a long-term loan.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:normal balance","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Normal balance","back":"The side on which an account records increases, and so the side on which its balance usually sits: debit for assets, expenses and dividends; credit for liabilities, equity, revenue and contra-asset accounts.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:note receivable","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Note receivable","back":"A written promise by a customer or borrower to pay a stated sum on a stated date, usually with interest.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:npv profile","kind":"term","course":"f04","lesson":"discounting-cash-flows","front":"NPV profile","back":"A graph of a decision’s net present value against the discount rate. For a conventional project it slopes down and crosses zero at the internal rate of return.","href":"learn/finance/f04/discounting-cash-flows/"},{"id":"t:nudge","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Nudge","back":"Any aspect of how a choice is presented that changes behaviour predictably without forbidding options or significantly changing incentives (Thaler and Sunstein, 2008). A nudge can help or harm the person nudged.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:numerical variable","kind":"term","course":"b01","lesson":"data-types","front":"Numerical variable","back":"A variable whose values are amounts found by counting or measuring, such as visits, packs ordered or an order total. It is discrete or continuous.","href":"learn/analytics/b01/data-types/"},{"id":"t:objective","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Objective","back":"In an optimisation model, the quantity to be maximised or minimised, such as total contribution; in Solver, the formula in the objective cell.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:objective-and-task method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Objective-and-task method","back":"Setting the promotion budget by defining specific objectives, listing the tasks needed to achieve them and adding up the cost of those tasks.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:observation","kind":"term","course":"b01","lesson":"data-types","front":"Observation","back":"One row of a dataset: all the values recorded for one instance of the unit of observation. Also called a record.","href":"learn/analytics/b01/data-types/"},{"id":"t:omnichannel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Omnichannel","back":"Managing several channels as one system from the customer’s point of view, with consistent prices, promotions, stock information and service across them.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:one-hot encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"One-hot encoding","back":"Encoding a categorical variable with k categories as k columns of 0s and 1s, with a 1 in the column of each row’s category.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:operating activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Operating activities","back":"Cash flows from running the business: receipts from customers and payments to suppliers, employees and others; under US GAAP also interest paid and received.","href":"learn/finance/f01/financial-statements/"},{"id":"t:operating cash flow","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Operating cash flow","back":"The cash brought in by a business’s day-to-day activities minus the cash those activities paid out, over a period.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:operating cycle","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Operating cycle","back":"The average time between acquiring the materials or services a business works with and collecting cash from the customers it sells to.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:operating expense","kind":"term","course":"f02","lesson":"income-statement","front":"Operating expenses","back":"The costs of running a business that are not part of cost of sales, such as selling, general and administrative costs, rent and depreciation.","href":"learn/finance/f02/income-statement/"},{"id":"t:operating income","kind":"term","course":"f02","lesson":"income-statement","front":"Operating income","back":"Gross profit less operating expenses: what a business earns from its ordinary activities before interest, other non-operating items and income tax. Also called income from operations or operating profit. Under US GAAP it includes gains and losses on selling long-lived assets.","href":"learn/finance/f02/income-statement/"},{"id":"t:operating working capital","kind":"term","course":"f02","lesson":"indirect-method","front":"Operating working capital","back":"The current assets other than cash and the current liabilities that arise from day-to-day operations: receivables, inventory, prepayments, accounts payable, accrued expenses, unearned revenue and income taxes payable. Current items that belong to investing or financing, such as short-term investments, the current portion of long-term debt and dividends payable, are excluded.","href":"learn/finance/f02/indirect-method/"},{"id":"t:operational definition","kind":"term","course":"b01","lesson":"business-questions","front":"Operational definition","back":"An exact statement of how a concept is measured: which records count, from which source, by which rule and over which period, so that two people applying it to the same data get the same number.","href":"learn/analytics/b01/business-questions/"},{"id":"t:opinion leader","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Opinion leader","back":"A person whose views others in a group seek out and follow because of their knowledge, experience or standing, not necessarily their wealth or education.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:opportunity cost","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Opportunity cost","back":"The value of the best alternative given up when a choice is made, such as the salary an owner forgoes to run her own business.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:optimisation","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Optimisation","back":"Finding the choice that gives the best value of a goal, such as the highest profit or the lowest cost, while meeting the constraints on the decision.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:order of liquidity","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Order of liquidity","back":"Listing assets from the most easily turned into cash (cash, then receivables, inventory and prepayments) to the least, and liabilities in roughly the order they fall due.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:ordinal encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Ordinal encoding","back":"Encoding an ordered categorical variable as integers that follow its order, in one column. It assumes equal steps between levels.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:ordinal variable","kind":"term","course":"b01","lesson":"data-types","front":"Ordinal variable","back":"A categorical variable whose categories have a meaningful order but no fixed distance between them, such as a 1–5 rating. Also supports the median and percentiles.","href":"learn/analytics/b01/data-types/"},{"id":"t:ordinary annuity","kind":"term","course":"f04","lesson":"annuities","front":"Ordinary annuity","back":"An annuity whose payments are made at the end of each period, so the first payment comes one period from now. The default meaning of “annuity”.","href":"learn/finance/f04/annuities/"},{"id":"t:other comprehensive income","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Other comprehensive income","back":"Income and expenses that accounting standards require to be reported outside profit or loss and accumulated in a separate part of equity, such as revaluation increases on property under IAS 16.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:other income and expense","kind":"term","course":"f02","lesson":"income-statement","front":"Other income and expenses","back":"Income and expenses that do not arise from a business’s main operations, such as interest revenue and interest expense. Shown after operating income. Under US GAAP, gains and losses on selling long-lived assets are not among them: they are included in operating income.","href":"learn/finance/f02/income-statement/"},{"id":"t:outlier","kind":"term","course":"b02","lesson":"outliers","front":"Outlier","back":"An observation that lies an abnormal distance from the other values in a dataset; it may be an error or a genuine extreme.","href":"learn/analytics/b02/outliers/"},{"id":"t:outstanding balance","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Outstanding balance","back":"The principal still owed on a loan at a given date: the present value of the remaining payments at the loan rate.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:outstanding share","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Outstanding shares","back":"Shares that have been issued and are held by shareholders, that is, issued shares less any held as treasury stock. They carry votes and receive dividends.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:over-the-counter market","kind":"term","course":"f00","lesson":"financial-markets","front":"Over-the-counter market","back":"A market without a central marketplace, in which trades are negotiated between two parties, usually with a dealer (OTC).","href":"learn/finance/f00/financial-markets/"},{"id":"t:ownership category","kind":"term","course":"f00","lesson":"market-participants","front":"Ownership category","back":"For FDIC insurance, the capacity in which deposits are held (single, joint, certain retirement, trust, business, and others); each category at each bank is insured separately.","href":"learn/finance/f00/market-participants/"},{"id":"t:p-value","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"P-value","back":"The probability of a result at least as extreme as the one observed if the null hypothesis (for a regression coefficient, that it is 0) were true. A small p-value is evidence against the null hypothesis, not the probability that it is true.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:p/e ratio","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"P/E ratio","back":"Price-to-earnings ratio: share price divided by earnings per share, or market capitalisation divided by net income.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:packaging","kind":"term","course":"m02","lesson":"product-decisions","front":"Packaging","back":"The container and wrapping of a product, which protects it, makes it convenient, informs the buyer and promotes it at the point of choice.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:pairwise deletion","kind":"term","course":"b02","lesson":"missing-values","front":"Pairwise deletion","back":"Computing each statistic from all rows that have the values it needs, so different statistics use different rows; also called available-case analysis.","href":"learn/analytics/b02/missing-values/"},{"id":"t:panel data","kind":"term","course":"b01","lesson":"data-types","front":"Panel data","back":"Data on the same units at several points in time, such as each customer’s spending in each month. Also called longitudinal data.","href":"learn/analytics/b01/data-types/"},{"id":"t:par value","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Par value","back":"A nominal amount per share set in a corporation’s charter, often a cent or less, with legal rather than economic meaning. In states such as Delaware, shares with a par value can’t be issued for less than par.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:patent","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Patent","back":"An exclusive legal right to make, use and sell an invention. A US utility patent runs for 20 years from the date the application was filed.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:payment date","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Payment date","back":"The date a declared dividend is paid, settling the dividends payable.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:penetration pricing","kind":"term","course":"m02","lesson":"price-response","front":"Penetration pricing","back":"Launching a new product at a low price to win many buyers quickly, accepting a low margin per unit in exchange for volume.","href":"learn/marketing/m02/price-response/"},{"id":"t:pension fund","kind":"term","course":"f00","lesson":"market-participants","front":"Pension fund","back":"A fund that invests contributions from employers and employees to pay retirement income.","href":"learn/finance/f00/market-participants/"},{"id":"t:percentage change","kind":"term","course":"b01","lesson":"summarising-data","front":"Percentage change","back":"The change in a value divided by its starting value, times 100: (new − old) ÷ old × 100. The starting value is the base.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:percentage point","kind":"term","course":"b01","lesson":"summarising-data","front":"Percentage point","back":"The unit for the difference between two percentages: a change from 8% to 5% is a fall of 3 percentage points (and a relative fall of 37.5%).","href":"learn/analytics/b01/summarising-data/"},{"id":"t:percentage-of-sales method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Percentage-of-sales method","back":"Setting the promotion budget as a fixed percentage of past or forecast sales.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:percentile","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Percentile","back":"The value with a given percentage of the sorted data at or below it, interpolating between values when needed; the 25th, 50th and 75th percentiles are the quartiles.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:perception","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Perception","back":"The process by which a person selects, organises and interprets information to form a meaningful picture of the world.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:performance obligation","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Performance obligation","back":"A promise in a contract to transfer a distinct good or service to a customer. Revenue is recognised as each one is satisfied, at a point in time or over time.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:periodic inventory system","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Periodic inventory system","back":"A system that records purchases in a Purchases account and calculates cost of goods sold only at the end of the period, from a physical count of ending inventory.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:periodic rate","kind":"term","course":"f04","lesson":"effective-annual-rates","front":"Periodic rate","back":"The interest rate charged or paid for one compounding period: the nominal annual rate divided by the number of periods in a year.","href":"learn/finance/f04/effective-annual-rates/"},{"id":"t:permanent account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Permanent account","back":"An account whose balance carries forward from one period to the next: every asset, liability and equity account, including contra-asset accounts. Also called a real account.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:perpetual inventory system","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Perpetual inventory system","back":"A system that updates the Inventory account with every purchase and records cost of goods sold with every sale.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:perpetuity","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Perpetuity","back":"A stream of equal payments at equal intervals that continues for ever. Its present value is the payment divided by the rate per period, C ÷ r.","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:perpetuity due","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Perpetuity due","back":"A perpetuity whose first payment is made today. Worth the payment plus an ordinary perpetuity: C + C ÷ r.","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:personal data","kind":"term","course":"b01","lesson":"data-collection","front":"Personal data","back":"Under the UK GDPR, any information relating to an identified or identifiable natural person: someone who can be identified directly or indirectly, for example from a name, an identification number, location data or an online identifier.","href":"learn/analytics/b01/data-collection/"},{"id":"t:personal finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Personal finance","back":"The branch of finance concerned with the decisions of individuals and households: budgeting, saving, borrowing, insurance and retirement.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:personal selling","kind":"term","course":"m02","lesson":"promotion-mix","front":"Personal selling","back":"Person-to-person communication by a salesperson aimed at making sales and building customer relationships.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:pestel","kind":"term","course":"m01","lesson":"situation-analysis","front":"PESTEL","back":"A checklist for scanning the macroenvironment: political, economic, social, technological, environmental and legal factors. Variants include PEST, STEEP and STEEPLE.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:pivot","kind":"term","course":"b02","lesson":"transforming-data","front":"Pivot","back":"Reshaping from long to wide format: the values of one column become column headers. It needs exactly one value for each pair of row label and column label.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:pivot cache","kind":"term","course":"b03","lesson":"pivot-tables","front":"Pivot cache","back":"The copy of the source data that a PivotTable summarises; the PivotTable shows new or corrected data only after it is refreshed.","href":"learn/analytics/b03/pivot-tables/"},{"id":"t:pivottable","kind":"term","course":"b03","lesson":"pivot-tables","front":"PivotTable","back":"Excel’s interactive summary table: it groups the records of a source by the fields placed in its Rows and Columns areas and aggregates a field placed in its Values area, rebuilding when fields are moved.","href":"learn/analytics/b03/pivot-tables/"},{"id":"t:population","kind":"term","course":"b01","lesson":"data-collection","front":"Population","back":"Everything a question is about: all the people, things or events whose characteristics you want to know.","href":"learn/analytics/b01/data-collection/"},{"id":"t:positioning","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Positioning","back":"The place a business wants its offer to occupy in target customers’ minds, relative to competing offers.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:post-closing trial balance","kind":"term","course":"f01","lesson":"closing-entries","front":"Post-closing trial balance","back":"A trial balance prepared after the closing entries are posted. It contains only permanent accounts and confirms that debits equal credits as the next period begins.","href":"learn/finance/f01/closing-entries/"},{"id":"t:post-purchase dissonance","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Post-purchase dissonance","back":"Discomfort after a purchase when the buyer doubts the choice, often because the rejected options had attractive features; also called buyer’s remorse.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:posting","kind":"term","course":"f01","lesson":"general-ledger","front":"Posting","back":"Copying each line of a journal entry to the ledger account it names, on the same side, with the same date and amount.","href":"learn/finance/f01/general-ledger/"},{"id":"t:posting reference","kind":"term","course":"f01","lesson":"general-ledger","front":"Posting reference","back":"A cross-reference written during posting: the journal page in the ledger account, and the account number in the journal, so any amount can be traced in both directions.","href":"learn/finance/f01/general-ledger/"},{"id":"t:power query","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Power Query","back":"Excel’s tool for importing and reshaping data (Data › Get & Transform Data), which records each transformation as a step and reruns all of them when the query is refreshed.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:predictive analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Predictive analytics","back":"Analytics that answers “what will happen?” by using past patterns to estimate future or unknown values, such as a forecast of demand or the probability that a customer orders again.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:preferred stock","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Preferred stock","back":"A class of shares that pays a fixed dividend, usually stated as a percentage of par value, and ranks ahead of common stock for dividends and in a liquidation, usually without voting rights. Called preference shares in the UK.","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:prepaid expense","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Prepaid expense","back":"A cost paid in advance for benefits to be received in later periods, such as insurance or rent. It is an asset until it is used up.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:prepayment","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Prepayment","back":"Repaying principal earlier than the schedule requires, which reduces the interest charged and, if the payment is kept the same, shortens the loan.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:prepayment penalty","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Prepayment penalty","back":"A fee some loan agreements charge if the borrower repays all or a large part of the loan early.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:prescriptive analytic","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Prescriptive analytics","back":"Analytics that answers “what should we do?” by combining predictions with the options, costs, constraints and goals of a decision to recommend an action.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:present value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Present value","back":"What an amount to be received in the future is worth today, at a given discount rate: PV = FV ÷ (1 + r)ⁿ.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:price build-up","kind":"term","course":"m02","lesson":"distribution-channels","front":"Price build-up","back":"A calculation that traces a product’s price through each level of the channel, from what the producer receives to what the final customer pays.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:price ceiling","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Price ceiling","back":"The highest price customers would pay, set by the value they place on the product compared with their alternatives.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:price discovery","kind":"term","course":"f00","lesson":"financial-markets","front":"Price discovery","back":"The process by which trading among many buyers and sellers produces a price that reflects their combined information and expectations.","href":"learn/finance/f00/financial-markets/"},{"id":"t:price discrimination","kind":"term","course":"m02","lesson":"price-response","front":"Price discrimination","back":"Charging different customers different prices for the same product when the difference does not reflect a difference in cost. Also called segmented pricing.","href":"learn/marketing/m02/price-response/"},{"id":"t:price elasticity of demand","kind":"term","course":"m02","lesson":"price-response","front":"Price elasticity of demand","back":"The percentage change in quantity demanded divided by the percentage change in price. Usually negative; this course keeps the sign, while many texts report the absolute value.","href":"learn/marketing/m02/price-response/"},{"id":"t:price floor","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Price floor","back":"The lowest price worth accepting, set by costs: in the short run the variable cost per unit; in the long run a price that covers all costs at a realistic volume.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:price index","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Price index","back":"A number tracking the cost of a fixed basket of goods and services over time, set to 100 in a base period.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:price premium","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Price premium","back":"The amount by which a firm’s price exceeds a rival’s for a comparable offer, usually as a percentage of the rival’s price.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:price skimming","kind":"term","course":"m02","lesson":"price-response","front":"Price skimming","back":"Launching a new product at a high price to sell first to the buyers who value it most, then lowering the price in steps to reach more buyers.","href":"learn/marketing/m02/price-response/"},{"id":"t:primary data","kind":"term","course":"b01","lesson":"data-types","front":"Primary data","back":"Data collected for the question at hand, such as a survey designed to answer it.","href":"learn/analytics/b01/data-types/"},{"id":"t:primary key","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Primary key","back":"A column, or set of columns, whose values identify each row uniquely: no two rows share a value and none is blank.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:primary market","kind":"term","course":"f00","lesson":"financial-markets","front":"Primary market","back":"The market in which new securities are sold for the first time, with the money going to the issuer.","href":"learn/finance/f00/financial-markets/"},{"id":"t:principal","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Principal","back":"The amount originally borrowed or invested, on which interest is calculated.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:principal (agency)","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Principal (agency)","back":"In an agency relationship, the person whose interests are at stake and who delegates decisions to an agent.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:principal (in a sale)","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Principal (in a sale)","back":"In revenue recognition, a business that controls a good or service before it is transferred to the customer. It recognises revenue at the gross amount the customer pays.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:private company council","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Private Company Council","back":"The body set up in 2012 by the Financial Accounting Foundation, which oversees the FASB, as the FASB’s main advisory body on private-company matters. It develops accounting alternatives that private companies may elect, subject to the FASB’s endorsement.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:product","kind":"term","course":"m02","lesson":"product-decisions","front":"Product","back":"Anything offered to a market to satisfy a want or need: physical goods, services, experiences, places, organisations or ideas.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product concept","kind":"term","course":"m01","lesson":"market-orientation","front":"Product concept","back":"The belief that customers want the best quality, performance and features, so a business should concentrate on continually improving its product.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:product life cycle","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Product life cycle","back":"The typical pattern of a product’s sales and profits over time, from introduction through growth and maturity to decline.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:product line","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line","back":"A group of closely related products that meet similar needs, are sold to similar customers or go through similar channels.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product line depth","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line depth","back":"The number of versions offered of each item in a line, such as sizes, flavours or colours (in Kotler’s convention).","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product line length","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line length","back":"The number of items in a product line (in Kotler’s convention; OpenStax calls this depth).","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix","back":"All the product lines and items a company sells; also called the product portfolio.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix consistency","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix consistency","back":"How closely a company’s product lines are related in end use, production, distribution channels or customers.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix width","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix width","back":"The number of different product lines a company carries.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:production concept","kind":"term","course":"m01","lesson":"market-orientation","front":"Production concept","back":"The belief that customers want offers that are available and affordable, so a business should concentrate on making as much as it can as efficiently as possible.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:promotion mix","kind":"term","course":"m02","lesson":"promotion-mix","front":"Promotion mix","back":"The combination of communication tools (advertising, sales promotion, personal selling, public relations, and direct and digital marketing) a business uses to communicate with its audiences.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:property, plant and equipment","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Property, plant and equipment","back":"Tangible assets a business uses to produce or supply goods and services, rent to others or administer itself, and expects to use for more than one year, such as land, buildings, vehicles and equipment. Also called fixed assets.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:proportion","kind":"term","course":"b01","lesson":"summarising-data","front":"Proportion","back":"A part divided by the whole it belongs to, a number between 0 and 1. Multiplied by 100 it is a percentage.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:pseudonymised","kind":"term","course":"b02","lesson":"data-quality-report","front":"Pseudonymised","back":"Describes data in which direct identifiers such as names or e-mail addresses are replaced by codes, so that records can still be linked but people can’t be identified without separately held information.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:psychological pricing","kind":"term","course":"m02","lesson":"price-response","front":"Psychological pricing","back":"Setting prices with regard to how buyers perceive numbers, for example charm prices just below a round number, or round prices that suggest quality.","href":"learn/marketing/m02/price-response/"},{"id":"t:public business entity","kind":"term","course":"f02","lesson":"gaap-and-ifrs","front":"Public business entity","back":"A US GAAP term for a business that meets any of five criteria, such as filing financial statements with the SEC or having securities traded, listed or quoted on an exchange or an over-the-counter market. Some standards, such as ASU 2024-03, apply only to public business entities.","href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"t:public finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Public finance","back":"The branch of finance (often treated as part of economics) concerned with how governments tax, spend and borrow.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:public relation","kind":"term","course":"m02","lesson":"promotion-mix","front":"Public relations","back":"Building good relationships with a company’s publics and earning favourable coverage, for example through press releases, events and sponsorships.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:pull strategy","kind":"term","course":"m02","lesson":"promotion-mix","front":"Pull strategy","back":"Directing promotion at final customers to create demand that draws the product through the channel.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:purchasing power","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Purchasing power","back":"What a given amount of money can buy. Inflation reduces it.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:push strategy","kind":"term","course":"m02","lesson":"promotion-mix","front":"Push strategy","back":"Directing promotion at channel members, through personal selling and trade promotions, so that they stock, support and sell the product.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:quartile","kind":"term","course":"b01","lesson":"summarising-data","front":"Quartile","back":"One of the three values that divide sorted data into four equal parts: a quarter of the data lie below the first quartile (Q1), half below the second (the median) and three-quarters below the third (Q3).","href":"learn/analytics/b01/summarising-data/"},{"id":"t:quick ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Quick ratio","back":"Cash, short-term investments and receivables divided by current liabilities. It leaves out inventory and prepayments. Also called the acid-test ratio.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:r squared","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"R squared","back":"The share of the variation of y around its mean that a regression accounts for, from 0 to 1; with one X it is the square of the correlation coefficient. Also called the coefficient of determination.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:range","kind":"term","course":"b01","lesson":"summarising-data","front":"Range","back":"The largest value minus the smallest: a measure of spread that depends only on the two extremes.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:range check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Range check","back":"A validation rule that a value lies between a minimum and a maximum.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:rate cap","kind":"term","course":"f04","lesson":"mortgages","front":"Rate cap","back":"A limit on how much an adjustable rate can change at the first reset, at each later reset, or in total over the life of the loan.","href":"learn/finance/f04/mortgages/"},{"id":"t:ratio variable","kind":"term","course":"b01","lesson":"data-types","front":"Ratio variable","back":"A numerical variable with a true zero meaning “none”, so differences and ratios are both meaningful, such as quantity, price or nights stayed.","href":"learn/analytics/b01/data-types/"},{"id":"t:raw data","kind":"term","course":"b02","lesson":"data-quality-report","front":"Raw data","back":"Data exactly as received from their source, before any cleaning or transformation. Kept read-only so that every cleaned version can be rebuilt from them.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:reach","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Reach","back":"The number or percentage of different people in the target audience exposed to a campaign at least once.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:real amount","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Real amount","back":"An amount of money restated in the purchasing power of a chosen base period, by dividing out the inflation since that period. Also called constant dollars.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:real interest rate","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Real interest rate","back":"An interest rate adjusted for inflation: what borrowing really costs, or lending really earns, in purchasing power.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:real return","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Real return","back":"The percentage change in the purchasing power of an investment: (1 + nominal return) ÷ (1 + inflation) − 1.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:reconciliation check","kind":"term","course":"b03","lesson":"dashboards","front":"Reconciliation check","back":"A formula that compares a total shown in a report with the same total calculated another way, such as from the source data or the accounts, and flags any difference.","href":"learn/analytics/b03/dashboards/"},{"id":"t:reference category","kind":"term","course":"b02","lesson":"encoding-categories","front":"Reference category","back":"The category left without a dummy variable. The intercept describes it, and each dummy coefficient is a difference from it. Also called the baseline.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:reference group","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Reference group","back":"A group a person compares themselves with, belongs to, would like to belong to or wants to avoid resembling, whose standards influence what they buy.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:reference price","kind":"term","course":"m02","lesson":"price-response","front":"Reference price","back":"The price a buyer expects or regards as normal for a product, formed largely from past prices, against which an actual price is judged as a gain or a loss.","href":"learn/marketing/m02/price-response/"},{"id":"t:referential integrity","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Referential integrity","back":"The condition that every reference from one table to another (a foreign key) points to a row that exists.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:referral multiplier","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Referral multiplier","back":"The factor by which referrals multiply the customers won directly: 1 ÷ (1 − r) in the long run when each new customer refers r new customers on average (r below 1).","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:refinancing","kind":"term","course":"f04","lesson":"loan-amortisation","front":"Refinancing","back":"Replacing an existing loan with a new one, usually at a lower rate or for a different term, and using the new loan to pay off the old balance.","href":"learn/finance/f04/loan-amortisation/"},{"id":"t:refund liability","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Refund liability","back":"A liability for the amount a business expects to refund to customers, for example for goods it expects to be returned. Revenue is not recognised for that amount.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:regression line","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Regression line","back":"A straight line, ŷ = b₀ + b₁x, fitted to paired data to describe how the average of y changes with x.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:regression to the mean","kind":"term","course":"b01","lesson":"interpreting-results","front":"Regression to the mean","back":"The tendency of unusually high or low measurements, which are partly due to chance, to be followed by measurements closer to the average.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:regular expression","kind":"term","course":"b02","lesson":"text-and-categories","front":"Regular expression","back":"A pattern that describes a set of text strings, used to find, check, extract or replace text.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:relative reference","kind":"term","course":"b03","lesson":"cells-and-formulas","front":"Relative reference","back":"A cell reference without dollar signs, such as A1, which Excel adjusts when the formula is filled or copied, so that it keeps the same position relative to the formula’s cell.","href":"learn/analytics/b03/cells-and-formulas/"},{"id":"t:relevance","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Relevance","back":"The quality of information that is capable of making a difference to users’ decisions, through predictive value, confirmatory value or both. One of the two fundamental qualitative characteristics.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:report form","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Report form","back":"A balance sheet layout with assets listed first and liabilities and equity below them.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:reproducibility","kind":"term","course":"b02","lesson":"data-quality-report","front":"Reproducibility","back":"The property that running the same steps on the same data gives the same result every time.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:request for proposal","kind":"term","course":"m01","lesson":"business-buying","front":"Request for proposal","back":"A formal invitation to suppliers to propose how they would meet a stated need and at what price, used when the buyer wants to compare solutions as well as prices.","href":"learn/marketing/m01/business-buying/"},{"id":"t:reshaping","kind":"term","course":"b02","lesson":"transforming-data","front":"Reshaping","back":"Changing the layout of a table between wide and long format without changing its values.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:residual","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Residual","back":"The actual value of y minus the value the regression line predicts for it.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:residual value","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Residual value","back":"The amount a business expects to receive for an asset at the end of its useful life. Also called salvage value.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:response rate","kind":"term","course":"b01","lesson":"data-collection","front":"Response rate","back":"The share of the people invited to a survey who answered it: responses ÷ people invited × 100. Say whether invitations that never arrived are counted.","href":"learn/analytics/b01/data-collection/"},{"id":"t:retailer","kind":"term","course":"m02","lesson":"distribution-channels","front":"Retailer","back":"An intermediary that sells goods to final consumers.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:retained earning","kind":"term","course":"f01","lesson":"accounting-equation","front":"Retained earnings","back":"Cumulative net income kept in the business since it began, after dividends.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:retention rate","kind":"term","course":"m01","lesson":"customer-value","front":"Retention rate","back":"The share of customers at the start of a period who are still customers at its end.","href":"learn/marketing/m01/customer-value/"},{"id":"t:revaluation model","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Revaluation model","back":"An IFRS option (IAS 16) to carry a whole class of property, plant and equipment at fair value at the revaluation date, less later depreciation and impairment, with increases taken to other comprehensive income. Not permitted under US GAAP.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:revenue","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Revenue","back":"Increases in assets, or decreases in liabilities, from delivering goods or services to customers in the business’s ordinary activities. Revenue increases equity.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:revenue recognition principle","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Revenue recognition principle","back":"Revenue is recognised when, or as, the business satisfies a performance obligation by transferring control of a promised good or service to the customer, at the amount it expects to be entitled to (ASC 606, IFRS 15).","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:reversal of entry","kind":"term","course":"f01","lesson":"trial-balance","front":"Reversal of entries","back":"An error in which the correct accounts and amount are used but the debit and credit are swapped.","href":"learn/finance/f01/trial-balance/"},{"id":"t:reversing entry","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Reversing entry","back":"An optional entry made on the first day of a new period that is the exact opposite of an accrual adjustment made at the end of the previous period, so that the later payment or receipt can be recorded in the routine way.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:right-skewed","kind":"term","course":"b02","lesson":"skewed-data","front":"Right-skewed","back":"Having a long tail of large values; the mean is usually above the median. Also called positively skewed.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:risk","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk","back":"In finance, the possibility that an outcome will differ from what is expected, for better or for worse.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk aversion","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk aversion","back":"Preferring a certain amount to a gamble with the same expected value. Most savers and investors are assumed to be risk averse.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk premium","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk premium","back":"The extra expected return that investors demand for bearing risk: the expected return on a risky investment minus the risk-free rate.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk shifting","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Risk shifting","back":"Switching to riskier projects after borrowing, which can raise the expected payoff to shareholders while lowering the expected payoff to lenders. Also called asset substitution.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:risk-free rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk-free rate","back":"The return on an investment whose payoff is certain, such as an insured short-term deposit or a short-term loan to a government that is almost sure to repay.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:roa","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"ROAS","back":"Return on ad spend: revenue attributed to a campaign ÷ the campaign’s ad spend. It ignores costs and whether the revenue was caused by the ads.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:robust scaling","kind":"term","course":"b02","lesson":"scaling","front":"Robust scaling","back":"Rescaling a variable as (x − median) ÷ interquartile range, so that extreme values have little influence on the scale.","href":"learn/analytics/b02/scaling/"},{"id":"t:robust statistic","kind":"term","course":"b02","lesson":"outliers","front":"Robust statistic","back":"A summary that a few extreme values can’t move far, such as the median, the interquartile range or the median absolute deviation.","href":"learn/analytics/b02/outliers/"},{"id":"t:roll-forward","kind":"term","course":"f02","lesson":"linking-the-statements","front":"Roll-forward","back":"A check or schedule that starts from an account’s opening balance, adds and subtracts the period’s movements and arrives at its closing balance, with each movement traced to another statement or to the ledger.","href":"learn/finance/f02/linking-the-statements/"},{"id":"t:root cause","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Root cause","back":"A cause which, if removed, would prevent a problem from recurring. Many problems have several.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:root-cause analysi","kind":"term","course":"b01","lesson":"problem-solving-frameworks","front":"Root-cause analysis","back":"A structured search for the underlying causes of a problem, rather than its symptoms, so that fixing them prevents it from recurring.","href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"t:row explosion","kind":"term","course":"b02","lesson":"transforming-data","front":"Row explosion","back":"The multiplication of rows in a join when a key value appears more than once in the other table. Totals computed from the joined table are inflated.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:rule of 72","kind":"term","course":"f04","lesson":"simple-and-compound-interest","front":"Rule of 72","back":"A shortcut for doubling time: about 72 divided by the percentage rate per period. Close for rates between about 2% and 15%; exact near 7.85%.","href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"t:sales discount","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Sales discount","back":"A reduction of the amount owed that a seller offers for prompt payment, for example 2% off if the invoice is paid within 10 days (2/10, n/30). Recorded in a contra-revenue account.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:sales promotion","kind":"term","course":"m02","lesson":"promotion-mix","front":"Sales promotion","back":"Short-term incentives to encourage buying or selling now, aimed at consumers (coupons, samples, price cuts) or at the trade (allowances, display payments).","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:sales returns and allowance","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Sales Returns and Allowances","back":"A contra-revenue account for refunds and credits given to customers who return goods or accept a price reduction for unsatisfactory goods.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:sample","kind":"term","course":"b01","lesson":"data-collection","front":"Sample","back":"The part of a population that is actually observed or asked, used to learn about the whole.","href":"learn/analytics/b01/data-collection/"},{"id":"t:sampling bia","kind":"term","course":"b01","lesson":"data-collection","front":"Sampling bias","back":"Systematic error that arises when some members of the population are less likely than others to be included in the sample.","href":"learn/analytics/b01/data-collection/"},{"id":"t:sampling error","kind":"term","course":"b01","lesson":"data-collection","front":"Sampling error","back":"The chance difference between a sample’s result and the population’s, which arises because only part of the population was observed. It shrinks as the sample grows.","href":"learn/analytics/b01/data-collection/"},{"id":"t:sampling frame","kind":"term","course":"b01","lesson":"data-collection","front":"Sampling frame","back":"The list or source from which a sample is actually drawn, such as a customer e-mail list. Anyone missing from the frame can’t be sampled.","href":"learn/analytics/b01/data-collection/"},{"id":"t:scarcity","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Scarcity","back":"The condition that resources such as time, money, labour and materials are limited relative to what people want, so every use of a resource means giving up another.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:scatter chart","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Scatter chart","back":"A chart with two value axes that plots each observation as a point at its x and y values, used to show the relationship between two numeric variables. Also called an XY chart.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:scenario","kind":"term","course":"b01","lesson":"four-kinds-of-analytics","front":"Scenario","back":"One possible future, described by the values of the uncertain inputs (such as low, medium or high demand), often with a probability attached.","href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"t:scenario manager","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Scenario Manager","back":"An Excel what-if tool that saves named sets of values for up to 32 changing cells, substitutes a chosen set into the sheet and summarises the scenarios’ results side by side.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:seasonality","kind":"term","course":"b01","lesson":"interpreting-results","front":"Seasonality","back":"A regular pattern that repeats at the same time each year (or week, or day), such as gift buying in December.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:sec","kind":"term","course":"f00","lesson":"market-participants","front":"SEC","back":"The Securities and Exchange Commission: the US federal agency, founded in 1934, that protects investors, keeps securities markets fair, orderly and efficient, and facilitates capital formation, and has legal authority over the financial reporting of public companies.","href":"learn/finance/f00/market-participants/"},{"id":"t:secondary axi","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Secondary axis","back":"A second value axis, usually on the right of a chart, with its own scale for one or more series.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:secondary data","kind":"term","course":"b01","lesson":"data-types","front":"Secondary data","back":"Data that already exists because it was collected for another purpose, such as transaction records or official statistics, reused for a new question.","href":"learn/analytics/b01/data-types/"},{"id":"t:secondary market","kind":"term","course":"f00","lesson":"financial-markets","front":"Secondary market","back":"The market in which existing securities are resold between investors; the issuer receives none of the money.","href":"learn/finance/f00/financial-markets/"},{"id":"t:security","kind":"term","course":"f00","lesson":"financial-markets","front":"Security","back":"A financial asset that can be bought and sold, such as a share or a bond.","href":"learn/finance/f00/financial-markets/"},{"id":"t:segregation of duty","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Segregation of duties","back":"An internal control that divides the authorisation, recording and custody of assets for a transaction among different people, so that no one person can both commit and conceal an error or a theft.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:selective attention","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Selective attention","back":"The tendency to notice only a small share of the messages and stimuli around us, mostly those related to a current need or interest.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:selective distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Selective distribution","back":"Placing a product in more than one but fewer than all of the outlets that would stock it, chosen for their fit with the product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:self-selected sample","kind":"term","course":"b01","lesson":"data-collection","front":"Self-selected sample","back":"A sample made up of the people who choose to take part, such as everyone who answers a link posted online. Also called a voluntary-response sample; people with strong views tend to be over-represented.","href":"learn/analytics/b01/data-collection/"},{"id":"t:selling concept","kind":"term","course":"m01","lesson":"market-orientation","front":"Selling concept","back":"The belief that customers won’t buy enough unless persuaded, so a business should sell and promote hard what it has already decided to make.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:semi-structured data","kind":"term","course":"b01","lesson":"data-types","front":"Semi-structured data","back":"Data that labels its parts, such as the named fields of a JSON record or an e-mail’s headers, without forcing every record into the same columns.","href":"learn/analytics/b01/data-types/"},{"id":"t:sensitivity analysi","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Sensitivity analysis","back":"Measuring how much a model’s output changes when an input changes, usually one input at a time, to find the assumptions that matter most.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:separation of ownership and control","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Separation of ownership and control","back":"The situation in most large companies, in which the shareholders who own the company hire professional managers to run it.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:serial date","kind":"term","course":"b02","lesson":"types-and-formats","front":"Serial date","back":"A date stored as a count of days from a fixed starting point, as spreadsheets do. In Excel’s 1900 date system, 1 January 1900 is serial number 1.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:shadow price","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Shadow price","back":"In a linear programme without integer constraints, the change in the optimal objective per unit increase in a constraint’s limit, valid over a stated range.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:shareholder view","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Shareholder view","back":"The view that managers, as agents of the owners, should run the company to maximise its value for shareholders, within the law and ethical custom.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:shopping product","kind":"term","course":"m02","lesson":"product-decisions","front":"Shopping product","back":"A consumer product bought less often, after comparing quality, price and style across a few outlets.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:short selling","kind":"term","course":"f00","lesson":"market-participants","front":"Short selling","back":"Selling borrowed securities in the hope of buying them back later at a lower price and returning them.","href":"learn/finance/f00/market-participants/"},{"id":"t:shrinkage","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Shrinkage","back":"Inventory lost to theft, damage, spoilage or recording error, found when a physical count is lower than the records.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:simple interest","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Simple interest","back":"Interest calculated on the original principal only, so it is the same every period: principal × rate × time.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:simple random sample","kind":"term","course":"b01","lesson":"data-collection","front":"Simple random sample","back":"A sample chosen so that every group of the same size in the frame is equally likely to be selected, for example by drawing customer numbers at random.","href":"learn/analytics/b01/data-collection/"},{"id":"t:simpsons paradox","kind":"term","course":"b01","lesson":"interpreting-results","front":"Simpson’s paradox","back":"A relationship that holds within each of several groups but disappears or reverses when the groups are combined, usually because the groups’ sizes or mix differ.","href":"learn/analytics/b01/interpreting-results/"},{"id":"t:single-step income statement","kind":"term","course":"f02","lesson":"income-statement","front":"Single-step income statement","back":"An income statement that adds up all revenues and all expenses and subtracts once to give net income, with no intermediate subtotals.","href":"learn/finance/f02/income-statement/"},{"id":"t:situation analysi","kind":"term","course":"m01","lesson":"situation-analysis","front":"Situation analysis","back":"A structured review of a business’s current position (its customers, competitors, wider environment and its own strengths and weaknesses) used as the starting point of a marketing plan.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:skewness","kind":"term","course":"b02","lesson":"skewed-data","front":"Skewness","back":"A measure of the asymmetry of a distribution: positive for a long right tail, negative for a long left tail, near 0 for symmetric data.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:slack","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Slack","back":"The unused part of a constraint at a solution: its limit minus what the solution uses.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:slicer","kind":"term","course":"b03","lesson":"pivot-tables","front":"Slicer","back":"An Excel panel of buttons that filters a table or PivotTable and shows which items are selected; one slicer can control several PivotTables that share the same data source.","href":"learn/analytics/b03/pivot-tables/"},{"id":"t:slide error","kind":"term","course":"f01","lesson":"trial-balance","front":"Slide error","back":"An error in which the decimal point is misplaced, so every digit shifts, such as $350 written as $35. When it makes the totals differ, the difference is a multiple of 9.","href":"learn/finance/f01/trial-balance/"},{"id":"t:slotting fee","kind":"term","course":"m02","lesson":"distribution-channels","front":"Slotting fee","back":"A payment from a supplier to a retailer to have a new product placed on its shelves or in its warehouse; also called a slotting allowance. Listing fees are similar charges for being stocked.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:smart objective","kind":"term","course":"b01","lesson":"business-questions","front":"SMART objective","back":"An objective that is Specific, Measurable, Achievable, Relevant and Time-bound. Sources expand some letters differently: Doran’s 1981 original used Assignable, Realistic and Time-related, and some guides use Attainable for A.","href":"learn/analytics/b01/business-questions/"},{"id":"t:social class","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Social class","back":"A relatively lasting division of a society whose members have similar income, occupation and education, and often similar values.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:societal marketing concept","kind":"term","course":"m01","lesson":"market-orientation","front":"Societal marketing concept","back":"The belief that a business should satisfy customers in ways that also protect the long-term interests of society and the environment.","href":"learn/marketing/m01/market-orientation/"},{"id":"t:solvency","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Solvency","back":"The ability to meet all obligations over the long run, because assets are worth more than everything owed.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:solver","kind":"term","course":"b03","lesson":"what-if-analysis","front":"Solver","back":"An Excel add-in that chooses the values of several decision-variable cells to maximise, minimise or set the value of an objective cell, subject to constraints.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:source document","kind":"term","course":"f01","lesson":"journal-entries","front":"Source document","back":"The original record of a business event, such as an invoice, receipt, bank statement, contract or payroll record, that provides the evidence for a journal entry. Also called an original source.","href":"learn/finance/f01/journal-entries/"},{"id":"t:sparkline","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Sparkline","back":"A tiny chart inside a single worksheet cell that shows the trend of a row or column of numbers.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:specialty product","kind":"term","course":"m02","lesson":"product-decisions","front":"Specialty product","back":"A consumer product with unique features or a brand identity for which buyers make a special effort and compare little.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:spill","kind":"term","course":"b03","lesson":"lookups","front":"Spill","back":"What a formula that returns several values does in Excel for Microsoft 365, Excel 2021 and Excel 2024: the results fill the neighbouring cells, the spill range, starting from the formula’s cell.","href":"learn/analytics/b03/lookups/"},{"id":"t:square-root transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Square-root transformation","back":"Replacing each value x with √x; a milder correction for right skew that handles zeros.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:stakeholder","kind":"term","course":"b01","lesson":"business-questions","front":"Stakeholder","back":"A person or group who affects or is affected by a decision: those who decide, those who supply the data, those who carry out the result and those the result affects.","href":"learn/analytics/b01/business-questions/"},{"id":"t:stakeholder view","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Stakeholder view","back":"The view that a company should be run for the benefit of all who have a stake in it (customers, employees, suppliers, communities and shareholders).","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:stand-alone selling price","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Stand-alone selling price","back":"The price at which a business would sell a promised good or service separately to a customer. Used to allocate a contract’s transaction price among its performance obligations.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:standard deviation","kind":"term","course":"b01","lesson":"summarising-data","front":"Standard deviation","back":"A measure of spread: roughly the typical distance of values from their mean, calculated as the square root of the average squared distance (dividing by n − 1 for a sample).","href":"learn/analytics/b01/summarising-data/"},{"id":"t:standard error of the mean","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Standard error of the mean","back":"The sample standard deviation divided by the square root of the number of values, s ÷ √n: how much the mean would vary from one sample of that size to another.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:standard error of the regression","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Standard error of the regression","back":"The typical size of a residual, √(residual sum of squares ÷ (n − k − 1)), in the units of y. The Standard Error line in Excel’s regression output.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:standardisation","kind":"term","course":"b02","lesson":"scaling","front":"Standardisation","back":"Rescaling a variable as (x − mean) ÷ standard deviation, so the training data have mean 0 and standard deviation 1. The result is a z-score.","href":"learn/analytics/b02/scaling/"},{"id":"t:statement of cash flow","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of cash flows","back":"The statement of cash received and paid during a period, classified as operating, investing or financing activities, reconciling beginning to ending cash.","href":"learn/finance/f01/financial-statements/"},{"id":"t:statement of changes in equity","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of changes in equity","back":"The statement showing how each component of equity (such as common stock and retained earnings) changed during a period. Often called the statement of stockholders’ equity in the United States.","href":"learn/finance/f01/financial-statements/"},{"id":"t:statement of retained earning","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of retained earnings","back":"A simpler statement, common in introductory texts, showing beginning retained earnings plus net income minus dividends equals ending retained earnings.","href":"learn/finance/f01/financial-statements/"},{"id":"t:statutory tax rate","kind":"term","course":"f02","lesson":"income-statement","front":"Statutory tax rate","back":"The rate of tax set by law, such as the 21% US federal corporate income tax rate.","href":"learn/finance/f02/income-statement/"},{"id":"t:stock option","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Stock options","back":"Rights to buy a company’s shares at a fixed price (the exercise price) during a set period; valuable to the holder only if the share price rises above that price.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:straight rebuy","kind":"term","course":"m01","lesson":"business-buying","front":"Straight rebuy","back":"A buying situation in which an organisation reorders something it has bought before, from the same supplier and on the same terms, with little search or deliberation.","href":"learn/marketing/m01/business-buying/"},{"id":"t:straight-line method","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Straight-line method","back":"A depreciation method that charges the same amount in every full period: (cost − residual value) ÷ useful life.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:structured data","kind":"term","course":"b01","lesson":"data-types","front":"Structured data","back":"Data organised in a fixed layout of rows and columns in which every record has the same fields, such as an order export or a database table.","href":"learn/analytics/b01/data-types/"},{"id":"t:structured reference","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Structured reference","back":"A reference to part of an Excel table by its table and column names, such as Orders[order_total], or [@quantity] for the value in the formula’s own row.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:stuck in the middle","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Stuck in the middle","back":"Porter’s term for a firm that pursues low cost and differentiation at once without achieving either, and so has no clear advantage.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:style","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Style","back":"A basic and distinctive mode of expression, such as casual or formal dress, that can last for generations, going in and out of favour.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:subculture","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Subculture","back":"A group within a culture whose members share values or experiences of their own, such as an ethnic or religious group, a region or a community of enthusiasts.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:subsidiary ledger","kind":"term","course":"f01","lesson":"general-ledger","front":"Subsidiary ledger","back":"A separate ledger giving the detail behind one general-ledger account, such as one account for each customer or each supplier.","href":"learn/finance/f01/general-ledger/"},{"id":"t:substitute","kind":"term","course":"m01","lesson":"situation-analysis","front":"Substitute","back":"A product or service that meets the same customer need in a different way, such as a leased office coffee machine instead of a coffee caterer.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:summary table","kind":"term","course":"b03","lesson":"conditional-sums-and-counts","front":"Summary table","back":"A table of aggregates for each combination of categories, such as order value by month and channel, often built with one formula filled across and down.","href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"t:sunk cost","kind":"term","course":"f00","lesson":"decision-principles","front":"Sunk cost","back":"Money already spent that cannot be recovered whatever is decided now. It is not an incremental cash flow and should be ignored.","href":"learn/finance/f00/decision-principles/"},{"id":"t:sunk cost fallacy","kind":"term","course":"f00","lesson":"decision-principles","front":"Sunk cost fallacy","back":"Letting money already spent influence a decision, typically by continuing a failing project so that past spending is not “wasted”.","href":"learn/finance/f00/decision-principles/"},{"id":"t:survivorship bia","kind":"term","course":"b01","lesson":"data-collection","front":"Survivorship bias","back":"Systematic error from studying only the people or things that passed some filter, such as current customers, while those that dropped out are invisible.","href":"learn/analytics/b01/data-collection/"},{"id":"t:survivorship rule","kind":"term","course":"b02","lesson":"duplicates","front":"Survivorship rule","back":"The rule that decides which record in a group of duplicates is kept, or how their fields are combined: for example first, latest update, most complete or merge.","href":"learn/analytics/b02/duplicates/"},{"id":"t:sustained competitive advantage","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Sustained competitive advantage","back":"An advantage that rivals cannot easily copy or substitute, so that it lasts after they have tried.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:swot analysi","kind":"term","course":"m01","lesson":"situation-analysis","front":"SWOT analysis","back":"A summary of a business’s situation in four lists: internal strengths and weaknesses, and external opportunities and threats.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:systematic risk","kind":"term","course":"f00","lesson":"decision-principles","front":"Systematic risk","back":"Risk that affects nearly all investments at once, such as a recession or a change in interest rates, and cannot be removed by diversification. Also called market or non-diversifiable risk.","href":"learn/finance/f00/decision-principles/"},{"id":"t:t-account","kind":"term","course":"f01","lesson":"debits-and-credits","front":"T-account","back":"A sketch of an account shaped like a letter T, with debits to the left of the vertical line and credits to the right. Used for teaching and analysis; ledgers kept in practice use columns.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:target encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Target encoding","back":"Replacing each category with the average value of the target variable for that category in the training data, ideally smoothed and computed out-of-fold.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:target market","kind":"term","course":"m02","lesson":"marketing-mix","front":"Target market","back":"The group of customers a business chooses to serve with a particular offer.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:target-return pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Target-return pricing","back":"Setting the price that earns a chosen rate of return on the capital invested, at a forecast volume: unit cost + (target return × capital invested) ÷ forecast units.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:tax accounting","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Tax accounting","back":"The branch of accounting that applies tax law to work out a business’s taxable income and the tax it owes.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:temporary account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Temporary account","back":"An account that collects one period’s activity and is closed to retained earnings at the end of the period: revenue, expense and dividends accounts. Also called a nominal account.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:terminal value","kind":"term","course":"f04","lesson":"perpetuities-and-growth","front":"Terminal value","back":"The value, at the end of an explicit forecast period, of all the cash flows expected after it, often estimated as a growing perpetuity: CF(N+1) ÷ (r − g).","href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"t:test market","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Test market","back":"Launching a product or marketing plan in a limited area to measure results before a full roll-out.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:test set","kind":"term","course":"b02","lesson":"scaling","front":"Test set","back":"Data held back from all fitting and used only to estimate how a model will perform on data it has not seen.","href":"learn/analytics/b02/scaling/"},{"id":"t:text string","kind":"term","course":"b03","lesson":"functions-and-logic","front":"Text string","back":"A piece of text in a cell or a formula, whose characters are numbered from 1; in a formula it is written in double quotation marks.","href":"learn/analytics/b03/functions-and-logic/"},{"id":"t:three-statement model","kind":"term","course":"f02","lesson":"linking-the-statements","front":"Three-statement model","back":"A financial model in which the income statement, balance sheet and statement of cash flows are linked, so that a change in one assumption flows through all three and the forecast balance sheet still balances.","href":"learn/finance/f02/linking-the-statements/"},{"id":"t:tidy data","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Tidy data","back":"A layout in which each variable forms a column, each observation forms a row and each type of observational unit forms a table (Wickham, 2014).","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:tie-out","kind":"term","course":"f02","lesson":"linking-the-statements","front":"Tie-out","back":"Confirming that a figure shown in one statement or note agrees with the same figure wherever else it appears and with the ledger.","href":"learn/finance/f02/linking-the-statements/"},{"id":"t:time frame","kind":"term","course":"b01","lesson":"business-questions","front":"Time frame","back":"The period a question covers and the length of the periods it compares, such as calendar months, or four weeks either side of a change.","href":"learn/analytics/b01/business-questions/"},{"id":"t:time period assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Time period assumption","back":"The assumption that a business’s life can be divided into periods, such as months, quarters and years, for which reports are prepared.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:time value of money","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Time value of money","back":"The principle that a dollar available today is worth more than a dollar available later, because today’s dollar can earn a return in the meantime.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:time-series data","kind":"term","course":"b01","lesson":"data-types","front":"Time-series data","back":"Data on one unit at many points in time, kept in time order, such as a shop’s visits month by month.","href":"learn/analytics/b01/data-types/"},{"id":"t:timeline","kind":"term","course":"b03","lesson":"dashboards","front":"Timeline","back":"An Excel filter for the date fields of PivotTables: a slider that selects years, quarters, months or days.","href":"learn/analytics/b03/dashboards/"},{"id":"t:timeliness","kind":"term","course":"b01","lesson":"data-quality","front":"Timeliness","back":"Whether data represents reality at the point in time it is needed and is up to date.","href":"learn/analytics/b01/data-quality/"},{"id":"t:total cost of ownership","kind":"term","course":"m01","lesson":"business-buying","front":"Total cost of ownership","back":"Everything an organisation pays to acquire, use, maintain and eventually replace or dispose of a product over its life, not just the purchase price.","href":"learn/marketing/m01/business-buying/"},{"id":"t:total row","kind":"term","course":"b03","lesson":"tables-and-cleaning","front":"Total row","back":"An optional last row of an Excel table that summarises its columns, by default with SUBTOTAL so that rows hidden by a filter are left out.","href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"t:touchpoint","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Touchpoint","back":"Any point at which a customer meets a brand, such as an advertisement, a search result, a review, a website, a salesperson or a delivery message.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:tows matrix","kind":"term","course":"m01","lesson":"situation-analysis","front":"TOWS matrix","back":"Heinz Weihrich’s (1982) way of turning a SWOT into strategic options by pairing its boxes: strengths with opportunities (SO) or threats (ST), and weaknesses with opportunities (WO) or threats (WT).","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:trade margin","kind":"term","course":"m02","lesson":"distribution-channels","front":"Trade margin","back":"The share of the final selling price kept by the intermediaries, usually quoted as a percentage of that price.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:trade promotion","kind":"term","course":"m02","lesson":"promotion-mix","front":"Trade promotion","back":"A sales promotion aimed at intermediaries, such as funding for a retailer’s temporary price cut or a payment for a display.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:training set","kind":"term","course":"b02","lesson":"scaling","front":"Training set","back":"The part of the data used to fit a model and every data-dependent preparation step, such as scaling parameters and encodings.","href":"learn/analytics/b02/scaling/"},{"id":"t:transaction analysi","kind":"term","course":"f01","lesson":"journal-entries","front":"Transaction analysis","back":"Working out from a source document which accounts a transaction affects, whether each increases or decreases, by how much and on which side, and checking that debits equal credits.","href":"learn/finance/f01/journal-entries/"},{"id":"t:transaction price","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Transaction price","back":"The amount a business expects to be entitled to in exchange for the goods or services promised in a contract, excluding amounts collected for third parties such as some sales taxes.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:transactional data","kind":"term","course":"b01","lesson":"data-collection","front":"Transactional data","back":"Data recorded as a by-product of doing business, such as orders, payments, refunds and bookings.","href":"learn/analytics/b01/data-collection/"},{"id":"t:transposition error","kind":"term","course":"f01","lesson":"trial-balance","front":"Transposition error","back":"An error in which two digits of an amount are swapped, such as 1,600 written as 1,060. When it makes the totals differ, the difference is a multiple of 9.","href":"learn/finance/f01/trial-balance/"},{"id":"t:treasury inflation-protected security","kind":"term","course":"f04","lesson":"inflation-and-real-returns","front":"Treasury Inflation-Protected Securities","back":"US Treasury securities whose principal is adjusted with the Consumer Price Index and which pay a fixed rate of interest on the adjusted principal every six months; at maturity the holder receives the greater of the adjusted and the original principal. Often shortened to TIPS.","href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"t:treasury stock","kind":"term","course":"f02","lesson":"balance-sheet-and-equity","front":"Treasury stock","back":"A corporation’s own shares that it has issued and later bought back and holds. Shown as a deduction from equity; treasury shares have no votes and receive no dividends.","href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"t:trial balance","kind":"term","course":"f01","lesson":"trial-balance","front":"Trial balance","back":"A list of every general-ledger account with a balance at a given date, each balance in its debit or credit column, with both columns totalled to check that they agree.","href":"learn/finance/f01/trial-balance/"},{"id":"t:truncated axi","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Truncated axis","back":"A value axis that starts above zero. It distorts bar lengths, and so the comparisons a bar chart makes.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:tukey fence","kind":"term","course":"b02","lesson":"outliers","front":"Tukey fences","back":"Limits at Q1 − 1.5 × IQR and Q3 + 1.5 × IQR; values outside them are flagged as potential outliers. Outer fences use 3 × IQR.","href":"learn/analytics/b02/outliers/"},{"id":"t:two-way lookup","kind":"term","course":"b03","lesson":"lookups","front":"Two-way lookup","back":"A lookup that finds a value by its row label and its column label at once, for example with INDEX and two MATCH functions.","href":"learn/analytics/b03/lookups/"},{"id":"t:type conversion","kind":"term","course":"b02","lesson":"types-and-formats","front":"Type conversion","back":"Turning a value of one data type into another, for example the text “14.50” into the number 14.5. Deliberate when the format is stated, automatic when software guesses.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:unadjusted trial balance","kind":"term","course":"f01","lesson":"trial-balance","front":"Unadjusted trial balance","back":"A trial balance prepared after the period’s transactions are posted and before the end-of-period adjusting entries.","href":"learn/finance/f01/trial-balance/"},{"id":"t:underwriting","kind":"term","course":"f00","lesson":"market-participants","front":"Underwriting","back":"Managing and selling a new issue of securities for an issuer, including setting the price and finding the buyers.","href":"learn/finance/f00/market-participants/"},{"id":"t:underwriting spread","kind":"term","course":"f00","lesson":"market-participants","front":"Underwriting spread","back":"The difference between the price investors pay for a new issue and the amount per share the issuer receives: the underwriters’ pay.","href":"learn/finance/f00/market-participants/"},{"id":"t:unearned revenue","kind":"term","course":"f01","lesson":"accounting-equation","front":"Unearned revenue","back":"Cash received for goods or services not yet delivered. It is a liability until the business delivers them.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:unicode normalisation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Unicode normalisation","back":"Converting text to one of the standard forms defined in Unicode Standard Annex #15 (NFC, NFD, NFKC, NFKD), so that equivalent characters are stored the same way.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:uniqueness","kind":"term","course":"b01","lesson":"data-quality","front":"Uniqueness","back":"Whether each real-world thing is recorded only once.","href":"learn/analytics/b01/data-quality/"},{"id":"t:unit of analysi","kind":"term","course":"b01","lesson":"business-questions","front":"Unit of analysis","back":"The entity a question is about and the results are reported for, such as the order, the customer, the visit or the day.","href":"learn/analytics/b01/business-questions/"},{"id":"t:unit of observation","kind":"term","course":"b01","lesson":"data-types","front":"Unit of observation","back":"The kind of thing one row describes, such as an order, an order line, a booking or a student.","href":"learn/analytics/b01/data-types/"},{"id":"t:units-of-production method","kind":"term","course":"f02","lesson":"long-lived-assets","front":"Units-of-production method","back":"A depreciation method that charges depreciation in proportion to use: (cost − residual value) ÷ total expected units, times the units used in the period.","href":"learn/finance/f02/long-lived-assets/"},{"id":"t:unsought product","kind":"term","course":"m02","lesson":"product-decisions","front":"Unsought product","back":"A consumer product that people don’t know about or don’t think about buying until a need arises, such as funeral plans or emergency repairs.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:unstructured data","kind":"term","course":"b01","lesson":"data-types","front":"Unstructured data","back":"Data with no predefined data model, such as free text, images, audio and video, which must be coded into variables before it can be counted.","href":"learn/analytics/b01/data-types/"},{"id":"t:unsystematic risk","kind":"term","course":"f00","lesson":"decision-principles","front":"Unsystematic risk","back":"Risk specific to one company or industry, such as a product recall or a lost customer, which can be largely removed by diversification. Also called specific or diversifiable risk.","href":"learn/finance/f00/decision-principles/"},{"id":"t:useful life","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Useful life","back":"The period over which a business expects to use an asset, in years or units of output.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:user (buying centre)","kind":"term","course":"m01","lesson":"business-buying","front":"User (buying centre)","back":"In a buying centre, the people who will use the product or service; they often help define the need and judge the supplier afterwards.","href":"learn/marketing/m01/business-buying/"},{"id":"t:utc","kind":"term","course":"b01","lesson":"data-quality","front":"UTC","back":"Coordinated Universal Time, the reference time scale against which time zones are defined by their offsets, such as −05:00.","href":"learn/analytics/b01/data-quality/"},{"id":"t:validation rule","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Validation rule","back":"A precisely stated condition that a value, a row or a set of rows must satisfy, written so that a computer can test it.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:validity","kind":"term","course":"b01","lesson":"data-quality","front":"Validity","back":"Whether values conform to their definition: the right type, format and range, and a member of the allowed set.","href":"learn/analytics/b01/data-quality/"},{"id":"t:valuation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Valuation","back":"An estimate of what an asset, share or business is worth, made with stated methods and assumptions.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:valuation multiple","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Valuation multiple","back":"A ratio of a measure of value (such as enterprise value or market capitalisation) to a measure of earnings or size (such as EBITDA or net income), used to compare companies.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:value axi","kind":"term","course":"b03","lesson":"charts-and-conditional-formatting","front":"Value axis","back":"A chart axis with a numeric scale. Column, bar and line charts have one; a scatter chart has two.","href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"t:value created","kind":"term","course":"m01","lesson":"competitive-advantage","front":"Value created","back":"The customer’s willingness to pay minus the business’s cost of serving them; the price divides it between the customer and the business.","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:value proposition","kind":"term","course":"m01","lesson":"customer-value","front":"Value proposition","back":"The promise of benefits that gives target customers a reason to choose an offer over the alternatives.","href":"learn/marketing/m01/customer-value/"},{"id":"t:value-based pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Value-based pricing","back":"Setting a price from the customer’s economic value: the price of the next-best alternative plus the value, positive or negative, of the differences from it.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:variable","kind":"term","course":"b01","lesson":"data-types","front":"Variable","back":"One column of a dataset: a characteristic recorded for every observation. Also called a field or an attribute, and in machine learning a feature.","href":"learn/analytics/b01/data-types/"},{"id":"t:variable consideration","kind":"term","course":"f02","lesson":"revenue-recognition","front":"Variable consideration","back":"A part of the transaction price that can change, for example because of discounts, rebates, refunds, price concessions, bonuses or penalties. It is estimated and included only to the extent that a significant reversal of revenue is not expected.","href":"learn/finance/f02/revenue-recognition/"},{"id":"t:variable cost","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Variable cost","back":"A cost incurred for each unit made or sold, so its total rises in proportion to volume: materials, packaging, per-unit fees, delivery.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:variance","kind":"term","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Variance","back":"The average squared distance of values from their mean, dividing by n − 1 for a sample (VAR.S) or by n for a whole population (VAR.P); the square of the standard deviation.","href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"t:variety-seeking buying behaviour","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Variety-seeking buying behaviour","back":"Buying with low involvement among brands that differ: switching brands for a change rather than from dissatisfaction.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:visual hierarchy","kind":"term","course":"b03","lesson":"dashboards","front":"Visual hierarchy","back":"The ordering of a page by position, size and emphasis so that readers see the most important information first.","href":"learn/analytics/b03/dashboards/"},{"id":"t:vrio","kind":"term","course":"m01","lesson":"competitive-advantage","front":"VRIO","back":"Four questions for judging whether a resource or capability can give a sustained advantage: is it valuable, rare, hard to imitate, and is the business organised to exploit it?","href":"learn/marketing/m01/competitive-advantage/"},{"id":"t:want","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Want","back":"The particular form a need takes, shaped by culture, experience and the options a person knows about.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:weighted average","kind":"term","course":"b01","lesson":"summarising-data","front":"Weighted average","back":"An average in which each value counts in proportion to a weight. The mean of all rows equals the average of the group means weighted by group size.","href":"learn/analytics/b01/summarising-data/"},{"id":"t:weighted average cost","kind":"term","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Weighted average cost","back":"A cost formula that assigns every unit the average cost of the goods available: total cost divided by total units. Under a perpetual system the moving average recalculates it after each purchase.","href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"t:weighted competitive-strength scorecard","kind":"term","course":"m01","lesson":"situation-analysis","front":"Weighted competitive-strength scorecard","back":"A comparison of competitors in which each is rated on the factors customers use to choose, each rating is multiplied by the factor’s weight, and the results are added up.","href":"learn/marketing/m01/situation-analysis/"},{"id":"t:weighted-attribute model","kind":"term","course":"m01","lesson":"consumer-decisions","front":"Weighted-attribute model","back":"A compensatory model of choice: each option’s score on each attribute is multiplied by the attribute’s importance weight and the results are added. The option with the highest total is the one the buyer is expected to prefer.","href":"learn/marketing/m01/consumer-decisions/"},{"id":"t:what-if analysi","kind":"term","course":"b03","lesson":"what-if-analysis","front":"What-if analysis","back":"Changing the inputs of a model to see how its outputs respond, or working back from a target output to the input values that reach it.","href":"learn/analytics/b03/what-if-analysis/"},{"id":"t:whitespace","kind":"term","course":"b02","lesson":"text-and-categories","front":"Whitespace","back":"Characters that display as blank space, including the ordinary space, tabs, line breaks and special spaces such as the non-breaking space.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:wholesaler","kind":"term","course":"m02","lesson":"distribution-channels","front":"Wholesaler","back":"An intermediary that buys goods in bulk and resells them to retailers and other businesses rather than to consumers.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:wide format","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Wide format","back":"A layout in which the values of one variable, such as the month, are spread across several columns.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:wildcard character","kind":"term","course":"b03","lesson":"conditional-sums-and-counts","front":"Wildcard character","back":"A character that matches others in a text criterion: ? matches any one character and * any run of characters; a tilde (~) before either matches it literally.","href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"t:willingness to pay","kind":"term","course":"m01","lesson":"what-is-marketing","front":"Willingness to pay","back":"The most a customer would pay for an offer rather than go without it; faced with alternatives, the customer compares what each leaves them.","href":"learn/marketing/m01/what-is-marketing/"},{"id":"t:win rate","kind":"term","course":"m01","lesson":"marketing-objectives","front":"Win rate","back":"The share of proposals, quotes or bids that turn into sales.","href":"learn/marketing/m01/marketing-objectives/"},{"id":"t:winsorising","kind":"term","course":"b02","lesson":"outliers","front":"Winsorising","back":"Replacing values beyond a chosen limit, such as a fence or a percentile, with the limit itself, so that extreme values keep their rows but lose most of their pull.","href":"learn/analytics/b02/outliers/"},{"id":"t:word of mouth","kind":"term","course":"m01","lesson":"influences-on-buying","front":"Word of mouth","back":"Communication about products and brands between customers, in person or online (recommendations, reviews, posts), rather than from the seller.","href":"learn/marketing/m01/influences-on-buying/"},{"id":"t:working capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Working capital","back":"Current assets minus current liabilities: the short-term cushion in a firm’s balance sheet. It is a measure, not a source of capital.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:worksheet","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Worksheet","back":"An optional internal working paper, usually a spreadsheet, that carries each account from the trial balance through the adjustments to the income statement and balance sheet. It is not a financial statement.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:write-off","kind":"term","course":"f02","lesson":"receivables-and-payables","front":"Write-off","back":"Removing a specific customer’s balance from accounts receivable once it is judged uncollectible. Under the allowance method it is charged against the allowance, not to expense.","href":"learn/finance/f02/receivables-and-payables/"},{"id":"t:year to date","kind":"term","course":"b03","lesson":"dashboards","front":"Year to date","back":"The period from the start of the year, or of the series, to the end of the latest complete period. Abbreviated YTD.","href":"learn/analytics/b03/dashboards/"},{"id":"t:z-score","kind":"term","course":"b02","lesson":"outliers","front":"Z-score","back":"The number of standard deviations a value lies from the mean: (x − mean) ÷ s.","href":"learn/analytics/b02/outliers/"},{"id":"f:f00:future-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Future value of a single amount (annual compounding)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi>F</mi><mi>V</mi></mrow><mo>=</mo><mrow><mi>P</mi><mi>V</mi></mrow><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV} = \\mathit{PV}\\,(1 + r)^n</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV}</annotation></semantics></math></span>","Future value: what the amount will be worth after n years ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV}</annotation></semantics></math></span>","Present value: the amount invested today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per year, as a decimal (1.5% is 0.015) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:present-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Present value of a single amount (annual discounting)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi>P</mi><mi>V</mi></mrow><mo>=</mo><mfrac><mrow><mi>F</mi><mi>V</mi></mrow><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV} = \\dfrac{\\mathit{FV}}{(1 + r)^n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV}</annotation></semantics></math></span>","Present value: what the future amount is worth today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV}</annotation></semantics></math></span>","The amount to be received in the future ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per year, as a decimal: the return available elsewhere at similar risk (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years until the amount is received (years)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:expected-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Expected value of an uncertain outcome","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>X</mi><mo stretchy=\"false\">]</mo><mo>=</mo><msub><mi>p</mi><mn>1</mn></msub><msub><mi>x</mi><mn>1</mn></msub><mo>+</mo><msub><mi>p</mi><mn>2</mn></msub><msub><mi>x</mi><mn>2</mn></msub><mo>+</mo><mo>⋯</mo><mo>+</mo><msub><mi>p</mi><mi>k</mi></msub><msub><mi>x</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">E[X] = p_1 x_1 + p_2 x_2 + \\cdots + p_k x_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>X</mi><mo stretchy=\"false\">]</mo></mrow><annotation encoding=\"application/x-tex\">E[X]</annotation></semantics></math></span>","Expected value of the uncertain outcome X (same unit as the outcomes)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th possible outcome (e.g. $)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_i</annotation></semantics></math></span>","The probability of the i-th outcome; the probabilities add up to 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The number of possible outcomes"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:risk-premium","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Risk premium","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Risk premium</mtext><mo>=</mo><mi>E</mi><mo stretchy=\"false\">[</mo><mi>R</mi><mo stretchy=\"false\">]</mo><mo>−</mo><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Risk premium} = E[R] - r_f</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>R</mi><mo stretchy=\"false\">]</mo></mrow><annotation encoding=\"application/x-tex\">E[R]</annotation></semantics></math></span>","Expected return on the risky investment (% per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_f</annotation></semantics></math></span>","Risk-free rate: the return on an investment whose payoff is certain (% per year)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:economic-profit","kind":"formula","course":"f00","lesson":"finance-accounting-economics","front":"Economic profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Economic profit</mtext><mo>=</mo><mtext>Accounting profit</mtext><mo>−</mo><mtext>Opportunity costs not recorded</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Economic profit} = \\text{Accounting profit} - \\text{Opportunity costs not recorded}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accounting profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accounting profit}</annotation></semantics></math></span>","Revenue minus expenses as recorded under the accounting rules (net income) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Opportunity costs not recorded</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Opportunity costs not recorded}</annotation></semantics></math></span>","The value of alternatives given up that involve no transaction, such as the owner’s forgone salary and the return her money could earn elsewhere ($)"]],"href":"learn/finance/f00/finance-accounting-economics/"},{"id":"f:f00:operating-cash-flow-simple","kind":"formula","course":"f00","lesson":"finance-accounting-economics","front":"Operating cash flow (simplified)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Operating cash flow</mtext><mo>=</mo><mtext>Accounting profit</mtext><mo>+</mo><mtext>Non-cash expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating cash flow} = \\text{Accounting profit} + \\text{Non-cash expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accounting profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accounting profit}</annotation></semantics></math></span>","Net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Non-cash expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Non-cash expenses}</annotation></semantics></math></span>","Expenses that used no cash in the period, chiefly depreciation ($)"]],"href":"learn/finance/f00/finance-accounting-economics/"},{"id":"f:f00:incremental-cash-flow","kind":"formula","course":"f00","lesson":"decision-principles","front":"Incremental cash flow of a decision","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Incremental cash flow</mtext><mo>=</mo><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>with</mtext></msub><mo>−</mo><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>without</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Incremental cash flow} = \\mathit{CF}_{\\text{with}} - \\mathit{CF}_{\\text{without}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>with</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\mathit{CF}_{\\text{with}}</annotation></semantics></math></span>","Cash flows of the business (or person) if the decision is taken, in a given period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>without</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\mathit{CF}_{\\text{without}}</annotation></semantics></math></span>","Cash flows in the same period if it is not taken ($)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:portfolio-return","kind":"formula","course":"f00","lesson":"decision-principles","front":"Return on a portfolio of two investments","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mi>p</mi></msub><mo>=</mo><mi>w</mi><mtext> </mtext><msub><mi>R</mi><mi>A</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>w</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msub><mi>R</mi><mi>B</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_p = w\\,R_A + (1 - w)\\,R_B</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_p</annotation></semantics></math></span>","Return on the whole portfolio (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow><annotation encoding=\"application/x-tex\">w</annotation></semantics></math></span>","Share of the money invested in A, as a decimal (the rest is in B)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>A</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_A</annotation></semantics></math></span>","Return on investment A (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>B</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_B</annotation></semantics></math></span>","Return on investment B (%)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:no-arbitrage-price","kind":"formula","course":"f00","lesson":"decision-principles","front":"No-arbitrage price of a safe future payment","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>X</mi><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\dfrac{X}{(1 + r_f)^n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Today’s price of the promise ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X</annotation></semantics></math></span>","The certain amount to be paid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_f</annotation></semantics></math></span>","Risk-free rate at which money can be borrowed and lent, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Years until payment (years)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:working-capital","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Working capital","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Working capital</mtext><mo>=</mo><mtext>Current assets</mtext><mo>−</mo><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Working capital} = \\text{Current assets} - \\text{Current liabilities}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","Cash and assets expected to become cash or be used up within a year: receivables, inventory, prepayments ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","Obligations due within a year: amounts owed to suppliers, wages and taxes due, loan repayments due within the year ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:current-ratio","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Current ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Current ratio</mtext><mo>=</mo><mfrac><mtext>Current assets</mtext><mtext>Current liabilities</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Current ratio} = \\dfrac{\\text{Current assets}}{\\text{Current liabilities}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","As above ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","As above; must be greater than zero ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:quick-ratio","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Quick (acid-test) ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Quick ratio</mtext><mo>=</mo><mfrac><mrow><mtext>Cash</mtext><mo>+</mo><mtext>Short-term investments</mtext><mo>+</mo><mtext>Receivables</mtext></mrow><mtext>Current liabilities</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Quick ratio} = \\dfrac{\\text{Cash} + \\text{Short-term investments} + \\text{Receivables}}{\\text{Current liabilities}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}</annotation></semantics></math></span>","Cash and bank balances ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Short-term investments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Short-term investments}</annotation></semantics></math></span>","Investments that can be sold quickly at close to their value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Receivables</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Receivables}</annotation></semantics></math></span>","Amounts customers owe for goods or services already delivered ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","Obligations due within a year ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:debt-to-equity","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Debt-to-equity ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Debt-to-equity</mtext><mo>=</mo><mfrac><mtext>Debt</mtext><mtext>Equity</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Debt-to-equity} = \\dfrac{\\text{Debt}}{\\text{Equity}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Debt</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Debt}</annotation></semantics></math></span>","Interest-bearing borrowing (loans and bonds); some analysts use total liabilities instead ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","Shareholders’ equity as recorded in the balance sheet (book value) ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:emergency-months","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Emergency-fund cover (months)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Months covered</mtext><mo>=</mo><mfrac><mtext>Liquid savings</mtext><mtext>Essential spending per month</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Months covered} = \\dfrac{\\text{Liquid savings}}{\\text{Essential spending per month}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liquid savings</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liquid savings}</annotation></semantics></math></span>","Money that can be reached quickly at full value, such as cash and bank deposits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Essential spending per month</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Essential spending per month}</annotation></semantics></math></span>","Costs that cannot easily be cut: housing, food, insurance, transport, loan payments ($ per month)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:market-cap","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Market capitalisation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Market cap</mtext><mo>=</mo><mi>P</mi><mo>×</mo><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap} = P \\times N</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Current share price ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of shares outstanding (shares)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:enterprise-value","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Enterprise value","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV</mtext><mo>=</mo><mtext>Market cap</mtext><mo>+</mo><mtext>Debt</mtext><mo>−</mo><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV} = \\text{Market cap} + \\text{Debt} - \\text{Cash}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Market value of the equity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Debt</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Debt}</annotation></semantics></math></span>","Interest-bearing debt: loans and bonds ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}</annotation></semantics></math></span>","Cash and short-term investments not needed to run the business; this course subtracts all cash ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:ebitda","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"EBITDA","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EBITDA</mtext><mo>=</mo><mtext>EBIT</mtext><mo>+</mo><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBITDA} = \\text{EBIT} + \\text{D\\&amp;A}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EBIT</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBIT}</annotation></semantics></math></span>","Earnings before interest and taxes: net income + interest + taxes (equal to operating profit when, as at Harbourline, there is no income or cost outside operations) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{D\\&amp;A}</annotation></semantics></math></span>","Depreciation and amortisation for the period ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:ev-ebitda","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"EV/EBITDA multiple","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV/EBITDA</mtext><mo>=</mo><mfrac><mtext>EV</mtext><mtext>EBITDA</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{EV/EBITDA} = \\dfrac{\\text{EV}}{\\text{EBITDA}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV}</annotation></semantics></math></span>","Enterprise value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EBITDA</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBITDA}</annotation></semantics></math></span>","Usually the last twelve months or the next year’s forecast; must be positive to be meaningful ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:pe-ratio","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Price-to-earnings (P/E) ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>P/E</mtext><mo>=</mo><mfrac><mtext>Market cap</mtext><mtext>Net income</mtext></mfrac><mo>=</mo><mfrac><mi>P</mi><mtext>EPS</mtext></mfrac><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>EPS</mtext><mo>=</mo><mfrac><mtext>Net income</mtext><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{P/E} = \\dfrac{\\text{Market cap}}{\\text{Net income}} = \\dfrac{P}{\\text{EPS}}, \\quad \\text{EPS} = \\dfrac{\\text{Net income}}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Share price ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EPS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EPS}</annotation></semantics></math></span>","Earnings per share ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Shares outstanding (shares)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Share price × shares outstanding ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit after interest and tax; must be positive for a meaningful P/E ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:market-to-book","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Market-to-book ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Market-to-book</mtext><mo>=</mo><mfrac><mtext>Market cap</mtext><mtext>Book value of equity</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Market-to-book} = \\dfrac{\\text{Market cap}}{\\text{Book value of equity}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Market value of the equity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Book value of equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Book value of equity}</annotation></semantics></math></span>","Total assets minus total liabilities, as recorded ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:simple-interest","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Simple interest","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>F</mi><mi>V</mi><mo>=</mo><mi>P</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mi>t</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t, \\qquad FV = P(1 + rt)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Total interest earned or paid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal: the amount lent or borrowed ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (6% = 0.06) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">FV</annotation></semantics></math></span>","Balance at the end, if the interest is added to it rather than paid out ($)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:compound-m","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Compound interest with m periods a year","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>F</mi><mi>V</mi><mo>=</mo><mi>P</mi><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mi>r</mi><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mi>m</mi><mi>n</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">FV = P\\left(1 + \\frac{r}{m}\\right)^{m n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">FV</annotation></semantics></math></span>","Future value: the balance after n years ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Quoted (nominal) annual rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year (1 annual, 4 quarterly, 12 monthly, 365 daily)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:ear","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Effective annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EAR</mtext><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mi>r</mi><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mi>m</mi></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\text{EAR} = \\left(1 + \\frac{r}{m}\\right)^{m} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","The equivalent rate compounded once a year (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Quoted (nominal) annual rate, such as an APR in its simple sense (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:inflation-rate","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Inflation rate from a price index","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>i</mi><mo>=</mo><mfrac><mrow><msub><mtext>Index</mtext><mn>1</mn></msub><mo>−</mo><msub><mtext>Index</mtext><mn>0</mn></msub></mrow><msub><mtext>Index</mtext><mn>0</mn></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">i = \\frac{\\text{Index}_1 - \\text{Index}_0}{\\text{Index}_0}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation rate over the period (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Index</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Index}_0</annotation></semantics></math></span>","Price index at the start (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Index</mtext><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Index}_1</annotation></semantics></math></span>","Price index at the end (index points)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:purchasing-power","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Purchasing power in today’s dollars","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Real value</mtext><mo>=</mo><mfrac><mtext>Future dollars</mtext><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Real value} = \\frac{\\text{Future dollars}}{(1 + i)^{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Future dollars</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Future dollars}</annotation></semantics></math></span>","An amount of money n years from now ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Annual inflation rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Real value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Real value}</annotation></semantics></math></span>","What that amount will buy, measured in today’s prices ($ of today)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:real-return","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Real return (Fisher relation)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><mrow><mn>1</mn><mo>+</mo><mi>i</mi></mrow></mfrac><mo>−</mo><mn>1</mn><mtext>  </mtext><mo>≈</mo><mtext>  </mtext><msub><mi>r</mi><mtext>nom</mtext></msub><mo>−</mo><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}} = \\frac{1 + r_{\\text{nom}}}{1 + i} - 1 \\;\\approx\\; r_{\\text{nom}} - i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}}</annotation></semantics></math></span>","Real return: growth in purchasing power (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{nom}}</annotation></semantics></math></span>","Nominal return: growth in dollars (use the effective annual rate) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation rate (per year)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:interest-spread","kind":"formula","course":"f00","lesson":"financial-markets","front":"Intermediary’s interest-rate spread","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>s</mi><mo>=</mo><msub><mi>r</mi><mi>L</mi></msub><mo>−</mo><msub><mi>r</mi><mi>D</mi></msub></mrow><annotation encoding=\"application/x-tex\">s = r_L - r_D</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","The spread: the gap between the lending rate and the deposit rate (percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_L</annotation></semantics></math></span>","The rate the intermediary charges borrowers (% a year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>D</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_D</annotation></semantics></math></span>","The rate the intermediary pays savers (% a year)"]],"href":"learn/finance/f00/financial-markets/"},{"id":"f:f00:currency-conversion","kind":"formula","course":"f00","lesson":"financial-markets","front":"Converting between currencies","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>A</mi><mi mathvariant=\"normal\">$</mi></msub><mo>=</mo><msub><mi>A</mi><mi>F</mi></msub><mo>×</mo><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">A_{\\$} = A_{F} \\times S</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi mathvariant=\"normal\">$</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_{\\$}</annotation></semantics></math></span>","The amount in US dollars ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>F</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_{F}</annotation></semantics></math></span>","The amount in the foreign currency (units of foreign currency)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","The exchange rate quoted as dollars per one unit of the foreign currency ($ per unit)"]],"href":"learn/finance/f00/financial-markets/"},{"id":"f:f00:bid-ask-spread","kind":"formula","course":"f00","lesson":"market-participants","front":"Bid-ask spread and relative spread","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Spread</mtext><mo>=</mo><msub><mi>P</mi><mtext>ask</mtext></msub><mo>−</mo><msub><mi>P</mi><mtext>bid</mtext></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Relative spread</mtext><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mtext>ask</mtext></msub><mo>−</mo><msub><mi>P</mi><mtext>bid</mtext></msub></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mtext>ask</mtext></msub><mo>+</mo><msub><mi>P</mi><mtext>bid</mtext></msub><mo stretchy=\"false\">)</mo><mo>÷</mo><mn>2</mn></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Spread} = P_{\\text{ask}} - P_{\\text{bid}}, \\qquad \\text{Relative spread} = \\dfrac{P_{\\text{ask}} - P_{\\text{bid}}}{(P_{\\text{ask}} + P_{\\text{bid}}) \\div 2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mtext>ask</mtext></msub></mrow><annotation encoding=\"application/x-tex\">P_{\\text{ask}}</annotation></semantics></math></span>","The price at which the dealer will sell to you ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mtext>bid</mtext></msub></mrow><annotation encoding=\"application/x-tex\">P_{\\text{bid}}</annotation></semantics></math></span>","The price at which the dealer will buy from you ($ per share)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:net-proceeds","kind":"formula","course":"f00","lesson":"market-participants","front":"Net proceeds of an underwritten offering","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net proceeds</mtext><mo>=</mo><mi>N</mi><mo>×</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>g</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Net proceeds} = N \\times P \\times (1 - g)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of new shares sold (shares)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Offer price paid by investors ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Underwriting spread as a fraction of the offer price"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:nav","kind":"formula","course":"f00","lesson":"market-participants","front":"Net asset value per fund share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>NAV per share</mtext><mo>=</mo><mfrac><mrow><mtext>Assets</mtext><mo>−</mo><mtext>Liabilities</mtext></mrow><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{NAV per share} = \\dfrac{\\text{Assets} - \\text{Liabilities}}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets}</annotation></semantics></math></span>","Market value of everything the fund owns ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liabilities}</annotation></semantics></math></span>","Everything the fund owes, such as fees due ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of fund shares outstanding (shares)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:fdic-insured","kind":"formula","course":"f00","lesson":"market-participants","front":"FDIC-insured amount in one ownership category at one bank","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Insured</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>B</mi><mo separator=\"true\">,</mo><mtext> </mtext><mn>250,000</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Uninsured</mtext><mo>=</mo><mi>B</mi><mo>−</mo><mtext>Insured</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Insured} = \\min(B,\\ 250{,}000), \\qquad \\text{Uninsured} = B - \\text{Insured}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","The depositor’s combined deposits in that ownership category at that bank ($)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:agency-costs","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Agency costs (Jensen and Meckling)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Agency costs</mtext><mo>=</mo><mi>M</mi><mo>+</mo><mi>B</mi><mo>+</mo><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Agency costs} = M + B + L</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","Monitoring costs paid by principals (audits, boards, time spent checking reports) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Bonding costs paid by agents to assure principals (detailed reports, penalty clauses) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">L</annotation></semantics></math></span>","Residual loss: value still lost because the agent’s decisions differ from the principal’s ideal ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f00:perk-split","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Who bears the cost of a perk","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>C</mi><mtext>manager</mtext></msub><mo>=</mo><mi>α</mi><mo>×</mo><mi>P</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>C</mi><mtext>others</mtext></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>α</mi><mo stretchy=\"false\">)</mo><mo>×</mo><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">C_{\\text{manager}} = \\alpha \\times P, \\qquad C_{\\text{others}} = (1 - \\alpha) \\times P</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α</mi></mrow><annotation encoding=\"application/x-tex\">\\alpha</annotation></semantics></math></span>","The fraction of the company’s shares the manager owns (between 0 and 1)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","The cost of a perk that adds nothing to the company’s value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mtext>manager</mtext></msub></mrow><annotation encoding=\"application/x-tex\">C_{\\text{manager}}</annotation></semantics></math></span>","The fall in the value of the manager’s own shares ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mtext>others</mtext></msub></mrow><annotation encoding=\"application/x-tex\">C_{\\text{others}}</annotation></semantics></math></span>","The cost borne by the other shareholders ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f00:claims-payoff","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Payoffs to shareholders and lenders when debt is due","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Shareholders</mtext><mo>=</mo><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>V</mi><mo>−</mo><mi>D</mi><mo separator=\"true\">,</mo><mtext> </mtext><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Lenders</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>V</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>D</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Shareholders} = \\max(V - D,\\ 0), \\qquad \\text{Lenders} = \\min(V,\\ D)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Value of the company’s assets when the debt falls due ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Amount owed to lenders (principal plus interest due) ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f01:accounting-equation","kind":"formula","course":"f01","lesson":"accounting-equation","front":"The accounting equation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Assets</mtext><mo>=</mo><mtext>Liabilities</mtext><mo>+</mo><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets} = \\text{Liabilities} + \\text{Equity}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets}</annotation></semantics></math></span>","Resources the business controls that are expected to bring economic benefits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liabilities}</annotation></semantics></math></span>","Present obligations to transfer resources to outsiders ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","The owners’ residual claim on the assets ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:net-assets","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Equity as net assets","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Equity</mtext><mo>=</mo><mtext>Assets</mtext><mo>−</mo><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity} = \\text{Assets} - \\text{Liabilities}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","The residual claim: what would be left for owners after every liability is settled at book amounts ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:expanded-equation","kind":"formula","course":"f01","lesson":"accounting-equation","front":"The expanded accounting equation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>A</mi><mo>=</mo><mi>L</mi><mo>+</mo><mi>C</mi><mi>S</mi><mo>+</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mi>R</mi><mo>−</mo><mi>E</mi><mo>−</mo><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">A = L + CS + RE_{\\text{beg}} + R - E - D</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">A,\\ L</annotation></semantics></math></span>","Assets and liabilities at the end of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">CS</annotation></semantics></math></span>","Common stock: capital contributed by owners ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{beg}}</annotation></semantics></math></span>","Retained earnings at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">R,\\ E</annotation></semantics></math></span>","Revenue and expenses for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Dividends declared in the period ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:net-income","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mtext>Revenue</mtext><mo>−</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\text{Revenue} - \\text{Expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit for the period; negative means a net loss ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:retained-earnings","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Retained earnings at the end of a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}} = RE_{\\text{beg}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}}</annotation></semantics></math></span>","Profit kept in the business since it began, at the end of the period ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:debit-normal-balance","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"Balance of an account with a normal debit balance","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Ending balance</mtext><mo>=</mo><mtext>Beginning balance</mtext><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext><mo>−</mo><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\text{Ending balance} = \\text{Beginning balance} + \\textstyle\\sum \\text{Debits} - \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Beginning balance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Beginning balance}</annotation></semantics></math></span>","The balance brought forward from the previous period (zero for a new account) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total of the amounts entered on the left side during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total of the amounts entered on the right side during the period ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:credit-normal-balance","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"Balance of an account with a normal credit balance","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Ending balance</mtext><mo>=</mo><mtext>Beginning balance</mtext><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext><mo>−</mo><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\text{Ending balance} = \\text{Beginning balance} + \\textstyle\\sum \\text{Credits} - \\sum \\text{Debits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Beginning balance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Beginning balance}</annotation></semantics></math></span>","The credit balance brought forward from the previous period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total amounts entered on the right side (increases) during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total amounts entered on the left side (decreases) during the period ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:double-entry-rule","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"The double-entry rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext><mo>=</mo><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits} = \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total of the amounts debited in an entry ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total of the amounts credited in the same entry ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:journal-entry-balance","kind":"formula","course":"f01","lesson":"journal-entries","front":"A journal entry balances","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Debits</mtext><mo>=</mo><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Debits} = \\sum_{\\text{lines}} \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Debits}</annotation></semantics></math></span>","Total of the debit amounts on all lines of the entry ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Credits}</annotation></semantics></math></span>","Total of the credit amounts on all lines of the entry ($)"]],"href":"learn/finance/f01/journal-entries/"},{"id":"f:f01:balance-debit-normal","kind":"formula","course":"f01","lesson":"general-ledger","front":"Balance of a debit-normal account","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Balance</mtext><mo>=</mo><mo>∑</mo><mtext>Debits</mtext><mo>−</mo><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Balance} = \\sum \\text{Debits} - \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debits}</annotation></semantics></math></span>","Total of all amounts posted to the debit side, including any opening debit balance ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credits}</annotation></semantics></math></span>","Total of all amounts posted to the credit side ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:balance-credit-normal","kind":"formula","course":"f01","lesson":"general-ledger","front":"Balance of a credit-normal account","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Balance</mtext><mo>=</mo><mo>∑</mo><mtext>Credits</mtext><mo>−</mo><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Balance} = \\sum \\text{Credits} - \\sum \\text{Debits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credits}</annotation></semantics></math></span>","Total of all amounts posted to the credit side, including any opening credit balance ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debits}</annotation></semantics></math></span>","Total of all amounts posted to the debit side ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:running-balance","kind":"formula","course":"f01","lesson":"general-ledger","front":"Running balance after a posting (debit-normal account)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>B</mi><mi>n</mi></msub><mo>=</mo><msub><mi>B</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><msub><mtext>Dr</mtext><mi>n</mi></msub><mo>−</mo><msub><mtext>Cr</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_n = B_{n-1} + \\text{Dr}_n - \\text{Cr}_n</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_n</annotation></semantics></math></span>","Balance after the n-th posting ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">B_{n-1}</annotation></semantics></math></span>","Balance before it (zero for a new account) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Dr</mtext><mi>n</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mtext>Cr</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Dr}_n,\\ \\text{Cr}_n</annotation></semantics></math></span>","The debit or credit posted (one of them is zero) ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:control-account","kind":"formula","course":"f01","lesson":"general-ledger","front":"Control account check","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Control account balance</mtext><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mtext>Subsidiary balance</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Control account balance} = \\sum_{i} \\text{Subsidiary balance}_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Subsidiary balance</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Subsidiary balance}_i</annotation></semantics></math></span>","Balance of customer (or supplier) account i in the subsidiary ledger ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:trial-balance-check","kind":"formula","course":"f01","lesson":"trial-balance","front":"Trial balance check","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mo>∑</mo><mtext>Debit balances</mtext><mo>=</mo><mo>∑</mo><mtext>Credit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debit balances} = \\sum \\text{Credit balances}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debit balances}</annotation></semantics></math></span>","Total of the debit column: every account whose debits exceed its credits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credit balances}</annotation></semantics></math></span>","Total of the credit column: every account whose credits exceed its debits ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:tb-difference","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference between the totals","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mrow><mo fence=\"true\">∣</mo><mtext> </mtext><mo>∑</mo><mtext>Debit balances</mtext><mo>−</mo><mo>∑</mo><mtext>Credit balances</mtext><mtext> </mtext><mo fence=\"true\">∣</mo></mrow></mrow><annotation encoding=\"application/x-tex\">d = \\left|\\, \\sum \\text{Debit balances} - \\sum \\text{Credit balances} \\,\\right|</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","The amount to be explained ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:wrong-side","kind":"formula","course":"f01","lesson":"trial-balance","front":"Amount on the wrong side","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>x</mi><mo>=</mo><mfrac><mi>d</mi><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">x = \\dfrac{d}{2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The amount posted to the wrong side, or the balance listed in the wrong column ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference between the totals ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:transposition","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference left by swapping two neighbouring digits","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>9</mn><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mo>−</mo><mi>b</mi><mi mathvariant=\"normal\">∣</mi><mo>×</mo><msup><mn>10</mn><mi>k</mi></msup></mrow><annotation encoding=\"application/x-tex\">d = 9\\,|a - b| \\times 10^{k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">a,\\ b</annotation></semantics></math></span>","The two digits that were swapped"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Place of the lower digit: 0 for units and tens, 1 for tens and hundreds, and so on"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference the transposition leaves ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:slide","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference left by a slide","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msup><mn>10</mn><mi>n</mi></msup><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext> </mtext><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">d = (10^{n} - 1)\\, y</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference the slide leaves ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">y</annotation></semantics></math></span>","The smaller of the correct and the recorded amounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of places the decimal point moved"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:cash-basis-profit","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"Cash-basis profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cash-basis profit</mtext><mo>=</mo><mtext>Operating receipts</mtext><mo>−</mo><mtext>Operating payments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash-basis profit} = \\text{Operating receipts} - \\text{Operating payments}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Operating receipts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating receipts}</annotation></semantics></math></span>","Cash received from customers in the period, whatever period the work belongs to ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Operating payments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating payments}</annotation></semantics></math></span>","Cash paid in the period for running costs (wages, rent, supplies, insurance…) ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:accrual-net-income","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"Accrual-basis net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mtext>Revenue earned</mtext><mo>−</mo><mtext>Expenses incurred</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\text{Revenue earned} - \\text{Expenses incurred}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Revenue earned</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Revenue earned}</annotation></semantics></math></span>","Revenue for performance obligations satisfied in the period, received or not ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Expenses incurred</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Expenses incurred}</annotation></semantics></math></span>","Resources used up and obligations incurred in the period’s operations, paid or not ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:cash-to-accrual","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"From cash-basis profit to accrual net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mi>I</mi><mo>=</mo><mi>C</mi><mi>P</mi><mo>+</mo><msub><mi>A</mi><mi>R</mi></msub><mo>−</mo><msub><mi>D</mi><mi>R</mi></msub><mo>+</mo><msub><mi>D</mi><mi>E</mi></msub><mo>−</mo><msub><mi>A</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">NI = CP + A_R - D_R + D_E - A_E</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">NI</annotation></semantics></math></span>","Accrual-basis net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">CP</annotation></semantics></math></span>","Cash-basis profit for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_R</annotation></semantics></math></span>","Revenue earned this period but not yet received (accrued revenue, unpaid invoices) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_R</annotation></semantics></math></span>","Cash received this period for revenue of later periods (unearned revenue) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_E</annotation></semantics></math></span>","Cash paid this period for costs of later periods (prepayments, paid-for supplies still on hand) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_E</annotation></semantics></math></span>","Expenses of this period not paid from this period’s operating cash (unpaid bills, wages and interest owed, depreciation) ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:straight-line","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Straight-line depreciation (per year)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Depreciation per year</mtext><mo>=</mo><mfrac><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Useful life</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Depreciation per year} = \\dfrac{\\text{Cost} - \\text{Residual value}}{\\text{Useful life}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost}</annotation></semantics></math></span>","What the asset cost to buy and get ready for use ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Residual value}</annotation></semantics></math></span>","What the business expects to get for the asset at the end of its useful life ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Useful life</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Useful life}</annotation></semantics></math></span>","How long the business expects to use the asset (years)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:partial-period-depreciation","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Straight-line depreciation for part of a year","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Depreciation</mtext><mo>=</mo><mfrac><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Useful life</mtext></mfrac><mo>×</mo><mfrac><mi>m</mi><mn>12</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Depreciation} = \\dfrac{\\text{Cost} - \\text{Residual value}}{\\text{Useful life}} \\times \\dfrac{m}{12}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Months the asset is in use during the period, counted by the business’s convention (months)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:book-value","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Book value (carrying amount)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Book value</mtext><mo>=</mo><mtext>Cost</mtext><mo>−</mo><mtext>Accumulated depreciation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Book value} = \\text{Cost} - \\text{Accumulated depreciation}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accumulated depreciation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accumulated depreciation}</annotation></semantics></math></span>","All depreciation recorded on the asset since it was bought ($)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:simple-interest","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Simple interest for a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Interest for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal: the amount borrowed or lent ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (6% = 0.06)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time in years (one month = 1/12) (years)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:supplies-used","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Supplies used in a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Supplies used</mtext><mo>=</mo><mtext>Supplies at start</mtext><mo>+</mo><mtext>Purchases</mtext><mo>−</mo><mtext>Supplies on hand</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies used} = \\text{Supplies at start} + \\text{Purchases} - \\text{Supplies on hand}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Supplies at start</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies at start}</annotation></semantics></math></span>","Balance of the Supplies account at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Purchases</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Purchases}</annotation></semantics></math></span>","Supplies bought during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Supplies on hand</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies on hand}</annotation></semantics></math></span>","Cost of supplies counted at the end of the period ($)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:net-income-statement","kind":"formula","course":"f01","lesson":"financial-statements","front":"Net income (single-step income statement)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mo>∑</mo><mtext>Revenues</mtext><mo>−</mo><mo>∑</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\sum \\text{Revenues} - \\sum \\text{Expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo></mrow><annotation encoding=\"application/x-tex\">\\sum</annotation></semantics></math></span>","The total of every account of that type in the adjusted trial balance"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:ending-retained-earnings","kind":"formula","course":"f01","lesson":"financial-statements","front":"Ending retained earnings","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}} = RE_{\\text{beg}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{beg}}</annotation></semantics></math></span>","Retained earnings at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}}</annotation></semantics></math></span>","Retained earnings at the end of the period, reported on the balance sheet ($)"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:net-change-in-cash","kind":"formula","course":"f01","lesson":"financial-statements","front":"Net change in cash","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Cash</mtext><mo>=</mo><msub><mtext>CF</mtext><mtext>operating</mtext></msub><mo>+</mo><msub><mtext>CF</mtext><mtext>investing</mtext></msub><mo>+</mo><msub><mtext>CF</mtext><mtext>financing</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Cash} = \\text{CF}_{\\text{operating}} + \\text{CF}_{\\text{investing}} + \\text{CF}_{\\text{financing}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Cash}</annotation></semantics></math></span>","Ending cash minus beginning cash ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CF</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CF}</annotation></semantics></math></span>","Net cash flow from each kind of activity (negative when cash is used) ($)"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:income-summary-balance","kind":"formula","course":"f01","lesson":"closing-entries","front":"Income Summary after closing revenue and expenses","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Income Summary balance</mtext><mo>=</mo><mo>∑</mo><mtext>Revenue</mtext><mo>−</mo><mo>∑</mo><mtext>Expenses</mtext><mo>=</mo><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Income Summary balance} = \\sum \\text{Revenue} - \\sum \\text{Expenses} = \\text{Net income}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Revenue}</annotation></semantics></math></span>","Total of the revenue account balances for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Expenses}</annotation></semantics></math></span>","Total of the expense account balances for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit for the period; a negative result is a net loss ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:retained-earnings-after-closing","kind":"formula","course":"f01","lesson":"closing-entries","front":"Retained Earnings after closing","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>after</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>before</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{after}} = RE_{\\text{before}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>before</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{before}}</annotation></semantics></math></span>","Retained Earnings balance before the closing entries, which is its balance at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{after}}</annotation></semantics></math></span>","Retained Earnings balance after the closing entries are posted ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Dividends}</annotation></semantics></math></span>","Dividends declared in the period ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:post-closing-total","kind":"formula","course":"f01","lesson":"closing-entries","front":"Post-closing trial balance and the balance sheet","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Total debits</mtext><mo>=</mo><mtext>Total assets</mtext><mo>+</mo><mtext>Contra-asset balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Total debits} = \\text{Total assets} + \\text{Contra-asset balances}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Total assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Total assets}</annotation></semantics></math></span>","Total assets on the balance sheet, after contra-assets are deducted ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Contra-asset balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Contra-asset balances}</annotation></semantics></math></span>","Credit balances such as accumulated depreciation, which a trial balance lists on the credit side ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:correcting-entry","kind":"formula","course":"f01","lesson":"accounting-cycle","front":"Correcting entry","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Correcting entry</mtext><mo>=</mo><mtext>Correct entry</mtext><mo>−</mo><mtext>Entry made</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Correcting entry} = \\text{Correct entry} - \\text{Entry made}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Correct entry</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Correct entry}</annotation></semantics></math></span>","The entry that should have been recorded ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Entry made</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Entry made}</annotation></semantics></math></span>","The entry that was actually recorded and posted ($)"]],"href":"learn/finance/f01/accounting-cycle/"},{"id":"f:f01:payroll-accrual-split","kind":"formula","course":"f01","lesson":"accounting-cycle","front":"Wages accrued at the end of a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Accrued wages</mtext><mo>=</mo><mtext>Pay for the pay period</mtext><mo>×</mo><mfrac><mtext>Days worked by the period end</mtext><mtext>Days in the pay period</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Accrued wages} = \\text{Pay for the pay period} \\times \\dfrac{\\text{Days worked by the period end}}{\\text{Days in the pay period}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Pay for the pay period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Pay for the pay period}</annotation></semantics></math></span>","The total that will be paid for the whole pay period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days worked by the period end</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days worked by the period end}</annotation></semantics></math></span>","Days of the pay period that fall in the period being closed (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days in the pay period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days in the pay period}</annotation></semantics></math></span>","Length of the pay period (days)"]],"href":"learn/finance/f01/accounting-cycle/"},{"id":"f:f02:rr-allocation","kind":"formula","course":"f02","lesson":"revenue-recognition","front":"Allocating a transaction price (relative stand-alone selling prices)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>Allocated price</mtext><mi>i</mi></msub><mo>=</mo><mtext>Transaction price</mtext><mo>×</mo><mfrac><msub><mtext>SSP</mtext><mi>i</mi></msub><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mtext>SSP</mtext><mi>j</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Allocated price}_i = \\text{Transaction price} \\times \\dfrac{\\text{SSP}_i}{\\sum_j \\text{SSP}_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Allocated price</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Allocated price}_i</annotation></semantics></math></span>","The part of the transaction price assigned to performance obligation i ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Transaction price</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Transaction price}</annotation></semantics></math></span>","What the business expects to be entitled to for the whole contract ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>SSP</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{SSP}_i</annotation></semantics></math></span>","The stand-alone selling price of obligation i: what it would sell for on its own ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑</mo><mi>j</mi></msub><msub><mtext>SSP</mtext><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\sum_j \\text{SSP}_j</annotation></semantics></math></span>","The total of the stand-alone selling prices of all the obligations in the contract ($)"]],"href":"learn/finance/f02/revenue-recognition/"},{"id":"f:f02:rr-over-time","kind":"formula","course":"f02","lesson":"revenue-recognition","front":"Revenue to date on an obligation satisfied evenly over time","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Revenue to date</mtext><mo>=</mo><mtext>Allocated price</mtext><mo>×</mo><mfrac><mi>t</mi><mi>T</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Revenue to date} = \\text{Allocated price} \\times \\dfrac{t}{T}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Allocated price</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Allocated price}</annotation></semantics></math></span>","The part of the transaction price assigned to the service ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","The part of the service period that has passed (months)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","The whole service period (months)"]],"href":"learn/finance/f02/revenue-recognition/"},{"id":"f:f02:rr-contract-liability","kind":"formula","course":"f02","lesson":"revenue-recognition","front":"Contract liability (unearned revenue) at the end of a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>CL</mtext><mtext>end</mtext></msub><mo>=</mo><msub><mtext>CL</mtext><mtext>beg</mtext></msub><mo>+</mo><mtext>Received in advance</mtext><mo>−</mo><mtext>Recognised from advances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CL}_{\\text{end}} = \\text{CL}_{\\text{beg}} + \\text{Received in advance} - \\text{Recognised from advances}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CL</mtext><mtext>beg</mtext></msub><mo separator=\"true\">,</mo><msub><mtext>CL</mtext><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CL}_{\\text{beg}}, \\text{CL}_{\\text{end}}</annotation></semantics></math></span>","The contract liability at the start and end of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Received in advance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Received in advance}</annotation></semantics></math></span>","Payments received (or due) for goods and services not yet transferred ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Recognised from advances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Recognised from advances}</annotation></semantics></math></span>","Revenue recognised in the period for obligations that had been paid for in advance ($)"]],"href":"learn/finance/f02/revenue-recognition/"},{"id":"f:f02:rr-net-revenue","kind":"formula","course":"f02","lesson":"revenue-recognition","front":"Net revenue","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net revenue</mtext><mo>=</mo><mtext>Gross revenue</mtext><mo>−</mo><mtext>Sales returns and allowances</mtext><mo>−</mo><mtext>Sales discounts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net revenue} = \\text{Gross revenue} - \\text{Sales returns and allowances} - \\text{Sales discounts}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Gross revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Gross revenue}</annotation></semantics></math></span>","Revenue recognised for goods and services transferred, before reductions ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Sales returns and allowances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Sales returns and allowances}</annotation></semantics></math></span>","Refunds and price reductions for returned or unsatisfactory goods (a contra-revenue account) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Sales discounts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Sales discounts}</annotation></semantics></math></span>","Reductions for prompt payment taken by customers (a contra-revenue account) ($)"]],"href":"learn/finance/f02/revenue-recognition/"},{"id":"f:f02:inv-cogs","kind":"formula","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Cost of goods sold (periodic formula)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>COGS</mtext><mo>=</mo><mtext>BI</mtext><mo>+</mo><mtext>P</mtext><mo>−</mo><mtext>EI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{COGS} = \\text{BI} + \\text{P} - \\text{EI}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>COGS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{COGS}</annotation></semantics></math></span>","Cost of goods sold for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>BI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{BI}</annotation></semantics></math></span>","Beginning inventory: the cost of goods on hand at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>P</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{P}</annotation></semantics></math></span>","Net purchases: purchases plus freight-in, less purchase returns and discounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EI}</annotation></semantics></math></span>","Ending inventory: the cost of goods on hand at the end, from a count, after any write-down ($)"]],"href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"f:f02:inv-layers","kind":"formula","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Cost of goods sold by FIFO or LIFO","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>COGS</mtext><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>q</mi><mi>k</mi></msub><mo>×</mo><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{COGS} = \\sum_k q_k \\times c_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">q_k</annotation></semantics></math></span>","Units taken from cost layer k: oldest layers first under FIFO, newest first under LIFO, until the units sold are covered (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_k</annotation></semantics></math></span>","Unit cost of layer k ($ per unit)"]],"href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"f:f02:inv-average","kind":"formula","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Weighted average cost","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>c</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mtext>Cost of goods available</mtext><mtext>Units available</mtext></mfrac><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>COGS</mtext><mo>=</mo><mover accent=\"true\"><mi>c</mi><mo>ˉ</mo></mover><mo>×</mo><mtext>Units sold</mtext></mrow><annotation encoding=\"application/x-tex\">\\bar{c} = \\dfrac{\\text{Cost of goods available}}{\\text{Units available}}, \\quad \\text{COGS} = \\bar{c} \\times \\text{Units sold}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>c</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{c}</annotation></semantics></math></span>","Average cost a unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost of goods available</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost of goods available}</annotation></semantics></math></span>","Beginning inventory plus purchases, at cost ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Units available</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Units available}</annotation></semantics></math></span>","Units on hand at the start plus units bought (units)"]],"href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"f:f02:inv-gross-margin","kind":"formula","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Gross profit and gross margin","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gross profit</mtext><mo>=</mo><mtext>Net sales</mtext><mo>−</mo><mtext>COGS</mtext><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>Gross margin</mtext><mo>=</mo><mfrac><mtext>Gross profit</mtext><mtext>Net sales</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Gross profit} = \\text{Net sales} - \\text{COGS}, \\quad \\text{Gross margin} = \\dfrac{\\text{Gross profit}}{\\text{Net sales}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net sales</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net sales}</annotation></semantics></math></span>","Revenue from goods sold, after returns, allowances and discounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>COGS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{COGS}</annotation></semantics></math></span>","Cost of goods sold for the same period ($)"]],"href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"f:f02:inv-lcnrv","kind":"formula","course":"f02","lesson":"inventory-and-cost-of-goods-sold","front":"Lower of cost and net realisable value","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>NRV</mtext><mo>=</mo><mtext>Estimated selling price</mtext><mo>−</mo><mtext>Costs to complete</mtext><mo>−</mo><mtext>Costs to sell</mtext><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>Carrying amount</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>Cost</mtext><mo separator=\"true\">,</mo><mtext>NRV</mtext><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{NRV} = \\text{Estimated selling price} - \\text{Costs to complete} - \\text{Costs to sell}, \\quad \\text{Carrying amount} = \\min(\\text{Cost}, \\text{NRV})</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>NRV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{NRV}</annotation></semantics></math></span>","Net realisable value of the item ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Estimated selling price</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Estimated selling price}</annotation></semantics></math></span>","The price expected in the ordinary course of business ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Costs to complete</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Costs to complete}</annotation></semantics></math></span>","Costs still needed to finish the goods (none for goods bought ready to sell) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Costs to sell</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Costs to sell}</annotation></semantics></math></span>","Costs of making the sale, such as fees, commissions and shipping ($)"]],"href":"learn/finance/f02/inventory-and-cost-of-goods-sold/"},{"id":"f:f02:is-gross-profit","kind":"formula","course":"f02","lesson":"income-statement","front":"Gross profit and gross margin (multi-step)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gross profit</mtext><mo>=</mo><mtext>Net revenue</mtext><mo>−</mo><mtext>Cost of sales</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Gross margin</mtext><mo>=</mo><mfrac><mtext>Gross profit</mtext><mtext>Net revenue</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Gross profit} = \\text{Net revenue} - \\text{Cost of sales}, \\qquad \\text{Gross margin} = \\dfrac{\\text{Gross profit}}{\\text{Net revenue}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net revenue}</annotation></semantics></math></span>","Revenue less returns, allowances and discounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost of sales</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost of sales}</annotation></semantics></math></span>","Cost of goods sold plus cost of services: the direct cost of what was sold ($)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:is-operating-income","kind":"formula","course":"f02","lesson":"income-statement","front":"Operating income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Operating income</mtext><mo>=</mo><mtext>Gross profit</mtext><mo>−</mo><mtext>Operating expenses</mtext><mo>+</mo><mtext>Gains on disposals</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating income} = \\text{Gross profit} - \\text{Operating expenses} + \\text{Gains on disposals}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Gross profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Gross profit}</annotation></semantics></math></span>","Net revenue less cost of sales ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Operating expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating expenses}</annotation></semantics></math></span>","Selling, general and administrative and other costs of running the business, including depreciation ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Gains on disposals</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Gains on disposals}</annotation></semantics></math></span>","Gains on selling long-lived assets such as equipment; losses on disposals are included in operating expenses (ASC 360-10-45-5) ($)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:is-net-income","kind":"formula","course":"f02","lesson":"income-statement","front":"From operating income to net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>IBT</mtext><mo>=</mo><mtext>Operating income</mtext><mo>+</mo><mtext>Other income</mtext><mo>−</mo><mtext>Other expenses</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Net income</mtext><mo>=</mo><mtext>IBT</mtext><mo>−</mo><mtext>Income tax expense</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IBT} = \\text{Operating income} + \\text{Other income} - \\text{Other expenses}, \\qquad \\text{Net income} = \\text{IBT} - \\text{Income tax expense}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IBT</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IBT}</annotation></semantics></math></span>","Income before income tax ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Other income</mtext><mo separator=\"true\">,</mo><mtext>Other expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Other income}, \\text{Other expenses}</annotation></semantics></math></span>","Non-operating items such as interest revenue and interest expense (under US GAAP, gains and losses on disposals are operating items) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Income tax expense</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Income tax expense}</annotation></semantics></math></span>","The tax charged on the period’s income (Lantern: 25% of IBT) ($)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:is-ebit-ebitda","kind":"formula","course":"f02","lesson":"income-statement","front":"EBIT and EBITDA from net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EBIT</mtext><mo>=</mo><mtext>NI</mtext><mo>+</mo><mtext>Interest expense</mtext><mo>+</mo><mtext>Income tax expense</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>EBITDA</mtext><mo>=</mo><mtext>EBIT</mtext><mo>+</mo><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBIT} = \\text{NI} + \\text{Interest expense} + \\text{Income tax expense}, \\qquad \\text{EBITDA} = \\text{EBIT} + \\text{D\\&amp;A}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>NI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{NI}</annotation></semantics></math></span>","Net income as reported under GAAP ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Interest expense</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Interest expense}</annotation></semantics></math></span>","Interest charged in the period (net of interest revenue, if the company defines it that way) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{D\\&amp;A}</annotation></semantics></math></span>","Depreciation and amortisation expense ($)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:is-effective-rate","kind":"formula","course":"f02","lesson":"income-statement","front":"Effective tax rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Effective tax rate</mtext><mo>=</mo><mfrac><mtext>Income tax expense</mtext><mtext>Income before income tax</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Effective tax rate} = \\dfrac{\\text{Income tax expense}}{\\text{Income before income tax}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Income tax expense</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Income tax expense}</annotation></semantics></math></span>","Total tax charged in the income statement for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Income before income tax</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Income before income tax}</annotation></semantics></math></span>","The subtotal before tax ($)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:is-basic-eps","kind":"formula","course":"f02","lesson":"income-statement","front":"Basic earnings per share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Basic EPS</mtext><mo>=</mo><mfrac><mrow><mtext>Net income</mtext><mo>−</mo><mtext>Preferred dividends</mtext></mrow><mtext>Weighted shares</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Basic EPS} = \\dfrac{\\text{Net income} - \\text{Preferred dividends}}{\\text{Weighted shares}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Preferred dividends</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Preferred dividends}</annotation></semantics></math></span>","Dividends due to preferred shareholders for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Weighted shares</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Weighted shares}</annotation></semantics></math></span>","The weighted average number of common shares outstanding: each share weighted by the fraction of the period it was outstanding (shares)"]],"href":"learn/finance/f02/income-statement/"},{"id":"f:f02:receivables-rollforward","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Accounts receivable roll-forward","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>AR</mtext><mtext>end</mtext></msub><mo>=</mo><msub><mtext>AR</mtext><mtext>beg</mtext></msub><mo>+</mo><mtext>Credit sales</mtext><mo>−</mo><mtext>Collections</mtext><mo>−</mo><mtext>Write-offs</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{AR}_{\\text{end}} = \\text{AR}_{\\text{beg}} + \\text{Credit sales} - \\text{Collections} - \\text{Write-offs}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>AR</mtext><mtext>beg</mtext></msub><mo separator=\"true\">,</mo><msub><mtext>AR</mtext><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{AR}_{\\text{beg}}, \\text{AR}_{\\text{end}}</annotation></semantics></math></span>","Accounts receivable at the start and end of the period (gross, before the allowance) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Credit sales</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Credit sales}</annotation></semantics></math></span>","Sales invoiced to customers on credit during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Collections</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Collections}</annotation></semantics></math></span>","Cash received from customers against their accounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Write-offs</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Write-offs}</annotation></semantics></math></span>","Customer balances removed as uncollectible during the period ($)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:aging-allowance","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Allowance required by an aging of receivables","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Required allowance</mtext><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>B</mi><mi>i</mi></msub><mo>×</mo><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Required allowance} = \\sum_{i} B_i \\times r_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_i</annotation></semantics></math></span>","Receivables in age band i (for example, not yet due, 31–60 days, over 60 days) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_i</annotation></semantics></math></span>","Expected loss rate for band i, as a decimal; higher for older bands"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑</mo><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\sum_{i}</annotation></semantics></math></span>","Sum over all the age bands"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:bad-debt-balance-sheet","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Bad debt expense under the balance sheet approach","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Bad debt expense</mtext><mo>=</mo><mtext>Required allowance</mtext><mo>−</mo><mtext>Unadjusted allowance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Bad debt expense} = \\text{Required allowance} - \\text{Unadjusted allowance}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Required allowance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Required allowance}</annotation></semantics></math></span>","The credit balance the allowance must have after adjustment (from the aging or a percentage of receivables) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Unadjusted allowance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Unadjusted allowance}</annotation></semantics></math></span>","The allowance’s balance before the adjustment: positive if a credit balance, negative if a debit balance ($)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:bad-debt-sales","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Bad debt expense under the income statement approach","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Bad debt expense</mtext><mo>=</mo><mi>p</mi><mo>×</mo><mtext>Credit sales</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Bad debt expense} = p \\times \\text{Credit sales}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Expected loss rate on credit sales, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Credit sales</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Credit sales}</annotation></semantics></math></span>","Sales on credit for the period (cash and card sales carry no credit risk) ($)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:net-receivables","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Net receivables (net realisable value of receivables)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net receivables</mtext><mo>=</mo><mtext>Accounts receivable</mtext><mo>−</mo><mtext>Allowance for doubtful accounts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net receivables} = \\text{Accounts receivable} - \\text{Allowance for doubtful accounts}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accounts receivable</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accounts receivable}</annotation></semantics></math></span>","Gross amount customers owe at the balance sheet date ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Allowance for doubtful accounts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Allowance for doubtful accounts}</annotation></semantics></math></span>","Credit balance of the allowance after adjustment ($)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:note-interest","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Interest on a note for part of a year","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Interest earned (or owed) for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal of the note ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time in years: months outstanding ÷ 12 (years)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:discount-cost","kind":"formula","course":"f02","lesson":"receivables-and-payables","front":"Annualised cost of skipping a cash discount","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cost</mtext><mo>=</mo><mfrac><mi>d</mi><mrow><mn>1</mn><mo>−</mo><mi>d</mi></mrow></mfrac><mo>×</mo><mfrac><mn>365</mn><mrow><mi>n</mi><mo>−</mo><mi>p</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Cost} = \\dfrac{d}{1 - d} \\times \\dfrac{365}{n - p}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount for early payment, as a decimal (2% = 0.02)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Days until the full amount is due (30 in 2/10, n/30) (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Last day of the discount period (10 in 2/10, n/30) (days)"]],"href":"learn/finance/f02/receivables-and-payables/"},{"id":"f:f02:depreciable-amount","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Depreciable amount","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Depreciable amount</mtext><mo>=</mo><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Depreciable amount} = \\text{Cost} - \\text{Residual value}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost}</annotation></semantics></math></span>","Everything paid to acquire the asset and get it ready for use ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Residual value}</annotation></semantics></math></span>","What the business expects to get for the asset at the end of its useful life ($)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:ddb","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Double-declining-balance depreciation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>D</mi><mi>t</mi></msub><mo>=</mo><mfrac><mn>2</mn><mi>n</mi></mfrac><mo>×</mo><mi>B</mi><msub><mi>V</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>but never taking </mtext><mi>B</mi><msub><mi>V</mi><mi>t</mi></msub><mtext> below the residual value</mtext></mrow><annotation encoding=\"application/x-tex\">D_t = \\dfrac{2}{n} \\times BV_{t-1}, \\quad \\text{but never taking } BV_t \\text{ below the residual value}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_t</annotation></semantics></math></span>","Depreciation for year t (for a part year, multiply by months used ÷ 12) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Useful life (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><msub><mi>V</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">BV_{t-1}</annotation></semantics></math></span>","Book value at the start of year t: cost minus accumulated depreciation ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><msub><mi>V</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">BV_t</annotation></semantics></math></span>","Book value at the end of year t ($)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:units-of-production","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Units-of-production depreciation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>D</mi><mo>=</mo><mfrac><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Total expected units</mtext></mfrac><mo>×</mo><mtext>Units used</mtext></mrow><annotation encoding=\"application/x-tex\">D = \\dfrac{\\text{Cost} - \\text{Residual value}}{\\text{Total expected units}} \\times \\text{Units used}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Depreciation for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost}</annotation></semantics></math></span>","Everything paid to acquire the asset and get it ready for use ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Residual value}</annotation></semantics></math></span>","What the business expects to get for the asset at the end of its useful life ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Total expected units</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Total expected units}</annotation></semantics></math></span>","Output expected over the asset’s life: miles, hours, units made (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Units used</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Units used}</annotation></semantics></math></span>","Output in the period (units)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:revised-depreciation","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Depreciation after a change in estimate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>New depreciation per year</mtext><mo>=</mo><mfrac><mrow><mi>B</mi><mi>V</mi><mo>−</mo><mtext>New residual value</mtext></mrow><mtext>Remaining useful life</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{New depreciation per year} = \\dfrac{BV - \\text{New residual value}}{\\text{Remaining useful life}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">BV</annotation></semantics></math></span>","Book value at the date of the change ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>New residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{New residual value}</annotation></semantics></math></span>","Revised estimate of what the asset will fetch at the end ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Remaining useful life</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Remaining useful life}</annotation></semantics></math></span>","Revised years of use left from the date of the change (years)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:disposal-gain-loss","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Gain or loss on disposal","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gain (loss)</mtext><mo>=</mo><mtext>Proceeds</mtext><mo>−</mo><mi>B</mi><msub><mi>V</mi><mtext>disposal</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Gain (loss)} = \\text{Proceeds} - BV_{\\text{disposal}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Proceeds</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Proceeds}</annotation></semantics></math></span>","Cash or the fair value of other assets received, less costs of selling ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><msub><mi>V</mi><mtext>disposal</mtext></msub></mrow><annotation encoding=\"application/x-tex\">BV_{\\text{disposal}}</annotation></semantics></math></span>","Cost minus accumulated depreciation, updated to the date of disposal ($)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:patent-amortisation","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Straight-line amortisation of a finite-lived intangible","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Amortisation per year</mtext><mo>=</mo><mfrac><mtext>Cost</mtext><mrow><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>Legal life left</mtext><mo separator=\"true\">,</mo><mtext> Useful life</mtext><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Amortisation per year} = \\dfrac{\\text{Cost}}{\\min(\\text{Legal life left}, \\ \\text{Useful life})}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost}</annotation></semantics></math></span>","Price paid for the intangible (residual value usually nil) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Legal life left</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Legal life left}</annotation></semantics></math></span>","Years of legal protection remaining (20 years from filing for a US utility patent) (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Useful life</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Useful life}</annotation></semantics></math></span>","Years the business expects the intangible to bring benefits (years)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:goodwill","kind":"formula","course":"f02","lesson":"long-lived-assets","front":"Goodwill in an acquisition","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Goodwill</mtext><mo>=</mo><mtext>Price paid</mtext><mo>−</mo><mo stretchy=\"false\">(</mo><mtext>FV of identifiable assets</mtext><mo>−</mo><mtext>FV of liabilities assumed</mtext><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Goodwill} = \\text{Price paid} - (\\text{FV of identifiable assets} - \\text{FV of liabilities assumed})</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Price paid</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Price paid}</annotation></semantics></math></span>","Consideration transferred for the business ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV of identifiable assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV of identifiable assets}</annotation></semantics></math></span>","Fair value of the assets that can be recognised separately, including intangibles ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV of liabilities assumed</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV of liabilities assumed}</annotation></semantics></math></span>","Fair value of the liabilities the buyer takes on ($)"]],"href":"learn/finance/f02/long-lived-assets/"},{"id":"f:f02:working-capital","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Working capital","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Working capital</mtext><mo>=</mo><mtext>Current assets</mtext><mo>−</mo><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Working capital} = \\text{Current assets} - \\text{Current liabilities}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","Cash and assets expected to become cash, be sold or be used up within one year or the operating cycle ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","Obligations due within the same horizon, including the current portion of long-term debt ($)"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:current-ratio","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Current ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Current ratio</mtext><mo>=</mo><mfrac><mtext>Current assets</mtext><mtext>Current liabilities</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Current ratio} = \\dfrac{\\text{Current assets}}{\\text{Current liabilities}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","As above ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","As above; must be greater than zero ($)"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:current-portion","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Splitting a loan at the balance sheet date","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Noncurrent portion</mtext><mo>=</mo><mtext>Principal outstanding</mtext><mo>−</mo><mtext>Principal due within 12 months</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Noncurrent portion} = \\text{Principal outstanding} - \\text{Principal due within 12 months}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Principal outstanding</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Principal outstanding}</annotation></semantics></math></span>","Loan principal owed at the balance sheet date ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Principal due within 12 months</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Principal due within 12 months}</annotation></semantics></math></span>","Instalments due in the next year: the current portion of long-term debt ($)"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:apic","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Common stock and additional paid-in capital on an issue of shares","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Common stock</mtext><mo>=</mo><mi>N</mi><mo>×</mo><mtext>Par</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>APIC</mtext><mo>=</mo><mi>N</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mi>P</mi><mo>−</mo><mtext>Par</mtext><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Common stock} = N \\times \\text{Par}, \\qquad \\text{APIC} = N \\times (P - \\text{Par})</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of shares issued (shares)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Issue price per share ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Par</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Par}</annotation></semantics></math></span>","Par (or stated) value per share; for no-par stock without a stated value, all proceeds go to common stock ($ per share)"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:dividend-amount","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Cash dividend declared","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Dividend</mtext><mo>=</mo><mi>d</mi><mo>×</mo><msub><mi>N</mi><mtext>out</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Dividend} = d \\times N_{\\text{out}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Dividend per share declared by the board ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>out</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{out}}</annotation></semantics></math></span>","Shares outstanding (issued shares less treasury shares) on the date of record (shares)"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:ratio-headroom","kind":"formula","course":"f02","lesson":"balance-sheet-and-equity","front":"Largest cash payment that keeps a minimum current ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Maximum payment</mtext><mo>=</mo><mtext>CA</mtext><mo>−</mo><mi>k</mi><mo>×</mo><mtext>CL</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Maximum payment} = \\text{CA} - k \\times \\text{CL}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CA</mtext><mo separator=\"true\">,</mo><mtext>CL</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CA}, \\text{CL}</annotation></semantics></math></span>","Current assets and current liabilities before the payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Minimum current ratio required, for example by a loan agreement"]],"href":"learn/finance/f02/balance-sheet-and-equity/"},{"id":"f:f02:cash-bridge","kind":"formula","course":"f02","lesson":"cash-flow-statement","front":"Opening cash to closing cash","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>Cash</mtext><mtext>end</mtext></msub><mo>=</mo><msub><mtext>Cash</mtext><mtext>beg</mtext></msub><mo>+</mo><mtext>CFO</mtext><mo>+</mo><mtext>CFI</mtext><mo>+</mo><mtext>CFF</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}_{\\text{end}} = \\text{Cash}_{\\text{beg}} + \\text{CFO} + \\text{CFI} + \\text{CFF}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Cash</mtext><mtext>beg</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mtext>Cash</mtext><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}_{\\text{beg}},\\ \\text{Cash}_{\\text{end}}</annotation></semantics></math></span>","Cash and cash equivalents at the start and the end of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CFO</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CFO}</annotation></semantics></math></span>","Net cash from operating activities ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CFI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CFI}</annotation></semantics></math></span>","Net cash from investing activities (negative when cash is used) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CFF</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CFF}</annotation></semantics></math></span>","Net cash from financing activities (negative when cash is used) ($)"]],"href":"learn/finance/f02/cash-flow-statement/"},{"id":"f:f02:cash-from-customers","kind":"formula","course":"f02","lesson":"cash-flow-statement","front":"Cash received from customers","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cash collected</mtext><mo>=</mo><mtext>Revenue</mtext><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Receivables</mtext><mo>−</mo><mtext>Write-offs</mtext><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Unearned revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash collected} = \\text{Revenue} - \\Delta\\text{Receivables} - \\text{Write-offs} + \\Delta\\text{Unearned revenue}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Revenue}</annotation></semantics></math></span>","Net revenue on the income statement (after returns and discounts) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Receivables</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Receivables}</annotation></semantics></math></span>","Closing minus opening accounts receivable, before the allowance ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Write-offs</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Write-offs}</annotation></semantics></math></span>","Receivables written off during the period as uncollectible ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Unearned revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Unearned revenue}</annotation></semantics></math></span>","Closing minus opening unearned revenue (customer deposits and prepayments) ($)"]],"href":"learn/finance/f02/cash-flow-statement/"},{"id":"f:f02:cash-paid-inventory","kind":"formula","course":"f02","lesson":"cash-flow-statement","front":"Cash paid for inventory","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cash paid</mtext><mo>=</mo><mtext>COGS</mtext><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Inventory</mtext><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Payables</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash paid} = \\text{COGS} + \\Delta\\text{Inventory} - \\Delta\\text{Payables}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>COGS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{COGS}</annotation></semantics></math></span>","Cost of goods sold for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Inventory</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Inventory}</annotation></semantics></math></span>","Closing minus opening inventory ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Payables</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Payables}</annotation></semantics></math></span>","Closing minus opening accounts payable to inventory suppliers ($)"]],"href":"learn/finance/f02/cash-flow-statement/"},{"id":"f:f02:cash-paid-expense","kind":"formula","course":"f02","lesson":"cash-flow-statement","front":"Cash paid for an operating expense","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cash paid</mtext><mo>=</mo><mtext>Expense</mtext><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Prepaid</mtext><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Accrued liability</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash paid} = \\text{Expense} + \\Delta\\text{Prepaid} - \\Delta\\text{Accrued liability}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Expense</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Expense}</annotation></semantics></math></span>","The expense on the income statement (wages, insurance, interest, income tax …) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Prepaid</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Prepaid}</annotation></semantics></math></span>","Closing minus opening prepayment for that expense, if any ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Accrued liability</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Accrued liability}</annotation></semantics></math></span>","Closing minus opening payable for that expense (wages payable, interest payable …) ($)"]],"href":"learn/finance/f02/cash-flow-statement/"},{"id":"f:f02:indirect-cfo","kind":"formula","course":"f02","lesson":"indirect-method","front":"Net cash from operating activities (indirect method)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CFO</mtext><mo>=</mo><mtext>NI</mtext><mo>+</mo><mtext>Noncash expenses</mtext><mo>+</mo><mtext>Losses</mtext><mo>−</mo><mtext>Gains</mtext><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><msub><mtext>CA</mtext><mtext>op</mtext></msub><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><msub><mtext>CL</mtext><mtext>op</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CFO} = \\text{NI} + \\text{Noncash expenses} + \\text{Losses} - \\text{Gains} - \\Delta\\text{CA}_{\\text{op}} + \\Delta\\text{CL}_{\\text{op}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CFO</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CFO}</annotation></semantics></math></span>","Net cash from operating activities ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>NI</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{NI}</annotation></semantics></math></span>","Net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Noncash expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Noncash expenses}</annotation></semantics></math></span>","Depreciation, amortisation, impairment and similar charges ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Losses</mtext><mo separator=\"true\">,</mo><mtext> Gains</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Losses},\\ \\text{Gains}</annotation></semantics></math></span>","Losses and gains on selling long-term assets or settling debt ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mtext>CA</mtext><mtext>op</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{CA}_{\\text{op}}</annotation></semantics></math></span>","Closing minus opening operating current assets other than cash (receivables net of the allowance, inventory, prepayments) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mtext>CL</mtext><mtext>op</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{CL}_{\\text{op}}</annotation></semantics></math></span>","Closing minus opening operating current liabilities (payables, accruals, unearned revenue, income taxes payable) ($)"]],"href":"learn/finance/f02/indirect-method/"},{"id":"f:f02:cash-identity","kind":"formula","course":"f02","lesson":"indirect-method","front":"The change in cash from the balance sheet","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Cash</mtext><mo>=</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Liabilities</mtext><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Equity</mtext><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mtext>Noncash assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta\\text{Cash} = \\Delta\\text{Liabilities} + \\Delta\\text{Equity} - \\Delta\\text{Noncash assets}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta</annotation></semantics></math></span>","Closing balance minus opening balance"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Noncash assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Noncash assets}</annotation></semantics></math></span>","Every asset except cash and cash equivalents, net of contra accounts ($)"]],"href":"learn/finance/f02/indirect-method/"},{"id":"f:f02:sale-proceeds","kind":"formula","course":"f02","lesson":"indirect-method","front":"Cash proceeds from selling a long-term asset","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Proceeds</mtext><mo>=</mo><mo stretchy=\"false\">(</mo><mtext>Cost</mtext><mo>−</mo><mtext>Accumulated depreciation</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mtext>Gain</mtext><mo>−</mo><mtext>Loss</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Proceeds} = (\\text{Cost} - \\text{Accumulated depreciation}) + \\text{Gain} - \\text{Loss}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Accumulated depreciation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost} - \\text{Accumulated depreciation}</annotation></semantics></math></span>","The asset’s book value at the date of sale ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Gain</mtext><mo separator=\"true\">,</mo><mtext> Loss</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Gain},\\ \\text{Loss}</annotation></semantics></math></span>","The gain or loss recorded on the sale (only one is non-zero) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Proceeds</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Proceeds}</annotation></semantics></math></span>","Cash received: an investing inflow ($)"]],"href":"learn/finance/f02/indirect-method/"},{"id":"f:f02:roll-forward","kind":"formula","course":"f02","lesson":"indirect-method","front":"Account roll-forward","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Closing</mtext><mo>=</mo><mtext>Opening</mtext><mo>+</mo><mtext>Additions</mtext><mo>−</mo><mtext>Reductions</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Closing} = \\text{Opening} + \\text{Additions} - \\text{Reductions}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Opening</mtext><mo separator=\"true\">,</mo><mtext> Closing</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Opening},\\ \\text{Closing}</annotation></semantics></math></span>","The account’s balances on the two balance sheets ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Additions</mtext><mo separator=\"true\">,</mo><mtext> Reductions</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Additions},\\ \\text{Reductions}</annotation></semantics></math></span>","What increased and decreased the account during the year (purchases and disposals, borrowing and repayments, net income and dividends) ($)"]],"href":"learn/finance/f02/indirect-method/"},{"id":"f:f02:lnk-gap-clue","kind":"formula","course":"f02","lesson":"linking-the-statements","front":"Reading the size of a failed cash link","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gap</mtext><mo>=</mo><mrow><mo fence=\"true\">{</mo><mtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>X</mi></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mtext>item omitted, counted twice, or noncash treated as cash</mtext></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mn>2</mn><mi>X</mi></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mtext>item entered with the wrong sign</mtext></mstyle></mtd></mtr></mtable></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{Gap} = \\begin{cases} X &amp; \\text{item omitted, counted twice, or noncash treated as cash} \\\\ 2X &amp; \\text{item entered with the wrong sign} \\end{cases}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Gap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Gap}</annotation></semantics></math></span>","Ending cash on the draft statement of cash flows minus cash on the balance sheet (or the reverse) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X</annotation></semantics></math></span>","The amount of the item that is wrong ($)"]],"href":"learn/finance/f02/linking-the-statements/"},{"id":"f:f02:lnk-after-tax","kind":"formula","course":"f02","lesson":"linking-the-statements","front":"After-tax effect of a change in a pretax expense","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>N</mi><mi>I</mi><mo>=</mo><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>t</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta NI = -(1 - t)\\,\\Delta X</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>N</mi><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta NI</annotation></semantics></math></span>","Change in net income ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta X</annotation></semantics></math></span>","Change in an expense deducted before tax (positive when the expense rises) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Tax rate on income before tax, as a decimal"]],"href":"learn/finance/f02/linking-the-statements/"},{"id":"f:f02:lnk-noncash-cash","kind":"formula","course":"f02","lesson":"linking-the-statements","front":"Cash and tax payable after a change in a noncash expense","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>CFO</mtext><mo>=</mo><mi>t</mi><mo>×</mo><mi>p</mi><mo>×</mo><mi mathvariant=\"normal\">Δ</mi><mi>N</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">Δ</mi><mtext>Tax payable</mtext><mo>=</mo><mo>−</mo><mi>t</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>p</mi><mo stretchy=\"false\">)</mo><mo>×</mo><mi mathvariant=\"normal\">Δ</mi><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{CFO} = t \\times p \\times \\Delta N, \\qquad \\Delta \\text{Tax payable} = -t \\times (1 - p) \\times \\Delta N</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>CFO</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{CFO}</annotation></semantics></math></span>","Change in cash from operating activities ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Tax payable</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Tax payable}</annotation></semantics></math></span>","Change in income taxes payable at the year end ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta N</annotation></semantics></math></span>","Change in a tax-deductible noncash expense, such as depreciation or a write-down ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Tax rate on income before tax, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Share of the change in tax that is paid within the year (1 if all of it, 0 if none)"]],"href":"learn/finance/f02/linking-the-statements/"},{"id":"f:f02:gi-revaluation","kind":"formula","course":"f02","lesson":"gaap-and-ifrs","front":"Revaluation surplus and depreciation after revaluation (IAS 16)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Surplus</mtext><mo>=</mo><mtext>FV</mtext><mo>−</mo><mtext>CA</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Depreciation</mtext><mo>=</mo><mfrac><mrow><mtext>FV</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Remaining life</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Surplus} = \\text{FV} - \\text{CA}, \\qquad \\text{Depreciation} = \\dfrac{\\text{FV} - \\text{Residual value}}{\\text{Remaining life}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Fair value of the asset at the revaluation date ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CA</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CA}</annotation></semantics></math></span>","Carrying amount just before the revaluation (cost less accumulated depreciation) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Residual value}</annotation></semantics></math></span>","Expected value at the end of the asset’s use ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Remaining life</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Remaining life}</annotation></semantics></math></span>","Years of use left after the revaluation (years)"]],"href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"f:f02:gi-reval-decrease","kind":"formula","course":"f02","lesson":"gaap-and-ifrs","front":"A later fall in value under the revaluation model (IAS 16)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>OCI part</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>Decrease</mtext><mo separator=\"true\">,</mo><mtext> Surplus</mtext><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Loss in profit</mtext><mo>=</mo><mtext>Decrease</mtext><mo>−</mo><mtext>OCI part</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{OCI part} = \\min(\\text{Decrease},\\ \\text{Surplus}), \\qquad \\text{Loss in profit} = \\text{Decrease} - \\text{OCI part}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Decrease</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Decrease}</annotation></semantics></math></span>","Carrying amount just before the valuation minus the new fair value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Surplus</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Surplus}</annotation></semantics></math></span>","Revaluation surplus still held in equity for the same asset ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>OCI part</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{OCI part}</annotation></semantics></math></span>","Part of the decrease taken against the surplus, through other comprehensive income ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Loss in profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Loss in profit}</annotation></semantics></math></span>","Part of the decrease recognised in profit or loss ($)"]],"href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"f:f02:gi-dev-profit","kind":"formula","course":"f02","lesson":"gaap-and-ifrs","front":"Profit difference from capitalised development costs","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mtext>Profit</mtext><mrow><mtext>IFRS</mtext><mo>−</mo><mtext>US</mtext></mrow></msub><mo>=</mo><mtext>Development capitalised</mtext><mo>−</mo><mtext>Amortisation</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Profit}_{\\text{IFRS} - \\text{US}} = \\text{Development capitalised} - \\text{Amortisation}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mtext>Profit</mtext><mrow><mtext>IFRS</mtext><mo>−</mo><mtext>US</mtext></mrow></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Profit}_{\\text{IFRS} - \\text{US}}</annotation></semantics></math></span>","IFRS profit before tax minus US GAAP profit before tax for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Development capitalised</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Development capitalised}</annotation></semantics></math></span>","Development costs recognised as an intangible asset in the period (zero under US GAAP) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Amortisation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Amortisation}</annotation></semantics></math></span>","Amortisation of capitalised development costs charged in the period ($)"]],"href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"f:f02:gi-ifrs-to-us","kind":"formula","course":"f02","lesson":"gaap-and-ifrs","front":"Restating IFRS profit before tax on a US GAAP basis","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>PBT</mtext><mtext>US</mtext></msub><mo>=</mo><msub><mtext>PBT</mtext><mtext>IFRS</mtext></msub><mo>−</mo><mtext>DC</mtext><mo>+</mo><mtext>AM</mtext><mo>−</mo><mtext>RV</mtext><mo>+</mo><mtext>XD</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PBT}_{\\text{US}} = \\text{PBT}_{\\text{IFRS}} - \\text{DC} + \\text{AM} - \\text{RV} + \\text{XD}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PBT</mtext><mtext>IFRS</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mtext>PBT</mtext><mtext>US</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PBT}_{\\text{IFRS}},\\ \\text{PBT}_{\\text{US}}</annotation></semantics></math></span>","Profit before tax under each framework ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>DC</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{DC}</annotation></semantics></math></span>","Development costs capitalised under IAS 38 in the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>AM</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{AM}</annotation></semantics></math></span>","Amortisation of development costs capitalised earlier ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>RV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{RV}</annotation></semantics></math></span>","Reversals of inventory write-downs recognised in the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>XD</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{XD}</annotation></semantics></math></span>","Depreciation on revalued amounts above what cost-based depreciation would be, plus any revaluation losses in profit ($)"]],"href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"f:f02:gi-cfo-ifrs18","kind":"formula","course":"f02","lesson":"gaap-and-ifrs","front":"Operating cash flow: from US GAAP to IAS 7 as amended by IFRS 18","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>CFO</mtext><mtext>IFRS 18</mtext></msub><mo>=</mo><msub><mtext>CFO</mtext><mtext>US</mtext></msub><mo>+</mo><mtext>IP</mtext><mo>−</mo><mtext>IR</mtext><mo>−</mo><mtext>DR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CFO}_{\\text{IFRS 18}} = \\text{CFO}_{\\text{US}} + \\text{IP} - \\text{IR} - \\text{DR}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CFO</mtext><mtext>US</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CFO}_{\\text{US}}</annotation></semantics></math></span>","Cash from operating activities under US GAAP ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IP</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IP}</annotation></semantics></math></span>","Interest paid (moves to financing) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IR}</annotation></semantics></math></span>","Interest received (moves to investing) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>DR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{DR}</annotation></semantics></math></span>","Dividends received (move to investing) ($)"]],"href":"learn/finance/f02/gaap-and-ifrs/"},{"id":"f:f04:sci-simple","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Simple interest","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>FV</mtext><mo>=</mo><mi>P</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mi>t</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t, \\qquad \\text{FV} = P(1 + rt)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Interest for the whole time ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal: the amount lent, borrowed or deposited (its present value) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (6% = 0.06) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Balance at the end, if the interest is added rather than paid out ($)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:sci-daycount","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Interest for part of a year (day count)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mfrac><mi>D</mi><mi>B</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times \\frac{D}{B}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Interest accrued over the days counted ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Days counted under the convention: actual calendar days, or 30 a month under 30/360 (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Days in the convention’s year: 365 (actual/365) or 360 (actual/360 and 30/360) (days)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:sci-fv","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Future value under compound interest","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>FV</mtext><mo>=</mo><mtext>PV</mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\"application/x-tex\">\\text{FV} = \\text{PV}(1 + r)^n</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Future value: the balance after n periods ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value: the amount today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods (may be fractional) (periods)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:sci-rate","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Rate linking two amounts (compound annual growth rate)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mfrac><mtext>FV</mtext><mtext>PV</mtext></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">r = \\left(\\frac{\\text{FV}}{\\text{PV}}\\right)^{1/n} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Constant compound rate per period (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Amount at the end ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount at the start ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods between them (periods)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:sci-periods","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Number of periods to reach a target","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>n</mi><mo>=</mo><mfrac><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>FV</mtext><mi mathvariant=\"normal\">/</mi><mtext>PV</mtext><mo stretchy=\"false\">)</mo></mrow><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">n = \\frac{\\ln(\\text{FV}/\\text{PV})}{\\ln(1 + r)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods needed (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Target amount ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Starting amount ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:sci-double","kind":"formula","course":"f04","lesson":"simple-and-compound-interest","front":"Doubling time and the rule of 72","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>n</mi><mtext>double</mtext></msub><mo>=</mo><mfrac><mrow><mi>ln</mi><mo>⁡</mo><mn>2</mn></mrow><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow></mfrac><mtext>  </mtext><mo>≈</mo><mtext>  </mtext><mfrac><mn>72</mn><mrow><mn>100</mn><mtext> </mtext><mi>r</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">n_{\\text{double}} = \\frac{\\ln 2}{\\ln(1 + r)} \\;\\approx\\; \\frac{72}{100\\,r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>double</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{double}}</annotation></semantics></math></span>","Periods needed for an amount to double (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/simple-and-compound-interest/"},{"id":"f:f04:ear-periodic","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Periodic rate from a nominal annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><mfrac><mtext>APR</mtext><mi>m</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\frac{\\text{APR}}{m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per compounding period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Nominal annual rate: the quoted yearly rate, ignoring compounding (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year (1, 2, 4, 12, 52, 365)"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:ear-ear","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Effective annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EAR</mtext><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mtext>APR</mtext><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mi>m</mi></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\text{EAR} = \\left(1 + \\frac{\\text{APR}}{m}\\right)^{m} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","Effective annual rate: the equivalent rate compounded once a year (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Nominal annual rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:ear-back","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Nominal rate from an effective annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>APR</mtext><mo>=</mo><mi>m</mi><mrow><mo fence=\"true\">[</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mtext>EAR</mtext><msup><mo stretchy=\"false\">)</mo><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>m</mi></mrow></msup><mo>−</mo><mn>1</mn><mo fence=\"true\">]</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{APR} = m\\left[(1 + \\text{EAR})^{1/m} - 1\\right]</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Nominal annual rate compounded m times a year (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","Effective annual rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:ear-equiv","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Equivalent rate at another compounding frequency","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>APR</mtext><mn>2</mn></msub><mo>=</mo><msub><mi>m</mi><mn>2</mn></msub><mrow><mo fence=\"true\">[</mo><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><msub><mtext>APR</mtext><mn>1</mn></msub><msub><mi>m</mi><mn>1</mn></msub></mfrac><mo fence=\"true\">)</mo></mrow><mrow><msub><mi>m</mi><mn>1</mn></msub><mi mathvariant=\"normal\">/</mi><msub><mi>m</mi><mn>2</mn></msub></mrow></msup><mo>−</mo><mn>1</mn><mo fence=\"true\">]</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{APR}_2 = m_2\\left[\\left(1 + \\frac{\\text{APR}_1}{m_1}\\right)^{m_1/m_2} - 1\\right]</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>APR</mtext><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{APR}_1</annotation></semantics></math></span>","The quoted nominal annual rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_1</annotation></semantics></math></span>","Compounding periods per year of the quoted rate"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>APR</mtext><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{APR}_2</annotation></semantics></math></span>","The equivalent nominal annual rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_2</annotation></semantics></math></span>","Compounding periods per year wanted"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:ear-continuous","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Continuous compounding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>FV</mtext><mo>=</mo><mtext>PV</mtext><mtext> </mtext><msup><mi>e</mi><mrow><mtext>APR</mtext><mtext> </mtext><mi>t</mi></mrow></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>EAR</mtext><mo>=</mo><msup><mi>e</mi><mtext>APR</mtext></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\text{FV} = \\text{PV}\\,e^{\\text{APR}\\,t}, \\qquad \\text{EAR} = e^{\\text{APR}} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Future value after t years ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Nominal annual rate, compounded continuously (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e</mi></mrow><annotation encoding=\"application/x-tex\">e</annotation></semantics></math></span>","The constant 2.718282…, base of natural logarithms"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","Effective annual rate (per year)"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:ear-apy","kind":"formula","course":"f04","lesson":"effective-annual-rates","front":"Annual percentage yield (Regulation DD, Appendix A)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>APY</mtext><mo>=</mo><mn>100</mn><mrow><mo fence=\"true\">[</mo><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mtext>Interest</mtext><mtext>Principal</mtext></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mn>365</mn><mi mathvariant=\"normal\">/</mi><mtext>Days in term</mtext></mrow></msup><mo>−</mo><mn>1</mn><mo fence=\"true\">]</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{APY} = 100\\left[\\left(1 + \\frac{\\text{Interest}}{\\text{Principal}}\\right)^{365/\\text{Days in term}} - 1\\right]</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APY</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APY}</annotation></semantics></math></span>","Annual percentage yield (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Interest</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Interest}</annotation></semantics></math></span>","Total interest earned on the principal over the term ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Principal</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Principal}</annotation></semantics></math></span>","Amount assumed deposited at the start ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days in term</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days in term}</annotation></semantics></math></span>","Actual number of days in the term (365 for an account with no fixed term) (days)"]],"href":"learn/finance/f04/effective-annual-rates/"},{"id":"f:f04:pfv-fv","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Future value of a single amount","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>FV</mtext><mo>=</mo><mtext>PV</mtext><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\"application/x-tex\">\\text{FV} = \\text{PV}\\,(1 + r)^{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Future value: what the amount is worth after n periods ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value: the amount today (time 0) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods; need not be a whole number (periods)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:pfv-pv","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Present value and the discount factor","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><mfrac><mtext>FV</mtext><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac><mo>=</mo><mtext>FV</mtext><mo>×</mo><msub><mtext>DF</mtext><mi>n</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>DF</mtext><mi>n</mi></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\frac{\\text{FV}}{(1 + r)^{n}} = \\text{FV} \\times \\text{DF}_n, \\qquad \\text{DF}_n = \\frac{1}{(1 + r)^{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value: what the future amount is worth today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","The amount received after n periods ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>DF</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{DF}_n</annotation></semantics></math></span>","Discount factor: the present value of $1 received after n periods"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per period, as a decimal: the return available elsewhere at similar risk (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods until the amount is received (periods)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:pfv-apr","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Rate per period and number of periods from a quoted annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><mfrac><mtext>APR</mtext><mi>m</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>n</mi><mo>=</mo><mi>m</mi><mtext> </mtext><mi>t</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>PV</mtext><mo>=</mo><mtext>FV</mtext><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mtext>APR</mtext><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mo>−</mo><mi>m</mi><mi>t</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">r = \\frac{\\text{APR}}{m}, \\qquad n = m\\,t, \\qquad \\text{PV} = \\text{FV}\\left(1 + \\frac{\\text{APR}}{m}\\right)^{-m t}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per compounding period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Quoted (nominal) annual rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year (2 semi-annual, 4 quarterly, 12 monthly) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of compounding periods (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time until the amount is received (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","The future amount ($)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:pfv-move","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Value at any date (moving an amount)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>V</mi><mi>k</mi></msub><mo>=</mo><mi>X</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mi>k</mi><mo>−</mo><mi>j</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">V_k = X\\,(1 + r)^{k - j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">V_k</annotation></semantics></math></span>","Value of the amount at the comparison date, period k ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X</annotation></semantics></math></span>","The amount, which falls due at period j ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">j</annotation></semantics></math></span>","The period when the amount falls due (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The comparison date (periods)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:pfv-changing","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Changing rates and the equivalent constant rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>FV</mtext><mo>=</mo><mtext>PV</mtext><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo><mo>⋯</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>n</mi></msub><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mover accent=\"true\"><mi>r</mi><mo>ˉ</mo></mover><mo>=</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">[</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo><mo>⋯</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>n</mi></msub><mo stretchy=\"false\">)</mo><msup><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">]</mo><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\text{FV} = \\text{PV}\\,(1 + r_1)(1 + r_2)\\cdots(1 + r_n), \\qquad \\bar{r} = \\big[(1 + r_1)(1 + r_2)\\cdots(1 + r_n)\\big]^{1/n} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Value at the end of period n ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Value at time 0 ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_i</annotation></semantics></math></span>","Rate in period i, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>r</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{r}</annotation></semantics></math></span>","The constant rate per period that gives the same growth (a geometric mean) (per period)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:pfv-solve","kind":"formula","course":"f04","lesson":"present-and-future-value","front":"Solving for the rate or the number of periods","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mfrac><mtext>FV</mtext><mtext>PV</mtext></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>n</mi><mo>=</mo><mfrac><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>FV</mtext><mi mathvariant=\"normal\">/</mi><mtext>PV</mtext><mo stretchy=\"false\">)</mo></mrow><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\left(\\frac{\\text{FV}}{\\text{PV}}\\right)^{1/n} - 1, \\qquad n = \\frac{\\ln(\\text{FV} / \\text{PV})}{\\ln(1 + r)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount at time 0 ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Amount after n periods ($)"]],"href":"learn/finance/f04/present-and-future-value/"},{"id":"f:f04:dcf-pv","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Present value of an uneven stream","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mfrac><msub><mi>C</mi><mi>t</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\sum_{t=1}^{n} \\frac{C_t}{(1 + r)^{t}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value of the stream at time 0 ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_t</annotation></semantics></math></span>","Cash flow at the end of period t (positive if received, negative if paid) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Period in which the cash flow arrives (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Last period with a cash flow (periods)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:dcf-any-date","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Value of a stream at any date","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>V</mi><mi>T</mi></msub><mo>=</mo><munder><mo>∑</mo><mi>t</mi></munder><msub><mi>C</mi><mi>t</mi></msub><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mi>T</mi><mo>−</mo><mi>t</mi></mrow></msup><mo>=</mo><mtext>PV</mtext><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>T</mi></msup></mrow><annotation encoding=\"application/x-tex\">V_T = \\sum_{t} C_t\\,(1 + r)^{T - t} = \\text{PV} \\times (1 + r)^{T}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V</mi><mi>T</mi></msub></mrow><annotation encoding=\"application/x-tex\">V_T</annotation></semantics></math></span>","Value of the whole stream at period T ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_t</annotation></semantics></math></span>","Cash flow at period t ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","The comparison date (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Period in which the cash flow arrives (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Value of the stream at time 0 ($)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:dcf-npv","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Net present value","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>NPV</mtext><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>0</mn></mrow><mi>n</mi></munderover><mfrac><msub><mi>C</mi><mi>t</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac><mo>=</mo><msub><mi>C</mi><mn>0</mn></msub><mo>+</mo><mfrac><msub><mi>C</mi><mn>1</mn></msub><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo>+</mo><mo>⋯</mo><mo>+</mo><mfrac><msub><mi>C</mi><mi>n</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{NPV} = \\sum_{t=0}^{n} \\frac{C_t}{(1 + r)^{t}} = C_0 + \\frac{C_1}{1 + r} + \\cdots + \\frac{C_n}{(1 + r)^{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>NPV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{NPV}</annotation></semantics></math></span>","Net present value of the decision ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">C_0</annotation></semantics></math></span>","Cash flow today, usually a cost (negative) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_t</annotation></semantics></math></span>","Incremental cash flow at the end of period t ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per period: the return available elsewhere at similar risk (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Period in which the cash flow arrives (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Last period with a cash flow (periods)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:dcf-irregular","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Present value with irregular dates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><mfrac><msub><mi>C</mi><mi>i</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mtext>EAR</mtext><msup><mo stretchy=\"false\">)</mo><msub><mi>t</mi><mi>i</mi></msub></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\sum_{i} \\frac{C_i}{(1 + \\text{EAR})^{t_i}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value of the cash flows ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_i</annotation></semantics></math></span>","The i-th cash flow ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">t_i</annotation></semantics></math></span>","Time from today until the i-th cash flow (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","Effective annual discount rate, as a decimal (per year)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:dcf-irr","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Internal rate of return","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mn>0</mn><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>0</mn></mrow><mi>n</mi></munderover><mfrac><msub><mi>C</mi><mi>t</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mtext>IRR</mtext><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">0 = \\sum_{t=0}^{n} \\frac{C_t}{(1 + \\text{IRR})^{t}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IRR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IRR}</annotation></semantics></math></span>","Internal rate of return: the rate per period at which the NPV is zero (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_t</annotation></semantics></math></span>","Cash flow at period t, including the time-0 cost ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Period in which the cash flow arrives (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Last period with a cash flow (periods)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:dcf-interp","kind":"formula","course":"f04","lesson":"discounting-cash-flows","front":"Linear interpolation between two trial rates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>IRR</mtext><mo>≈</mo><msub><mi>r</mi><mi>L</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><msub><mi>r</mi><mi>H</mi></msub><mo>−</mo><msub><mi>r</mi><mi>L</mi></msub><mo stretchy=\"false\">)</mo><mtext> </mtext><mfrac><msub><mtext>NPV</mtext><mi>L</mi></msub><mrow><msub><mtext>NPV</mtext><mi>L</mi></msub><mo>−</mo><msub><mtext>NPV</mtext><mi>H</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{IRR} \\approx r_L + (r_H - r_L)\\,\\frac{\\text{NPV}_L}{\\text{NPV}_L - \\text{NPV}_H}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_L</annotation></semantics></math></span>","Lower trial rate, where the NPV is positive (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>H</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_H</annotation></semantics></math></span>","Higher trial rate, where the NPV is negative (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>NPV</mtext><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{NPV}_L</annotation></semantics></math></span>","NPV at the lower rate ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>NPV</mtext><mi>H</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{NPV}_H</annotation></semantics></math></span>","NPV at the higher rate ($)"]],"href":"learn/finance/f04/discounting-cash-flows/"},{"id":"f:f04:pv-annuity","kind":"formula","course":"f04","lesson":"annuities","front":"Present value of an ordinary annuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = C \\times \\frac{1 - (1 + r)^{-n}}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value: the value of the whole stream one period before the first payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (an APR compounded monthly ÷ 12 for monthly payments) (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:fv-annuity","kind":"formula","course":"f04","lesson":"annuities","front":"Future value of an ordinary annuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>FV</mtext><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup><mo>−</mo><mn>1</mn></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{FV} = C \\times \\frac{(1 + r)^{n} - 1}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Future value: the value of the stream at the date of the last payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment (deposit) per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:annuity-due","kind":"formula","course":"f04","lesson":"annuities","front":"Annuity due (payments at the start of each period)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>PV</mtext><mtext>due</mtext></msub><mo>=</mo><msub><mtext>PV</mtext><mtext>ord</mtext></msub><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>FV</mtext><mtext>due</mtext></msub><mo>=</mo><msub><mtext>FV</mtext><mtext>ord</mtext></msub><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_{\\text{due}} = \\text{PV}_{\\text{ord}} \\times (1 + r), \\qquad \\text{FV}_{\\text{due}} = \\text{FV}_{\\text{ord}} \\times (1 + r)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PV</mtext><mtext>due</mtext></msub><mo separator=\"true\">,</mo><msub><mtext>FV</mtext><mtext>due</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_{\\text{due}}, \\text{FV}_{\\text{due}}</annotation></semantics></math></span>","Values when each payment is made at the start of its period: the present value today (time 0, the date of the first payment) and the future value at the end of period n, one period after the last payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PV</mtext><mtext>ord</mtext></msub><mo separator=\"true\">,</mo><msub><mtext>FV</mtext><mtext>ord</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_{\\text{ord}}, \\text{FV}_{\\text{ord}}</annotation></semantics></math></span>","The same values for an ordinary annuity with the same payment, rate and number of payments ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:deferred-annuity","kind":"formula","course":"f04","lesson":"annuities","front":"Deferred annuity (first payment at the end of period k + 1)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>PV</mtext><mn>0</mn></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>k</mi></msup></mrow></mfrac><mo>×</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_0 = \\frac{1}{(1 + r)^{k}} \\times C \\times \\frac{1 - (1 + r)^{-n}}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PV</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_0</annotation></semantics></math></span>","Value today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of periods before the annuity formula’s valuation date: one less than the period of the first payment (periods)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:growing-annuity","kind":"formula","course":"f04","lesson":"annuities","front":"Present value of a growing annuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><mfrac><msub><mi>C</mi><mn>1</mn></msub><mrow><mi>r</mi><mo>−</mo><mi>g</mi></mrow></mfrac><mrow><mo fence=\"true\">[</mo><mn>1</mn><mo>−</mo><msup><mrow><mo fence=\"true\">(</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>g</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo fence=\"true\">)</mo></mrow><mi>n</mi></msup><mo fence=\"true\">]</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\frac{C_1}{r - g}\\left[1 - \\left(\\frac{1 + g}{1 + r}\\right)^{n}\\right]</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value, one period before the first payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">C_1</annotation></semantics></math></span>","The first payment, made at the end of period 1 ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Growth rate of the payment per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:annuity-payment","kind":"formula","course":"f04","lesson":"annuities","front":"The payment of an annuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>C</mi><mo>=</mo><mfrac><mrow><mtext>PV</mtext><mo>×</mo><mi>r</mi></mrow><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow></mfrac><mspace width=\"2em\"/><mtext>or</mtext><mspace width=\"2em\"/><mi>C</mi><mo>=</mo><mfrac><mrow><mtext>FV</mtext><mo>×</mo><mi>r</mi></mrow><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup><mo>−</mo><mn>1</mn></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">C = \\frac{\\text{PV} \\times r}{1 - (1 + r)^{-n}} \\qquad\\text{or}\\qquad C = \\frac{\\text{FV} \\times r}{(1 + r)^{n} - 1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount to be repaid or drawn down (a loan, a fund) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>FV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{FV}</annotation></semantics></math></span>","Target to be reached by saving (a sinking fund) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:annuity-periods","kind":"formula","course":"f04","lesson":"annuities","front":"The number of payments","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>n</mi><mo>=</mo><mfrac><mrow><mo>−</mo><mi>ln</mi><mo>⁡</mo><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>−</mo><mfrac><mrow><mtext>PV</mtext><mo>×</mo><mi>r</mi></mrow><mi>C</mi></mfrac><mo fence=\"true\">)</mo></mrow></mrow><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">n = \\frac{-\\ln\\left(1 - \\dfrac{\\text{PV} \\times r}{C}\\right)}{\\ln(1 + r)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (usually not a whole number: round up, with a smaller last payment) (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount to be repaid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period; must exceed PV × r ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/annuities/"},{"id":"f:f04:perpetuity","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Present value of a level perpetuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><mfrac><mi>C</mi><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\frac{C}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Value one period before the first payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period, for ever ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest (discount) rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:growing-perpetuity","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Present value of a growing perpetuity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><mfrac><msub><mi>C</mi><mn>1</mn></msub><mrow><mi>r</mi><mo>−</mo><mi>g</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\frac{C_1}{r - g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Value one period before the first payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">C_1</annotation></semantics></math></span>","The first payment, one period from now (C₁ = C₀(1 + g) if C₀ has just been paid) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Constant growth rate of the payment per period, as a decimal (per period)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:preferred-share","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Value of a preferred share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>D</mi><msub><mi>r</mi><mi>p</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\frac{D}{r_p}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Value of one preferred share, one period before the next dividend ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Fixed dividend per period (par value × dividend rate, per period) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_p</annotation></semantics></math></span>","Return investors require on similar preferred shares, per period, as a decimal (per period)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:perpetuity-due","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Perpetuity due (first payment today)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>PV</mtext><mtext>due</mtext></msub><mo>=</mo><mi>C</mi><mo>+</mo><mfrac><mi>C</mi><mi>r</mi></mfrac><mo>=</mo><mfrac><mrow><mi>C</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_{\\text{due}} = C + \\frac{C}{r} = \\frac{C(1 + r)}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PV</mtext><mtext>due</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_{\\text{due}}</annotation></semantics></math></span>","Value today, including today’s payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:deferred-perpetuity","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Deferred perpetuity (first payment at the end of period k + 1)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>PV</mtext><mn>0</mn></msub><mo>=</mo><mfrac><mi>C</mi><mi>r</mi></mfrac><mo>×</mo><mfrac><mn>1</mn><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>k</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_0 = \\frac{C}{r} \\times \\frac{1}{(1 + r)^{k}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>PV</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{PV}_0</annotation></semantics></math></span>","Value today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","One less than the period of the first payment (periods)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:terminal-value","kind":"formula","course":"f04","lesson":"perpetuities-and-growth","front":"Terminal value with constant growth","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>TV</mtext><mi>N</mi></msub><mo>=</mo><mfrac><msub><mtext>CF</mtext><mrow><mi>N</mi><mo>+</mo><mn>1</mn></mrow></msub><mrow><mi>r</mi><mo>−</mo><mi>g</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{TV}_N = \\frac{\\text{CF}_{N+1}}{r - g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>TV</mtext><mi>N</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{TV}_N</annotation></semantics></math></span>","Value at the end of year N of all cash flows after year N ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CF</mtext><mrow><mi>N</mi><mo>+</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CF}_{N+1}</annotation></semantics></math></span>","Cash flow in the first year after the forecast, = CF_N × (1 + g) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Last year of the explicit forecast (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Long-run growth rate of the cash flows, below r (per year)"]],"href":"learn/finance/f04/perpetuities-and-growth/"},{"id":"f:f04:loan-payment","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"Payment on an amortising loan","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>C</mi><mo>=</mo><mfrac><mrow><mtext>PV</mtext><mo>×</mo><mi>r</mi></mrow><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">C = \\frac{\\text{PV} \\times r}{1 - (1 + r)^{-n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Level payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount borrowed ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (the nominal annual rate ÷ 12 for monthly payments) (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:amortisation-step","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"One row of an amortisation schedule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>I</mi><mi>k</mi></msub><mo>=</mo><mi>r</mi><mo>×</mo><msub><mi>B</mi><mrow><mi>k</mi><mo>−</mo><mn>1</mn></mrow></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>P</mi><mi>k</mi></msub><mo>=</mo><mi>C</mi><mo>−</mo><msub><mi>I</mi><mi>k</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>B</mi><mi>k</mi></msub><mo>=</mo><msub><mi>B</mi><mrow><mi>k</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>−</mo><msub><mi>P</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">I_k = r \\times B_{k-1}, \\qquad P_k = C - I_k, \\qquad B_k = B_{k-1} - P_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">I_k</annotation></semantics></math></span>","Interest in payment k ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">P_k</annotation></semantics></math></span>","Principal repaid by payment k ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_k</annotation></semantics></math></span>","Balance after payment k (B₀ is the amount borrowed) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:balance-prospective","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"Balance outstanding: prospective method","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msup></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">B_k = C \\times \\frac{1 - (1 + r)^{-(n-k)}}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_k</annotation></semantics></math></span>","Balance after k payments ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Total number of payments (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of payments already made (periods)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:balance-retrospective","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"Balance outstanding: retrospective method","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub><mo>=</mo><mtext>PV</mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>k</mi></msup><mo>−</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>k</mi></msup><mo>−</mo><mn>1</mn></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">B_k = \\text{PV}(1 + r)^{k} - C \\times \\frac{(1 + r)^{k} - 1}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_k</annotation></semantics></math></span>","Balance after k payments ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount borrowed ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per period, as a decimal (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of payments already made (periods)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:interest-paid","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"Total interest, and interest paid between two dates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Total interest</mtext><mo>=</mo><mi>n</mi><mi>C</mi><mo>−</mo><mtext>PV</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Interest in payments </mtext><mi>j</mi><mtext> to </mtext><mi>k</mi><mo>=</mo><mo stretchy=\"false\">(</mo><mi>k</mi><mo>−</mo><mi>j</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext> </mtext><mi>C</mi><mo>−</mo><mo stretchy=\"false\">(</mo><msub><mi>B</mi><mrow><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>−</mo><msub><mi>B</mi><mi>k</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Total interest} = nC - \\text{PV}, \\qquad \\text{Interest in payments } j \\text{ to } k = (k - j + 1)\\,C - (B_{j-1} - B_k)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount borrowed ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j</mi><mo separator=\"true\">,</mo><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">j, k</annotation></semantics></math></span>","First and last payment of the stretch (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mrow><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo separator=\"true\">,</mo><msub><mi>B</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_{j-1}, B_k</annotation></semantics></math></span>","Balance before payment j and after payment k ($)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:apr-with-fee","kind":"formula","course":"f04","lesson":"loan-amortisation","front":"APR of a loan with an up-front fee","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>−</mo><mi>F</mi><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow><mi>r</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>APR</mtext><mo>=</mo><mi>m</mi><mo>×</mo><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">\\text{PV} - F = C \\times \\frac{1 - (1 + r)^{-n}}{r}, \\qquad \\text{APR} = m \\times r</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount of the loan ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">F</annotation></semantics></math></span>","Fees paid up front (deducted from the loan or paid at signing) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Payment per period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of payments (periods)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","The rate per period that solves the equation, found by trial and error or =RATE(n, −C, PV − F) (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Payment periods per year"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Annual percentage rate including the fee (per year)"]],"href":"learn/finance/f04/loan-amortisation/"},{"id":"f:f04:inflation-multi","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Cumulative and average annual inflation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>I</mi><mi>n</mi></msub><mo>=</mo><mfrac><msub><mtext>CPI</mtext><mi>n</mi></msub><msub><mtext>CPI</mtext><mn>0</mn></msub></mfrac><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>i</mi><mtext>avg</mtext></msub><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mfrac><msub><mtext>CPI</mtext><mi>n</mi></msub><msub><mtext>CPI</mtext><mn>0</mn></msub></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">I_n = \\frac{\\text{CPI}_n}{\\text{CPI}_0} - 1, \\qquad i_{\\text{avg}} = \\left(\\frac{\\text{CPI}_n}{\\text{CPI}_0}\\right)^{1/n} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I</mi><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">I_n</annotation></semantics></math></span>","Cumulative inflation over the whole interval, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>i</mi><mtext>avg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">i_{\\text{avg}}</annotation></semantics></math></span>","Average annual inflation rate: the constant yearly rate giving the same cumulative inflation (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_0</annotation></semantics></math></span>","Price index at the start (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_n</annotation></semantics></math></span>","Price index at the end (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years in the interval (years)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:restate-dollars","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Restating an amount in base-period dollars","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Real amount</mtext><mo>=</mo><msub><mtext>Nominal amount</mtext><mi>t</mi></msub><mo>×</mo><mfrac><msub><mtext>CPI</mtext><mtext>base</mtext></msub><msub><mtext>CPI</mtext><mi>t</mi></msub></mfrac><mo>=</mo><mfrac><msub><mtext>Nominal amount</mtext><mi>t</mi></msub><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Real amount} = \\text{Nominal amount}_t \\times \\frac{\\text{CPI}_{\\text{base}}}{\\text{CPI}_t} = \\frac{\\text{Nominal amount}_t}{(1 + i)^{t}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Nominal amount</mtext><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Nominal amount}_t</annotation></semantics></math></span>","An amount paid or received at date t, in that date’s dollars ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_t</annotation></semantics></math></span>","Price index at date t (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mtext>base</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_{\\text{base}}</annotation></semantics></math></span>","Price index at the base date (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Constant annual inflation rate (the second form only, for forecasts) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Years from the base date to the payment (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Real amount</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Real amount}</annotation></semantics></math></span>","What the amount buys at base-date prices ($ of the base date)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:fisher","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Fisher relation (exact)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>nom</mtext></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>real</mtext></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><mo stretchy=\"false\">)</mo><mspace width=\"1em\"/><mo>⟺</mo><mspace width=\"1em\"/><msub><mi>r</mi><mtext>real</mtext></msub><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><mrow><mn>1</mn><mo>+</mo><mi>i</mi></mrow></mfrac><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">1 + r_{\\text{nom}} = (1 + r_{\\text{real}})(1 + i) \\quad\\Longleftrightarrow\\quad r_{\\text{real}} = \\frac{1 + r_{\\text{nom}}}{1 + i} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{nom}}</annotation></semantics></math></span>","Nominal rate: growth in dollars, as an effective rate for the period (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}}</annotation></semantics></math></span>","Real rate: growth in purchasing power over the same period (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation over the same period (per period)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:real-nominal-flows","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Real and nominal cash flows","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msubsup><mi>C</mi><mi>t</mi><mtext>nom</mtext></msubsup><mo>=</mo><msubsup><mi>C</mi><mi>t</mi><mtext>real</mtext></msubsup><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow><annotation encoding=\"application/x-tex\">C^{\\text{nom}}_t = C^{\\text{real}}_t\\,(1 + i)^t</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>C</mi><mi>t</mi><mtext>nom</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">C^{\\text{nom}}_t</annotation></semantics></math></span>","Cash flow in year t, in the dollars of year t ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>C</mi><mi>t</mi><mtext>real</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">C^{\\text{real}}_t</annotation></semantics></math></span>","The same cash flow in today’s dollars ($ of today)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Expected annual inflation (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Years from today (years)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:consistent-pv","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Consistent discounting","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mfrac><msubsup><mi>C</mi><mi>t</mi><mtext>nom</mtext></msubsup><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>nom</mtext></msub><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mfrac><msubsup><mi>C</mi><mi>t</mi><mtext>real</mtext></msubsup><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>real</mtext></msub><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{PV} = \\sum_{t=1}^{n} \\frac{C^{\\text{nom}}_t}{(1 + r_{\\text{nom}})^t} = \\sum_{t=1}^{n} \\frac{C^{\\text{real}}_t}{(1 + r_{\\text{real}})^t}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Present value today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>C</mi><mi>t</mi><mtext>nom</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">C^{\\text{nom}}_t</annotation></semantics></math></span>","Nominal cash flow at the end of year t ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>C</mi><mi>t</mi><mtext>real</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">C^{\\text{real}}_t</annotation></semantics></math></span>","Real cash flow at the end of year t, in today’s dollars ($ of today)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{nom}}</annotation></semantics></math></span>","Nominal discount rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}}</annotation></semantics></math></span>","Real discount rate, linked to the nominal rate by the Fisher relation (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Year of each cash flow (years)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:real-growth","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"Real growth of a salary or price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>g</mi><mtext>real</mtext></msub><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>g</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>i</mi></mrow></mfrac><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">g_{\\text{real}} = \\frac{1 + g}{1 + i} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g</mi><mtext>real</mtext></msub></mrow><annotation encoding=\"application/x-tex\">g_{\\text{real}}</annotation></semantics></math></span>","Growth in purchasing power per year (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Nominal growth rate per year (for example a pay rise) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation per year (per year)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:tips-payment","kind":"formula","course":"f04","lesson":"inflation-and-real-returns","front":"TIPS principal and interest (simplified)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>Adjusted principal</mtext><mi>t</mi></msub><mo>=</mo><mtext>Principal</mtext><mo>×</mo><mfrac><msub><mtext>CPI</mtext><mi>t</mi></msub><msub><mtext>CPI</mtext><mn>0</mn></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>Interest</mtext><mi>t</mi></msub><mo>=</mo><msub><mtext>Adjusted principal</mtext><mi>t</mi></msub><mo>×</mo><mfrac><msub><mi>r</mi><mtext>fixed</mtext></msub><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Adjusted principal}_t = \\text{Principal} \\times \\frac{\\text{CPI}_t}{\\text{CPI}_0}, \\qquad \\text{Interest}_t = \\text{Adjusted principal}_t \\times \\frac{r_{\\text{fixed}}}{2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Principal</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Principal}</annotation></semantics></math></span>","Original principal (par value) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Adjusted principal</mtext><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Adjusted principal}_t</annotation></semantics></math></span>","Principal after the inflation adjustment at date t ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_0</annotation></semantics></math></span>","Reference price index when the security was issued (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>CPI</mtext><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{CPI}_t</annotation></semantics></math></span>","Reference price index at payment date t (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>fixed</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{fixed}}</annotation></semantics></math></span>","Fixed annual interest rate set at auction (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Interest</mtext><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Interest}_t</annotation></semantics></math></span>","Interest paid at the six-monthly payment date t ($)"]],"href":"learn/finance/f04/inflation-and-real-returns/"},{"id":"f:f04:mortgage-payment","kind":"formula","course":"f04","lesson":"mortgages","front":"Fixed-rate mortgage payment (principal and interest)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>C</mi><mo>=</mo><mtext>PV</mtext><mo>×</mo><mfrac><mi>r</mi><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>r</mi><mo>=</mo><mfrac><mtext>annual rate</mtext><mn>12</mn></mfrac><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mi>n</mi><mo>=</mo><mn>12</mn><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">C = \\text{PV} \\times \\frac{r}{1 - (1 + r)^{-n}}, \\qquad r = \\frac{\\text{annual rate}}{12}, \\quad n = 12t</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Monthly payment of principal and interest ($ per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Amount borrowed: the price less the down payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Monthly interest rate: the annual interest rate in the loan contract ÷ 12, as a decimal (not the disclosed APR, which also includes points and fees) (per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of monthly payments (months)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Term of the loan (years)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:mortgage-balance","kind":"formula","course":"f04","lesson":"mortgages","front":"Mortgage balance after k monthly payments","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msup></mrow><mi>r</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">B_k = C \\times \\frac{1 - (1 + r)^{-(n - k)}}{r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_k</annotation></semantics></math></span>","Balance still owed immediately after payment k ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Monthly payment ($ per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Monthly interest rate (per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Total number of payments in the term (months)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of payments already made (months)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:points-breakeven","kind":"formula","course":"f04","lesson":"mortgages","front":"Discount points: cost and simple break-even","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cost of points</mtext><mo>=</mo><mi>p</mi><mo>×</mo><mn>1</mn><mi mathvariant=\"normal\">%</mi><mo>×</mo><mtext>PV</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Break-even</mtext><mo>≈</mo><mfrac><mtext>Cost of points</mtext><mrow><msub><mi>C</mi><mn>0</mn></msub><mo>−</mo><msub><mi>C</mi><mn>1</mn></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Cost of points} = p \\times 1\\% \\times \\text{PV}, \\qquad \\text{Break-even} \\approx \\frac{\\text{Cost of points}}{C_0 - C_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Number of points bought (may be fractional) (points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Loan amount ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">C_0</annotation></semantics></math></span>","Monthly payment without points ($ per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">C_1</annotation></semantics></math></span>","Monthly payment at the lower rate ($ per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Break-even</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Break-even}</annotation></semantics></math></span>","Months of saving needed to recover the cost, ignoring time value (months)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:apr-points","kind":"formula","course":"f04","lesson":"mortgages","front":"APR with points (points as the only finance charge)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>PV</mtext><mo>−</mo><mi>F</mi><mo>=</mo><mi>C</mi><mo>×</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>q</mi><msup><mo stretchy=\"false\">)</mo><mrow><mo>−</mo><mi>n</mi></mrow></msup></mrow><mi>q</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>APR</mtext><mo>=</mo><mn>12</mn><mo>×</mo><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">\\text{PV} - F = C \\times \\frac{1 - (1 + q)^{-n}}{q}, \\qquad \\text{APR} = 12 \\times q</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Loan amount ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">F</annotation></semantics></math></span>","Fees paid up front: here the cost of the points, paid at closing ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Monthly payment at the contract rate ($ per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Monthly rate that solves the equation, found by trial or a spreadsheet RATE function (per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of monthly payments (months)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>APR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{APR}</annotation></semantics></math></span>","Annual percentage rate including the points (per year)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:payoff-time","kind":"formula","course":"f04","lesson":"mortgages","front":"Months to repay with a larger payment","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>n</mi><mo>=</mo><mo>−</mo><mfrac><mrow><mi>ln</mi><mo>⁡</mo><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>−</mo><mfrac><mrow><mi>r</mi><mo>×</mo><mtext>PV</mtext></mrow><mi>C</mi></mfrac><mo fence=\"true\">)</mo></mrow></mrow><mrow><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">n = -\\frac{\\ln\\left(1 - \\dfrac{r \\times \\text{PV}}{C}\\right)}{\\ln(1 + r)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Months needed to repay the balance (round up: the last payment is smaller) (months)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Monthly interest rate (per month)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>PV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{PV}</annotation></semantics></math></span>","Balance to be repaid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Monthly payment, including the extra amount ($ per month)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:real-payment","kind":"formula","course":"f04","lesson":"mortgages","front":"Real value of a fixed payment","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Real value in year </mtext><mi>t</mi><mo>=</mo><mfrac><mi>C</mi><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Real value in year } t = \\frac{C}{(1 + i)^{t}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Fixed nominal payment ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Annual inflation rate (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Years from today (years)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:f04:arm-rate","kind":"formula","course":"f04","lesson":"mortgages","front":"Adjustable-rate mortgage: the new rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Fully indexed rate</mtext><mo>=</mo><mtext>Index</mtext><mo>+</mo><mtext>Margin</mtext><mo separator=\"true\">;</mo><mspace width=\"1em\"/><mtext>new rate within current rate</mtext><mo>±</mo><mtext>adjustment cap and initial rate</mtext><mo>±</mo><mtext>lifetime cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Fully indexed rate} = \\text{Index} + \\text{Margin}; \\quad \\text{new rate within } \\text{current rate} \\pm \\text{adjustment cap} \\text{ and } \\text{initial rate} \\pm \\text{lifetime cap}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Fully indexed rate</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Fully indexed rate}</annotation></semantics></math></span>","Index plus margin: the rate before any caps apply (% per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Index</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Index}</annotation></semantics></math></span>","A market interest rate named in the loan, which changes over time (% per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Margin</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Margin}</annotation></semantics></math></span>","Percentage points added to the index, fixed in the loan agreement (percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>adjustment cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{adjustment cap}</annotation></semantics></math></span>","Most the rate can move at one reset (the initial cap at the first reset, the subsequent cap after) (percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>lifetime cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{lifetime cap}</annotation></semantics></math></span>","Most the rate can move over the life of the loan (percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>current rate</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{current rate}</annotation></semantics></math></span>","The rate charged before this reset (% per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>initial rate</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{initial rate}</annotation></semantics></math></span>","The loan’s starting rate (% per year)"]],"href":"learn/finance/f04/mortgages/"},{"id":"f:b01:fka-expected-value","kind":"formula","course":"b01","lesson":"four-kinds-of-analytics","front":"Expected value of a decision option","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV</mtext><mo>=</mo><munder><mo>∑</mo><mi>s</mi></munder><msub><mi>p</mi><mi>s</mi></msub><mtext> </mtext><msub><mi>V</mi><mi>s</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{EV} = \\sum_{s} p_s \\, V_s</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV}</annotation></semantics></math></span>","Expected value of the option: its probability-weighted average outcome ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>s</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_s</annotation></semantics></math></span>","Probability of scenario s; the probabilities of all the scenarios add up to 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V</mi><mi>s</mi></msub></mrow><annotation encoding=\"application/x-tex\">V_s</annotation></semantics></math></span>","Outcome of the option, such as profit, if scenario s happens ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","A scenario: one possible future, such as low, medium or high demand"]],"href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"f:b01:fka-forecast-error","kind":"formula","course":"b01","lesson":"four-kinds-of-analytics","front":"Forecast error and percentage error","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>e</mi><mo>=</mo><mi>A</mi><mo>−</mo><mi>F</mi><mspace width=\"2em\"/><mtext>Percentage error</mtext><mo>=</mo><mfrac><mrow><mi>A</mi><mo>−</mo><mi>F</mi></mrow><mi>A</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">e = A - F \\qquad \\text{Percentage error} = \\dfrac{A - F}{A} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e</mi></mrow><annotation encoding=\"application/x-tex\">e</annotation></semantics></math></span>","Forecast error (units of the forecast)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span>","Actual value, once it is known (units of the forecast)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">F</annotation></semantics></math></span>","Forecast made in advance (units of the forecast)"]],"href":"learn/analytics/b01/four-kinds-of-analytics/"},{"id":"f:b01:bq-share-by-unit","kind":"formula","course":"b01","lesson":"business-questions","front":"Share of a group, for a chosen unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Share of group </mtext><mi>g</mi><mo>=</mo><mfrac><msub><mi>n</mi><mi>g</mi></msub><mrow><munder><mo>∑</mo><mi>h</mi></munder><msub><mi>n</mi><mi>h</mi></msub></mrow></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Share of group } g = \\dfrac{n_g}{\\sum_h n_h} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","The group whose share you want, such as the app"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_g</annotation></semantics></math></span>","Number of units (customers, orders, visits) in group g (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑</mo><mi>h</mi></msub><msub><mi>n</mi><mi>h</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\sum_h n_h</annotation></semantics></math></span>","Total number of the same units across all the groups h (units)"]],"href":"learn/analytics/b01/business-questions/"},{"id":"f:b01:bq-rate-per-day","kind":"formula","course":"b01","lesson":"business-questions","front":"Rate per day, for periods of different length","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Daily rate</mtext><mo>=</mo><mfrac><mtext>Count in the period</mtext><mtext>Days in the period</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Daily rate} = \\dfrac{\\text{Count in the period}}{\\text{Days in the period}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Count in the period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Count in the period}</annotation></semantics></math></span>","Number of events in the period, such as orders or visits (events)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days in the period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days in the period}</annotation></semantics></math></span>","Length of the period (days)"]],"href":"learn/analytics/b01/business-questions/"},{"id":"f:b01:psf-growth-factors","kind":"formula","course":"b01","lesson":"problem-solving-frameworks","front":"Growth of a product of drivers","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mn>1</mn><mo>+</mo><msub><mi>g</mi><mi>R</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>g</mi><mi>V</mi></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>g</mi><mi>c</mi></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>g</mi><mi>A</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">1 + g_R = (1 + g_V)(1 + g_c)(1 + g_A)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">g_R</annotation></semantics></math></span>","Growth rate of revenue between the two periods, as a decimal (−0.05 for a 5% fall)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g</mi><mi>V</mi></msub></mrow><annotation encoding=\"application/x-tex\">g_V</annotation></semantics></math></span>","Growth rate of visits"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">g_c</annotation></semantics></math></span>","Growth rate of the conversion rate (a relative change, not a change in percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g</mi><mi>A</mi></msub></mrow><annotation encoding=\"application/x-tex\">g_A</annotation></semantics></math></span>","Growth rate of average order value"]],"href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"f:b01:psf-sequential","kind":"formula","course":"b01","lesson":"problem-solving-frameworks","front":"Step-by-step (sequential) contributions to a change in revenue","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi>V</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>V</mi><mn>1</mn></msub><mo>−</mo><msub><mi>V</mi><mn>0</mn></msub><mo stretchy=\"false\">)</mo><mtext> </mtext><msub><mi>c</mi><mn>0</mn></msub><msub><mi>A</mi><mn>0</mn></msub><mspace width=\"2em\"/><msub><mi mathvariant=\"normal\">Δ</mi><mi>c</mi></msub><mo>=</mo><msub><mi>V</mi><mn>1</mn></msub><mo stretchy=\"false\">(</mo><msub><mi>c</mi><mn>1</mn></msub><mo>−</mo><msub><mi>c</mi><mn>0</mn></msub><mo stretchy=\"false\">)</mo><msub><mi>A</mi><mn>0</mn></msub><mspace width=\"2em\"/><msub><mi mathvariant=\"normal\">Δ</mi><mi>A</mi></msub><mo>=</mo><msub><mi>V</mi><mn>1</mn></msub><msub><mi>c</mi><mn>1</mn></msub><mo stretchy=\"false\">(</mo><msub><mi>A</mi><mn>1</mn></msub><mo>−</mo><msub><mi>A</mi><mn>0</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\Delta_V = (V_1 - V_0)\\,c_0 A_0 \\qquad \\Delta_c = V_1 (c_1 - c_0) A_0 \\qquad \\Delta_A = V_1 c_1 (A_1 - A_0)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>V</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">V_0,\\ V_1</annotation></semantics></math></span>","Visits in the earlier and the later period (visits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>c</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">c_0,\\ c_1</annotation></semantics></math></span>","Conversion rate in the earlier and the later period, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>A</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">A_0,\\ A_1</annotation></semantics></math></span>","Average order value in the earlier and the later period ($ per order)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi>V</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi mathvariant=\"normal\">Δ</mi><mi>c</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi mathvariant=\"normal\">Δ</mi><mi>A</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_V,\\ \\Delta_c,\\ \\Delta_A</annotation></semantics></math></span>","Change in revenue attributed to visits, conversion and order value, changed in that order ($)"]],"href":"learn/analytics/b01/problem-solving-frameworks/"},{"id":"f:b01:category-share","kind":"formula","course":"b01","lesson":"data-types","front":"Share of a category","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>Share</mtext><mi>k</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>k</mi></msub><mi>n</mi></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Share}_k = \\dfrac{n_k}{n} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_k</annotation></semantics></math></span>","Observations in category k (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","All observations with a recorded value (count)"]],"href":"learn/analytics/b01/data-types/"},{"id":"f:b01:median-position","kind":"formula","course":"b01","lesson":"data-types","front":"Position of the median","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Position</mtext><mo>=</mo><mfrac><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Position} = \\dfrac{n + 1}{2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of observations, sorted from lowest to highest (count)"]],"href":"learn/analytics/b01/data-types/"},{"id":"f:b01:rating-mean","kind":"formula","course":"b01","lesson":"data-types","front":"Mean of a rating scale from its counts","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>s</mi></munder><mi>s</mi><mo>×</mo><msub><mi>f</mi><mi>s</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>s</mi></munder><msub><mi>f</mi><mi>s</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x} = \\dfrac{\\sum_{s} s \\times f_s}{\\sum_{s} f_s}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean rating (stars)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","A score on the scale, such as 1 to 5 stars (stars)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mi>s</mi></msub></mrow><annotation encoding=\"application/x-tex\">f_s</annotation></semantics></math></span>","Number of responses with score s (responses)"]],"href":"learn/analytics/b01/data-types/"},{"id":"f:b01:response-rate","kind":"formula","course":"b01","lesson":"data-collection","front":"Response rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Response rate</mtext><mo>=</mo><mfrac><mi>r</mi><mi>N</mi></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Response rate} = \\dfrac{r}{N} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Completed responses (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","People invited who could have responded (people)"]],"href":"learn/analytics/b01/data-collection/"},{"id":"f:b01:nonresponse-bounds","kind":"formula","course":"b01","lesson":"data-collection","front":"Range allowed by non-response","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Lowest</mtext><mo>=</mo><mfrac><mi>y</mi><mi>N</mi></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi><mspace width=\"2em\"/><mtext>Highest</mtext><mo>=</mo><mfrac><mrow><mi>y</mi><mo>+</mo><mo stretchy=\"false\">(</mo><mi>N</mi><mo>−</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow><mi>N</mi></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Lowest} = \\dfrac{y}{N} \\times 100\\% \\qquad \\text{Highest} = \\dfrac{y + (N - r)}{N} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">y</annotation></semantics></math></span>","Respondents giving the answer of interest (for example, “satisfied”) (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Respondents (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","People invited (people)"]],"href":"learn/analytics/b01/data-collection/"},{"id":"f:b01:two-group-estimate","kind":"formula","course":"b01","lesson":"data-collection","front":"Combining respondents and a follow-up of non-respondents","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>p</mi><mo>^</mo></mover><mo>=</mo><mfrac><mrow><mi>r</mi><mo>×</mo><msub><mi>p</mi><mi>r</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mi>N</mi><mo>−</mo><mi>r</mi><mo stretchy=\"false\">)</mo><mo>×</mo><msub><mi>p</mi><mi>n</mi></msub></mrow><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\hat{p} = \\dfrac{r \\times p_r + (N - r) \\times p_n}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>p</mi><mo>^</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\hat{p}</annotation></semantics></math></span>","Estimated share of everyone invited giving the answer (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_r</annotation></semantics></math></span>","Share among respondents (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_n</annotation></semantics></math></span>","Share among non-respondents, from a follow-up of a random sample of them (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Respondents (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","People invited (people)"]],"href":"learn/analytics/b01/data-collection/"},{"id":"f:b01:dq-completeness","kind":"formula","course":"b01","lesson":"data-quality","front":"Completeness of a required field","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Completeness</mtext><mo>=</mo><mfrac><mtext>Values present</mtext><mtext>Values required</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Completeness} = \\dfrac{\\text{Values present}}{\\text{Values required}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values present</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values present}</annotation></semantics></math></span>","Non-blank values on the rows that require one (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values required</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values required}</annotation></semantics></math></span>","Rows on which a value is required (count)"]],"href":"learn/analytics/b01/data-quality/"},{"id":"f:b01:dq-duplicate-inflation","kind":"formula","course":"b01","lesson":"data-quality","front":"Overstatement caused by duplicates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Overstatement</mtext><mo>=</mo><mfrac><mrow><mtext>Rows counted</mtext><mo>−</mo><mtext>True records</mtext></mrow><mtext>True records</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Overstatement} = \\dfrac{\\text{Rows counted} - \\text{True records}}{\\text{True records}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows counted</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows counted}</annotation></semantics></math></span>","Rows in the file, duplicates included (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>True records</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{True records}</annotation></semantics></math></span>","Distinct real-world things (orders, bookings) the rows describe (count)"]],"href":"learn/analytics/b01/data-quality/"},{"id":"f:b01:dq-mean-shift","kind":"formula","course":"b01","lesson":"data-quality","front":"Effect of one wrong value on a mean","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Shift in the mean</mtext><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mtext>wrong</mtext></msub><mo>−</mo><msub><mi>x</mi><mtext>right</mtext></msub></mrow><mi>n</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Shift in the mean} = \\dfrac{x_{\\text{wrong}} - x_{\\text{right}}}{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>wrong</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{wrong}}</annotation></semantics></math></span>","The value recorded (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>right</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{right}}</annotation></semantics></math></span>","The value that should have been recorded (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values in the mean (count)"]],"href":"learn/analytics/b01/data-quality/"},{"id":"f:b01:kpi-conversion","kind":"formula","course":"b01","lesson":"kpis","front":"Conversion rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CR</mtext><mo>=</mo><mfrac><mi>O</mi><mi>V</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{CR} = \\dfrac{O}{V} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CR}</annotation></semantics></math></span>","Conversion rate: orders per 100 visits (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O</mi></mrow><annotation encoding=\"application/x-tex\">O</annotation></semantics></math></span>","Orders placed in the period, as the KPI dictionary defines an order (orders)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Visits (sessions) in the same period and channel (visits)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:kpi-aov","kind":"formula","course":"b01","lesson":"kpis","front":"Average order value","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>AOV</mtext><mo>=</mo><mfrac><mi>R</mi><mi>O</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{AOV} = \\dfrac{R}{O}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>AOV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{AOV}</annotation></semantics></math></span>","Average order value ($ per order)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Revenue from the orders in the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O</mi></mrow><annotation encoding=\"application/x-tex\">O</annotation></semantics></math></span>","Orders in the period (orders)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:kpi-revenue","kind":"formula","course":"b01","lesson":"kpis","front":"Revenue from its drivers","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>O</mi><mo>×</mo><mtext>AOV</mtext><mo>=</mo><mi>V</mi><mo>×</mo><mfrac><mtext>CR</mtext><mn>100</mn></mfrac><mo>×</mo><mtext>AOV</mtext></mrow><annotation encoding=\"application/x-tex\">R = O \\times \\text{AOV} = V \\times \\dfrac{\\text{CR}}{100} \\times \\text{AOV}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Revenue ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O</mi></mrow><annotation encoding=\"application/x-tex\">O</annotation></semantics></math></span>","Orders (orders)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Visits (visits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CR}</annotation></semantics></math></span>","Conversion rate (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>AOV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{AOV}</annotation></semantics></math></span>","Average order value ($ per order)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:kpi-returning","kind":"formula","course":"b01","lesson":"kpis","front":"Returning-customer share of orders","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>RS</mtext><mo>=</mo><mfrac><mrow><mi>O</mi><mo>−</mo><mi>N</mi></mrow><mi>O</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{RS} = \\dfrac{O - N}{O} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>RS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{RS}</annotation></semantics></math></span>","Share of the period’s orders placed by returning customers (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O</mi></mrow><annotation encoding=\"application/x-tex\">O</annotation></semantics></math></span>","Orders in the period (orders)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Orders that were a customer’s first ever order (orders)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:kpi-response","kind":"formula","course":"b01","lesson":"kpis","front":"Rating response rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>RR</mtext><mo>=</mo><mfrac><msub><mi>O</mi><mi>r</mi></msub><mi>O</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{RR} = \\dfrac{O_r}{O} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>RR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{RR}</annotation></semantics></math></span>","Rating response rate (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>O</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">O_r</annotation></semantics></math></span>","Orders placed in the period that were rated (orders)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O</mi></mrow><annotation encoding=\"application/x-tex\">O</annotation></semantics></math></span>","Orders placed in the period (orders)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:kpi-gap","kind":"formula","course":"b01","lesson":"kpis","front":"Gap to target","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gap</mtext><mo>=</mo><mi>A</mi><mo>−</mo><mi>T</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Share of target</mtext><mo>=</mo><mfrac><mi>A</mi><mi>T</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Gap} = A - T, \\qquad \\text{Share of target} = \\dfrac{A}{T} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span>","Actual value of the KPI (units of the KPI)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","Target value (units of the KPI)"]],"href":"learn/analytics/b01/kpis/"},{"id":"f:b01:sum-pct-change","kind":"formula","course":"b01","lesson":"summarising-data","front":"Absolute and percentage change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mo>=</mo><msub><mi>x</mi><mtext>new</mtext></msub><mo>−</mo><msub><mi>x</mi><mtext>old</mtext></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">%</mi><mi mathvariant=\"normal\">Δ</mi><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mtext>new</mtext></msub><mo>−</mo><msub><mi>x</mi><mtext>old</mtext></msub></mrow><msub><mi>x</mi><mtext>old</mtext></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\Delta = x_{\\text{new}} - x_{\\text{old}}, \\qquad \\%\\Delta = \\dfrac{x_{\\text{new}} - x_{\\text{old}}}{x_{\\text{old}}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>old</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{old}}</annotation></semantics></math></span>","The starting value: the base (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>new</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{new}}</annotation></semantics></math></span>","The later value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta</annotation></semantics></math></span>","Absolute change (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mi mathvariant=\"normal\">Δ</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\Delta</annotation></semantics></math></span>","Percentage change (%)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-pp","kind":"formula","course":"b01","lesson":"summarising-data","front":"Change in percentage points","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub><mo>=</mo><msub><mi>p</mi><mtext>new</mtext></msub><mo>−</mo><msub><mi>p</mi><mtext>old</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}} = p_{\\text{new}} - p_{\\text{old}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mtext>old</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>p</mi><mtext>new</mtext></msub></mrow><annotation encoding=\"application/x-tex\">p_{\\text{old}},\\ p_{\\text{new}}</annotation></semantics></math></span>","Two percentages, such as conversion rates in two months (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}}</annotation></semantics></math></span>","Change in percentage points (percentage points)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-cgr","kind":"formula","course":"b01","lesson":"summarising-data","front":"Compound growth rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mfrac><msub><mi>x</mi><mtext>end</mtext></msub><msub><mi>x</mi><mtext>start</mtext></msub></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">g = \\left(\\dfrac{x_{\\text{end}}}{x_{\\text{start}}}\\right)^{1/n} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Constant growth rate per period that links start and end (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>start</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{start}},\\ x_{\\text{end}}</annotation></semantics></math></span>","Values at the start and end (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of periods (steps) between them (periods)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-mean-median","kind":"formula","course":"b01","lesson":"summarising-data","front":"Mean and median","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>x</mi><mi>i</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>median position</mtext><mo>=</mo><mfrac><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x} = \\dfrac{1}{n}\\sum_{i=1}^{n} x_i, \\qquad \\text{median position} = \\dfrac{n + 1}{2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean (units of x)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-iqr","kind":"formula","course":"b01","lesson":"summarising-data","front":"Quartiles and interquartile range","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>position of </mtext><msub><mi>Q</mi><mi>p</mi></msub><mo>=</mo><mn>1</mn><mo>+</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mi>p</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>IQR</mtext><mo>=</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{position of } Q_p = 1 + (n - 1)p, \\qquad \\text{IQR} = Q_3 - Q_1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">Q_p</annotation></semantics></math></span>","Quartile: the value with a share p of the sorted data below it (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","The share below the quartile: 0.25 for Q1, 0.75 for Q3"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IQR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IQR}</annotation></semantics></math></span>","Interquartile range (units of x)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-sd","kind":"formula","course":"b01","lesson":"summarising-data","front":"Sample standard deviation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>s</mi><mo>=</mo><msqrt><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></mfrac></msqrt></mrow><annotation encoding=\"application/x-tex\">s = \\sqrt{\\dfrac{\\sum_{i=1}^{n} (x_i - \\bar{x})^2}{n - 1}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of the values (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:sum-weighted","kind":"formula","course":"b01","lesson":"summarising-data","front":"Weighted average","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>w</mi></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>w</mi><mi>i</mi></msub><msub><mi>x</mi><mi>i</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>w</mi><mi>i</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_w = \\dfrac{\\sum_{i} w_i x_i}{\\sum_{i} w_i}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The values being averaged, such as each channel’s conversion rate (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>w</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">w_i</annotation></semantics></math></span>","Their weights, such as each channel’s visits (units of the weight)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>w</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_w</annotation></semantics></math></span>","Weighted average (units of x)"]],"href":"learn/analytics/b01/summarising-data/"},{"id":"f:b01:int-per-day","kind":"formula","course":"b01","lesson":"interpreting-results","front":"Rate per day","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Per day</mtext><mo>=</mo><mfrac><mi>X</mi><mi>d</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Per day} = \\dfrac{X}{d}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X</annotation></semantics></math></span>","A count for the period, such as orders in a month (units of X)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Days in the period (days)"]],"href":"learn/analytics/b01/interpreting-results/"},{"id":"f:b01:int-mix","kind":"formula","course":"b01","lesson":"interpreting-results","front":"Overall rate as a mix of group rates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>s</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>r</mi><mi>i</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mfrac><msub><mi>V</mi><mi>i</mi></msub><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>V</mi><mi>j</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\sum_{i} s_i\\, r_i, \\qquad s_i = \\dfrac{V_i}{\\sum_j V_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Overall rate, such as overall conversion (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_i</annotation></semantics></math></span>","Rate in group i, such as a channel’s conversion (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_i</annotation></semantics></math></span>","Group i’s share of the denominator; the shares add to 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">V_i</annotation></semantics></math></span>","Group i’s denominator, such as its visits (visits)"]],"href":"learn/analytics/b01/interpreting-results/"},{"id":"f:b01:int-mix-adjusted","kind":"formula","course":"b01","lesson":"interpreting-results","front":"Mix-adjusted rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msubsup><mi>r</mi><mi>B</mi><mrow><mtext> </mtext><mtext>at A’s mix</mtext></mrow></msubsup><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>s</mi><mrow><mi>A</mi><mo separator=\"true\">,</mo><mi>i</mi></mrow></msub><mtext> </mtext><msub><mi>r</mi><mrow><mi>B</mi><mo separator=\"true\">,</mo><mi>i</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">r_B^{\\,\\text{at A’s mix}} = \\sum_i s_{A,i}\\, r_{B,i}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mrow><mi>B</mi><mo separator=\"true\">,</mo><mi>i</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">r_{B,i}</annotation></semantics></math></span>","Rate in group i in period B (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>A</mi><mo separator=\"true\">,</mo><mi>i</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{A,i}</annotation></semantics></math></span>","Group i’s share of the denominator in period A"]],"href":"learn/analytics/b01/interpreting-results/"},{"id":"f:b01:int-did","kind":"formula","course":"b01","lesson":"interpreting-results","front":"Difference in differences","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Effect</mtext><mo>≈</mo><mo stretchy=\"false\">(</mo><msub><mi>T</mi><mtext>after</mtext></msub><mo>−</mo><msub><mi>T</mi><mtext>before</mtext></msub><mo stretchy=\"false\">)</mo><mo>−</mo><mo stretchy=\"false\">(</mo><msub><mi>C</mi><mtext>after</mtext></msub><mo>−</mo><msub><mi>C</mi><mtext>before</mtext></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Effect} \\approx (T_{\\text{after}} - T_{\\text{before}}) - (C_{\\text{after}} - C_{\\text{before}})</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T</mi><mtext>before</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>T</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">T_{\\text{before}},\\ T_{\\text{after}}</annotation></semantics></math></span>","The measure in the group that got the change, before and after it (units of the measure)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mtext>before</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>C</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">C_{\\text{before}},\\ C_{\\text{after}}</annotation></semantics></math></span>","The same measure in a comparison group that did not (units of the measure)"]],"href":"learn/analytics/b01/interpreting-results/"},{"id":"f:b02:mean-per-unit","kind":"formula","course":"b02","lesson":"datasets-and-variables","front":"Average per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>unit</mtext></msub><mo>=</mo><mfrac><mtext>Sum of the values over all rows</mtext><mtext>Number of distinct units</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{unit}} = \\dfrac{\\text{Sum of the values over all rows}}{\\text{Number of distinct units}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>unit</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{unit}}</annotation></semantics></math></span>","The average per unit you are asking about: per order, per customer, per booking (unit of the values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Sum of the values over all rows</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Sum of the values over all rows}</annotation></semantics></math></span>","The column total, for example of line_total (unit of the values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Number of distinct units</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Number of distinct units}</annotation></semantics></math></span>","The number of distinct values of the unit’s identifier, such as distinct order_id (units)"]],"href":"learn/analytics/b02/datasets-and-variables/"},{"id":"f:b02:key-test","kind":"formula","course":"b02","lesson":"datasets-and-variables","front":"Primary key test","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Distinct key values</mtext><mo>=</mo><mi>n</mi><mspace width=\"1em\"/><mtext>and</mtext><mspace width=\"1em\"/><mtext>Rows with a blank key</mtext><mo>=</mo><mn>0</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values} = n \\quad \\text{and} \\quad \\text{Rows with a blank key} = 0</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rows in the table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Distinct key values</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values}</annotation></semantics></math></span>","Distinct values of the candidate key, or distinct combinations for a composite key (rows)"]],"href":"learn/analytics/b02/datasets-and-variables/"},{"id":"f:b02:completeness","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Completeness of a column","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Completeness</mtext><mo>=</mo><mfrac><mtext>Values present</mtext><mtext>Values required</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Completeness} = \\dfrac{\\text{Values present}}{\\text{Values required}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values present</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values present}</annotation></semantics></math></span>","Non-blank values on the rows that require one; placeholder codes known to mean “missing” count as blank (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values required</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values required}</annotation></semantics></math></span>","Rows on which the data dictionary requires a value (count)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:rule-failure-rate","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Failure rate of a validation rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Failure rate</mtext><mo>=</mo><mfrac><mtext>Rows that fail the rule</mtext><mtext>Rows the rule checks</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Failure rate} = \\dfrac{\\text{Rows that fail the rule}}{\\text{Rows the rule checks}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows the rule checks</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows the rule checks}</annotation></semantics></math></span>","Rows the rule applies to; blanks in an optional column are left out (rows)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:share-failing","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Share of rows failing at least one rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Share failing</mtext><mo>=</mo><mfrac><mtext>Rows failing at least one rule</mtext><mtext>Rows checked</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Share failing} = \\dfrac{\\text{Rows failing at least one rule}}{\\text{Rows checked}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows failing at least one rule</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows failing at least one rule}</annotation></semantics></math></span>","Each row counted once, however many rules it fails (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows checked</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows checked}</annotation></semantics></math></span>","All rows in the table (rows)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:uniqueness","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Uniqueness of a key","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Uniqueness</mtext><mo>=</mo><mfrac><mtext>Distinct key values</mtext><mtext>Rows</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Uniqueness} = \\dfrac{\\text{Distinct key values}}{\\text{Rows}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Distinct key values</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values}</annotation></semantics></math></span>","Distinct values of the primary key (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows}</annotation></semantics></math></span>","Rows in the table (count)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:surplus-rows","kind":"formula","course":"b02","lesson":"duplicates","front":"Surplus (duplicate) rows","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Surplus rows</mtext><mo>=</mo><mi>n</mi><mo>−</mo><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Surplus rows} = n - n_{\\text{distinct}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rows in the table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{distinct}}</annotation></semantics></math></span>","Number of distinct values of the business key (or of whole rows, when counting exact copies) (rows)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:duplicate-rate","kind":"formula","course":"b02","lesson":"duplicates","front":"Duplicate rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Duplicate rate</mtext><mo>=</mo><mfrac><mrow><mi>n</mi><mo>−</mo><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><mi>n</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Duplicate rate} = \\dfrac{n - n_{\\text{distinct}}}{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n,\\ n_{\\text{distinct}}</annotation></semantics></math></span>","As above (rows)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:mean-with-duplicates","kind":"formula","course":"b02","lesson":"duplicates","front":"Mean reported when duplicates are left in","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>reported</mtext></msub><mo>=</mo><mfrac><mrow><mi>n</mi><mtext> </mtext><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>+</mo><mi>k</mi><mtext> </mtext><mover accent=\"true\"><mi>d</mi><mo>ˉ</mo></mover></mrow><mrow><mi>n</mi><mo>+</mo><mi>k</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{reported}} = \\dfrac{n\\,\\bar{x} + k\\,\\bar{d}}{n + k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of genuine records (records)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","True mean of the genuine records (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of surplus duplicate rows (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>d</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{d}</annotation></semantics></math></span>","Mean of the variable in the surplus rows (units of the variable)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:levenshtein","kind":"formula","course":"b02","lesson":"duplicates","front":"Edit (Levenshtein) distance, filled in as a table","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>=</mo><mi>min</mi><mo>⁡</mo><mrow><mo fence=\"true\">{</mo><mtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>+</mo><mn>1</mn></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mn>1</mn></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><msub><mi>c</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow></mstyle></mtd></mtr></mtable></mrow><mspace width=\"2em\"/><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mn>0</mn></mrow></msub><mo>=</mo><mi>i</mi><mo separator=\"true\">,</mo><mspace width=\"1em\"/><msub><mi>d</mi><mrow><mn>0</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>=</mo><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">d_{i,j} = \\min\\begin{cases} d_{i-1,j} + 1 \\\\ d_{i,j-1} + 1 \\\\ d_{i-1,j-1} + c_{ij} \\end{cases} \\qquad d_{i,0} = i,\\quad d_{0,j} = j</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">d_{i,j}</annotation></semantics></math></span>","Distance between the first i characters of string a and the first j characters of string b (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">c_{ij}</annotation></semantics></math></span>","Substitution cost: 0 if the i-th character of a equals the j-th character of b, otherwise 1 (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mn>0</mn></mrow></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>d</mi><mrow><mn>0</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">d_{i,0},\\ d_{0,j}</annotation></semantics></math></span>","Turning i (or j) characters into an empty string takes one edit per character (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">i,\\ j</annotation></semantics></math></span>","Number of characters taken from the start of a and of b (characters)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:edit-similarity","kind":"formula","course":"b02","lesson":"duplicates","front":"Normalised edit similarity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Similarity</mtext><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi>a</mi><mo separator=\"true\">,</mo><mi>b</mi><mo stretchy=\"false\">)</mo></mrow><mrow><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mi mathvariant=\"normal\">∣</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>b</mi><mi mathvariant=\"normal\">∣</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Similarity} = 1 - \\dfrac{d(a,b)}{\\max(|a|,\\,|b|)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi>a</mi><mo separator=\"true\">,</mo><mi>b</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">d(a,b)</annotation></semantics></math></span>","Edit distance between strings a and b (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mi mathvariant=\"normal\">∣</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>b</mi><mi mathvariant=\"normal\">∣</mi></mrow><annotation encoding=\"application/x-tex\">|a|,\\ |b|</annotation></semantics></math></span>","Lengths of the two strings (characters)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:serial-1900","kind":"formula","course":"b02","lesson":"types-and-formats","front":"Spreadsheet serial number (1900 date system)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub><mo>=</mo><mtext>date</mtext><mo>−</mo><mtext>30 December 1899</mtext></mrow><annotation encoding=\"application/x-tex\">S_{1900} = \\text{date} - \\text{30 December 1899}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub></mrow><annotation encoding=\"application/x-tex\">S_{1900}</annotation></semantics></math></span>","The serial number Excel’s 1900 date system stores for the date (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{date}</annotation></semantics></math></span>","The calendar date, on or after 1 March 1900 (date)"]],"href":"learn/analytics/b02/types-and-formats/"},{"id":"f:b02:serial-1904","kind":"formula","course":"b02","lesson":"types-and-formats","front":"Converting between the 1904 and 1900 date systems","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub><mo>=</mo><msub><mi>S</mi><mn>1904</mn></msub><mo>+</mo><mn>1,462</mn></mrow><annotation encoding=\"application/x-tex\">S_{1900} = S_{1904} + 1{,}462</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mn>1904</mn></msub></mrow><annotation encoding=\"application/x-tex\">S_{1904}</annotation></semantics></math></span>","Serial number in the 1904 date system, which counts 1 January 1904 as day 0 (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1,462</mn></mrow><annotation encoding=\"application/x-tex\">1{,}462</annotation></semantics></math></span>","Days between the two starting points: four years and one leap day (days)"]],"href":"learn/analytics/b02/types-and-formats/"},{"id":"f:b02:combined-mean","kind":"formula","course":"b02","lesson":"text-and-categories","front":"Mean of a consolidated category","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>category</mtext></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>v</mi></munder><msub><mi>n</mi><mi>v</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>v</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>v</mi></munder><msub><mi>n</mi><mi>v</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{category}} = \\dfrac{\\sum_{v} n_v\\, \\bar{x}_v}{\\sum_{v} n_v}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","Each variant that maps to the category (for example “North”, “north”, “N.”)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>v</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_v</annotation></semantics></math></span>","Number of rows with variant v (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>v</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_v</annotation></semantics></math></span>","Mean of the variable among rows with variant v (units of the variable)"]],"href":"learn/analytics/b02/text-and-categories/"},{"id":"f:b02:vocabulary-coverage","kind":"formula","course":"b02","lesson":"text-and-categories","front":"Vocabulary coverage","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Coverage</mtext><mo>=</mo><mfrac><mtext>rows whose cleaned value is in the controlled vocabulary</mtext><mtext>all rows</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Coverage} = \\dfrac{\\text{rows whose cleaned value is in the controlled vocabulary}}{\\text{all rows}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Coverage</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Coverage}</annotation></semantics></math></span>","Share of rows the cleaning rules have placed in an allowed category (proportion (0–1))"]],"href":"learn/analytics/b02/text-and-categories/"},{"id":"f:b02:sd-after-mean-imputation","kind":"formula","course":"b02","lesson":"missing-values","front":"Standard deviation after mean imputation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mtext>after</mtext></msub><mo>=</mo><mi>s</mi><msqrt><mfrac><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><mrow><mi>n</mi><mo>+</mo><mi>m</mi><mo>−</mo><mn>1</mn></mrow></mfrac></msqrt></mrow><annotation encoding=\"application/x-tex\">s_{\\text{after}} = s\\sqrt{\\dfrac{n - 1}{n + m - 1}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation of the observed values (dividing by n − 1) (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of observed values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Number of missing values filled with the observed mean"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:group-weighted-mean","kind":"formula","course":"b02","lesson":"missing-values","front":"Group-weighted mean (group-wise imputation)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>μ</mi><mo>^</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>N</mi><mi>g</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>N</mi><mi>g</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\hat{\\mu} = \\dfrac{\\sum_g N_g\\,\\bar{y}_g}{\\sum_g N_g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">N_g</annotation></semantics></math></span>","Number of rows in group g, including those with a missing value (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_g</annotation></semantics></math></span>","Mean of the observed values in group g (units of the variable)"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:rubins-rules","kind":"formula","course":"b02","lesson":"missing-values","front":"Pooling multiple imputations (Rubin’s rules)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>Q</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>m</mi></mfrac><munderover><mo>∑</mo><mrow><mi>j</mi><mo>=</mo><mn>1</mn></mrow><mi>m</mi></munderover><msub><mi>Q</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>T</mi><mo>=</mo><mover accent=\"true\"><mi>U</mi><mo>ˉ</mo></mover><mo>+</mo><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mn>1</mn><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">\\bar{Q} = \\dfrac{1}{m}\\sum_{j=1}^{m} Q_j, \\qquad T = \\bar{U} + \\left(1 + \\dfrac{1}{m}\\right)B</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">Q_j</annotation></semantics></math></span>","The estimate (for example a mean or a coefficient) from completed dataset j (units of the estimate)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Number of completed datasets"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>U</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{U}</annotation></semantics></math></span>","Average of the squared standard errors across the m analyses (within-imputation variance) (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Sample variance of the m estimates (between-imputation variance) (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","Total variance of the pooled estimate; its square root is the standard error (squared units)"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:quantile-position","kind":"formula","course":"b02","lesson":"outliers","front":"Quantile by linear interpolation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>position</mtext><mo>=</mo><mn>1</mn><mo>+</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mi>p</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>Q</mi><mi>p</mi></msub><mo>=</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub><mo>+</mo><mi>f</mi><mtext> </mtext><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></msub><mo>−</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{position} = 1 + (n - 1)p, \\qquad Q_p = x_{(k)} + f\\,\\bigl(x_{(k+1)} - x_{(k)}\\bigr)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","The proportion wanted: 0.25 for Q1, 0.5 for the median, 0.75 for Q3"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub></mrow><annotation encoding=\"application/x-tex\">x_{(k)}</annotation></semantics></math></span>","The k-th smallest value, where k is the whole-number part of the position (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">f</annotation></semantics></math></span>","The fractional part of the position"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">Q_p</annotation></semantics></math></span>","The p-th quantile of the sorted values (units of the variable)"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:tukey-fences","kind":"formula","course":"b02","lesson":"outliers","front":"Interquartile range and Tukey fences","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>IQR</mtext><mo>=</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>Q</mi><mn>1</mn></msub><mo>−</mo><mn>1.5</mn><mtext> </mtext><mtext>IQR</mtext><mo separator=\"true\">,</mo><mspace width=\"1em\"/><msub><mi>Q</mi><mn>3</mn></msub><mo>+</mo><mn>1.5</mn><mtext> </mtext><mtext>IQR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IQR} = Q_3 - Q_1, \\qquad Q_1 - 1.5\\,\\text{IQR}, \\quad Q_3 + 1.5\\,\\text{IQR}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_3</annotation></semantics></math></span>","First and third quartiles (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IQR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IQR}</annotation></semantics></math></span>","Interquartile range: the width of the middle half of the data (units of the variable)"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:z-score","kind":"formula","course":"b02","lesson":"outliers","front":"Z-score","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>z</mi><mi>i</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><mi>s</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">z_i = \\dfrac{x_i - \\bar{x}}{s}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value being scored (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of all values, including x_i (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (dividing by n − 1) (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>z</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">z_i</annotation></semantics></math></span>","Z-score: standard deviations x_i lies above (+) or below (−) the mean"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:modified-z","kind":"formula","course":"b02","lesson":"outliers","front":"Modified z-score","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>M</mi><mi>i</mi></msub><mo>=</mo><mfrac><mrow><mn>0.6745</mn><mtext> </mtext><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo stretchy=\"false\">)</mo></mrow><mtext>MAD</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">M_i = \\dfrac{0.6745\\,(x_i - \\tilde{x})}{\\text{MAD}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value being scored (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\tilde{x}</annotation></semantics></math></span>","Median of the values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>MAD</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{MAD}</annotation></semantics></math></span>","Median absolute deviation: the median of |x_i − median| (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.6745</mn></mrow><annotation encoding=\"application/x-tex\">0.6745</annotation></semantics></math></span>","Makes M comparable with a z-score for normal data"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">M_i</annotation></semantics></math></span>","Modified z-score: distance from the median in robust standard-deviation units"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:skewness-g1","kind":"formula","course":"b02","lesson":"skewed-data","front":"Sample skewness (adjusted Fisher–Pearson coefficient)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>G</mi><mn>1</mn></msub><mo>=</mo><mfrac><msqrt><mrow><mi>n</mi><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></msqrt><mrow><mi>n</mi><mo>−</mo><mn>2</mn></mrow></mfrac><mo>⋅</mo><mfrac><msub><mi>m</mi><mn>3</mn></msub><msubsup><mi>m</mi><mn>2</mn><mrow><mn>3</mn><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></msubsup></mfrac></mrow><annotation encoding=\"application/x-tex\">G_1 = \\dfrac{\\sqrt{n(n-1)}}{n-2}\\cdot\\dfrac{m_3}{m_2^{3/2}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">G_1</annotation></semantics></math></span>","Sample skewness: positive for a long right tail, negative for a long left tail"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values (at least 3)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_2</annotation></semantics></math></span>","Mean squared deviation from the mean, dividing by n (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_3</annotation></semantics></math></span>","Mean cubed deviation from the mean, dividing by n (cubed units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:log-transforms","kind":"formula","course":"b02","lesson":"skewed-data","front":"Log and log(1 + x) transformations","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>y</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mi>x</mi><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mi>x</mi><mo>&gt;</mo><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>y</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mi>x</mi><mo>&gt;</mo><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">y = \\ln x \\quad (x &gt; 0), \\qquad y = \\ln(1 + x) \\quad (x &gt; -1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The original value (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">y</annotation></semantics></math></span>","The transformed value (log units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:box-cox","kind":"formula","course":"b02","lesson":"skewed-data","front":"Box–Cox transformation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>λ</mi><mo stretchy=\"false\">)</mo></mrow></msup><mo>=</mo><mfrac><mrow><msup><mi>x</mi><mi>λ</mi></msup><mo>−</mo><mn>1</mn></mrow><mi>λ</mi></mfrac><mtext> </mtext><mo stretchy=\"false\">(</mo><mi>λ</mi><mo mathvariant=\"normal\">≠</mo><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msup><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mn>0</mn><mo stretchy=\"false\">)</mo></mrow></msup><mo>=</mo><mi>ln</mi><mo>⁡</mo><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x^{(\\lambda)} = \\dfrac{x^{\\lambda} - 1}{\\lambda}\\ (\\lambda \\neq 0), \\qquad x^{(0)} = \\ln x</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The original value, strictly positive (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi></mrow><annotation encoding=\"application/x-tex\">\\lambda</annotation></semantics></math></span>","The power, estimated from the (training) data"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:geometric-mean","kind":"formula","course":"b02","lesson":"skewed-data","front":"Geometric mean","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>GM</mtext><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><munderover><mo>∏</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>x</mi><mi>i</mi></msub><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>=</mo><mi>exp</mi><mo>⁡</mo><mtext> ⁣</mtext><mrow><mo fence=\"true\">(</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mi>ln</mi><mo>⁡</mo><msub><mi>x</mi><mi>i</mi></msub><mo fence=\"true\">)</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{GM} = \\left(\\prod_{i=1}^{n} x_i\\right)^{1/n} = \\exp\\!\\left(\\dfrac{1}{n}\\sum_{i=1}^{n}\\ln x_i\\right)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","Positive values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>GM</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{GM}</annotation></semantics></math></span>","Geometric mean: the back-transformed mean of the logs (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:log-difference","kind":"formula","course":"b02","lesson":"skewed-data","front":"Log difference and percentage change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mfrac><msub><mi>x</mi><mtext>new</mtext></msub><msub><mi>x</mi><mtext>old</mtext></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>percentage change</mtext><mo>=</mo><mo stretchy=\"false\">(</mo><msup><mi>e</mi><mi>d</mi></msup><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">d = \\ln\\dfrac{x_{\\text{new}}}{x_{\\text{old}}}, \\qquad \\text{percentage change} = (e^{d} - 1) \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>new</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mtext>old</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{new}},\\ x_{\\text{old}}</annotation></semantics></math></span>","The new and old values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference between the logs of the new and old values (log units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:euclidean-distance","kind":"formula","course":"b02","lesson":"scaling","front":"Euclidean distance between two observations","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">p</mi><mo separator=\"true\">,</mo><mi mathvariant=\"bold\">q</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msqrt><mrow><munderover><mo>∑</mo><mrow><mi>j</mi><mo>=</mo><mn>1</mn></mrow><mi>k</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>p</mi><mi>j</mi></msub><mo>−</mo><msub><mi>q</mi><mi>j</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></msqrt></mrow><annotation encoding=\"application/x-tex\">d(\\mathbf{p}, \\mathbf{q}) = \\sqrt{\\sum_{j=1}^{k} (p_j - q_j)^2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">p</mi><mo separator=\"true\">,</mo><mi mathvariant=\"bold\">q</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">d(\\mathbf{p}, \\mathbf{q})</annotation></semantics></math></span>","Straight-line distance between observations p and q"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>q</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_j,\\ q_j</annotation></semantics></math></span>","The two observations’ values on variable j (units of variable j)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The number of variables"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:min-max","kind":"formula","course":"b02","lesson":"scaling","front":"Min–max normalisation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">x&#x27; = \\dfrac{x - x_{\\min}}{x_{\\max} - x_{\\min}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The value to scale (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\min},\\ x_{\\max}</annotation></semantics></math></span>","Smallest and largest values in the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup></mrow><annotation encoding=\"application/x-tex\">x&#x27;</annotation></semantics></math></span>","The scaled value: 0 at the training minimum, 1 at the training maximum"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:standardise","kind":"formula","course":"b02","lesson":"scaling","front":"Standardisation (z-score)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>z</mi><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><mi>s</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">z = \\dfrac{x - \\bar{x}}{s}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Standard deviation of the training data (sample formula, n − 1, in this course) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z</mi></mrow><annotation encoding=\"application/x-tex\">z</annotation></semantics></math></span>","Standard deviations above (+) or below (−) the training mean"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:robust-scale","kind":"formula","course":"b02","lesson":"scaling","front":"Robust scaling","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><mrow><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\dfrac{x - \\tilde{x}}{Q_3 - Q_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\tilde{x}</annotation></semantics></math></span>","Median of the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_3</annotation></semantics></math></span>","First and third quartiles of the training data (linear interpolation in this course) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interquartile ranges above (+) or below (−) the training median"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:inverse-scaling","kind":"formula","course":"b02","lesson":"scaling","front":"Converting scaled values back","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>x</mi><mo>=</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo>+</mo><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>x</mi><mo>=</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>+</mo><mi>z</mi><mtext> </mtext><mi>s</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>x</mi><mo>=</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo>+</mo><mi>r</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">x = x_{\\min} + x&#x27;(x_{\\max} - x_{\\min}), \\qquad x = \\bar{x} + z\\,s, \\qquad x = \\tilde{x} + r\\,(Q_3 - Q_1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The value in the original units (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo separator=\"true\">,</mo><mtext> </mtext><mi>z</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">x&#x27;,\\ z,\\ r</annotation></semantics></math></span>","A min–max, standardised or robust-scaled value, with the parameters it was fitted with"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\min},\\ x_{\\max}</annotation></semantics></math></span>","Training minimum and maximum (min–max) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mtext> </mtext><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">\\bar{x},\\ s</annotation></semantics></math></span>","Training mean and standard deviation (standardisation) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\tilde{x},\\ Q_1,\\ Q_3</annotation></semantics></math></span>","Training median and first and third quartiles (robust scaling) (original units)"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:coef-per-unit","kind":"formula","course":"b02","lesson":"scaling","front":"Coefficient per original unit from a standardised coefficient","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>b</mi><mi>j</mi></msub><mo>=</mo><mfrac><msubsup><mi>b</mi><mi>j</mi><mrow><mo stretchy=\"false\">(</mo><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></msubsup><msub><mi>s</mi><mi>j</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">b_j = \\dfrac{b_j^{(z)}}{s_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>b</mi><mi>j</mi><mrow><mo stretchy=\"false\">(</mo><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></msubsup></mrow><annotation encoding=\"application/x-tex\">b_j^{(z)}</annotation></semantics></math></span>","Coefficient on the standardised predictor j: change in the prediction per standard deviation of the predictor (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_j</annotation></semantics></math></span>","Standard deviation of predictor j used for the scaling (units of predictor j)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_j</annotation></semantics></math></span>","Change in the prediction per one-unit increase in predictor j (units of y per unit of predictor j)"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:encoded-columns","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Columns created by one-hot and dummy coding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>p</mi><mtext>one-hot</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>k</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>p</mi><mtext>dummy</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><mo stretchy=\"false\">(</mo><msub><mi>k</mi><mi>j</mi></msub><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">p_{\\text{one-hot}} = \\sum_{j} k_j, \\qquad p_{\\text{dummy}} = \\sum_{j} (k_j - 1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>k</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">k_j</annotation></semantics></math></span>","Number of categories of categorical variable j (after cleaning) (categories)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Number of columns the encoded variables occupy (columns)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:dummy-coefficients","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Dummy coefficients with one categorical predictor","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>^</mo></mover><mo>=</mo><msub><mi>b</mi><mn>0</mn></msub><mo>+</mo><munder><mo>∑</mo><mrow><mi>c</mi><mo mathvariant=\"normal\">≠</mo><mtext>ref</mtext></mrow></munder><msub><mi>b</mi><mi>c</mi></msub><msub><mi>D</mi><mi>c</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mn>0</mn></msub><mo>=</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mi>c</mi></msub><mo>=</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\hat{y} = b_0 + \\sum_{c \\neq \\text{ref}} b_c D_c, \\qquad b_0 = \\bar{y}_{\\text{ref}}, \\qquad b_c = \\bar{y}_c - \\bar{y}_{\\text{ref}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_c</annotation></semantics></math></span>","Dummy variable: 1 if the row is in category c, 0 otherwise"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_{\\text{ref}},\\ \\bar{y}_c</annotation></semantics></math></span>","Mean of the target in the reference category and in category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>b</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_0,\\ b_c</annotation></semantics></math></span>","Intercept and the coefficient of category c (units of y)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:frequency-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Frequency encoding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>f</mi><mi>c</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>c</mi></msub><mi>n</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">f_c = \\dfrac{n_c}{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","All training rows (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">f_c</annotation></semantics></math></span>","Frequency encoding of category c: its share of the training rows"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:target-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Target encoding (category mean)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>=</mo><mfrac><mn>1</mn><msub><mi>n</mi><mi>c</mi></msub></mfrac><munder><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><mi>c</mi></mrow></munder><msub><mi>y</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_c = \\dfrac{1}{n_c}\\sum_{i \\in c} y_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">y_i</annotation></semantics></math></span>","Target value of training row i (1 or 0 for a yes/no target) (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:smoothed-target-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Smoothed target encoding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mi>c</mi></msub><mo>=</mo><msub><mi>λ</mi><mi>c</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>λ</mi><mi>c</mi></msub><mo stretchy=\"false\">)</mo><mtext> </mtext><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>λ</mi><mi>c</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>c</mi></msub><mrow><msub><mi>n</mi><mi>c</mi></msub><mo>+</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">S_c = \\lambda_c\\,\\bar{y}_c + (1 - \\lambda_c)\\,\\bar{y}, \\qquad \\lambda_c = \\dfrac{n_c}{n_c + m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_c</annotation></semantics></math></span>","Smoothed target encoding of category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_c</annotation></semantics></math></span>","Mean of the target in category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{y}</annotation></semantics></math></span>","Overall mean of the target in the training data (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\lambda_c</annotation></semantics></math></span>","Weight on the category’s own mean, between 0 and 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Smoothing strength: the larger it is, the more small categories are pulled towards the overall mean (rows)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:derived-order-total","kind":"formula","course":"b02","lesson":"transforming-data","front":"Expected order total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>expected total</mtext><mo>=</mo><mi>q</mi><mo>×</mo><mi>p</mi><mo>−</mo><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">\\text{expected total} = q \\times p - d</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Quantity: number of packs ordered (packs)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Unit price of one pack ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount on the whole order ($)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:nights-between-dates","kind":"formula","course":"b02","lesson":"transforming-data","front":"Nights between two dates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>nights</mtext><mo>=</mo><mtext>check-out date</mtext><mo>−</mo><mtext>check-in date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{nights} = \\text{check-out date} - \\text{check-in date}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>check-in date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{check-in date}</annotation></semantics></math></span>","Date of arrival, stored as a true date (date)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>check-out date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{check-out date}</annotation></semantics></math></span>","Date of departure, stored as a true date (date)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>nights</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{nights}</annotation></semantics></math></span>","Number of nights stayed; the check-out day is not counted (nights)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:equal-width-bins","kind":"formula","course":"b02","lesson":"transforming-data","front":"Width of equal-width bins","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>w</mi><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><mi>k</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">w = \\dfrac{x_{\\max} - x_{\\min}}{k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow><annotation encoding=\"application/x-tex\">w</annotation></semantics></math></span>","Width of every bin (same unit as x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\max},\\ x_{\\min}</annotation></semantics></math></span>","Largest and smallest value (same unit as x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of bins"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:mean-from-group-means","kind":"formula","course":"b02","lesson":"transforming-data","front":"Overall mean from group means","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>n</mi><mi>g</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>n</mi><mi>g</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x} = \\dfrac{\\sum_g n_g\\,\\bar{x}_g}{\\sum_g n_g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_g</annotation></semantics></math></span>","Mean of group g (unit of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_g</annotation></semantics></math></span>","Number of rows in group g (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of all the rows (unit of x)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:join-row-count","kind":"formula","course":"b02","lesson":"transforming-data","front":"Rows produced by inner and left joins","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>inner</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>a</mi><mi>k</mi></msub><mtext> </mtext><msub><mi>b</mi><mi>k</mi></msub><mspace width=\"2em\"/><msub><mi>N</mi><mtext>left</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>a</mi><mi>k</mi></msub><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><msub><mi>b</mi><mi>k</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">N_{\\text{inner}} = \\sum_k a_k\\, b_k \\qquad N_{\\text{left}} = \\sum_k a_k \\max(b_k,\\, 1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">a_k</annotation></semantics></math></span>","Rows with key value k in the left table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_k</annotation></semantics></math></span>","Rows with key value k in the right table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Rows in the joined table (rows)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:full-join-row-count","kind":"formula","course":"b02","lesson":"transforming-data","front":"Rows produced by a full outer join","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>full</mtext></msub><mo>=</mo><msub><mi>N</mi><mtext>inner</mtext></msub><mo>+</mo><msub><mi>U</mi><mi>L</mi></msub><mo>+</mo><msub><mi>U</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{full}} = N_{\\text{inner}} + U_L + U_R</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>full</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>N</mi><mtext>inner</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{full}},\\ N_{\\text{inner}}</annotation></semantics></math></span>","Rows in the full outer join and in the inner join (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">U_L</annotation></semantics></math></span>","Left rows whose key has no match in the right table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">U_R</annotation></semantics></math></span>","Right rows whose key has no match in the left table (rows)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:missing-share","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Share of values missing in a column","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>missing %</mtext><mo>=</mo><mfrac><mi>m</mi><mi>n</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{missing \\%} = \\dfrac{m}{n} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Missing values in the column (values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Rows in the table at the time of the profile (rows)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:b02:rows-retained","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Share of rows retained","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>retained %</mtext><mo>=</mo><mfrac><msub><mi>n</mi><mtext>after</mtext></msub><msub><mi>n</mi><mtext>before</mtext></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{retained \\%} = \\dfrac{n_{\\text{after}}}{n_{\\text{before}}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>before</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{before}}</annotation></semantics></math></span>","Rows in the raw data (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{after}}</annotation></semantics></math></span>","Rows in the cleaned data (rows)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:b02:percentage-point-change","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Change in percentage points and relative change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub><mo>=</mo><msub><mi>p</mi><mn>2</mn></msub><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub><mspace width=\"2em\"/><msub><mi mathvariant=\"normal\">Δ</mi><mi mathvariant=\"normal\">%</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>p</mi><mn>2</mn></msub><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub></mrow><msub><mi>p</mi><mn>1</mn></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}} = p_2 - p_1 \\qquad \\Delta_{\\%} = \\dfrac{p_2 - p_1}{p_1} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>p</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">p_1,\\ p_2</annotation></semantics></math></span>","A percentage before and after (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}}</annotation></semantics></math></span>","Change in percentage points (pp)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi mathvariant=\"normal\">%</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\%}</annotation></semantics></math></span>","Relative (percentage) change (%)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:b03:line-total","kind":"formula","course":"b03","lesson":"cells-and-formulas","front":"Order line total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>T</mi><mo>=</mo><mi>q</mi><mo>×</mo><mi>p</mi><mo>−</mo><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">T = q \\times p - d</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","The order’s value after its discount ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Quantity: the number of items ordered (items)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Unit price: the shop price of one item ($ per item)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount on the whole order ($)"]],"href":"learn/analytics/b03/cells-and-formulas/"},{"id":"f:b03:price-rise","kind":"formula","course":"b03","lesson":"cells-and-formulas","front":"Price after a percentage rise","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>p</mi><mtext>new</mtext></msub><mo>=</mo><mi>p</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">p_{\\text{new}} = p \\times (1 + r)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mtext>new</mtext></msub></mrow><annotation encoding=\"application/x-tex\">p_{\\text{new}}</annotation></semantics></math></span>","The price after the rise ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","The current price ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","The rise as a decimal (6% is 0.06)"]],"href":"learn/analytics/b03/cells-and-formulas/"},{"id":"f:b03:share-of-total","kind":"formula","course":"b03","lesson":"cells-and-formulas","front":"Share of a total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mfrac><msub><mi>x</mi><mi>i</mi></msub><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>x</mi><mi>j</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">s_i = \\dfrac{x_i}{\\sum_j x_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_i</annotation></semantics></math></span>","The share of item i"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value of item i, such as one month’s order value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>x</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\sum_j x_j</annotation></semantics></math></span>","The total of all the items ($)"]],"href":"learn/analytics/b03/cells-and-formulas/"},{"id":"f:b03:subscription-discount","kind":"formula","course":"b03","lesson":"functions-and-logic","front":"Expected subscription discount","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mi mathvariant=\"normal\">round</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>r</mi><mo>×</mo><mi>q</mi><mo>×</mo><mi>p</mi><mo separator=\"true\">,</mo><mtext> </mtext><mn>2</mn><mo stretchy=\"false\">)</mo><mtext> if a subscription order, otherwise </mtext><mn>0</mn></mrow><annotation encoding=\"application/x-tex\">d = \\operatorname{round}(r \\times q \\times p,\\ 2) \\text{ if a subscription order, otherwise } 0</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","The discount the order should carry ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","The subscription discount rate (10% at Lantern)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Quantity (items)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Unit price ($ per item)"]],"href":"learn/analytics/b03/functions-and-logic/"},{"id":"f:b03:units-needed","kind":"formula","course":"b03","lesson":"functions-and-logic","front":"Whole units needed","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>n</mi><mo>=</mo><mrow><mo fence=\"true\">⌈</mo><mfrac><mi>g</mi><mi>k</mi></mfrac><mo fence=\"true\">⌉</mo></mrow></mrow><annotation encoding=\"application/x-tex\">n = \\left\\lceil \\dfrac{g}{k} \\right\\rceil</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Units to buy, rounded up to a whole number (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","What has to be covered, such as guests (guests)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","How much one unit covers, such as guests per pastry box (guests per unit)"]],"href":"learn/analytics/b03/functions-and-logic/"},{"id":"f:b03:catering-quote","kind":"formula","course":"b03","lesson":"functions-and-logic","front":"Lantern’s catering quote (one-day event)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>Q</mi><mo>=</mo><mi>max</mi><mo>⁡</mo><mrow><mo fence=\"true\">(</mo><mi>M</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>S</mi><mo>+</mo><mi>a</mi><mtext> </mtext><mi>g</mi><mo>+</mo><mi>b</mi><mtext> </mtext><mi>h</mi><mo>+</mo><mi>P</mi><mtext> </mtext><mi>x</mi><mo fence=\"true\">)</mo></mrow></mrow><annotation encoding=\"application/x-tex\">Q = \\max\\left(M,\\ S + a\\,g + b\\,h + P\\,x\\right)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","The quoted price ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","The minimum invoice ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","The setup charge for the day ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow><annotation encoding=\"application/x-tex\">a</annotation></semantics></math></span>","The price per guest ($ per guest)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Number of guests (guests)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">b</annotation></semantics></math></span>","The charge per hour of service ($ per hour)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi></mrow><annotation encoding=\"application/x-tex\">h</annotation></semantics></math></span>","Hours of service (hours)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","The pastry platter charge ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","1 if the client wants pastries, 0 if not"]],"href":"learn/analytics/b03/functions-and-logic/"},{"id":"f:b03:conditional-sum","kind":"formula","course":"b03","lesson":"conditional-sums-and-counts","front":"Conditional sum (SUMIFS)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>S</mi><mo>=</mo><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>x</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>c</mi><mi>i</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>c</mi><mi>i</mi></msub><mo>=</mo><mrow><mo fence=\"true\">{</mo><mtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mtext>if row </mtext><mi>i</mi><mtext> meets every criterion</mtext></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mtext>otherwise</mtext></mstyle></mtd></mtr></mtable></mrow></mrow><annotation encoding=\"application/x-tex\">S = \\sum_{i=1}^{n} x_i\\, c_i, \\qquad c_i = \\begin{cases} 1 &amp; \\text{if row } i \\text{ meets every criterion} \\\\ 0 &amp; \\text{otherwise} \\end{cases}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","The conditional sum (as x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rows in the data (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","The row number, from 1 to n"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value in row i of the sum range (as recorded)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_i</annotation></semantics></math></span>","Whether row i passes all the criteria"]],"href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"f:b03:weighted-average-price","kind":"formula","course":"b03","lesson":"conditional-sums-and-counts","front":"Weighted average price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>p</mi><mo>ˉ</mo></mover><mi>w</mi></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>q</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>p</mi><mi>i</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>q</mi><mi>i</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{p}_w = \\dfrac{\\sum_i q_i\\, p_i}{\\sum_i q_i}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>p</mi><mo>ˉ</mo></mover><mi>w</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{p}_w</annotation></semantics></math></span>","Average price per item, weighted by quantity ($ per item)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">q_i</annotation></semantics></math></span>","Quantity in order i (items)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_i</annotation></semantics></math></span>","Unit price in order i ($ per item)"]],"href":"learn/analytics/b03/conditional-sums-and-counts/"},{"id":"f:b03:approximate-match","kind":"formula","course":"b03","lesson":"lookups","front":"Approximate-match (band) lookup","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>result</mtext><mo>=</mo><msub><mi>r</mi><mi>k</mi></msub><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mi>k</mi><mo>=</mo><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">{</mo><mtext> </mtext><mi>i</mi><mo>:</mo><msub><mi>f</mi><mi>i</mi></msub><mo>≤</mo><mi>v</mi><mtext> </mtext><mo stretchy=\"false\">}</mo></mrow><annotation encoding=\"application/x-tex\">\\text{result} = r_k, \\quad k = \\max\\{\\, i : f_i \\le v \\,\\}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","The lookup value, such as an order value (as the table)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">f_i</annotation></semantics></math></span>","The lower bound (“from”) of band i; the bounds are sorted so that f₁ < f₂ < … (as v)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_i</annotation></semantics></math></span>","The result for band i, such as its delivery charge or its label (any)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","A band’s position in the table, counting from the top"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The band the value falls in: the last band whose lower bound is not above v"]],"href":"learn/analytics/b03/lookups/"},{"id":"f:b03:order-total-check","kind":"formula","course":"b03","lesson":"tables-and-cleaning","front":"The order-total check (a cross-field rule)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>order_total</mtext><mo>=</mo><mi>q</mi><mo>×</mo><mi>p</mi><mo>−</mo><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">\\text{order\\_total} = q \\times p - d</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Quantity: the number of items in the order (items)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Unit price: Lantern’s shop price per item ($ per item)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount on the whole order (10% for subscriptions, $5 for a promotion code) ($)"]],"href":"learn/analytics/b03/tables-and-cleaning/"},{"id":"f:b03:pct-grand-total","kind":"formula","course":"b03","lesson":"pivot-tables","front":"% of Grand Total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mi>V</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">s_{ij} = \\dfrac{v_{ij}}{V}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">v_{ij}</annotation></semantics></math></span>","The value in row i and column j of the PivotTable (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","The grand total of all the values (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{ij}</annotation></semantics></math></span>","The cell’s share of the whole table (%)"]],"href":"learn/analytics/b03/pivot-tables/"},{"id":"f:b03:pct-row-total","kind":"formula","course":"b03","lesson":"pivot-tables","front":"% of Row Total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>R</mi><mi>i</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">s_{ij} = \\dfrac{v_{ij}}{R_i}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">v_{ij}</annotation></semantics></math></span>","The value in row i and column j (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_i</annotation></semantics></math></span>","The total of row i (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{ij}</annotation></semantics></math></span>","The cell’s share of its row (%)"]],"href":"learn/analytics/b03/pivot-tables/"},{"id":"f:b03:pct-column-total","kind":"formula","course":"b03","lesson":"pivot-tables","front":"% of Column Total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>C</mi><mi>j</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">s_{ij} = \\dfrac{v_{ij}}{C_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">v_{ij}</annotation></semantics></math></span>","The value in row i and column j (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_j</annotation></semantics></math></span>","The total of column j (as the data)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{ij}</annotation></semantics></math></span>","The cell’s share of its column (%)"]],"href":"learn/analytics/b03/pivot-tables/"},{"id":"f:b03:cc-share","kind":"formula","course":"b03","lesson":"charts-and-conditional-formatting","front":"Share of a whole (100% stacked bar or pie)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mfrac><msub><mi>x</mi><mi>i</mi></msub><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>x</mi><mi>j</mi></msub></mrow></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">s_i = \\dfrac{x_i}{\\sum_{j} x_j} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value of part i, such as one channel’s order value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>x</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\sum_{j} x_j</annotation></semantics></math></span>","The total of all the parts (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_i</annotation></semantics></math></span>","Part i’s share of the whole (%)"]],"href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"f:b03:cc-truncation","kind":"formula","course":"b03","lesson":"charts-and-conditional-formatting","front":"Apparent ratio of two bars on a truncated axis","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>apparent ratio</mtext><mo>=</mo><mfrac><mrow><msub><mi>v</mi><mn>1</mn></msub><mo>−</mo><mi>b</mi></mrow><mrow><msub><mi>v</mi><mn>2</mn></msub><mo>−</mo><mi>b</mi></mrow></mfrac><mspace width=\"1em\"/><mtext>against the true ratio</mtext><mspace width=\"1em\"/><mfrac><msub><mi>v</mi><mn>1</mn></msub><msub><mi>v</mi><mn>2</mn></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{apparent ratio} = \\dfrac{v_1 - b}{v_2 - b} \\quad \\text{against the true ratio} \\quad \\dfrac{v_1}{v_2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><msub><mi>v</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">v_1, v_2</annotation></semantics></math></span>","The two values the bars show (units of v)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">b</annotation></semantics></math></span>","The value at which the axis starts (its minimum) (units of v)"]],"href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"f:b03:cc-contrast","kind":"formula","course":"b03","lesson":"charts-and-conditional-formatting","front":"WCAG contrast ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>contrast ratio</mtext><mo>=</mo><mfrac><mrow><msub><mi>L</mi><mn>1</mn></msub><mo>+</mo><mn>0.05</mn></mrow><mrow><msub><mi>L</mi><mn>2</mn></msub><mo>+</mo><mn>0.05</mn></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{contrast ratio} = \\dfrac{L_1 + 0.05}{L_2 + 0.05}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">L_1</annotation></semantics></math></span>","Relative luminance of the lighter colour (0 for black to 1 for white)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">L_2</annotation></semantics></math></span>","Relative luminance of the darker colour"]],"href":"learn/analytics/b03/charts-and-conditional-formatting/"},{"id":"f:b03:ds-sd","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Sample and population standard deviation (STDEV.S, STDEV.P)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>s</mi><mo>=</mo><msqrt><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></mfrac></msqrt><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>σ</mi><mo>=</mo><msqrt><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><mi>n</mi></mfrac></msqrt></mrow><annotation encoding=\"application/x-tex\">s = \\sqrt{\\dfrac{\\sum_{i=1}^{n} (x_i - \\bar{x})^2}{n - 1}}, \\qquad \\sigma = \\sqrt{\\dfrac{\\sum_{i=1}^{n} (x_i - \\bar{x})^2}{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","The mean of the values (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (STDEV.S) (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ</mi></mrow><annotation encoding=\"application/x-tex\">\\sigma</annotation></semantics></math></span>","Population standard deviation (STDEV.P) (units of x)"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-se-mean","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Standard error of the mean","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>SE</mtext><mo>=</mo><mfrac><mi>s</mi><msqrt><mi>n</mi></msqrt></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{SE} = \\dfrac{s}{\\sqrt{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>SE</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{SE}</annotation></semantics></math></span>","Standard error of the mean (units of x)"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-kurt","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Excess kurtosis (Excel’s KURT)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>KURT</mtext><mo>=</mo><mfrac><mrow><mi>n</mi><mo stretchy=\"false\">(</mo><mi>n</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><mrow><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>3</mn><mo stretchy=\"false\">)</mo></mrow></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msup><mrow><mo fence=\"true\">(</mo><mfrac><mrow><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><mi>s</mi></mfrac><mo fence=\"true\">)</mo></mrow><mn>4</mn></msup><mo>−</mo><mfrac><mrow><mn>3</mn><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><mrow><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>3</mn><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{KURT} = \\dfrac{n(n+1)}{(n-1)(n-2)(n-3)} \\sum_{i=1}^{n} \\left(\\dfrac{x_i - \\bar{x}}{s}\\right)^{4} - \\dfrac{3(n-1)^2}{(n-2)(n-3)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th value (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values (at least 4)"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-correl","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Correlation coefficient (CORREL)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><mfrac><mrow><mo>∑</mo><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mi>y</mi><mo>−</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mo stretchy=\"false\">)</mo></mrow><msqrt><mrow><mo>∑</mo><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mtext> </mtext><mo>∑</mo><mo stretchy=\"false\">(</mo><mi>y</mi><mo>−</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></msqrt></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\dfrac{\\sum (x - \\bar{x})(y - \\bar{y})}{\\sqrt{\\sum (x - \\bar{x})^2 \\, \\sum (y - \\bar{y})^2}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo separator=\"true\">,</mo><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">x, y</annotation></semantics></math></span>","Paired values of the two variables (their units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}, \\bar{y}</annotation></semantics></math></span>","Their means (their units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Pearson’s correlation coefficient, from −1 to +1"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-ls-line","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"Least-squares line (SLOPE, INTERCEPT, FORECAST.LINEAR)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>^</mo></mover><mo>=</mo><msub><mi>b</mi><mn>0</mn></msub><mo>+</mo><msub><mi>b</mi><mn>1</mn></msub><mi>x</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mn>1</mn></msub><mo>=</mo><mfrac><mrow><mo>∑</mo><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mi>y</mi><mo>−</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mo stretchy=\"false\">)</mo></mrow><mrow><mo>∑</mo><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mn>0</mn></msub><mo>=</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mo>−</mo><msub><mi>b</mi><mn>1</mn></msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\hat{y} = b_0 + b_1 x, \\qquad b_1 = \\dfrac{\\sum (x - \\bar{x})(y - \\bar{y})}{\\sum (x - \\bar{x})^2}, \\qquad b_0 = \\bar{y} - b_1 \\bar{x}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The explanatory variable (guests) (units of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>^</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\hat{y}</annotation></semantics></math></span>","The predicted value of y (invoice) (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">b_1</annotation></semantics></math></span>","Slope: change in predicted y per unit of x (units of y per unit of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">b_0</annotation></semantics></math></span>","Intercept: predicted y when x = 0 (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}, \\bar{y}</annotation></semantics></math></span>","Means of x and y (their units)"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-fit","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"R² and the standard error of the regression","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup><mo>=</mo><mfrac><msub><mtext>SS</mtext><mtext>reg</mtext></msub><msub><mtext>SS</mtext><mtext>tot</mtext></msub></mfrac><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><msub><mtext>SS</mtext><mtext>res</mtext></msub><msub><mtext>SS</mtext><mtext>tot</mtext></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>s</mi><mi>e</mi></msub><mo>=</mo><msqrt><mfrac><msub><mtext>SS</mtext><mtext>res</mtext></msub><mrow><mi>n</mi><mo>−</mo><mi>k</mi><mo>−</mo><mn>1</mn></mrow></mfrac></msqrt></mrow><annotation encoding=\"application/x-tex\">R^2 = \\dfrac{\\text{SS}_{\\text{reg}}}{\\text{SS}_{\\text{tot}}} = 1 - \\dfrac{\\text{SS}_{\\text{res}}}{\\text{SS}_{\\text{tot}}}, \\qquad s_e = \\sqrt{\\dfrac{\\text{SS}_{\\text{res}}}{n - k - 1}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding=\"application/x-tex\">R^2</annotation></semantics></math></span>","Share of the variation in y around its mean that the regression accounts for"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>SS</mtext><mtext>tot</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{SS}_{\\text{tot}}</annotation></semantics></math></span>","Total sum of squares: Σ(y − ȳ)² (units of y squared)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>SS</mtext><mtext>res</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{SS}_{\\text{res}}</annotation></semantics></math></span>","Residual sum of squares: Σ(y − ŷ)² (units of y squared)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>SS</mtext><mtext>reg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{SS}_{\\text{reg}}</annotation></semantics></math></span>","Regression sum of squares: SS_tot − SS_res (units of y squared)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Observations"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of X variables (1 here)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>e</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_e</annotation></semantics></math></span>","Standard error of the regression (the ToolPak’s Standard Error) (units of y)"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:ds-t","kind":"formula","course":"b03","lesson":"descriptive-statistics-and-regression","front":"t Stat and the 95% limits of a coefficient","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>t</mi><mo>=</mo><mfrac><mi>b</mi><msub><mtext>SE</mtext><mi>b</mi></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>b</mi><mo>±</mo><msub><mi>t</mi><mrow><mn>0.025</mn><mo separator=\"true\">,</mo><mtext> </mtext><mi>n</mi><mo>−</mo><mi>k</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>×</mo><msub><mtext>SE</mtext><mi>b</mi></msub></mrow><annotation encoding=\"application/x-tex\">t = \\dfrac{b}{\\text{SE}_b}, \\qquad b \\pm t_{0.025,\\,n-k-1} \\times \\text{SE}_b</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">b</annotation></semantics></math></span>","A coefficient (slope or intercept) (its units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>SE</mtext><mi>b</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{SE}_b</annotation></semantics></math></span>","Its standard error (its units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mrow><mn>0.025</mn><mo separator=\"true\">,</mo><mtext> </mtext><mi>n</mi><mo>−</mo><mi>k</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">t_{0.025,\\,n-k-1}</annotation></semantics></math></span>","The t value with 2.5% in each tail and n − k − 1 degrees of freedom"]],"href":"learn/analytics/b03/descriptive-statistics-and-regression/"},{"id":"f:b03:wi-baristas","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"Baristas for an event","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><mrow><mo fence=\"true\">⌈</mo><mfrac><mi>G</mi><mi>g</mi></mfrac><mo fence=\"true\">⌉</mo></mrow></mrow><annotation encoding=\"application/x-tex\">B = \\left\\lceil \\dfrac{G}{g} \\right\\rceil</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Baristas sent to the event (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G</mi></mrow><annotation encoding=\"application/x-tex\">G</annotation></semantics></math></span>","Guests (guests)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Guests per barista (Ana’s rule: 40) (guests per barista)"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:wi-invoice","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"Invoice from the quote sheet (one event day)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>max</mi><mo>⁡</mo><mtext> ⁣</mtext><mrow><mo fence=\"true\">(</mo><mi>M</mi><mo separator=\"true\">,</mo><mtext>  </mtext><mi>S</mi><mo>+</mo><mi>p</mi><mi>G</mi><mo>+</mo><mi>h</mi><mi>H</mi><mo>+</mo><mi>k</mi><mi>P</mi><mo fence=\"true\">)</mo></mrow></mrow><annotation encoding=\"application/x-tex\">I = \\max\\!\\left(M,\\; S + pG + hH + kP\\right)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Invoice ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","Minimum invoice ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","Setup charge per event day ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Price per guest ($ per guest)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G</mi></mrow><annotation encoding=\"application/x-tex\">G</annotation></semantics></math></span>","Guests (guests)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi></mrow><annotation encoding=\"application/x-tex\">h</annotation></semantics></math></span>","Charge per hour of service ($ per hour)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H</mi></mrow><annotation encoding=\"application/x-tex\">H</annotation></semantics></math></span>","Hours of service (hours)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Pastry platter price ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","1 if a platter is ordered, 0 if not"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:wi-contribution","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"Contribution and contribution margin ratio of an event","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>C</mi><mo>=</mo><mi>I</mi><mo>−</mo><mrow><mo fence=\"true\">[</mo><mtext> </mtext><mi>B</mi><mo stretchy=\"false\">(</mo><mi>H</mi><mo>+</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mi>w</mi><mo>+</mo><mi>c</mi><mi>G</mi><mo>+</mo><mi>q</mi><mi>P</mi><mo>+</mo><mi>v</mi><mtext> </mtext><mo fence=\"true\">]</mo></mrow><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>r</mi><mo>=</mo><mfrac><mi>C</mi><mi>I</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">C = I - \\left[\\,B(H + u)w + cG + qP + v\\,\\right], \\qquad r = \\dfrac{C}{I}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Contribution of the event ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Invoice ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Baristas (people)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H</mi></mrow><annotation encoding=\"application/x-tex\">H</annotation></semantics></math></span>","Hours of service (hours)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u</mi></mrow><annotation encoding=\"application/x-tex\">u</annotation></semantics></math></span>","Paid set-up hours per barista (hours)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow><annotation encoding=\"application/x-tex\">w</annotation></semantics></math></span>","Barista wage ($ per hour)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">c</annotation></semantics></math></span>","Coffee, milk and cups per guest ($ per guest)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G</mi></mrow><annotation encoding=\"application/x-tex\">G</annotation></semantics></math></span>","Guests (guests)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Pastry platter cost ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","1 if a platter is ordered, 0 if not"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","Van cost per event day ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Contribution margin ratio"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:wi-target-price","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"Price per guest for a target contribution margin ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>p</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup><mo>=</mo><mfrac><mrow><mfrac><mi>D</mi><mrow><mn>1</mn><mo>−</mo><msup><mi>r</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow></mfrac><mo>−</mo><mi>S</mi><mo>−</mo><mi>h</mi><mi>H</mi><mo>−</mo><mi>k</mi><mi>P</mi></mrow><mi>G</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">p^{*} = \\dfrac{\\dfrac{D}{1 - r^{*}} - S - hH - kP}{G}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>p</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><annotation encoding=\"application/x-tex\">p^{*}</annotation></semantics></math></span>","Price per guest that gives the target ratio ($ per guest)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Direct costs of the event ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>r</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><annotation encoding=\"application/x-tex\">r^{*}</annotation></semantics></math></span>","Target contribution margin ratio"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","Setup charge ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi></mrow><annotation encoding=\"application/x-tex\">h</annotation></semantics></math></span>","Charge per hour ($ per hour)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H</mi></mrow><annotation encoding=\"application/x-tex\">H</annotation></semantics></math></span>","Hours of service (hours)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Platter price ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","1 if a platter is ordered, 0 if not"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G</mi></mrow><annotation encoding=\"application/x-tex\">G</annotation></semantics></math></span>","Guests (guests)"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:wi-lp","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"A linear programme (maximisation)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>max</mi><mo>⁡</mo><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>c</mi><mi>j</mi></msub><msub><mi>x</mi><mi>j</mi></msub><mspace width=\"1em\"/><mtext>subject to</mtext><mspace width=\"1em\"/><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>a</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>x</mi><mi>j</mi></msub><mo>≤</mo><msub><mi>b</mi><mi>i</mi></msub><mtext> for each </mtext><mi>i</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>x</mi><mi>j</mi></msub><mo>≥</mo><mn>0</mn></mrow><annotation encoding=\"application/x-tex\">\\max \\sum_{j} c_j x_j \\quad \\text{subject to} \\quad \\sum_{j} a_{ij} x_j \\le b_i \\ \\text{for each } i, \\qquad x_j \\ge 0</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">i,\\ j</annotation></semantics></math></span>","Indexes: i counts the constraints (resources), j the decision variables"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_j</annotation></semantics></math></span>","Decision variable j (such as the number of events) (units chosen)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_j</annotation></semantics></math></span>","Contribution of one unit of variable j ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">a_{ij}</annotation></semantics></math></span>","Amount of resource i that one unit of variable j uses (resource units per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_i</annotation></semantics></math></span>","Amount of resource i available (the limit) (resource units)"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:wi-slack","kind":"formula","course":"b03","lesson":"what-if-analysis","front":"Slack in a constraint","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><msub><mi>b</mi><mi>i</mi></msub><mo>−</mo><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>a</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>x</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_i = b_i - \\sum_{j} a_{ij} x_j</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_i</annotation></semantics></math></span>","Slack in constraint i at a solution (resource units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_i</annotation></semantics></math></span>","Limit of constraint i (resource units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">a_{ij}</annotation></semantics></math></span>","Use of resource i per unit of variable j (resource units per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_j</annotation></semantics></math></span>","Value of decision variable j in the solution (units)"]],"href":"learn/analytics/b03/what-if-analysis/"},{"id":"f:b03:db-gap","kind":"formula","course":"b03","lesson":"dashboards","front":"Gap to plan and share of plan","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Gap</mtext><mo>=</mo><mi>A</mi><mo>−</mo><mi>P</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Share of plan</mtext><mo>=</mo><mfrac><mi>A</mi><mi>P</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Gap} = A - P, \\qquad \\text{Share of plan} = \\dfrac{A}{P} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span>","Actual value for the period (units of the measure)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Planned (target) value for the same period (units of the measure)"]],"href":"learn/analytics/b03/dashboards/"},{"id":"f:b03:db-change","kind":"formula","course":"b03","lesson":"dashboards","front":"Change on the previous period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mi mathvariant=\"normal\">Δ</mi><mo>=</mo><mfrac><mrow><msub><mi>A</mi><mi>t</mi></msub><mo>−</mo><msub><mi>A</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><msub><mi>A</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\%\\Delta = \\dfrac{A_t - A_{t-1}}{A_{t-1}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mi mathvariant=\"normal\">Δ</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\Delta</annotation></semantics></math></span>","Percentage change on the previous period (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_t</annotation></semantics></math></span>","Value this period (units of the measure)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">A_{t-1}</annotation></semantics></math></span>","Value in the previous period (units of the measure)"]],"href":"learn/analytics/b03/dashboards/"},{"id":"f:b03:db-average","kind":"formula","course":"b03","lesson":"dashboards","front":"Average invoice from totals","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>I</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>m</mi></munder><msub><mi>R</mi><mi>m</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>m</mi></munder><msub><mi>N</mi><mi>m</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{I} = \\dfrac{\\sum_{m} R_m}{\\sum_{m} N_m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>I</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{I}</annotation></semantics></math></span>","Average invoice over the months ($ per event)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>m</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_m</annotation></semantics></math></span>","Revenue in month m ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>m</mi></msub></mrow><annotation encoding=\"application/x-tex\">N_m</annotation></semantics></math></span>","Events in month m (events)"]],"href":"learn/analytics/b03/dashboards/"},{"id":"f:b03:db-concentration","kind":"formula","course":"b03","lesson":"dashboards","front":"Top-k client share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>C</mi><mi>k</mi></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mrow><mi>c</mi><mo>∈</mo><mtext>top </mtext><mi>k</mi></mrow></munder><msub><mi>R</mi><mi>c</mi></msub></mrow><mi>R</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">C_k = \\dfrac{\\sum_{c \\in \\text{top } k} R_c}{R} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">C_k</annotation></semantics></math></span>","Share of revenue from the k largest clients (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of clients counted (Ana uses 4) (clients)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_c</annotation></semantics></math></span>","Revenue from client c over the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Total revenue over the period ($)"]],"href":"learn/analytics/b03/dashboards/"},{"id":"f:m01:m01-exchange-value","kind":"formula","course":"m01","lesson":"what-is-marketing","front":"Value created by an exchange, and how the price divides it","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>V</mi><mo>=</mo><mi>W</mi><mo>−</mo><mi>C</mi><mspace width=\"2em\"/><mtext>Gain to buyer</mtext><mo>=</mo><mi>W</mi><mo>−</mo><mi>P</mi><mspace width=\"2em\"/><mtext>Gain to seller</mtext><mo>=</mo><mi>P</mi><mo>−</mo><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">V = W - C \\qquad \\text{Gain to buyer} = W - P \\qquad \\text{Gain to seller} = P - C</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Value created by the exchange: the total gain to both sides ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi></mrow><annotation encoding=\"application/x-tex\">W</annotation></semantics></math></span>","Willingness to pay: the most the buyer would pay for the offer rather than go without it ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price paid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Seller’s cost of providing this one sale (only the costs the sale causes) ($)"]],"href":"learn/marketing/m01/what-is-marketing/"},{"id":"f:m01:m01-net-value","kind":"formula","course":"m01","lesson":"customer-value","front":"Net value of an offer to a customer (when benefits and costs can be put in money)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net value</mtext><mo>=</mo><mi>W</mi><mo>−</mo><mo stretchy=\"false\">(</mo><mi>P</mi><mo>+</mo><mi>N</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Net value} = W - (P + N)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi></mrow><annotation encoding=\"application/x-tex\">W</annotation></semantics></math></span>","Willingness to pay: the most this customer would pay for the offer rather than go without it (the money value of its benefits to her) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price, including any money extras such as delivery ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Non-money costs put in money: time at the customer’s own value of time, effort, and the expected cost of risk (probability × cost if it goes wrong) ($)"]],"href":"learn/marketing/m01/customer-value/"},{"id":"f:m01:m01-clv","kind":"formula","course":"m01","lesson":"customer-value","front":"Customer lifetime value (margins at year end; retention constant)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CLV</mtext><mo>=</mo><munderover><mo>∑</mo><mrow><mi>t</mi><mo>=</mo><mn>1</mn></mrow><mi>T</mi></munderover><mfrac><mrow><mi>m</mi><mtext> </mtext><msup><mi>r</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msup></mrow><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>d</mi><msup><mo stretchy=\"false\">)</mo><mi>t</mi></msup></mrow></mfrac><mspace width=\"2em\"/><mtext>every future year: CLV</mtext><mo>=</mo><mfrac><mi>m</mi><mrow><mn>1</mn><mo>+</mo><mi>d</mi><mo>−</mo><mi>r</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CLV} = \\sum_{t=1}^{T} \\frac{m\\, r^{t-1}}{(1+d)^{t}} \\qquad \\text{every future year: } \\text{CLV} = \\frac{m}{1 + d - r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CLV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CLV}</annotation></semantics></math></span>","Customer lifetime value: the present value of the margins the customer is expected to bring in ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Margin per year from the customer: revenue minus the costs that serving them causes (not revenue) ($ per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Retention rate: the probability that a customer in one year is still a customer the next (decimal (0.70 = 70%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount rate per year (decimal (0.10 = 10%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Year of the relationship, 1 for the first year (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","Number of years counted (the horizon) (years)"]],"href":"learn/marketing/m01/customer-value/"},{"id":"f:m01:m01-cac","kind":"formula","course":"m01","lesson":"customer-value","front":"Customer acquisition cost, and the net value of winning a customer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CAC</mtext><mo>=</mo><mfrac><mi>S</mi><mi>n</mi></mfrac><mspace width=\"2em\"/><mtext>Net value of a new customer</mtext><mo>=</mo><mtext>CLV</mtext><mo>−</mo><mtext>CAC</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CAC} = \\frac{S}{n} \\qquad \\text{Net value of a new customer} = \\text{CLV} - \\text{CAC}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CAC</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CAC}</annotation></semantics></math></span>","Customer acquisition cost: the average cost of winning one new customer ($ per customer)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","Marketing and sales spending on winning new customers in the period, including free samples and introductory discounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of new customers won in the period (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CLV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CLV}</annotation></semantics></math></span>","Customer lifetime value of the customers won, measured from margin ($ per customer)"]],"href":"learn/marketing/m01/customer-value/"},{"id":"f:m01:m01-share-citing","kind":"formula","course":"m01","lesson":"market-orientation","front":"Share of respondents giving a reason, and reasons per respondent","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mi>k</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>k</mi></msub><mi>N</mi></mfrac><mo>×</mo><mn>100</mn><mspace width=\"2em\"/><mover accent=\"true\"><mi>r</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>n</mi><mi>k</mi></msub></mrow><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">s_k = \\frac{n_k}{N} \\times 100 \\qquad \\bar{r} = \\frac{\\sum_k n_k}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_k</annotation></semantics></math></span>","Share of respondents who gave reason k (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_k</annotation></semantics></math></span>","Number of respondents who gave reason k (respondents)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of respondents (respondents)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>r</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{r}</annotation></semantics></math></span>","Average number of reasons each respondent gave (reasons per respondent)"]],"href":"learn/marketing/m01/market-orientation/"},{"id":"f:m01:weighted-attribute-score","kind":"formula","course":"m01","lesson":"consumer-decisions","front":"Weighted-attribute score of an option","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mi>j</mi></msub><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>w</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">S_j = \\sum_{i} w_i \\, s_{ij}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_j</annotation></semantics></math></span>","Weighted score of option j (points (same scale as the scores))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>w</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">w_i</annotation></semantics></math></span>","Importance weight of attribute i; the weights add up to 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{ij}</annotation></semantics></math></span>","Score of option j on attribute i, as the buyer judges it (here on a 1–10 scale) (points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">i,\\ j</annotation></semantics></math></span>","Labels: i runs over the attributes, j identifies the option"]],"href":"learn/marketing/m01/consumer-decisions/"},{"id":"f:m01:score-gap-to-close","kind":"formula","course":"m01","lesson":"consumer-decisions","front":"Improvement needed to draw level with the leader","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mi>s</mi><mrow><mi>k</mi><mi>j</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>S</mi><mtext>lead</mtext></msub><mo>−</mo><msub><mi>S</mi><mi>j</mi></msub></mrow><msub><mi>w</mi><mi>k</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\Delta s_{kj} = \\dfrac{S_{\\text{lead}} - S_j}{w_k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mi>s</mi><mrow><mi>k</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta s_{kj}</annotation></semantics></math></span>","Rise in option j’s score on attribute k that would bring its weighted score level with the leader’s (points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mtext>lead</mtext></msub></mrow><annotation encoding=\"application/x-tex\">S_{\\text{lead}}</annotation></semantics></math></span>","Weighted score of the option currently in the lead (points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_j</annotation></semantics></math></span>","Weighted score of option j (points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>w</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">w_k</annotation></semantics></math></span>","Importance weight of attribute k"]],"href":"learn/marketing/m01/consumer-decisions/"},{"id":"f:m01:referral-multiplier","kind":"formula","course":"m01","lesson":"influences-on-buying","front":"Customers including referrals (referral multiplier)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>T</mi><mi>n</mi></msub><mo>=</mo><mi>N</mi><mtext> </mtext><mfrac><mrow><mn>1</mn><mo>−</mo><msup><mi>r</mi><mrow><mtext> </mtext><mi>n</mi><mo>+</mo><mn>1</mn></mrow></msup></mrow><mrow><mn>1</mn><mo>−</mo><mi>r</mi></mrow></mfrac><mspace width=\"2em\"/><msub><mi>T</mi><mi mathvariant=\"normal\">∞</mi></msub><mo>=</mo><mfrac><mi>N</mi><mrow><mn>1</mn><mo>−</mo><mi>r</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">T_n = N \\, \\dfrac{1 - r^{\\,n+1}}{1 - r} \\qquad T_{\\infty} = \\dfrac{N}{1 - r}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T</mi><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">T_n</annotation></semantics></math></span>","Total customers after n rounds of referrals, including the N won directly (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T</mi><mi mathvariant=\"normal\">∞</mi></msub></mrow><annotation encoding=\"application/x-tex\">T_{\\infty}</annotation></semantics></math></span>","Long-run total if referrals carried on for ever (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Customers won directly (by advertising, say) at the start (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Average number of new customers each new customer refers, from 0 up to but not including 1 (customers per customer)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rounds of referrals counted (rounds)"]],"href":"learn/marketing/m01/influences-on-buying/"},{"id":"f:m01:equipment-orders","kind":"formula","course":"m01","lesson":"business-buying","front":"Equipment orders under derived demand (acceleration effect)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>O</mi><mi>t</mi></msub><mo>=</mo><mi>max</mi><mo>⁡</mo><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><mn>0</mn><mo separator=\"true\">,</mo><mtext>  </mtext><msub><mi>K</mi><mi>t</mi></msub><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>d</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msub><mi>F</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo><mspace width=\"2em\"/><msub><mi>F</mi><mi>t</mi></msub><mo>=</mo><mi>max</mi><mo>⁡</mo><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><msub><mi>K</mi><mi>t</mi></msub><mo separator=\"true\">,</mo><mtext>  </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>d</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msub><mi>F</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo></mrow><annotation encoding=\"application/x-tex\">O_t = \\max\\bigl(0,\\; K_t - (1 - d)\\,F_{t-1}\\bigr) \\qquad F_t = \\max\\bigl(K_t,\\; (1 - d)\\,F_{t-1}\\bigr)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>O</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">O_t</annotation></semantics></math></span>","Units of equipment ordered in year t (for example, vans) (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>K</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">K_t</annotation></semantics></math></span>","Units needed in year t, in proportion to the customer’s own demand (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">F_t</annotation></semantics></math></span>","Units in service at the end of year t, including any spare units kept when demand falls (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">F_{t-1}</annotation></semantics></math></span>","Units in service at the end of the previous year (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Share of the units in service that wear out and are retired each year (decimal (0.1 = 10%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Year"]],"href":"learn/marketing/m01/business-buying/"},{"id":"f:m01:sa-market-share","kind":"formula","course":"m01","lesson":"situation-analysis","front":"Market share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>s</mi><mo>=</mo><mfrac><mi>Q</mi><msub><mi>Q</mi><mtext>market</mtext></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">s = \\dfrac{Q}{Q_{\\text{market}}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Market share of the business (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","The business’s sales in the market over the period ($ or units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>market</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{market}}</annotation></semantics></math></span>","Total sales of all businesses in the same market over the same period ($ or units (the same as Q))"]],"href":"learn/marketing/m01/situation-analysis/"},{"id":"f:m01:sa-weighted-strength","kind":"formula","course":"m01","lesson":"situation-analysis","front":"Weighted competitive-strength score","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mi>j</mi></msub><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>w</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>w</mi><mi>i</mi></msub><mo>=</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">S_j = \\sum_{i} w_i \\, s_{ij}, \\qquad \\sum_i w_i = 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_j</annotation></semantics></math></span>","Weighted strength score of competitor j (points on the rating scale)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>w</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">w_i</annotation></semantics></math></span>","Weight of factor i: its importance to customers, as a share of the total"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">s_{ij}</annotation></semantics></math></span>","Rating of competitor j on factor i, for example from 1 (poor) to 5 (excellent) (points)"]],"href":"learn/marketing/m01/situation-analysis/"},{"id":"f:m01:obj-required-customers","kind":"formula","course":"m01","lesson":"marketing-objectives","front":"Customers needed for a revenue target","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>req</mtext></msub><mo>=</mo><mfrac><msub><mi>R</mi><mtext>target</mtext></msub><mi>v</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">N_{\\text{req}} = \\dfrac{R_{\\text{target}}}{v}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>req</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{req}}</annotation></semantics></math></span>","Customers the business must have during the period (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mtext>target</mtext></msub></mrow><annotation encoding=\"application/x-tex\">R_{\\text{target}}</annotation></semantics></math></span>","Revenue target for the period ($ per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","Average revenue per customer over the period ($ per customer per year)"]],"href":"learn/marketing/m01/marketing-objectives/"},{"id":"f:m01:obj-new-customers","kind":"formula","course":"m01","lesson":"marketing-objectives","front":"New customers needed, allowing for retention","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>new</mtext></msub><mo>=</mo><msub><mi>N</mi><mtext>req</mtext></msub><mo>−</mo><mi>r</mi><mtext> </mtext><msub><mi>N</mi><mn>0</mn></msub><mspace width=\"2em\"/><mtext>and, if </mtext><mi>v</mi><mtext> is unchanged,</mtext><mspace width=\"2em\"/><msub><mi>N</mi><mtext>new</mtext></msub><mo>=</mo><msub><mi>N</mi><mn>0</mn></msub><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>g</mi><mo>−</mo><mi>r</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">N_{\\text{new}} = N_{\\text{req}} - r\\,N_0 \\qquad \\text{and, if } v \\text{ is unchanged,} \\qquad N_{\\text{new}} = N_0\\,(1 + g - r)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>new</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{new}}</annotation></semantics></math></span>","New customers the business must win during the period (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>req</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{req}}</annotation></semantics></math></span>","Customers needed for the revenue target (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">N_0</annotation></semantics></math></span>","Customers at the start of the period (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Retention rate: share of starting customers still customers at the end of the period (decimal (0.85 = 85%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Growth target for revenue (or for customers, when revenue per customer is unchanged) (decimal (0.15 = 15%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","Average revenue per customer per period ($ per customer)"]],"href":"learn/marketing/m01/marketing-objectives/"},{"id":"f:m01:obj-funnel-volume","kind":"formula","course":"m01","lesson":"marketing-objectives","front":"Top-of-funnel volume needed","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>V</mi><mo>=</mo><mfrac><msub><mi>N</mi><mtext>new</mtext></msub><mrow><msub><mi>c</mi><mn>1</mn></msub><mo>×</mo><msub><mi>c</mi><mn>2</mn></msub><mo>×</mo><mo>⋯</mo><mo>×</mo><msub><mi>c</mi><mi>k</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">V = \\dfrac{N_{\\text{new}}}{c_1 \\times c_2 \\times \\cdots \\times c_k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Leads, enquiries or visits needed at the top of the funnel (leads)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>new</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{new}}</annotation></semantics></math></span>","New customers needed (customers)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_i</annotation></semantics></math></span>","Conversion rate from each stage to the next, for stages 1 to k (decimal)"]],"href":"learn/marketing/m01/marketing-objectives/"},{"id":"f:m01:ca-value-created","kind":"formula","course":"m01","lesson":"competitive-advantage","front":"Value created, and how the price shares it","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>V</mi><mo>=</mo><mi>W</mi><mo>−</mo><mi>C</mi><mo>=</mo><munder><munder><mrow><mo stretchy=\"false\">(</mo><mi>W</mi><mo>−</mo><mi>P</mi><mo stretchy=\"false\">)</mo></mrow><mo stretchy=\"true\">⏟</mo></munder><mtext>customer</mtext></munder><mo>+</mo><munder><munder><mrow><mo stretchy=\"false\">(</mo><mi>P</mi><mo>−</mo><mi>C</mi><mo stretchy=\"false\">)</mo></mrow><mo stretchy=\"true\">⏟</mo></munder><mtext>business</mtext></munder></mrow><annotation encoding=\"application/x-tex\">V = W - C = \\underbrace{(W - P)}_{\\text{customer}} + \\underbrace{(P - C)}_{\\text{business}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Value created by serving one customer ($ per customer (or per unit))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi></mrow><annotation encoding=\"application/x-tex\">W</annotation></semantics></math></span>","The customer’s willingness to pay for this offer: the most they would pay rather than go without it ($ per customer)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","The price the customer pays ($ per customer)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","The cost to the business of serving that customer ($ per customer)"]],"href":"learn/marketing/m01/competitive-advantage/"},{"id":"f:m01:ca-price-premium","kind":"formula","course":"m01","lesson":"competitive-advantage","front":"Price premium","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Premium</mtext><mo>=</mo><mrow><mo fence=\"true\">(</mo><mfrac><msub><mi>P</mi><mi>f</mi></msub><msub><mi>P</mi><mi>r</mi></msub></mfrac><mo>−</mo><mn>1</mn><mo fence=\"true\">)</mo></mrow><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Premium} = \\left(\\dfrac{P_f}{P_r} - 1\\right) \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">P_f</annotation></semantics></math></span>","The firm’s price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">P_r</annotation></semantics></math></span>","The rival’s price for a comparable offer ($ per unit)"]],"href":"learn/marketing/m01/competitive-advantage/"},{"id":"f:m01:ca-max-price","kind":"formula","course":"m01","lesson":"competitive-advantage","front":"Highest price that still wins the customer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>P</mi><mi>max</mi><mo>⁡</mo></msub><mo>=</mo><msub><mi>P</mi><mi>r</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><msub><mi>W</mi><mi>f</mi></msub><mo>−</mo><msub><mi>W</mi><mi>r</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">P_{\\max} = P_r + (W_f - W_r)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">P_{\\max}</annotation></semantics></math></span>","Highest price at which the customer is at least as well off choosing the firm ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">P_r</annotation></semantics></math></span>","The rival’s price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>W</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">W_f</annotation></semantics></math></span>","The customer’s willingness to pay for the firm’s offer ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>W</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">W_r</annotation></semantics></math></span>","The customer’s willingness to pay for the rival’s offer ($ per unit)"]],"href":"learn/marketing/m01/competitive-advantage/"},{"id":"f:m02:customer-value","kind":"formula","course":"m02","lesson":"marketing-mix","front":"Customer value (a way of thinking)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Customer value</mtext><mo>=</mo><mfrac><mtext>Perceived benefits</mtext><mtext>Perceived total cost</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Customer value} = \\dfrac{\\text{Perceived benefits}}{\\text{Perceived total cost}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Perceived benefits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Perceived benefits}</annotation></semantics></math></span>","The functional, emotional and social benefits of the offer, as the customer judges them"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Perceived total cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Perceived total cost}</annotation></semantics></math></span>","The price plus the time, effort and risk of buying and using the offer"]],"href":"learn/marketing/m02/marketing-mix/"},{"id":"f:m02:kept-per-unit","kind":"formula","course":"m02","lesson":"marketing-mix","front":"Gross margin per unit sold through a retailer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>m</mi><mo stretchy=\"false\">)</mo><mo>−</mo><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">g = P \\times (1 - m) - c</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit: what the producer keeps after the trade’s share and the cost of the unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Shelf price paid by the shopper ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Share of the shelf price kept by the distributor and retailer together (decimal (0.32 = 32%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">c</annotation></semantics></math></span>","Cost of goods per unit (for Lantern: liquid, can, co-packing and freight to the distributor) ($ per unit)"]],"href":"learn/marketing/m02/marketing-mix/"},{"id":"f:m02:cogs-difference","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra cost of goods from a better tier","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>c</mi><mtext>high</mtext></msub><mo>−</mo><msub><mi>c</mi><mtext>low</mtext></msub><mo stretchy=\"false\">)</mo><mo>×</mo><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C = (c_{\\text{high}} - c_{\\text{low}}) \\times Q</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C</annotation></semantics></math></span>","Extra cost of goods for the volume sold ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mtext>high</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>c</mi><mtext>low</mtext></msub></mrow><annotation encoding=\"application/x-tex\">c_{\\text{high}},\\ c_{\\text{low}}</annotation></semantics></math></span>","Cost of goods per unit of the two tiers ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Units sold (units)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:range-fixed-cost","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra fixed cost of a wider range","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>n</mi><mtext>wide</mtext></msub><mo>−</mo><msub><mi>n</mi><mtext>narrow</mtext></msub><mo stretchy=\"false\">)</mo><mo>×</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>L</mi><mi>k</mi></msub><mo>+</mo><msub><mi>F</mi><mtext>range</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta F = (n_{\\text{wide}} - n_{\\text{narrow}}) \\times \\sum_{k} L_k + F_{\\text{range}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta F</annotation></semantics></math></span>","Extra fixed cost per year of the wider range ($ per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>wide</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>n</mi><mtext>narrow</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{wide}},\\ n_{\\text{narrow}}</annotation></semantics></math></span>","Number of SKUs (flavours) in each range (SKUs)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">L_k</annotation></semantics></math></span>","Listing fee per SKU per year in retail channel k ($ per SKU per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mtext>range</mtext></msub></mrow><annotation encoding=\"application/x-tex\">F_{\\text{range}}</annotation></semantics></math></span>","Other fixed costs of the wider range: production runs, labels, printing plates ($ per year)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:payback-units","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra units needed to pay for a fixed cost","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>extra</mtext></msub><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><mi>g</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{extra}} = \\dfrac{\\Delta F}{g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>extra</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{extra}}</annotation></semantics></math></span>","Extra units the decision must sell to cover its own fixed cost (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta F</annotation></semantics></math></span>","The extra fixed cost of the decision ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit: what the producer keeps after the trade’s share and the cost of goods ($ per unit)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:yoy-growth","kind":"formula","course":"m02","lesson":"product-life-cycle","front":"Year-on-year growth","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mfrac><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>−</mo><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">g = \\dfrac{S_t - S_{t-1}}{S_{t-1}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Growth rate over a year (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_t</annotation></semantics></math></span>","Sales in the current year, or in a quarter (units or $)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">S_{t-1}</annotation></semantics></math></span>","Sales in the year before, or in the same quarter a year earlier (units or $)"]],"href":"learn/marketing/m02/product-life-cycle/"},{"id":"f:m02:seasonal-adjustment","kind":"formula","course":"m02","lesson":"product-life-cycle","front":"Seasonally adjusted sales","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msubsup><mi>S</mi><mi>q</mi><mtext>adj</mtext></msubsup><mo>=</mo><mfrac><msub><mi>S</mi><mi>q</mi></msub><msub><mi>s</mi><mi>q</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">S^{\\text{adj}}_q = \\dfrac{S_q}{s_q}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>S</mi><mi>q</mi><mtext>adj</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">S^{\\text{adj}}_q</annotation></semantics></math></span>","Sales in quarter q, adjusted to an average quarter (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>q</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_q</annotation></semantics></math></span>","Actual sales in quarter q (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>q</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_q</annotation></semantics></math></span>","Seasonal index for quarter q: its sales relative to an average quarter (Harbour City: 0.85, 1.05, 1.25, 0.85)"]],"href":"learn/marketing/m02/product-life-cycle/"},{"id":"f:m02:contribution-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Contribution margin per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CM</mtext><mo>=</mo><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\text{CM} = P - VC</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit, after any trade margin, commission or fulfilment cost deducted from it ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:cm-ratio","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Contribution margin ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CM ratio</mtext><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><mi>P</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CM ratio} = \\dfrac{P - VC}{P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CM ratio</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CM ratio}</annotation></semantics></math></span>","Share of each dollar of price left after variable costs (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:markup","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Markup on cost and the cost-plus price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>C</mi></mrow><mi>C</mi></mfrac><mspace width=\"2em\"/><mi>P</mi><mo>=</mo><mi>C</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">k = \\dfrac{P - C}{C} \\qquad P = C\\,(1 + k)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Markup: profit per unit as a share of the cost (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost the markup is applied to ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Selling price ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Margin on price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>C</mi></mrow><mi>P</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">m = \\dfrac{P - C}{P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Margin: profit per unit as a share of the price (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Selling price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:markup-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Converting between markup and margin","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mfrac><mi>k</mi><mrow><mn>1</mn><mo>+</mo><mi>k</mi></mrow></mfrac><mspace width=\"2em\"/><mi>k</mi><mo>=</mo><mfrac><mi>m</mi><mrow><mn>1</mn><mo>−</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">m = \\dfrac{k}{1 + k} \\qquad k = \\dfrac{m}{1 - m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Markup on cost (decimal)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Margin on price (decimal)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:price-for-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Price that gives a target margin","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>C</mi><mrow><mn>1</mn><mo>−</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\dfrac{C}{1 - m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Target margin on price (decimal)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price that gives the target margin ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:break-even-units","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Break-even volume","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>BE</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi></mrow><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{BE}} = \\dfrac{FC}{P - VC}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>BE</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{BE}}</annotation></semantics></math></span>","Units that must be sold in the period for total contribution to equal fixed costs (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">FC</annotation></semantics></math></span>","Fixed costs for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">P - VC</annotation></semantics></math></span>","Contribution margin per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:break-even-revenue","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Break-even revenue","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mtext>BE</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi></mrow><mtext>CM ratio</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">R_{\\text{BE}} = \\dfrac{FC}{\\text{CM ratio}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mtext>BE</mtext></msub></mrow><annotation encoding=\"application/x-tex\">R_{\\text{BE}}</annotation></semantics></math></span>","Sales value at which total contribution equals fixed costs ($)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:target-profit-volume","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Volume for a target profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>target</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi><mo>+</mo><msup><mi>π</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{target}} = \\dfrac{FC + \\pi^{*}}{P - VC}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>target</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{target}}</annotation></semantics></math></span>","Units that must be sold in the period to earn the target profit (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">FC</annotation></semantics></math></span>","Fixed costs for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>π</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><annotation encoding=\"application/x-tex\">\\pi^{*}</annotation></semantics></math></span>","Target profit for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:target-return-price","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Target-return price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mtext>unit cost</mtext><mo>+</mo><mfrac><mrow><mi>r</mi><mo>×</mo><mi>I</mi></mrow><mi>Q</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\text{unit cost} + \\dfrac{r \\times I}{Q}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Target-return price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>unit cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{unit cost}</annotation></semantics></math></span>","Full cost per unit at the forecast volume: variable cost plus fixed costs ÷ Q ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Target rate of return on the capital invested, per period (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Capital invested ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Forecast unit sales for the period (units)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:economic-value","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Economic value to the customer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV</mtext><mo>=</mo><mtext>reference value</mtext><mo>+</mo><mtext>differentiation value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV} = \\text{reference value} + \\text{differentiation value}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>reference value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{reference value}</annotation></semantics></math></span>","Price of the customer’s next-best alternative ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>differentiation value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{differentiation value}</annotation></semantics></math></span>","Value to the customer of every difference from that alternative, positive or negative ($)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:price-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Price elasticity of demand","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>Q</mi></mrow><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{\\%\\,\\Delta Q}{\\%\\,\\Delta P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q</annotation></semantics></math></span>","Percentage change in quantity demanded (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta P</annotation></semantics></math></span>","Percentage change in price (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Elasticity; usually negative. This course keeps the sign; many texts report the absolute value"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:point-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Point elasticity (from a starting point)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>2</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><msub><mi>Q</mi><mn>1</mn></msub></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>2</mn></msub><mo>−</mo><msub><mi>P</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><msub><mi>P</mi><mn>1</mn></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{(Q_2 - Q_1)/Q_1}{(P_2 - P_1)/P_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Price elasticity of demand; usually negative"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ Q_1</annotation></semantics></math></span>","Starting price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>2</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_2,\\ Q_2</annotation></semantics></math></span>","New price and quantity ($, units)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:midpoint-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Midpoint (arc) elasticity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>2</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">/</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>2</mn></msub><mo>−</mo><msub><mi>P</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">/</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>+</mo><msub><mi>P</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{(Q_2 - Q_1) \\big/ \\tfrac{1}{2}(Q_1 + Q_2)}{(P_2 - P_1) \\big/ \\tfrac{1}{2}(P_1 + P_2)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Price elasticity of demand; usually negative"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ Q_1</annotation></semantics></math></span>","First observed price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>2</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_2,\\ Q_2</annotation></semantics></math></span>","Second observed price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\tfrac{1}{2}(Q_1 + Q_2)</annotation></semantics></math></span>","Average of the two quantities (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>+</mo><msub><mi>P</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\tfrac{1}{2}(P_1 + P_2)</annotation></semantics></math></span>","Average of the two prices ($)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:revenue-change","kind":"formula","course":"m02","lesson":"price-response","front":"Revenue after a price change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mfrac><msub><mi>R</mi><mn>2</mn></msub><msub><mi>R</mi><mn>1</mn></msub></mfrac><mo>=</mo><mfrac><msub><mi>P</mi><mn>2</mn></msub><msub><mi>P</mi><mn>1</mn></msub></mfrac><mo>×</mo><mfrac><msub><mi>Q</mi><mn>2</mn></msub><msub><mi>Q</mi><mn>1</mn></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\dfrac{R_2}{R_1} = \\dfrac{P_2}{P_1} \\times \\dfrac{Q_2}{Q_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Revenue, price × quantity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>P</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ P_2</annotation></semantics></math></span>","Price before and after the change ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_2</annotation></semantics></math></span>","Quantity before and after the change (units)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:required-volume","kind":"formula","course":"m02","lesson":"price-response","front":"Volume change that keeps contribution unchanged","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><msub><mi>Q</mi><mtext>needed</mtext></msub><mo>=</mo><mfrac><mrow><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><mrow><mi>C</mi><mi>M</mi><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q_{\\text{needed}} = \\dfrac{-\\Delta P}{CM + \\Delta P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><msub><mi>Q</mi><mtext>needed</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q_{\\text{needed}}</annotation></semantics></math></span>","Percentage change in volume that keeps total contribution unchanged (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta P</annotation></semantics></math></span>","Change in the price the seller receives; negative for a cut ($ per unit or % of price)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">CM</annotation></semantics></math></span>","Contribution margin per unit at the current price (or the contribution margin ratio, if ΔP is a percentage) ($ per unit or % of price)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:net-price-indirect","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Net price through an indirect channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mo>=</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>m</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">N = P \\times (1 - m)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price: what the producer receives per unit ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Shelf price paid by the final customer ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Trade margin: the share of the shelf price kept by all intermediaries together"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:net-price-direct","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Net price through a direct channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mo>=</mo><mi>P</mi><mo>−</mo><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">N = P - f</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price: what the producer receives per unit ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price paid by the final customer ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">f</annotation></semantics></math></span>","Fulfilment cost per unit: storing, picking, packing and delivering ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:gross-margin-per-unit","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Gross margin per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mi>N</mi><mo>−</mo><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">g = N - c</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit, before fixed fees, promotion and overhead ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price per unit: what the producer receives after the trade’s margin (and, selling direct, after fulfilment) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">c</annotation></semantics></math></span>","Cost of goods per unit ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:compound-trade-margin","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Combined margin of a multi-level channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>m</mi><mi>r</mi></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>m</mi><mi>d</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">m = 1 - (1 - m_r)(1 - m_d)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_r</annotation></semantics></math></span>","Retailer’s margin, as a share of the shelf price"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>d</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_d</annotation></semantics></math></span>","Distributor’s margin, as a share of the price it sells to the retailer at"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:fee-payback-units","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Units needed to cover a fixed channel cost","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>Q</mi><mo>=</mo><mfrac><mi>F</mi><mi>g</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">Q = \\dfrac{F}{g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Units that must be sold in a year to cover the fee (round up) (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">F</annotation></semantics></math></span>","Fixed yearly cost of the channel: listing fees × SKUs, or the running cost of a direct channel ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit in the channel ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:pct-of-sales-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Percentage-of-sales budget","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><mi>s</mi><mo>×</mo><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">B = s \\times R</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Promotion budget for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Chosen percentage of sales, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Sales revenue: last period’s actual or this period’s forecast ($)"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:competitive-parity-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Competitive-parity budget (average of rivals)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>B</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">B = \\dfrac{1}{n}\\sum_{i=1}^{n} B_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_i</annotation></semantics></math></span>","Estimated promotion spending of rival i ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rivals used as the benchmark"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:objective-task-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Objective-and-task budget","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>q</mi><mi>k</mi></msub><mo>×</mo><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B = \\sum_{k} q_k \\times c_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Promotion budget for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">q_k</annotation></semantics></math></span>","Quantity of task k needed to reach the objectives (demo days, thousands of impressions, events…) (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_k</annotation></semantics></math></span>","Cost per unit of task k ($ per unit)"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:avg-frequency","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Average frequency","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mi>I</mi><mi>R</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{f} = \\dfrac{I}{R}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{f}</annotation></semantics></math></span>","Average frequency: times each reached person was exposed"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions delivered to the target audience (impressions)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Reach: different people exposed at least once (people)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:grp","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Gross rating points","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>GRPs</mtext><mo>=</mo><mi>r</mi><mo>×</mo><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mi>I</mi><mi>N</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{GRPs} = r \\times \\bar{f} = \\dfrac{I}{N} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Reach as a percentage of the target audience (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{f}</annotation></semantics></math></span>","Average frequency"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions delivered to the target audience (impressions)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Size of the target audience (people)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:cpm","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Cost per thousand impressions","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CPM</mtext><mo>=</mo><mfrac><mtext>Spend</mtext><mi>I</mi></mfrac><mo>×</mo><mn>1,000</mn></mrow><annotation encoding=\"application/x-tex\">\\text{CPM} = \\dfrac{\\text{Spend}}{I} \\times 1{,}000</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Spend</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Spend}</annotation></semantics></math></span>","Cost of the media ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions bought (impressions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:ctr","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Click-through rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CTR</mtext><mo>=</mo><mfrac><mtext>Clicks</mtext><mi>I</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CTR} = \\dfrac{\\text{Clicks}}{I}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Clicks</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Clicks}</annotation></semantics></math></span>","Clicks on the ad (clicks)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions of the ad (impressions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:conversion-rate","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Conversion rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CR</mtext><mo>=</mo><mfrac><mtext>Conversions</mtext><mtext>Clicks</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CR} = \\dfrac{\\text{Conversions}}{\\text{Clicks}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Conversions</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Conversions}</annotation></semantics></math></span>","Completed target actions, such as orders (conversions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:cpa","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Cost per acquisition","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CPA</mtext><mo>=</mo><mfrac><mtext>Spend</mtext><mtext>Conversions</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CPA} = \\dfrac{\\text{Spend}}{\\text{Conversions}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CPA</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CPA}</annotation></semantics></math></span>","Cost of each conversion ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:roas","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Return on ad spend","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>ROAS</mtext><mo>=</mo><mfrac><mtext>Attributed revenue</mtext><mtext>Ad spend</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROAS} = \\dfrac{\\text{Attributed revenue}}{\\text{Ad spend}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Attributed revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Attributed revenue}</annotation></semantics></math></span>","Revenue credited to the campaign by the attribution rule in use ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:marketing-roi","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Marketing ROI","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>ROI</mtext><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi><mo>−</mo><mi>M</mi></mrow><mi>M</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROI} = \\dfrac{\\Delta C - M}{M}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C</annotation></semantics></math></span>","Incremental contribution: extra revenue caused by the marketing minus its variable costs ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","Marketing cost ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:breakeven-roas","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Break-even ROAS","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>ROAS</mtext><mtext>BE</mtext></msub><mo>=</mo><mfrac><mn>1</mn><msub><mi>m</mi><mi>c</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROAS}_{\\text{BE}} = \\dfrac{1}{m_c}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_c</annotation></semantics></math></span>","Contribution margin ratio on the revenue counted in ROAS"]],"href":"learn/marketing/m02/measuring-the-mix/"}];
